    def _estimate_melt_fraction_from_attenuation(self, seismic_analysis: Dict, 
                                               velocity_structure: Dict, config: Dict) -> Dict:
        """Estimate melt fraction from seismic attenuation analysis"""
        try:
            print("Estimating melt fraction from seismic attenuation...")
            
            melt_analysis = {}
            
            # Extract attenuation data
            if 'attenuation' in velocity_structure:
                attenuation_data = velocity_structure['attenuation']
                
                # Estimate melt fraction using empirical relationships
                # Melt fraction correlates with seismic attenuation (Q-factor)
                q_factors = attenuation_data.get('q_factors', [])
                if q_factors:
                    # Empirical relationship: melt_fraction = (1/Q - 1/Q_solid) / (1/Q_melt - 1/Q_solid)
                    q_solid = 1000  # Typical Q for solid rock
                    q_melt = 50     # Typical Q for partial melt
                    
                    melt_fractions = []
                    for q in q_factors:
                        if q > 0:
                            melt_frac = max(0, min(1, (1/q - 1/q_solid) / (1/q_melt - 1/q_solid)))
                            melt_fractions.append(melt_frac)
                    
                    if melt_fractions:
                        melt_analysis['melt_fraction'] = np.mean(melt_fractions)
                        melt_analysis['melt_uncertainty'] = [np.min(melt_fractions), np.max(melt_fractions)]
                        melt_analysis['melt_confidence'] = 1.0 - np.std(melt_fractions)
            
            # Velocity-based melt fraction estimation
            if 'vp_vs_ratios' in velocity_structure:
                vp_vs_data = velocity_structure['vp_vs_ratios']
                # High Vp/Vs ratios often indicate partial melt
                vp_vs_ratios = vp_vs_data.get('ratios', [])
                if vp_vs_ratios:
                    # Empirical relationship for volcanic regions
                    baseline_ratio = 1.73  # Typical for solid rock
                    enhanced_ratios = [max(0, (ratio - baseline_ratio) / 0.2) for ratio in vp_vs_ratios if ratio > baseline_ratio]
                    
                    if enhanced_ratios:
                        velocity_melt_frac = min(0.3, np.mean(enhanced_ratios))  # Cap at 30%
                        if 'melt_fraction' in melt_analysis:
                            # Combine estimates
                            melt_analysis['melt_fraction'] = (melt_analysis['melt_fraction'] + velocity_melt_frac) / 2
                        else:
                            melt_analysis['melt_fraction'] = velocity_melt_frac
                            melt_analysis['melt_confidence'] = 0.7
            
            # Temperature constraints from melt fraction
            if 'melt_fraction' in melt_analysis:
                melt_frac = melt_analysis['melt_fraction']
                # Empirical temperature-melt fraction relationship
                solidus_temp = 1273  # K (1000°C)
                liquidus_temp = 1473  # K (1200°C)
                estimated_temp = solidus_temp + melt_frac * (liquidus_temp - solidus_temp)
                
                melt_analysis['temperature_estimate_K'] = estimated_temp
                melt_analysis['temperature_uncertainty'] = [estimated_temp - 50, estimated_temp + 50]
            
            return melt_analysis
            
        except Exception as e:
            print(f"Melt fraction estimation failed: {e}")
            return {'error': str(e)}
    
    def _analyze_volcanic_tremor_for_volatiles(self, processed_data: Dict, 
                                             event_catalog: List[Dict], config: Dict) -> Dict:
        """Analyze volcanic tremor and LP events for volatile content estimation"""
        try:
            print("Analyzing volcanic tremor for volatile content...")
            
            volatile_analysis = {}
            
            # Analyze tremor characteristics
            tremor_stats = self._extract_tremor_statistics(processed_data, config)
            volatile_analysis['tremor_statistics'] = tremor_stats
            
            # LP event analysis for gas content
            lp_events = [event for event in event_catalog if event.get('type') == 'LP']
            if lp_events:
                lp_analysis = self._analyze_lp_events_for_gas_content(lp_events, config)
                volatile_analysis.update(lp_analysis)
            
            # Spectral analysis for volatile signatures
            spectral_analysis = self._perform_spectral_analysis_for_volatiles(processed_data, config)
            volatile_analysis['spectral_signatures'] = spectral_analysis
            
            # Empirical volatile content estimation
            if tremor_stats:
                # Tremor amplitude correlates with volatile flux
                tremor_amplitude = tremor_stats.get('mean_amplitude', 0)
                # Empirical relationship for H2O content
                h2o_estimate = min(6.0, max(0.1, tremor_amplitude * 2.0))  # wt%
                volatile_analysis['h2o_content'] = h2o_estimate
                
                # CO2 estimation from tremor frequency content
                dominant_freq = tremor_stats.get('dominant_frequency', 2.0)
                co2_estimate = min(2000, max(50, (5.0 - dominant_freq) * 400))  # ppm
                volatile_analysis['co2_content'] = co2_estimate
                
                # Degassing rate estimation
                if len(lp_events) > 0:
                    lp_rate = len(lp_events) / max(1, config.get('time_window', 3600)) * 3600  # events/hour
                    degassing_rate = lp_rate * 0.1  # kg/s (empirical)
                    volatile_analysis['degassing_rate'] = degassing_rate
                
                volatile_analysis['volatile_confidence'] = 0.6  # Moderate confidence
            
            return volatile_analysis
            
        except Exception as e:
            print(f"Volatile analysis from tremor failed: {e}")
            return {'error': str(e)}
    
    def _integrate_seismic_thermodynamics(self, seismic_analysis: Dict, 
                                        velocity_structure: Dict, melt_characteristics: Dict) -> Dict:
        """Integrate seismic observations with thermodynamic modeling"""
        try:
            print("Integrating seismic data with thermodynamic constraints...")
            
            thermo_integration = {}
            
            # Extract constraints from seismic analysis
            depth_constraint = velocity_structure.get('magma_depth_km')
            melt_fraction = melt_characteristics.get('melt_fraction')
            temperature_estimate = melt_characteristics.get('temperature_estimate_K')
            
            if depth_constraint and hasattr(self, 'thermodynamic_engine'):
                # Calculate pressure from depth
                pressure_Pa = depth_constraint * 1000 * 9.81 * 2700  # Approximate lithostatic pressure
                thermo_integration['pressure_Pa'] = pressure_Pa
                thermo_integration['pressure_uncertainty'] = [pressure_Pa * 0.8, pressure_Pa * 1.2]
                
                # Use thermodynamic engine for advanced calculations
                try:
                    if temperature_estimate and melt_fraction:
                        # Calculate phase equilibrium at given P-T conditions
                        phase_equilibrium = self.thermodynamic_engine.calculate_phase_equilibrium(
                            temperature_estimate, pressure_Pa, {'SiO2': 0.5, 'Al2O3': 0.15, 'FeO': 0.1}
                        )
                        
                        thermo_integration['phase_equilibrium'] = phase_equilibrium
                        thermo_integration['thermodynamic_consistency'] = True
                        
                        # Refine temperature estimate using thermodynamics
                        refined_temp = self._refine_temperature_estimate(
                            temperature_estimate, pressure_Pa, melt_fraction
                        )
                        thermo_integration['temperature_K'] = refined_temp
                        thermo_integration['temp_uncertainty'] = [refined_temp - 25, refined_temp + 25]
                        
                except Exception as te_error:
                    print(f"Thermodynamic engine integration failed: {te_error}")
                    thermo_integration['temperature_K'] = temperature_estimate
                    thermo_integration['temp_uncertainty'] = [temperature_estimate - 50, temperature_estimate + 50]
            
            # Volatile solubility constraints
            if melt_fraction and 'h2o_content' in melt_characteristics:
                h2o_content = melt_characteristics['h2o_content']
                # Use Henry's law and pressure constraints
                if 'pressure_Pa' in thermo_integration:
                    pressure_MPa = thermo_integration['pressure_Pa'] / 1e6
                    # H2O solubility in basaltic melt (simplified)
                    max_h2o_solubility = 0.5 * np.sqrt(pressure_MPa)  # wt%
                    
                    if h2o_content > max_h2o_solubility:
                        # Supersaturated - indicates gas phase present
                        thermo_integration['gas_phase_present'] = True
                        thermo_integration['excess_h2o'] = h2o_content - max_h2o_solubility
                    else:
                        thermo_integration['gas_phase_present'] = False
            
            return thermo_integration
            
        except Exception as e:
            print(f"Seismic-thermodynamic integration failed: {e}")
            return {'error': str(e)}
            print("Estimating melt fraction from seismic attenuation...")
            
            melt_analysis = {}
            
            # Quality factor (Q) analysis for melt fraction
            if 'attenuation' in velocity_structure:
                q_values = velocity_structure['attenuation']
                melt_fraction = self._calculate_melt_fraction_from_q(q_values, config)
                melt_analysis['melt_fraction'] = melt_fraction
                melt_analysis['melt_confidence'] = self._assess_melt_fraction_confidence(
                    q_values, config
                )
            
            # Vp/Vs ratio contribution to melt estimation
            if 'vp_vs_ratios' in velocity_structure:
                vp_vs_melt = self._estimate_melt_from_vp_vs(
                    velocity_structure['vp_vs_ratios'], config
                )
                melt_analysis['vp_vs_melt_estimate'] = vp_vs_melt
            
            # Combine multiple estimates
            if 'melt_fraction' in melt_analysis and 'vp_vs_melt_estimate' in melt_analysis:
                combined_estimate = self._combine_melt_fraction_estimates(
                    melt_analysis, config
                )
                melt_analysis.update(combined_estimate)
            
            return melt_analysis
            
        except Exception as e:
            print(f"Melt fraction estimation failed: {e}")
            return {'error': str(e)}
    
