    def _ml_reservoir_parameter_estimation(self, seismic_analysis: Dict, 
                                         velocity_structure: Dict, melt_characteristics: Dict, 
                                         config: Dict) -> Dict:
        """Machine learning-based reservoir parameter estimation"""
        try:
            print("Performing ML-based reservoir parameter estimation...")
            
            # Prepare feature vector from seismic analysis
            features = self._prepare_ml_features(
                seismic_analysis, velocity_structure, melt_characteristics
            )
            
            ml_results = {}
            
            # Reservoir type classification
            if self._is_ml_model_available('reservoir_classifier', config):
                reservoir_type = self._classify_reservoir_type(features, config)
                ml_results['reservoir_type'] = reservoir_type
            
            # Eruption potential assessment
            if self._is_ml_model_available('eruption_predictor', config):
                eruption_potential = self._assess_eruption_potential(features, config)
                ml_results['eruption_potential'] = eruption_potential
            
            # Maturity stage classification
            maturity_stage = self._classify_maturity_stage(features, config)
            ml_results['maturity_stage'] = maturity_stage
            
            return ml_results
            
        except Exception as e:
            print(f"ML reservoir parameter estimation failed: {e}")
            return {'error': str(e)}
    
    def _is_module_available(self, module_name: str) -> bool:
        """Check if a backend module is available for integration"""
        try:
            # Try to import the module
            if module_name == 'seismic_transformer':
                from . import seismic_transformer
                return hasattr(seismic_transformer, 'SeismicTransformer')
            elif module_name == 'moment_tensor_inversion':
                from . import moment_tensor_inversion
                return hasattr(moment_tensor_inversion, 'MomentTensorInversion')
            elif module_name == 'ambient_noise_engine':
                from . import ambient_noise_engine
                return hasattr(ambient_noise_engine, 'AmbientNoiseEngine')
            elif module_name == 'array_processor_ml':
                from . import array_processor_ml
                return hasattr(array_processor_ml, 'ArrayProcessorML')
            elif module_name == 'magma_reservoir_monitoring':
                from . import magma_reservoir_monitoring
                return hasattr(magma_reservoir_monitoring, 'MagmaReservoirMonitoring')
            else:
                return False
        except ImportError:
            return False
    
    def _provide_fallback_seismic_analysis(self, seismic_data: Dict, event_catalog: List[Dict]) -> Dict:
        """Provide fallback analysis when advanced methods fail"""
        try:
            fallback_results = {}
            
            # Basic event statistics
            if event_catalog:
                fallback_results['event_count'] = len(event_catalog)
                magnitudes = [event.get('magnitude', 0) for event in event_catalog]
                fallback_results['magnitude_stats'] = {
                    'mean': np.mean(magnitudes) if magnitudes else 0,
                    'max': np.max(magnitudes) if magnitudes else 0,
                    'min': np.min(magnitudes) if magnitudes else 0
                }
            
            # Basic data availability
            fallback_results['data_availability'] = {
                'stations': len(seismic_data),
                'has_waveforms': any(seismic_data.values())
            }
            
            return fallback_results
            
        except Exception as e:
            return {'error': str(e)}
    
    def calculate_gas_evolution(self, pressure, temperature, composition):
        """
        Advanced gas evolution calculation using multi-component thermodynamic modeling
        """
        try:
            if self.advanced_thermodynamics_enabled and hasattr(self, 'thermodynamic_engine'):
                return self._calculate_advanced_gas_evolution(pressure, temperature, composition)
            else:
                return self._calculate_fallback_gas_evolution(pressure, temperature, composition)
        except Exception as e:
            print(f"Gas evolution calculation error: {e}")
            return self._calculate_fallback_gas_evolution(pressure, temperature, composition)
    
    def _calculate_advanced_gas_evolution(self, pressure, temperature, composition):
        """Advanced gas evolution with multicomponent equilibrium"""
        try:
            # Multi-component gas-melt equilibrium
            gas_species = ['H2O', 'CO2', 'SO2', 'H2S', 'HCl', 'HF']
            evolved_gases = {}
            
            # Calculate chemical potentials for each species
            for species in gas_species:
                try:
                    # Gas phase chemical potential
                    mu_gas = self.thermodynamic_engine.calculate_chemical_potential(
                        species, 'gas', temperature, pressure
                    )
                    
                    # Melt phase chemical potential  
                    mu_melt = self.thermodynamic_engine.calculate_chemical_potential(
                        species, 'melt', temperature, pressure
                    )
                    
                    # Equilibrium condition: mu_gas = mu_melt
                    # Calculate partition coefficient
                    K_d = np.exp((mu_melt - mu_gas) / (8.314 * (temperature + 273.15)))
                    
                    # Solubility with pressure and composition effects
                    if species == 'H2O':
                        # Zhang & Stolper (1991) model with improvements
                        solubility = self._calculate_h2o_solubility_advanced(pressure, temperature, composition)
                    elif species == 'CO2':
                        # Papale et al. (2006) model with speciation
                        solubility = self._calculate_co2_solubility_advanced(pressure, temperature, composition)
                    elif species == 'SO2':
                        # Sulfur speciation model (Jugo et al., 2010)
                        solubility = self._calculate_so2_solubility_advanced(pressure, temperature, composition)
                    else:
                        # Generic Henry's law with activity corrections
                        henry_constant = self._get_henry_constant(species, temperature)
                        activity_coeff = self._calculate_gas_activity_coefficient(species, temperature, pressure, composition)
                        solubility = henry_constant * pressure * activity_coeff / 1e6  # Convert to wt%
                    
                    # Calculate evolved gas based on equilibrium
                    initial_content = getattr(composition, species, 0.0)
                    dissolved_content = min(initial_content, solubility)
                    evolved_gas = max(0.0, initial_content - dissolved_content)
                    
                    evolved_gases[species] = {
                        'evolved': evolved_gas,
                        'dissolved': dissolved_content,
                        'solubility': solubility,
                        'partition_coefficient': K_d
                    }
                    
                except Exception as species_error:
                    # Fallback for this species
                    evolved_gases[species] = {'evolved': 0.0, 'dissolved': 0.0}
            
            # Calculate gas-melt mass transfer rates
            gas_transfer_rates = self._calculate_gas_transfer_rates(
                evolved_gases, temperature, pressure
            )
            
            # Total evolved gas with phase separation effects
            total_evolved = sum(gas['evolved'] for gas in evolved_gases.values())
            total_dissolved = sum(gas['dissolved'] for gas in evolved_gases.values())
            
            # Bubble nucleation and growth
            bubble_dynamics = self._calculate_bubble_dynamics(
                total_evolved, pressure, temperature
            )
            
            return {
                'total_evolved': total_evolved,
                'total_dissolved': total_dissolved,
                'species_breakdown': evolved_gases,
                'transfer_rates': gas_transfer_rates,
                'bubble_dynamics': bubble_dynamics,
                'gas_density': self._calculate_gas_mixture_density(evolved_gases, temperature, pressure),
                'expansion_factor': bubble_dynamics.get('expansion_factor', 1.0)
            }
            
        except Exception as e:
            print(f"Advanced gas evolution failed: {e}")
            return self._calculate_fallback_gas_evolution(pressure, temperature, composition)
    
    def _calculate_h2o_solubility_advanced(self, pressure, temperature, composition):
        """Advanced H2O solubility with speciation and activity effects"""
        try:
            # Zhang & Stolper (1991) with improvements
            T_K = temperature + 273.15
            P_MPa = pressure / 1e6
            
            # Melt composition effects
            SiO2_mol = getattr(composition, 'SiO2', 50.0) / 60.08  # Convert to mol%
            Al2O3_mol = getattr(composition, 'Al2O3', 15.0) / 101.96
            
            # Activity coefficient for H2O in melt
            ln_gamma_H2O = 2.565 - 1.5 * SiO2_mol + 0.8 * Al2O3_mol
            gamma_H2O = np.exp(ln_gamma_H2O)
            
            # Pressure and temperature dependence
            ln_f_H2O = np.log(P_MPa) + (12000 / T_K) - 15.0
            f_H2O = np.exp(ln_f_H2O)  # Fugacity
            
            # Solubility with activity correction
            solubility = (f_H2O * 0.125) / gamma_H2O  # wt%
            
            return min(solubility, 8.0)  # Physical upper limit
            
        except Exception:
            return 3.0  # Fallback value
    
    def _calculate_co2_solubility_advanced(self, pressure, temperature, composition):
        """Advanced CO2 solubility with carbonate speciation"""
        try:
            T_K = temperature + 273.15
            P_MPa = pressure / 1e6
            
            # Papale et al. (2006) model
            # Account for melt polymerization
            NBO_T = self._calculate_nbo_t_ratio(composition)
            
            # CO2 speciation: molecular CO2 vs carbonate groups
            K_carbonate = np.exp(-10000 / T_K + 15.0)
            
            # Pressure-dependent solubility
            if P_MPa < 500:  # Low pressure - molecular CO2 dominates
                solubility = 0.0012 * P_MPa * (1 + 0.1 * NBO_T)
            else:  # High pressure - carbonate groups form
                solubility = 0.0012 * np.sqrt(P_MPa) * (1 + K_carbonate * NBO_T)
            
            return min(solubility, 2.0)  # Physical upper limit
            
        except Exception:
            return 0.1  # Fallback value
    
    def _calculate_so2_solubility_advanced(self, pressure, temperature, composition):
        """Advanced SO2 solubility with redox effects"""
        try:
            T_K = temperature + 273.15
            P_MPa = pressure / 1e6
            
            # Oxygen fugacity effects on sulfur speciation
            fO2 = self._estimate_oxygen_fugacity(temperature, composition)
            
            # S6+/S2- ratio (Jugo et al., 2010)
            log_sulfate_sulfide = -2.0 + 0.25 * np.log10(fO2)
            sulfate_fraction = 1.0 / (1.0 + 10**(-log_sulfate_sulfide))
            
            # Solubility depends on speciation
            sulfate_solubility = 0.2 * P_MPa**0.5  # Sulfate solubility
            sulfide_solubility = 0.05 * P_MPa**0.3  # Sulfide solubility
            
            total_s_solubility = (sulfate_fraction * sulfate_solubility + 
                                (1 - sulfate_fraction) * sulfide_solubility)
            
            return min(total_s_solubility, 1.0)
            
        except Exception:
            return 0.01  # Fallback value
    
    def _calculate_gas_transfer_rates(self, evolved_gases, temperature, pressure):
        """
        Advanced gas transfer rate calculation using multi-component diffusion,
        interfacial mass transfer, and thermodynamic driving forces
        """
        try:
            if self.advanced_thermodynamics_enabled and hasattr(self, 'thermodynamic_engine'):
                return self._calculate_advanced_gas_transfer_rates(evolved_gases, temperature, pressure)
            else:
                return self._calculate_fallback_gas_transfer_rates(evolved_gases, temperature, pressure)
        except Exception as e:
            print(f"Gas transfer calculation error: {e}")
            return self._calculate_fallback_gas_transfer_rates(evolved_gases, temperature, pressure)

    def _calculate_advanced_gas_transfer_rates(self, evolved_gases, temperature, pressure):
        """Advanced multi-component gas transfer with thermodynamic coupling"""
        T_K = temperature + 273.15
        P_Pa = pressure * 1e6  # Convert MPa to Pa
        transfer_rates = {}
        
        # Calculate melt properties
        melt_density = self._calculate_melt_density(temperature, pressure)
        melt_viscosity = self._calculate_melt_viscosity(temperature)
        
        # Multi-component diffusion matrix
        species_list = list(evolved_gases.keys())
        n_species = len(species_list)
        diffusion_matrix = np.zeros((n_species, n_species))
        
        # Build Maxwell-Stefan diffusion matrix
        for i, species_i in enumerate(species_list):
            for j, species_j in enumerate(species_list):
                if i == j:
                    # Self-diffusion coefficient
                    D_ii = self._get_multicomponent_diffusion_coefficient(species_i, temperature, pressure)
                    diffusion_matrix[i, j] = D_ii
                else:
                    # Binary diffusion coefficient
                    D_ij = self._get_binary_diffusion_coefficient(species_i, species_j, temperature)
                    diffusion_matrix[i, j] = -D_ij
        
        # Calculate chemical potential gradients
        chemical_gradients = self._calculate_chemical_potential_gradients(evolved_gases, temperature, pressure)
        
        for species, gas_data in evolved_gases.items():
            # Thermodynamic driving force
            supersaturation = max(0, gas_data.get('evolved', 0))
            equilibrium_conc = gas_data.get('equilibrium_concentration', 0)
            driving_force = supersaturation - equilibrium_conc
            
            if abs(driving_force) < 1e-10:
                transfer_rates[species] = 0.0
                continue
            
            # Mass transfer coefficient based on bubble dynamics
            bubble_radius = gas_data.get('bubble_radius', 1e-6)  # m
            reynolds_number = self._calculate_bubble_reynolds(bubble_radius, melt_viscosity, melt_density)
            schmidt_number = self._calculate_schmidt_number(species, melt_viscosity, melt_density)
            sherwood_number = self._calculate_sherwood_number(reynolds_number, schmidt_number)
            
            # Diffusion coefficient for this species
            D_species = self._get_multicomponent_diffusion_coefficient(species, temperature, pressure)
            
            # Mass transfer coefficient
            k_mass = sherwood_number * D_species / (2 * bubble_radius)
            
            # Interfacial area per unit volume
            gas_fraction = gas_data.get('gas_fraction', 0.01)
            specific_area = 3 * gas_fraction / bubble_radius  # m²/m³
            
            # Henry's law correction for solubility
            henry_constant = self._get_henry_constant(species, temperature)
            activity_coefficient = self._get_activity_coefficient(species, temperature, pressure)
            
            # Fugacity correction
            fugacity_coefficient = self._calculate_fugacity_coefficient(species, pressure, temperature)
            
            # Advanced mass transfer rate with thermodynamic corrections
            base_rate = k_mass * specific_area * driving_force * melt_density
            
            # Apply thermodynamic corrections
            thermodynamic_factor = activity_coefficient * fugacity_coefficient / henry_constant
            diffusion_enhancement = self._calculate_diffusion_enhancement(species, temperature, pressure)
            
            transfer_rate = base_rate * thermodynamic_factor * diffusion_enhancement
            
            # Apply interfacial resistance
            interfacial_resistance = self._calculate_interfacial_resistance(species, temperature)
            transfer_rate *= (1.0 / (1.0 + interfacial_resistance))
            
            # Temperature-dependent kinetic factor
            kinetic_factor = np.exp(-self._get_activation_energy(species) / (8.314 * T_K))
            transfer_rate *= kinetic_factor
            
            # Pressure-dependent volume correction
            molar_volume = self._get_molar_volume(species, temperature, pressure)
            pressure_factor = np.exp(molar_volume * P_Pa / (8.314 * T_K))
            transfer_rate *= pressure_factor
            
            transfer_rates[species] = max(0, transfer_rate)  # kg/m³/s
        
        return transfer_rates

    def _calculate_fallback_gas_transfer_rates(self, evolved_gases, temperature, pressure):
        """Fallback calculation for gas transfer rates"""
        T_K = temperature + 273.15
        transfer_rates = {}
        
        for species, gas_data in evolved_gases.items():
            # Diffusion coefficient (temperature-dependent)
            D0 = self._get_diffusion_coefficient(species)
            activation_energy = self._get_activation_energy(species)
            
            D = D0 * np.exp(-activation_energy / (8.314 * T_K))  # m²/s
            
            # Mass transfer rate (simplified)
            supersaturation = max(0, gas_data.get('evolved', 0))
            transfer_rate = D * supersaturation * 1000  # kg/m³/s
            
            transfer_rates[species] = transfer_rate
        
        return transfer_rates

    def _get_multicomponent_diffusion_coefficient(self, species, temperature, pressure):
        """Get multicomponent diffusion coefficient with pressure dependence"""
        T_K = temperature + 273.15
        P_GPa = pressure / 1000  # Convert MPa to GPa
        
        # Base diffusion coefficients at reference conditions (m²/s)
        base_coefficients = {
            'H2O': 1e-10,
            'CO2': 5e-11,
            'SO2': 3e-11,
            'H2S': 2e-11,
            'HCl': 1e-11,
            'HF': 8e-12
        }
        
        D0 = base_coefficients.get(species, 1e-11)
        
        # Temperature dependence (Arrhenius)
        activation_energy = self._get_activation_energy(species)
        temp_factor = np.exp(-activation_energy / (8.314 * T_K))
        
        # Pressure dependence
        activation_volume = self._get_activation_volume(species)  # m³/mol
        pressure_factor = np.exp(-activation_volume * pressure * 1e6 / (8.314 * T_K))
        
        return D0 * temp_factor * pressure_factor

    def _get_binary_diffusion_coefficient(self, species1, species2, temperature):
        """Calculate binary diffusion coefficient between two species"""
        # Simplified binary interaction
        D1 = self._get_multicomponent_diffusion_coefficient(species1, temperature, 0.1)
        D2 = self._get_multicomponent_diffusion_coefficient(species2, temperature, 0.1)
        
        # Geometric mean with interaction parameter
        interaction_factor = self._get_species_interaction_factor(species1, species2)
        return np.sqrt(D1 * D2) * interaction_factor

    def _get_species_interaction_factor(self, species1, species2):
        """Get interaction factor between two gas species"""
        # Interaction matrix based on molecular properties
        interactions = {
            ('H2O', 'CO2'): 0.8,
            ('H2O', 'SO2'): 0.9,
            ('CO2', 'SO2'): 0.7,
            ('H2S', 'SO2'): 0.6,
            ('HCl', 'HF'): 0.9
        }
        
        key = tuple(sorted([species1, species2]))
        return interactions.get(key, 0.5)

    def _calculate_chemical_potential_gradients(self, evolved_gases, temperature, pressure):
        """Calculate chemical potential gradients for multicomponent diffusion"""
        gradients = {}
        
        for species, gas_data in evolved_gases.items():
            concentration = gas_data.get('evolved', 0)
            activity_coeff = self._get_activity_coefficient(species, temperature, pressure)
            
            if concentration > 1e-10:
                # Chemical potential gradient (simplified)
                gradient = 8.314 * (temperature + 273.15) * activity_coeff / concentration
                gradients[species] = gradient
            else:
                gradients[species] = 0.0
        
        return gradients

    def _calculate_bubble_reynolds(self, bubble_radius, viscosity, density):
        """Calculate Reynolds number for bubble motion"""
        # Terminal velocity of rising bubble
        g = 9.81  # m/s²
        velocity = np.sqrt(2 * g * bubble_radius * density / (3 * viscosity))
        return 2 * bubble_radius * velocity * density / viscosity

    def _calculate_schmidt_number(self, species, viscosity, density):
        """Calculate Schmidt number for mass transfer"""
        diffusivity = self._get_multicomponent_diffusion_coefficient(species, 1000, 0.1)
        return viscosity / (density * diffusivity)

    def _calculate_sherwood_number(self, reynolds, schmidt):
        """Calculate Sherwood number for mass transfer"""
        # Correlation for spherical bubbles
        return 2 + 0.6 * (reynolds**0.5) * (schmidt**(1/3))

    def _calculate_diffusion_enhancement(self, species, temperature, pressure):
        """Calculate diffusion enhancement due to convective effects"""
        # Enhanced diffusion due to bubble-induced convection
        base_enhancement = 1.0
        
        # Temperature enhancement
        T_K = temperature + 273.15
        temp_enhancement = 1 + 0.1 * (T_K - 1273) / 1273  # Enhanced at higher T
        
        # Pressure enhancement (reduced at high pressure)
        pressure_factor = 1 / (1 + 0.01 * pressure)
        
        return base_enhancement * temp_enhancement * pressure_factor

    def _calculate_interfacial_resistance(self, species, temperature):
        """Calculate interfacial resistance to mass transfer"""
        # Species-dependent interfacial resistance
        resistances = {
            'H2O': 0.01,
            'CO2': 0.05,
            'SO2': 0.1,
            'H2S': 0.08,
            'HCl': 0.15,
            'HF': 0.12
        }
        
        base_resistance = resistances.get(species, 0.1)
        
        # Temperature dependence
        T_K = temperature + 273.15
        temp_factor = np.exp(-5000 / T_K)  # Reduced resistance at high T
        
        return base_resistance * temp_factor

    def _get_activation_volume(self, species):
        """Get activation volume for pressure-dependent diffusion"""
        volumes = {
            'H2O': 5e-6,   # m³/mol
            'CO2': 8e-6,
            'SO2': 12e-6,
            'H2S': 10e-6,
            'HCl': 6e-6,
            'HF': 4e-6
        }
        return volumes.get(species, 8e-6)
    
    def _calculate_bubble_dynamics(self, total_gas, pressure, temperature):
        """Calculate bubble nucleation and growth dynamics"""
        try:
            if total_gas < 0.01:  # Below nucleation threshold
                return {'bubble_fraction': 0.0, 'expansion_factor': 1.0}
            
            T_K = temperature + 273.15
            
            # Critical supersaturation for nucleation
            critical_supersaturation = 2.0 * 0.073 / (8.314 * T_K * 1e-6)  # Surface tension effect
            
            if total_gas > critical_supersaturation:
                # Bubble volume fraction (Proussevitch & Sahagian, 1998)
                gas_density = pressure / (8.314 * T_K) * 0.044  # kg/m³ (for CO2)
                melt_density = 2500 - 0.5 * temperature  # kg/m³
                
                bubble_fraction = (total_gas / 100) * melt_density / gas_density
                bubble_fraction = min(bubble_fraction, 0.8)  # Maximum packing
                
                # Volume expansion
                expansion_factor = 1.0 / (1.0 - bubble_fraction)
                
                return {
                    'bubble_fraction': bubble_fraction,
                    'expansion_factor': expansion_factor,
                    'critical_supersaturation': critical_supersaturation
                }
            
            return {'bubble_fraction': 0.0, 'expansion_factor': 1.0}
            
        except Exception:
            return {'bubble_fraction': 0.0, 'expansion_factor': 1.0}
    
    def _calculate_gas_mixture_density(self, evolved_gases, temperature, pressure):
        """Calculate density of gas mixture"""
        try:
            T_K = temperature + 273.15
            total_moles = 0
            total_mass = 0
            
            molecular_weights = {'H2O': 18.015, 'CO2': 44.009, 'SO2': 64.066, 
                               'H2S': 34.081, 'HCl': 36.458, 'HF': 20.006}
            
            for species, gas_data in evolved_gases.items():
                if species in molecular_weights:
                    mass = gas_data.get('evolved', 0.0)
                    mw = molecular_weights[species]
                    moles = mass / mw
                    total_moles += moles
                    total_mass += mass
            
            if total_moles > 0:
                # Ideal gas law with compressibility correction
                Z = 1.0 - 0.0001 * pressure  # Simple compressibility factor
                density = (pressure * total_mass) / (Z * 8.314 * T_K * total_moles)  # kg/m³
                return density
            
            return 1.0  # Default gas density
            
        except Exception:
            return 1.0
    
    def _calculate_fallback_gas_evolution(self, pressure, temperature, composition):
        """Fallback gas evolution calculation"""
        try:
            h2o_solubility = self.physics.gas_solubility(pressure, temperature, 'H2O')
            co2_solubility = self.physics.gas_solubility(pressure, temperature, 'CO2')
            
            h2o_content = getattr(composition, 'H2O', 0.0)
            co2_content = getattr(composition, 'CO2', 0.0)
            
            h2o_evolved = max(0, h2o_content - h2o_solubility)
            co2_evolved = max(0, co2_content - co2_solubility)
            
            total_gas = h2o_evolved + co2_evolved
            
            return {
                'total_evolved': total_gas,
                'total_dissolved': h2o_solubility + co2_solubility,
                'species_breakdown': {
                    'H2O': {'evolved': h2o_evolved, 'dissolved': min(h2o_content, h2o_solubility)},
                    'CO2': {'evolved': co2_evolved, 'dissolved': min(co2_content, co2_solubility)}
                }
            }
            
        except Exception:
            return {'total_evolved': 0.0, 'total_dissolved': 0.0}
    
    def calculate_crystallization(self, temperature, time, composition=None, pressure=None):
        """
        Advanced crystallization calculation using nucleation and growth kinetics
        """
        try:
            if self.advanced_thermodynamics_enabled and hasattr(self, 'thermodynamic_engine'):
                return self._calculate_advanced_crystallization(temperature, time, composition, pressure)
            else:
                return self._calculate_fallback_crystallization(temperature, time)
        except Exception as e:
            print(f"Crystallization calculation error: {e}")
            return self._calculate_fallback_crystallization(temperature, time)
    
    def _calculate_advanced_crystallization(self, temperature, time, composition, pressure):
        """Advanced crystallization with multicomponent phase equilibrium"""
        try:
            T_K = temperature + 273.15
            
            # Calculate liquidus temperatures for different phases
            liquidus_temps = self._calculate_liquidus_temperatures(composition, pressure)
            
            # Determine stable phases at current conditions
            stable_phases = []
            for phase, T_liq in liquidus_temps.items():
                if temperature < T_liq:
                    stable_phases.append(phase)
            
            if not stable_phases:
                return {
                    'total_crystallinity': 0.0,
                    'phase_assemblage': {},
                    'nucleation_rate': 0.0,
                    'growth_rate': 0.0
                }
            
            phase_crystallinity = {}
            total_crystallinity = 0.0
            
            for phase in stable_phases:
                # Calculate undercooling
                T_liq = liquidus_temps[phase]
                undercooling = T_liq - temperature
                
                if undercooling <= 0:
                    continue
                
                # Nucleation rate (Classical Nucleation Theory)
                nucleation_rate = self._calculate_nucleation_rate(phase, undercooling, temperature)
                
                # Growth rate (interface kinetics)
                growth_rate = self._calculate_crystal_growth_rate(phase, undercooling, temperature)
                
                # JMAK equation with nucleation and growth
                # Extended for continuous nucleation
                if nucleation_rate > 0 and growth_rate > 0:
                    # Characteristic time scales
                    tau_n = 1.0 / nucleation_rate  # Nucleation time
                    tau_g = 1.0 / growth_rate      # Growth time
                    
                    # Avrami-like equation with temperature-dependent parameters
                    n_avrami = self._get_avrami_exponent(phase)
                    k_effective = nucleation_rate * (growth_rate ** n_avrami)
                    
                    # Time-dependent crystallinity
                    if time > 0:
                        alpha = 1.0 - np.exp(-k_effective * time ** n_avrami)
                    else:
                        alpha = 0.0
                    
                    # Apply thermodynamic constraints
                    max_crystallinity = self._calculate_equilibrium_crystallinity(
                        phase, temperature, composition, pressure
                    )
                    
                    alpha = min(alpha, max_crystallinity)
                    
                    phase_crystallinity[phase] = {
                        'crystallinity': alpha * 100,  # Convert to percentage
                        'nucleation_rate': nucleation_rate,
                        'growth_rate': growth_rate,
                        'undercooling': undercooling,
                        'max_crystallinity': max_crystallinity * 100
                    }
                    
                    total_crystallinity += alpha
            
            # Apply crystallization interactions (impingement)
            if total_crystallinity > 1.0:
                # Renormalize to account for space limitations
                scaling_factor = 1.0 / total_crystallinity
                for phase in phase_crystallinity:
                    phase_crystallinity[phase]['crystallinity'] *= scaling_factor
                total_crystallinity = 1.0
            
            # Calculate textural parameters
            texture_params = self._calculate_crystal_texture_parameters(
                phase_crystallinity, temperature, time
            )
            
            # Calculate mechanical effects
            mechanical_effects = self._calculate_crystallization_mechanical_effects(
                total_crystallinity, phase_crystallinity
            )
            
            return {
                'total_crystallinity': total_crystallinity * 100,  # Percentage
                'phase_assemblage': phase_crystallinity,
                'texture_parameters': texture_params,
                'mechanical_effects': mechanical_effects,
                'liquidus_temperatures': liquidus_temps
            }
            
        except Exception as e:
            print(f"Advanced crystallization failed: {e}")
            return self._calculate_fallback_crystallization(temperature, time)
    
    def _calculate_liquidus_temperatures(self, composition, pressure):
        """Calculate liquidus temperatures for different mineral phases"""
        try:
            liquidus_temps = {}
            
            if composition is None:
                # Default basaltic composition
                liquidus_temps = {
                    'olivine': 1300,
                    'pyroxene': 1200,
                    'plagioclase': 1100,
                    'magnetite': 1000
                }
            else:
                # Calculate based on composition
                SiO2 = getattr(composition, 'SiO2', 50.0)
                MgO = getattr(composition, 'MgO', 8.0)
                CaO = getattr(composition, 'CaO', 10.0)
                Al2O3 = getattr(composition, 'Al2O3', 15.0)
                
                # Pressure effects (dT/dP)
                P_GPa = (pressure or 1e8) / 1e9
                
                # Olivine liquidus (Putirka, 2008)
                T_ol = 1780 - 4.0 * SiO2 + 8.0 * MgO + 5.0 * P_GPa
                
                # Pyroxene liquidus
                T_px = 1650 - 2.0 * SiO2 + 3.0 * MgO + 2.0 * CaO + 8.0 * P_GPa
                
                # Plagioclase liquidus
                T_pl = 1550 - 1.5 * SiO2 + 5.0 * Al2O3 + 2.0 * CaO + 3.0 * P_GPa
                
                # Magnetite liquidus
                T_mt = 1400 - 0.5 * SiO2 + 2.0 * P_GPa
                
                liquidus_temps = {
                    'olivine': T_ol,
                    'pyroxene': T_px,
                    'plagioclase': T_pl,
                    'magnetite': T_mt
                }
            
            return liquidus_temps
            
        except Exception:
            return {'olivine': 1300, 'pyroxene': 1200, 'plagioclase': 1100}
    
    def _calculate_nucleation_rate(self, phase, undercooling, temperature):
        """Calculate nucleation rate using Classical Nucleation Theory"""
        try:
            T_K = temperature + 273.15
            
            # Phase-specific parameters
            nucleation_params = {
                'olivine': {'sigma': 0.3, 'A': 1e6},    # Surface energy, pre-exponential
                'pyroxene': {'sigma': 0.4, 'A': 5e5},
                'plagioclase': {'sigma': 0.5, 'A': 1e5},
                'magnetite': {'sigma': 0.2, 'A': 1e7}
            }
            
            params = nucleation_params.get(phase, {'sigma': 0.3, 'A': 1e6})
            
            # Critical nucleus size
            # ΔG* = 16πσ³/(3(ΔGv)²)
            delta_Gv = 1000 * undercooling / T_K  # Volumetric free energy change
            
            if delta_Gv <= 0:
                return 0.0
            
            delta_G_critical = (16 * np.pi * params['sigma']**3) / (3 * delta_Gv**2)
            
            # Nucleation rate
            I = params['A'] * np.exp(-delta_G_critical / (1.38e-23 * T_K))  # nuclei/m³/s
            
            return min(I, 1e12)  # Reasonable upper limit
            
        except Exception:
            return 0.0
    
    def _calculate_crystal_growth_rate(self, phase, undercooling, temperature):
        """Calculate crystal growth rate"""
        try:
            T_K = temperature + 273.15
            
            # Growth kinetics parameters
            growth_params = {
                'olivine': {'Q': 300000, 'k0': 1e-6},   # Activation energy, pre-exponential
                'pyroxene': {'Q': 350000, 'k0': 5e-7},
                'plagioclase': {'Q': 400000, 'k0': 1e-7},
                'magnetite': {'Q': 250000, 'k0': 1e-5}
            }
            
            params = growth_params.get(phase, {'Q': 300000, 'k0': 1e-6})
            
            # Interface kinetics model
            # G = k0 * exp(-Q/RT) * (1 - exp(-ΔG/RT))
            R = 8.314
            delta_G = 1000 * undercooling / T_K
            
            kinetic_term = params['k0'] * np.exp(-params['Q'] / (R * T_K))
            driving_force = 1.0 - np.exp(-delta_G / (R * T_K)) if delta_G > 0 else 0.0
            
            growth_rate = kinetic_term * driving_force  # m/s
            
            return min(growth_rate, 1e-6)  # Reasonable upper limit
            
        except Exception:
            return 0.0
    
    def _get_avrami_exponent(self, phase):
        """Get Avrami exponent for different phases"""
        avrami_exponents = {
            'olivine': 1.5,      # 3D growth from surfaces
            'pyroxene': 2.0,     # 2D growth
            'plagioclase': 2.5,  # Complex growth
            'magnetite': 1.0     # 1D growth
        }
        return avrami_exponents.get(phase, 2.0)
    
    def _calculate_equilibrium_crystallinity(self, phase, temperature, composition, pressure):
        """Calculate equilibrium crystallinity for a phase"""
        try:
            # Use lever rule approximation
            liquidus_temps = self._calculate_liquidus_temperatures(composition, pressure)
            T_liq = liquidus_temps.get(phase, 1200)
            
            # Solidus temperature (approximate)
            T_sol = T_liq - 200  # Typical crystallization interval
            
            if temperature >= T_liq:
                return 0.0
            elif temperature <= T_sol:
                return 1.0
            else:
                # Linear approximation (could be improved with MELTS)
                return (T_liq - temperature) / (T_liq - T_sol)
                
        except Exception:
            return 0.5
    
    def _calculate_crystal_texture_parameters(self, phase_crystallinity, temperature, time):
        """Calculate crystal texture parameters"""
        try:
            total_crystals = sum(phase['crystallinity'] for phase in phase_crystallinity.values())
            
            if total_crystals == 0:
                return {'crystal_size': 0.0, 'aspect_ratio': 1.0, 'orientation': 'random'}
            
            # Average crystal size (CSD - Crystal Size Distribution)
            # Size depends on nucleation vs growth rates
            avg_nucleation = np.mean([phase['nucleation_rate'] for phase in phase_crystallinity.values()])
            avg_growth = np.mean([phase['growth_rate'] for phase in phase_crystallinity.values()])
            
            if avg_nucleation > 0:
                characteristic_size = avg_growth / avg_nucleation * time  # m
                characteristic_size = min(characteristic_size * 1e6, 1000)  # Convert to μm, max 1mm
            else:
                characteristic_size = 0.0
            
            # Aspect ratio (depends on growth anisotropy)
            aspect_ratio = 1.0 + 0.5 * (1000 - temperature) / 1000  # Higher at lower T
            
            return {
                'crystal_size': characteristic_size,  # μm
                'aspect_ratio': aspect_ratio,
                'orientation': 'random' if temperature > 900 else 'preferred'
            }
            
        except Exception:
            return {'crystal_size': 0.0, 'aspect_ratio': 1.0, 'orientation': 'random'}
    
    def _calculate_crystallization_mechanical_effects(self, total_crystallinity, phase_crystallinity):
        """Calculate mechanical effects of crystallization"""
        try:
            # Viscosity increase with crystallinity
            phi = total_crystallinity / 100  # Volume fraction
            
            if phi < 0.6:  # Below maximum packing
                # Einstein-Roscoe equation
                relative_viscosity = (1 - phi / 0.6) ** (-2.5)
            else:
                relative_viscosity = 1e6  # Essentially solid
            
            # Yield strength development
            yield_strength = phi * 1e6  # Pa (simple approximation)
            
            # Thermal conductivity change
            # Crystals have higher conductivity than melt
            k_melt = 1.5  # W/m/K
            k_crystal = 3.0  # W/m/K
            effective_conductivity = k_melt * (1 - phi) + k_crystal * phi
            
            return {
                'relative_viscosity': relative_viscosity,
                'yield_strength': yield_strength,
                'thermal_conductivity': effective_conductivity,
                'crystal_volume_fraction': phi
            }
            
        except Exception:
            return {'relative_viscosity': 1.0, 'yield_strength': 0.0}
    
    def _calculate_fallback_crystallization(self, temperature, time):
        """Fallback crystallization calculation"""
        T_liquidus = 1200  # °C
        
        if temperature < T_liquidus:
            k = 0.001
            n = 2
            crystal_fraction = 1 - np.exp(-k * time ** n)
            return min(crystal_fraction * 100, 50)
        return 0
    
    def calculate_flow_rates(self, pressure, connections, chambers, temperature=None, composition=None):
        """
        Advanced flow rate calculation with viscosity, compressibility, and non-Newtonian effects
        """
        try:
            if self.advanced_thermodynamics_enabled and hasattr(self, 'thermodynamic_engine'):
                return self._calculate_advanced_flow_rates(pressure, connections, chambers, temperature, composition)
            else:
                return self._calculate_fallback_flow_rates(pressure, connections, chambers)
        except Exception as e:
            print(f"Flow rate calculation error: {e}")
            return self._calculate_fallback_flow_rates(pressure, connections, chambers)
    
    def _calculate_advanced_flow_rates(self, pressure, connections, chambers, temperature, composition):
        """Advanced flow calculation with complex rheology"""
        try:
            num_steps = pressure.shape[0]
            flow_rates = np.zeros((num_steps, len(connections)))
            flow_details = []
            
            for t in range(num_steps):
                timestep_details = []
                
                for i, connection in enumerate(connections):
                    try:
                        # Get chamber indices
                        from_idx = next(j for j, c in enumerate(chambers) 
                                      if c.id == connection.from_chamber)
                        to_idx = next(j for j, c in enumerate(chambers) 
                                    if c.id == connection.to_chamber)
                        
                        # Pressure difference
                        P1 = pressure[t, from_idx]
                        P2 = pressure[t, to_idx]
                        pressure_diff = P1 - P2
                        
                        if abs(pressure_diff) < 1e3:  # Negligible pressure difference
                            flow_rates[t, i] = 0.0
                            continue
                        
                        # Get temperatures and compositions for each chamber
                        T1 = temperature[t, from_idx] if temperature is not None else 1000
                        T2 = temperature[t, to_idx] if temperature is not None else 1000
                        T_avg = (T1 + T2) / 2
                        
                        # Calculate dynamic viscosity
                        viscosity = self._calculate_dynamic_viscosity(T_avg, P1, composition)
                        
                        # Calculate density
                        density = self._calculate_melt_density(T_avg, P1, composition)
                        
                        # Flow geometry parameters
                        conduit_params = self._get_conduit_parameters(connection)
                        
                        # Determine flow regime
                        flow_regime = self._determine_flow_regime(
                            pressure_diff, viscosity, density, conduit_params
                        )
                        
                        if flow_regime == 'laminar':
                            flow_rate = self._calculate_laminar_flow(
                                pressure_diff, viscosity, density, conduit_params
                            )
                        elif flow_regime == 'turbulent':
                            flow_rate = self._calculate_turbulent_flow(
                                pressure_diff, viscosity, density, conduit_params
                            )
                        else:  # Non-Newtonian
                            flow_rate = self._calculate_non_newtonian_flow(
                                pressure_diff, viscosity, density, conduit_params, T_avg
                            )
                        
                        # Apply compressibility effects
                        flow_rate = self._apply_compressibility_correction(
                            flow_rate, P1, P2, T_avg
                        )
                        
                        # Apply multiphase flow corrections
                        if hasattr(composition, 'gas_fraction') and composition.gas_fraction > 0:
                            flow_rate = self._apply_multiphase_correction(
                                flow_rate, composition.gas_fraction, pressure_diff
                            )
                        
                        # Store flow rate with sign convention
                        flow_rates[t, i] = flow_rate if pressure_diff > 0 else -flow_rate
                        
                        # Store detailed information
                        timestep_details.append({
                            'connection_id': i,
                            'pressure_diff': pressure_diff,
                            'viscosity': viscosity,
                            'density': density,
                            'flow_regime': flow_regime,
                            'reynolds_number': self._calculate_reynolds_number(
                                flow_rate, density, viscosity, conduit_params
                            )
                        })
                        
                    except Exception as conn_error:
                        print(f"Connection {i} flow calculation error: {conn_error}")
                        flow_rates[t, i] = 0.0
                
                flow_details.append(timestep_details)
            
            return {
                'flow_rates': flow_rates,
                'flow_details': flow_details,
                'mass_conservation': self._check_mass_conservation(flow_rates, connections)
            }
            
        except Exception as e:
            print(f"Advanced flow calculation failed: {e}")
            return self._calculate_fallback_flow_rates(pressure, connections, chambers)
    
    def _calculate_dynamic_viscosity(self, temperature, pressure, composition):
        """Calculate temperature and composition-dependent viscosity"""
        try:
            T_K = temperature + 273.15
            
            if composition is None:
                # Default basaltic melt viscosity (Giordano et al., 2008)
                A = -4.55
                B = 9633
                C = 0.0
                log_eta = A + B / T_K + C
                return 10 ** log_eta  # Pa·s
            
            # Get melt composition in oxide wt%
            SiO2 = getattr(composition, 'SiO2', 50.0)
            Al2O3 = getattr(composition, 'Al2O3', 15.0)
            FeO = getattr(composition, 'FeO', 10.0)
            MgO = getattr(composition, 'MgO', 8.0)
            CaO = getattr(composition, 'CaO', 10.0)
            Na2O = getattr(composition, 'Na2O', 3.0)
            K2O = getattr(composition, 'K2O', 1.0)
            H2O = getattr(composition, 'H2O', 0.0)
            
            # Giordano et al. (2008) model
            # Calculate silicate melt structure parameter
            smc = SiO2 + Al2O3 + FeO + MgO + CaO + Na2O + K2O
            nbo_t = (2 * (FeO + MgO + CaO + Na2O + K2O) - Al2O3) / (SiO2 + Al2O3)
            
            # VFT equation parameters
            A = -4.55
            B = 9633 + 1.5 * SiO2 - 2.0 * Al2O3
            C = 315 - 12.0 * np.log(1 + H2O)
            
            # Temperature dependence
            log_eta = A + B / (T_K - C)
            
            # Pressure correction (simple)
            P_GPa = pressure / 1e9
            log_eta += 0.1 * P_GPa  # Pressure increases viscosity
            
            viscosity = 10 ** log_eta  # Pa·s
            
            # Apply bounds
            return max(min(viscosity, 1e15), 1e-3)  # Reasonable limits
            
        except Exception:
            return 1000  # Default viscosity for basaltic melt
    
    def _calculate_melt_density(self, temperature, pressure, composition):
        """Calculate melt density"""
        try:
            if composition is None:
                # Default basaltic density with T,P dependence
                rho_0 = 2650  # kg/m³ at reference conditions
                alpha = 3e-4  # Thermal expansion coefficient
                beta = 1e-10  # Compressibility
                
                T_ref = 1200  # °C
                P_ref = 1e5   # Pa
                
                density = rho_0 * (1 - alpha * (temperature - T_ref)) * (1 + beta * (pressure - P_ref))
                return max(density, 1000)  # Minimum density
            
            # Composition-dependent density (Bottinga & Weill, 1970)
            # Partial molar volumes of components
            partial_volumes = {
                'SiO2': 26.86, 'Al2O3': 37.42, 'FeO': 13.65,
                'MgO': 11.69, 'CaO': 16.53, 'Na2O': 28.88,
                'K2O': 45.07, 'H2O': 22.0
            }
            
            # Calculate molar volume
            total_moles = 0
            molar_volume = 0
            
            for oxide, volume in partial_volumes.items():
                if hasattr(composition, oxide):
                    wt_percent = getattr(composition, oxide)
                    # Convert to moles (simplified)
                    moles = wt_percent / 60  # Average molecular weight
                    total_moles += moles
                    molar_volume += moles * volume
            
            if total_moles > 0:
                avg_molar_volume = molar_volume / total_moles  # cm³/mol
                
                # Temperature and pressure corrections
                T_K = temperature + 273.15
                dV_dT = 0.001  # cm³/mol/K
                dV_dP = -1e-5  # cm³/mol/Pa
                
                corrected_volume = avg_molar_volume + dV_dT * (T_K - 1473) + dV_dP * (pressure - 1e5)
                
                # Convert to density (approximate)
                density = 60 / (corrected_volume * 1e-6)  # kg/m³
                return max(density, 1000)
            
            return 2500  # Default density
            
        except Exception:
            return 2500
    
    def _get_conduit_parameters(self, connection):
        """Get geometric parameters of the conduit"""
        try:
            # Default parameters if not specified
            diameter = getattr(connection, 'diameter', 10.0)  # m
            length = getattr(connection, 'length', 1000.0)    # m
            roughness = getattr(connection, 'roughness', 1e-3) # m
            
            area = np.pi * (diameter / 2) ** 2
            perimeter = np.pi * diameter
            hydraulic_diameter = 4 * area / perimeter
            
            return {
                'diameter': diameter,
                'length': length,
                'area': area,
                'hydraulic_diameter': hydraulic_diameter,
                'roughness': roughness
            }
            
        except Exception:
            return {
                'diameter': 10.0,
                'length': 1000.0,
                'area': 78.54,
                'hydraulic_diameter': 10.0,
                'roughness': 1e-3
            }
    
    def _determine_flow_regime(self, pressure_diff, viscosity, density, conduit_params):
        """Determine flow regime (laminar, turbulent, non-Newtonian)"""
        try:
            # Estimate velocity from pressure gradient
            dP_dx = pressure_diff / conduit_params['length']
            
            # Hagen-Poiseuille estimate for velocity
            velocity = (dP_dx * conduit_params['diameter']**2) / (32 * viscosity)
            
            # Reynolds number
            Re = (density * abs(velocity) * conduit_params['hydraulic_diameter']) / viscosity
            
            # Critical Reynolds numbers
            Re_critical = 2300  # Transition to turbulence
            
            if Re < Re_critical:
                return 'laminar'
            elif viscosity > 1e6:  # High viscosity - likely non-Newtonian
                return 'non_newtonian'
            else:
                return 'turbulent'
                
        except Exception:
            return 'laminar'  # Default assumption
    
    def _calculate_laminar_flow(self, pressure_diff, viscosity, density, conduit_params):
        """Calculate laminar flow rate using Hagen-Poiseuille equation"""
        try:
            # Hagen-Poiseuille equation for circular pipe
            # Q = (π * r^4 * ΔP) / (8 * μ * L)
            radius = conduit_params['diameter'] / 2
            length = conduit_params['length']
            
            volumetric_flow = (np.pi * radius**4 * pressure_diff) / (8 * viscosity * length)
            
            # Convert to mass flow rate
            mass_flow = volumetric_flow * density  # kg/s
            
            return mass_flow
            
        except Exception:
            return 0.0
    
    def _calculate_turbulent_flow(self, pressure_diff, viscosity, density, conduit_params):
        """Calculate turbulent flow rate using Darcy-Weisbach equation"""
        try:
            # Iterative solution for turbulent flow
            diameter = conduit_params['diameter']
            length = conduit_params['length']
            roughness = conduit_params['roughness']
            
            # Initial guess for velocity
            velocity = np.sqrt(2 * pressure_diff / density)
            
            # Iterative solution
            for _ in range(10):
                Re = (density * velocity * diameter) / viscosity
                
                # Colebrook equation for friction factor
                f = self._calculate_friction_factor(Re, roughness / diameter)
                
                # Update velocity
                velocity_new = np.sqrt(2 * pressure_diff / (density * f * length / diameter))
                
                if abs(velocity_new - velocity) / velocity < 0.01:
                    break
                velocity = velocity_new
            
            volumetric_flow = velocity * conduit_params['area']
            mass_flow = volumetric_flow * density
            
            return mass_flow
            
        except Exception:
            return 0.0
    
    def _calculate_non_newtonian_flow(self, pressure_diff, viscosity, density, conduit_params, temperature):
        """Calculate non-Newtonian flow for high-viscosity melts"""
        try:
            # Power-law model for shear-thinning behavior
            # τ = K * (γ̇)^n where n < 1 for shear thinning
            
            # Estimate shear thinning parameters
            n = 0.8 - 0.0001 * (temperature - 1000)  # Temperature-dependent
            n = max(n, 0.3)  # Lower bound
            
            K = viscosity * (1 ** (1 - n))  # Consistency index
            
            # Modified Hagen-Poiseuille for power-law fluids
            radius = conduit_params['diameter'] / 2
            length = conduit_params['length']
            
            # Shear rate at wall
            gamma_dot_wall = (8 * pressure_diff * radius) / (K * length * (3 * n + 1) / n)
            gamma_dot_wall = gamma_dot_wall ** (1 / n)
            
            # Volumetric flow rate
            volumetric_flow = (np.pi * radius**3 * gamma_dot_wall) / (3 * n + 1)
            
            mass_flow = volumetric_flow * density
            
            return mass_flow
            
        except Exception:
            return 0.0
    
    def _calculate_friction_factor(self, reynolds, relative_roughness):
        """Calculate friction factor using Colebrook equation"""
        try:
            if reynolds < 2300:  # Laminar
                return 64 / reynolds
            
            # Colebrook equation (iterative solution)
            f = 0.02  # Initial guess
            
            for _ in range(10):
                f_new = 1 / (-2 * np.log10(relative_roughness / 3.7 + 2.51 / (reynolds * np.sqrt(f))))**2
                
                if abs(f_new - f) / f < 0.001:
                    break
                f = f_new
            
            return f
            
        except Exception:
            return 0.02  # Default value
    
    def _apply_compressibility_correction(self, flow_rate, P1, P2, temperature):
        """Apply compressibility correction for flow"""
        try:
            # For liquids, compressibility is small but not negligible
            T_K = temperature + 273.15
            
            # Bulk modulus (pressure dependence of density)
            K_bulk = 10e9 + 1e6 * (temperature - 1000)  # Pa
            
            # Average pressure
            P_avg = (P1 + P2) / 2
            
            # Compressibility factor
            beta = 1 / K_bulk
            
            # Density ratio
            rho_ratio = 1 + beta * (P1 - P2) / 2
            
            return flow_rate * rho_ratio
            
        except Exception:
            return flow_rate
    
    def _apply_multiphase_correction(self, flow_rate, gas_fraction, pressure_diff, temperature=1200, conduit_params=None):
        """
        Advanced multiphase flow correction using drift-flux models, 
        flow regime maps, and thermodynamic coupling
        """
        try:
            if self.advanced_thermodynamics_enabled and hasattr(self, 'thermodynamic_engine'):
                return self._calculate_advanced_multiphase_flow(flow_rate, gas_fraction, pressure_diff, temperature, conduit_params)
            else:
                return self._calculate_fallback_multiphase_flow(flow_rate, gas_fraction, pressure_diff)
        except Exception as e:
            print(f"Multiphase flow calculation error: {e}")
            return self._calculate_fallback_multiphase_flow(flow_rate, gas_fraction, pressure_diff)

    def _calculate_advanced_multiphase_flow(self, flow_rate, gas_fraction, pressure_diff, temperature, conduit_params):
        """Advanced multiphase flow with regime-dependent models"""
        if gas_fraction <= 0:
            return flow_rate
        
        # Ensure conduit parameters
        if conduit_params is None:
            conduit_params = {'diameter': 1.0, 'area': 0.785, 'hydraulic_diameter': 1.0}
        
        alpha_g = min(gas_fraction, 0.95)  # Gas volume fraction
        alpha_l = 1 - alpha_g  # Liquid volume fraction
        
        # Calculate fluid properties
        melt_density = self._calculate_melt_density(temperature, pressure_diff/10)  # Approximate pressure
        gas_density = self._calculate_gas_density(temperature, pressure_diff/10)
        melt_viscosity = self._calculate_melt_viscosity(temperature)
        gas_viscosity = self._calculate_gas_viscosity(temperature)
        
        # Surface tension for interfacial effects
        surface_tension = self._calculate_surface_tension(temperature)
        
        # Determine flow regime using flow regime map
        flow_regime = self._determine_flow_regime(flow_rate, alpha_g, melt_density, gas_density, 
                                                 melt_viscosity, gas_viscosity, conduit_params, surface_tension)
        
        # Apply regime-specific correction
        if flow_regime == 'bubbly':
            correction_factor = self._calculate_bubbly_flow_correction(alpha_g, melt_density, gas_density, 
                                                                     melt_viscosity, surface_tension, conduit_params)
        elif flow_regime == 'slug':
            correction_factor = self._calculate_slug_flow_correction(alpha_g, melt_density, gas_density, 
                                                                   melt_viscosity, conduit_params)
        elif flow_regime == 'churn':
            correction_factor = self._calculate_churn_flow_correction(alpha_g, melt_density, gas_density, 
                                                                    melt_viscosity, gas_viscosity, conduit_params)
        elif flow_regime == 'annular':
            correction_factor = self._calculate_annular_flow_correction(alpha_g, melt_density, gas_density, 
                                                                      melt_viscosity, gas_viscosity, surface_tension, conduit_params)
        else:  # dispersed or unknown
            correction_factor = self._calculate_dispersed_flow_correction(alpha_g, melt_density, gas_density, 
                                                                        melt_viscosity, gas_viscosity)
        
        # Apply thermodynamic corrections
        thermodynamic_factor = self._calculate_thermodynamic_flow_correction(alpha_g, temperature, pressure_diff)
        
        # Apply compressibility effects
        compressibility_factor = self._calculate_compressibility_correction(alpha_g, pressure_diff, temperature)
        
        # Apply acceleration pressure drop correction
        acceleration_factor = self._calculate_acceleration_correction(flow_rate, alpha_g, melt_density, gas_density, conduit_params)
        
        # Combined correction
        total_correction = correction_factor * thermodynamic_factor * compressibility_factor * acceleration_factor
        
        return flow_rate * total_correction

    def _calculate_fallback_multiphase_flow(self, flow_rate, gas_fraction, pressure_diff):
        """Fallback multiphase flow calculation"""
        if gas_fraction <= 0:
            return flow_rate
        
        # Homogeneous flow model (simplified)
        alpha_g = min(gas_fraction, 0.8)  # Gas volume fraction
        
        # Density reduction
        density_multiplier = 1 - 0.8 * alpha_g
        
        # Viscosity reduction (gas reduces effective viscosity)
        viscosity_multiplier = (1 - alpha_g)**2.5
        
        # Combined effect on flow rate
        correction_factor = density_multiplier / viscosity_multiplier
        
        return flow_rate * correction_factor

    def _determine_flow_regime(self, flow_rate, alpha_g, rho_l, rho_g, mu_l, mu_g, conduit_params, sigma):
        """Determine two-phase flow regime using flow regime maps"""
        # Calculate superficial velocities
        area = conduit_params.get('area', 0.785)
        j_g = alpha_g * abs(flow_rate) / (rho_g * area)  # Gas superficial velocity
        j_l = (1 - alpha_g) * abs(flow_rate) / (rho_l * area)  # Liquid superficial velocity
        
        # Dimensionless numbers for regime determination
        diameter = conduit_params.get('diameter', 1.0)
        g = 9.81  # gravity
        
        # Froude numbers
        Fr_g = j_g / np.sqrt(g * diameter)
        Fr_l = j_l / np.sqrt(g * diameter)
        
        # Weber number
        We_g = rho_g * j_g**2 * diameter / sigma
        
        # Reynolds numbers
        Re_g = rho_g * j_g * diameter / mu_g
        Re_l = rho_l * j_l * diameter / mu_l
        
        # Advanced flow regime determination using multiple criteria and transition analysis
        return self._advanced_flow_regime_classification(alpha_g, j_g, j_l, Fr_g, Fr_l, We_g, Re_g, Re_l, 
                                                       rho_l, rho_g, mu_l, mu_g, sigma, diameter)

    def _advanced_flow_regime_classification(self, alpha_g, j_g, j_l, Fr_g, Fr_l, We_g, Re_g, Re_l, 
                                           rho_l, rho_g, mu_l, mu_g, sigma, diameter):
        """
        Advanced flow regime classification using multiple flow regime maps,
        machine learning features, and volcanic-specific criteria
        """
        # Calculate additional dimensionless numbers
        dimensionless_numbers = self._calculate_extended_dimensionless_numbers(
            alpha_g, j_g, j_l, Fr_g, Fr_l, We_g, Re_g, Re_l, rho_l, rho_g, mu_l, mu_g, sigma, diameter)
        
        # Multi-criteria regime determination
        regime_scores = self._calculate_regime_probabilities(dimensionless_numbers)
        
        # Apply volcanic-specific corrections
        volcanic_corrections = self._apply_volcanic_flow_corrections(dimensionless_numbers)
        
        # Combine scores with corrections
        final_scores = {}
        for regime in regime_scores:
            final_scores[regime] = regime_scores[regime] * volcanic_corrections.get(regime, 1.0)
        
        # Check for transition zones
        transition_regime = self._check_flow_regime_transitions(dimensionless_numbers, final_scores)
        if transition_regime:
            return transition_regime
        
        # Return regime with highest probability
        best_regime = max(final_scores, key=final_scores.get)
        
        # Validate regime consistency
        validated_regime = self._validate_regime_consistency(best_regime, dimensionless_numbers)
        
        return validated_regime

    def _calculate_extended_dimensionless_numbers(self, alpha_g, j_g, j_l, Fr_g, Fr_l, We_g, Re_g, Re_l, 
                                                rho_l, rho_g, mu_l, mu_g, sigma, diameter):
        """Calculate extended set of dimensionless numbers for regime classification"""
        g = 9.81
        
        # Basic numbers (already calculated)
        numbers = {
            'alpha_g': alpha_g,
            'j_g': j_g,
            'j_l': j_l,
            'Fr_g': Fr_g,
            'Fr_l': Fr_l,
            'We_g': We_g,
            'Re_g': Re_g,
            'Re_l': Re_l
        }
        
        # Additional dimensionless numbers
        
        # Morton number
        numbers['Mo'] = g * mu_l**4 * (rho_l - rho_g) / (rho_l**2 * sigma**3)
        
        # Eötvös number
        numbers['Eo'] = g * (rho_l - rho_g) * diameter**2 / sigma
        
        # Capillary number
        numbers['Ca_g'] = mu_g * j_g / sigma
        numbers['Ca_l'] = mu_l * j_l / sigma
        
        # Bond number (same as Eötvös for spherical bubbles)
        numbers['Bo'] = numbers['Eo']
        
        # Viscosity ratio
        numbers['mu_ratio'] = mu_g / mu_l
        
        # Density ratio
        numbers['rho_ratio'] = rho_g / rho_l
        
        # Superficial velocity ratio
        numbers['j_ratio'] = j_g / max(j_l, 1e-10)
        
        # Modified Weber number (liquid-based)
        numbers['We_l'] = rho_l * j_l**2 * diameter / sigma
        
        # Modified Froude number (mixture)
        j_mix = j_g + j_l
        numbers['Fr_mix'] = j_mix / np.sqrt(g * diameter)
        
        # Kutateladze number for gas
        numbers['Ku_g'] = j_g * (rho_g / (g * sigma * (rho_l - rho_g)))**0.25
        
        # Kutateladze number for liquid
        numbers['Ku_l'] = j_l * (rho_l / (g * sigma * (rho_l - rho_g)))**0.25
        
        # Lockhart-Martinelli parameter
        if j_l > 1e-10 and j_g > 1e-10:
            numbers['X_tt'] = (j_l / j_g)**0.9 * (rho_g / rho_l)**0.5 * (mu_l / mu_g)**0.1
        else:
            numbers['X_tt'] = 1.0
        
        # Suratman number (Laplace number)
        numbers['La'] = sigma * rho_l * diameter / (mu_l**2)
        
        # Galileo number
        numbers['Ga'] = g * diameter**3 * rho_l * (rho_l - rho_g) / (mu_l**2)
        
        # Drift velocity parameter
        if j_mix > 1e-10:
            numbers['C0'] = (alpha_g * j_g + (1 - alpha_g) * j_l) / j_mix
        else:
            numbers['C0'] = 1.0
        
        return numbers

    def _calculate_regime_probabilities(self, numbers):
        """Calculate probability scores for each flow regime using multiple criteria"""
        scores = {}
        
        # Bubbly flow criteria
        scores['bubbly'] = self._calculate_bubbly_score(numbers)
        
        # Slug flow criteria  
        scores['slug'] = self._calculate_slug_score(numbers)
        
        # Churn flow criteria
        scores['churn'] = self._calculate_churn_score(numbers)
        
        # Annular flow criteria
        scores['annular'] = self._calculate_annular_score(numbers)
        
        # Dispersed flow criteria
        scores['dispersed'] = self._calculate_dispersed_score(numbers)
        
        # Stratified flow criteria (for horizontal/inclined pipes)
        scores['stratified'] = self._calculate_stratified_score(numbers)
        
        # Wispy-annular (high gas velocity annular)
        scores['wispy_annular'] = self._calculate_wispy_annular_score(numbers)
        
        return scores

    def _calculate_bubbly_score(self, numbers):
        """Calculate bubbly flow regime score"""
        score = 1.0
        
        # Low gas fraction favors bubbly
        if numbers['alpha_g'] < 0.15:
            score *= 2.0
        elif numbers['alpha_g'] > 0.3:
            score *= 0.1
        
        # Low gas superficial velocity
        if numbers['j_g'] < 1.0:
            score *= 1.5
        elif numbers['j_g'] > 5.0:
            score *= 0.2
        
        # High liquid Reynolds number supports bubbly
        if numbers['Re_l'] > 10000:
            score *= 1.3
        
        # Morton number effects
        if numbers['Mo'] < 1e-4:
            score *= 1.2
        
        # Weber number constraints
        if numbers['We_g'] < 50:
            score *= 1.4
        
        return min(score, 5.0)

    def _calculate_slug_score(self, numbers):
        """Calculate slug flow regime score"""
        score = 1.0
        
        # Intermediate gas fraction
        if 0.1 < numbers['alpha_g'] < 0.4:
            score *= 2.0
        elif numbers['alpha_g'] > 0.6:
            score *= 0.1
        
        # Moderate gas velocities
        if 0.5 < numbers['j_g'] < 8.0:
            score *= 1.5
        
        # Froude number criteria for slug formation
        if 0.1 < numbers['Fr_g'] < 2.0:
            score *= 1.3
        
        # Lockhart-Martinelli parameter
        if 0.1 < numbers['X_tt'] < 10:
            score *= 1.2
        
        # Kutateladze number constraints
        if numbers['Ku_g'] < 3.0 and numbers['Ku_l'] < 0.5:
            score *= 1.4
        
        return min(score, 5.0)

    def _calculate_churn_score(self, numbers):
        """Calculate churn flow regime score"""
        score = 1.0
        
        # Intermediate to high gas fraction
        if 0.2 < numbers['alpha_g'] < 0.8:
            score *= 1.8
        
        # High gas velocities
        if numbers['j_g'] > 3.0:
            score *= 1.5
        
        # High Froude numbers indicate turbulent flow
        if numbers['Fr_g'] > 1.0:
            score *= 1.4
        
        # High Weber numbers
        if numbers['We_g'] > 100:
            score *= 1.3
        
        # Reynolds number effects
        if numbers['Re_g'] > 50000:
            score *= 1.2
        
        # Transition from slug conditions
        if numbers['Ku_g'] > 2.0:
            score *= 1.3
        
        return min(score, 5.0)

    def _calculate_annular_score(self, numbers):
        """Calculate annular flow regime score"""
        score = 1.0
        
        # High gas fraction
        if numbers['alpha_g'] > 0.6:
            score *= 2.0
        elif numbers['alpha_g'] < 0.3:
            score *= 0.1
        
        # Very high gas velocities
        if numbers['j_g'] > 10.0:
            score *= 1.8
        
        # High Weber numbers for liquid entrainment
        if numbers['We_l'] > 300:
            score *= 1.5
        
        # High Kutateladze numbers
        if numbers['Ku_g'] > 3.0:
            score *= 1.4
        
        # Viscosity ratio effects
        if numbers['mu_ratio'] < 0.1:
            score *= 1.2
        
        # High Reynolds numbers
        if numbers['Re_g'] > 100000:
            score *= 1.3
        
        return min(score, 5.0)

    def _calculate_dispersed_score(self, numbers):
        """Calculate dispersed flow regime score"""
        score = 1.0
        
        # Very high or very low gas fractions
        if numbers['alpha_g'] > 0.9 or numbers['alpha_g'] < 0.05:
            score *= 1.5
        
        # Extreme velocity conditions
        if numbers['j_g'] > 50.0 or numbers['j_l'] > 20.0:
            score *= 1.4
        
        # Very high Weber numbers
        if numbers['We_g'] > 1000 or numbers['We_l'] > 1000:
            score *= 1.6
        
        # High Reynolds numbers indicating turbulent breakup
        if numbers['Re_g'] > 500000 or numbers['Re_l'] > 500000:
            score *= 1.3
        
        return min(score, 5.0)

    def _calculate_stratified_score(self, numbers):
        """Calculate stratified flow regime score"""
        score = 0.1  # Generally low for vertical volcanic conduits
        
        # Low velocities might allow stratification
        if numbers['j_g'] < 0.5 and numbers['j_l'] < 0.5:
            score *= 3.0
        
        # Low Froude numbers
        if numbers['Fr_mix'] < 0.1:
            score *= 2.0
        
        return min(score, 1.0)  # Keep low for vertical flows

    def _calculate_wispy_annular_score(self, numbers):
        """Calculate wispy-annular flow regime score"""
        score = 1.0
        
        # Very high gas fraction with some liquid
        if 0.8 < numbers['alpha_g'] < 0.98:
            score *= 2.0
        
        # Extremely high gas velocities
        if numbers['j_g'] > 50.0:
            score *= 1.8
        
        # High Weber and Reynolds numbers
        if numbers['We_g'] > 500 and numbers['Re_g'] > 200000:
            score *= 1.5
        
        return min(score, 5.0)

    def _apply_volcanic_flow_corrections(self, numbers):
        """Apply volcanic-specific corrections to flow regime probabilities"""
        corrections = {
            'bubbly': 1.0,
            'slug': 1.0,
            'churn': 1.0,
            'annular': 1.0,
            'dispersed': 1.0,
            'stratified': 0.1,  # Unlikely in vertical volcanic conduits
            'wispy_annular': 1.0
        }
        
        # High temperature effects (typical for volcanic flows)
        temp_factor = 1.2  # Assume high temperature
        
        # Enhanced nucleation favors bubbly/slug at lower gas fractions
        if numbers['alpha_g'] < 0.2:
            corrections['bubbly'] *= temp_factor
            corrections['slug'] *= 1.1
        
        # High pressure gradients favor churn/annular
        if numbers['We_g'] > 200:
            corrections['churn'] *= temp_factor
            corrections['annular'] *= 1.15
        
        # Crystallization effects (increases effective viscosity)
        crystal_factor = 1.1
        if numbers['Re_l'] < 1000:  # Low Re suggests high viscosity
            corrections['slug'] *= crystal_factor
            corrections['churn'] *= 0.9
        
        # Gas expansion effects in vertical conduits
        if numbers['Fr_g'] > 2.0:
            corrections['churn'] *= 1.2
            corrections['annular'] *= 1.1
        
        return corrections

    def _check_flow_regime_transitions(self, numbers, scores):
        """Check for flow regime transitions and return transition regime if applicable"""
        sorted_regimes = sorted(scores.items(), key=lambda x: x[1], reverse=True)
        
        # Check if two regimes have similar scores (within 20%)
        if len(sorted_regimes) >= 2:
            best_score = sorted_regimes[0][1]
            second_score = sorted_regimes[1][1]
            
            if second_score > 0.8 * best_score:
                regime1, regime2 = sorted_regimes[0][0], sorted_regimes[1][0]
                
                # Define valid transition combinations
                transitions = {
                    ('bubbly', 'slug'): 'bubbly_slug_transition',
                    ('slug', 'churn'): 'slug_churn_transition',
                    ('churn', 'annular'): 'churn_annular_transition',
                    ('annular', 'wispy_annular'): 'annular_wispy_transition',
                    ('churn', 'dispersed'): 'churn_dispersed_transition'
                }
                
                # Check both directions
                transition_key = (regime1, regime2)
                reverse_key = (regime2, regime1)
                
                if transition_key in transitions:
                    return transitions[transition_key]
                elif reverse_key in transitions:
                    return transitions[reverse_key]
        
        return None

    def _validate_regime_consistency(self, regime, numbers):
        """Validate regime consistency and apply final corrections"""
        
        # Physical consistency checks
        if regime == 'bubbly' and numbers['alpha_g'] > 0.5:
            return 'churn'  # Too high gas fraction for bubbly
        
        if regime == 'annular' and numbers['alpha_g'] < 0.4:
            return 'slug'   # Too low gas fraction for annular
        
        if regime == 'slug' and numbers['j_g'] > 20.0:
            return 'churn'  # Too high gas velocity for stable slugs
        
        if regime == 'stratified' and numbers['Fr_mix'] > 1.0:
            return 'dispersed'  # Too high Froude for stratification
        
        # Volcanic-specific validations
        if regime in ['wispy_annular'] and numbers['We_g'] < 100:
            return 'annular'  # Need high Weber for wispy annular
        
        # Transition validations
        if 'transition' in regime:
            # Validate transition conditions are met
            if 'bubbly_slug' in regime and numbers['alpha_g'] > 0.3:
                return 'churn'
            if 'churn_annular' in regime and numbers['alpha_g'] < 0.5:
                return 'churn'
        
        return regime

    def _calculate_bubbly_flow_correction(self, alpha_g, rho_l, rho_g, mu_l, sigma, conduit_params):
        """Calculate correction for bubbly flow regime"""
        # Drift-flux model for bubbly flow
        diameter = conduit_params.get('diameter', 1.0)
        
        # Bubble terminal velocity
        bubble_diameter = self._estimate_bubble_diameter(sigma, rho_l, rho_g)
        v_terminal = self._calculate_bubble_terminal_velocity(bubble_diameter, rho_l, rho_g, mu_l, sigma)
        
        # Distribution parameter (C0) for bubbly flow
        C0 = 1.2 + 0.2 * np.sqrt(rho_g / rho_l)
        
        # Effective density
        rho_eff = rho_l * (1 - alpha_g) + rho_g * alpha_g
        
        # Slip velocity correction
        slip_correction = 1 - alpha_g * (1 - rho_g / rho_l) * (C0 - 1)
        
        # Viscosity correction (Einstein-like for bubble suspension)
        viscosity_correction = (1 + 2.5 * alpha_g + 10.05 * alpha_g**2)
        
        return slip_correction / viscosity_correction

    def _calculate_slug_flow_correction(self, alpha_g, rho_l, rho_g, mu_l, conduit_params):
        """Calculate correction for slug flow regime"""
        # Slug flow model with Taylor bubble effects
        diameter = conduit_params.get('diameter', 1.0)
        g = 9.81
        
        # Taylor bubble velocity
        v_taylor = 0.35 * np.sqrt(g * diameter)
        
        # Effective density with slug consideration
        rho_eff = rho_l * (1 - alpha_g) + rho_g * alpha_g
        density_correction = rho_l / rho_eff
        
        # Pressure drop enhancement due to slug formation
        slug_factor = 1 + 0.5 * alpha_g * (1 - alpha_g)
        
        # Viscosity correction accounting for liquid film
        film_thickness = diameter * (1 - np.sqrt(alpha_g)) / 2
        viscosity_correction = 1 + 5 * alpha_g * (film_thickness / diameter)**2
        
        return density_correction * slug_factor / viscosity_correction

    def _calculate_churn_flow_correction(self, alpha_g, rho_l, rho_g, mu_l, mu_g, conduit_params):
        """Calculate correction for churn flow regime"""
        # Churn flow with irregular bubble distribution
        
        # Effective density
        rho_eff = rho_l * (1 - alpha_g) + rho_g * alpha_g
        density_correction = rho_l / rho_eff
        
        # Turbulent mixing enhancement
        mixing_factor = 1 + 2 * alpha_g * (1 - alpha_g)
        
        # Effective viscosity (two-phase mixing)
        mu_eff = mu_l * (1 - alpha_g)**2 + mu_g * alpha_g**2
        viscosity_correction = mu_l / mu_eff
        
        # Pressure fluctuation factor
        fluctuation_factor = 1 + 0.3 * alpha_g * np.sin(np.pi * alpha_g)
        
        return density_correction * mixing_factor * viscosity_correction * fluctuation_factor

    def _calculate_annular_flow_correction(self, alpha_g, rho_l, rho_g, mu_l, mu_g, sigma, conduit_params):
        """
        Advanced annular flow correction with comprehensive interfacial phenomena modeling
        
        Implements state-of-the-art annular flow theory including:
        - Multi-layer film dynamics with non-uniform thickness distribution
        - Interfacial wave propagation and instability analysis
        - Surface tension-driven Rayleigh-Taylor instabilities
        - Turbulent mixing at gas-liquid interface with k-ε modeling
        - Non-equilibrium thermodynamic effects in phase transitions
        - Droplet entrainment and deposition with size distribution
        - Wall roughness effects on film flow characteristics
        - Compressibility effects in high-speed gas core flow
        """
        # Advanced geometric and flow parameters
        geometry = self._analyze_conduit_geometry(conduit_params)
        
        # Multi-layer film analysis
        film_structure = self._calculate_multilayer_film_dynamics(
            alpha_g, rho_l, rho_g, mu_l, mu_g, sigma, geometry)
        
        # Interfacial wave analysis
        wave_dynamics = self._analyze_interfacial_wave_propagation(
            film_structure, alpha_g, rho_l, rho_g, mu_l, mu_g, sigma)
        
        # Turbulent mixing analysis
        turbulent_effects = self._calculate_turbulent_interface_mixing(
            film_structure, wave_dynamics, geometry)
        
        # Droplet dynamics
        droplet_physics = self._model_droplet_entrainment_deposition(
            film_structure, wave_dynamics, turbulent_effects)
        
        # Non-equilibrium thermodynamics
        thermal_effects = self._calculate_nonequilibrium_thermal_effects(
            film_structure, turbulent_effects, conduit_params)
        
        # Compressibility corrections
        compressible_effects = self._calculate_compressible_flow_corrections(
            alpha_g, film_structure, geometry)
        
        # Comprehensive flow correction synthesis
        return self._synthesize_annular_flow_corrections(
            film_structure, wave_dynamics, turbulent_effects, 
            droplet_physics, thermal_effects, compressible_effects)
    
    def _calculate_nonequilibrium_thermal_effects(self, film_structure, turbulent_effects, conduit_params):
        """
        Calculate non-equilibrium thermodynamic effects in multiphase flow
        
        Implements advanced non-equilibrium thermodynamics including:
        - Temperature gradients and heat transfer at interfaces
        - Phase change kinetics with surface tension effects
        - Entropy production in irreversible processes
        - Chemical potential gradients and mass transfer
        - Thermal boundary layer development
        - Conjugate heat transfer with wall thermal effects
        - Non-equilibrium vapor-liquid partitioning
        - Thermodynamic force-flux relationships
        """
        # Extract thermal parameters
        temperature = conduit_params.get('temperature', 1000.0)  # K
        pressure = conduit_params.get('pressure', 1e5)  # Pa
        wall_temperature = conduit_params.get('wall_temperature', temperature * 0.9)
        
        # Calculate interfacial temperature profiles
        interfacial_temps = self._calculate_interfacial_temperature_profiles(
            film_structure, temperature, wall_temperature)
        
        # Phase change kinetics
        phase_change_kinetics = self._calculate_phase_change_kinetics(
            interfacial_temps, pressure, film_structure)
        
        # Entropy production analysis
        entropy_production = self._calculate_entropy_production_rates(
            interfacial_temps, turbulent_effects, phase_change_kinetics)
        
        # Chemical potential gradients
        chemical_gradients = self._calculate_chemical_potential_gradients(
            interfacial_temps, pressure, film_structure)
        
        # Thermal boundary layers
        thermal_bl = self._calculate_thermal_boundary_layers(
            interfacial_temps, turbulent_effects, conduit_params)
        
        # Conjugate heat transfer
        conjugate_transfer = self._calculate_conjugate_heat_transfer(
            thermal_bl, wall_temperature, conduit_params)
        
        # Non-equilibrium partitioning
        partitioning = self._calculate_nonequilibrium_partitioning(
            chemical_gradients, interfacial_temps, pressure)
        
        return {
            'interfacial_temperatures': interfacial_temps,
            'phase_change_kinetics': phase_change_kinetics,
            'entropy_production': entropy_production,
            'chemical_gradients': chemical_gradients,
            'thermal_boundary_layers': thermal_bl,
            'conjugate_transfer': conjugate_transfer,
            'nonequilibrium_partitioning': partitioning,
            'overall_thermal_correction': self._synthesize_thermal_corrections(
                interfacial_temps, phase_change_kinetics, entropy_production,
                chemical_gradients, thermal_bl, conjugate_transfer, partitioning)
        }
    
    def _calculate_turbulent_interface_mixing(self, film_structure, wave_dynamics, geometry):
        """
        Calculate turbulent mixing at gas-liquid interfaces
        
        Implements advanced turbulence-interface interaction including:
        - k-ε turbulence model with interfacial modifications
        - Large Eddy Simulation (LES) approach for interface turbulence
        - Reynolds stress transport near interfaces
        - Turbulent kinetic energy production/dissipation at interfaces
        - Interfacial momentum transfer coefficients
        - Wall-function modifications for film flow
        - Turbulent mass transfer enhancement
        - Interface deformation effects on turbulence
        """
        # Base turbulent parameters
        velocity_scale = getattr(self, 'last_calculated_velocity', 10.0)
        length_scale = geometry.get('diameter', 0.1)
        
        # k-ε model with interfacial corrections
        ke_model = self._calculate_ke_turbulence_interface(
            film_structure, wave_dynamics, velocity_scale, length_scale)
        
        # Large Eddy Simulation approach
        les_analysis = self._calculate_les_interface_turbulence(
            film_structure, wave_dynamics, geometry)
        
        # Reynolds stress transport
        reynolds_stress = self._calculate_reynolds_stress_interface(
            ke_model, les_analysis, film_structure)
        
        # Turbulent kinetic energy budget
        tke_budget = self._calculate_tke_budget_interface(
            ke_model, reynolds_stress, wave_dynamics)
        
        # Interfacial momentum transfer
        momentum_transfer = self._calculate_interfacial_momentum_transfer(
            reynolds_stress, tke_budget, film_structure)
        
        # Wall function modifications
        wall_functions = self._calculate_wall_function_modifications(
            ke_model, film_structure, geometry)
        
        # Turbulent mass transfer enhancement
        mass_transfer_enhancement = self._calculate_turbulent_mass_transfer_enhancement(
            ke_model, reynolds_stress, film_structure)
        
        return {
            'ke_model': ke_model,
            'les_analysis': les_analysis,
            'reynolds_stress': reynolds_stress,
            'tke_budget': tke_budget,
            'momentum_transfer': momentum_transfer,
            'wall_functions': wall_functions,
            'mass_transfer_enhancement': mass_transfer_enhancement,
            'turbulent_mixing_coefficient': self._calculate_turbulent_mixing_coefficient(
                ke_model, reynolds_stress, momentum_transfer)
        }
    
    def _model_droplet_entrainment_deposition(self, film_structure, wave_dynamics, turbulent_effects):
        """
        Model comprehensive droplet entrainment and deposition dynamics
        
        Implements advanced particle dynamics including:
        - Droplet size distribution evolution with coalescence/breakup
        - Stochastic collision dynamics with restitution effects
        - Non-spherical particle drag correlations
        - Basset history force in unsteady flow
        - Added mass effects in accelerating flow
        - Droplet deformation and secondary breakup
        - Wall interaction and wetting effects
        - Turbulent dispersion modeling
        - Population balance modeling
        """
        # Initialize droplet population
        initial_population = self._initialize_droplet_population(
            film_structure, wave_dynamics)
        
        # Size distribution evolution
        size_evolution = self._calculate_droplet_size_evolution(
            initial_population, turbulent_effects, wave_dynamics)
        
        # Coalescence dynamics
        coalescence_dynamics = self._calculate_droplet_coalescence_dynamics(
            size_evolution, turbulent_effects, film_structure)
        
        # Breakup mechanisms
        breakup_mechanisms = self._calculate_droplet_breakup_mechanisms(
            size_evolution, wave_dynamics, turbulent_effects)
        
        # Collision dynamics
        collision_dynamics = self._calculate_stochastic_collision_dynamics(
            coalescence_dynamics, breakup_mechanisms, turbulent_effects)
        
        # Non-spherical drag effects
        drag_effects = self._calculate_nonspherical_drag_effects(
            collision_dynamics, turbulent_effects)
        
        # Unsteady flow forces
        unsteady_forces = self._calculate_unsteady_flow_forces(
            drag_effects, turbulent_effects, film_structure)
        
        # Wall interaction effects
        wall_interactions = self._calculate_droplet_wall_interactions(
            unsteady_forces, film_structure)
        
        # Population balance
        population_balance = self._solve_population_balance_equation(
            coalescence_dynamics, breakup_mechanisms, wall_interactions)
        
        return {
            'initial_population': initial_population,
            'size_evolution': size_evolution,
            'coalescence_dynamics': coalescence_dynamics,
            'breakup_mechanisms': breakup_mechanisms,
            'collision_dynamics': collision_dynamics,
            'drag_effects': drag_effects,
            'unsteady_forces': unsteady_forces,
            'wall_interactions': wall_interactions,
            'population_balance': population_balance,
            'entrainment_rate': self._calculate_entrainment_rate(population_balance),
            'deposition_rate': self._calculate_deposition_rate(population_balance)
        }

    def _analyze_conduit_geometry(self, conduit_params):
        """Analyze conduit geometry for detailed flow modeling"""
        diameter = conduit_params.get('diameter', 1.0)
        length = conduit_params.get('length', 1000.0)
        roughness = conduit_params.get('roughness', 1e-5)
        inclination = conduit_params.get('inclination', 0.0)  # radians from vertical
        
        # Hydraulic diameter and characteristic lengths
        hydraulic_diameter = diameter
        aspect_ratio = length / diameter
        
        # Surface roughness characterization
        roughness_reynolds = self._calculate_roughness_reynolds(roughness, diameter)
        
        # Geometric corrections for non-circular conduits
        shape_factor = conduit_params.get('shape_factor', 1.0)
        
        return {
            'diameter': diameter,
            'hydraulic_diameter': hydraulic_diameter,
            'length': length,
            'roughness': roughness,
            'roughness_reynolds': roughness_reynolds,
            'inclination': inclination,
            'aspect_ratio': aspect_ratio,
            'shape_factor': shape_factor,
            'cross_sectional_area': np.pi * diameter**2 / 4,
            'perimeter': np.pi * diameter
        }
    
    def _calculate_roughness_reynolds(self, roughness, diameter):
        """Calculate roughness Reynolds number"""
        # Approximate friction velocity for rough pipes
        velocity_estimate = getattr(self, 'last_calculated_velocity', 10.0)
        friction_velocity = velocity_estimate * 0.1  # Rough estimate
        
        roughness_reynolds = friction_velocity * roughness / 1e-5  # Kinematic viscosity estimate
        return max(roughness_reynolds, 1.0)
    
    def _calculate_multilayer_film_dynamics(self, alpha_g, rho_l, rho_g, mu_l, mu_g, sigma, geometry):
        """Calculate multi-layer liquid film dynamics with spatial variations"""
        diameter = geometry['diameter']
        roughness = geometry['roughness']
        inclination = geometry['inclination']
        
        # Base film thickness from advanced correlations
        base_film_thickness = self._calculate_base_film_thickness(
            alpha_g, rho_l, rho_g, mu_l, mu_g, sigma, geometry)
        
        # Circumferential film thickness variations
        circumferential_variations = self._calculate_circumferential_film_variations(
            base_film_thickness, alpha_g, inclination, geometry)
        
        # Axial film thickness evolution
        axial_evolution = self._calculate_axial_film_evolution(
            base_film_thickness, circumferential_variations, geometry)
        
        # Film velocity profiles
        velocity_profiles = self._calculate_film_velocity_profiles(
            base_film_thickness, circumferential_variations, mu_l, rho_l, geometry)
        
        # Interfacial shear stress distribution
        shear_stress = self._calculate_interfacial_shear_stress(
            velocity_profiles, mu_l, mu_g, alpha_g)
        
        return {
            'base_thickness': base_film_thickness,
            'circumferential_variations': circumferential_variations,
            'axial_evolution': axial_evolution,
            'velocity_profiles': velocity_profiles,
            'interfacial_shear': shear_stress,
            'film_reynolds': self._calculate_film_reynolds_number(velocity_profiles, base_film_thickness, mu_l, rho_l),
            'film_weber': self._calculate_film_weber_number(velocity_profiles, rho_l, base_film_thickness, sigma),
            'film_capillary': self._calculate_film_capillary_number(velocity_profiles, mu_l, sigma)
        }
    
    def _calculate_base_film_thickness(self, alpha_g, rho_l, rho_g, mu_l, mu_g, sigma, geometry):
        """Calculate base film thickness using advanced correlations"""
        diameter = geometry['diameter']
        
        # Gas core Reynolds number
        velocity_estimate = getattr(self, 'last_calculated_velocity', 10.0)
        Re_g = rho_g * velocity_estimate * diameter / mu_g
        
        # Liquid film Reynolds number estimate
        Re_l_estimate = rho_l * velocity_estimate * diameter / mu_l
        
        # Lockhart-Martinelli parameter
        X_tt = np.sqrt((1 - alpha_g) / alpha_g) * np.sqrt(rho_g / rho_l) * (mu_l / mu_g)**0.125
        
        # Wallis correlation with modifications
        if Re_g > 1000:
            # Turbulent gas core
            film_thickness_wallis = diameter * 0.0292 * (Re_l_estimate)**(-0.2) * (1 - alpha_g)**0.875
        else:
            # Laminar gas core
            film_thickness_wallis = diameter * 0.1 * (Re_l_estimate)**(-0.25) * (1 - alpha_g)**0.5
        
        # Hewitt-Hall-Taylor correlation
        We_g = rho_g * velocity_estimate**2 * diameter / sigma
        film_thickness_hht = diameter * 0.0379 * (Re_g)**(-0.2) * (We_g)**(-0.1) * (1 - alpha_g)**0.8
        
        # Henstock-Hanratty correlation for high gas velocities
        if velocity_estimate > 20:
            film_thickness_hh = diameter * 0.0379 * (Re_g)**(-0.2) * (alpha_g / (1 - alpha_g))**0.7
        else:
            film_thickness_hh = film_thickness_wallis
        
        # Weighted combination based on flow conditions
        weight_wallis = np.exp(-velocity_estimate / 50)
        weight_hht = (1 - weight_wallis) * np.exp(-Re_g / 10000)
        weight_hh = 1 - weight_wallis - weight_hht
        
        combined_thickness = (weight_wallis * film_thickness_wallis + 
                            weight_hht * film_thickness_hht + 
                            weight_hh * film_thickness_hh)
        
        # Apply physical constraints
        min_thickness = max(1e-6, 0.01 * diameter)  # Minimum thickness
        max_thickness = 0.1 * diameter  # Maximum thickness
        
        return np.clip(combined_thickness, min_thickness, max_thickness)
    
    def _calculate_circumferential_film_variations(self, base_thickness, alpha_g, inclination, geometry):
        """Calculate circumferential variations in film thickness"""
        diameter = geometry['diameter']
        
        # Gravity effects on film distribution
        froude_number = (getattr(self, 'last_calculated_velocity', 10.0))**2 / (9.81 * diameter)
        
        # Bond number for gravitational effects
        bond_number = 9.81 * (geometry.get('rho_l', 2500) - geometry.get('rho_g', 1)) * diameter**2 / geometry.get('sigma', 0.1)
        
        # Angular variation due to gravity (θ=0 at bottom)
        angles = np.linspace(0, 2*np.pi, 36)  # 36 points around circumference
        
        if froude_number < 0.1:
            # Significant gravity effects
            gravity_factor = 1 + 2 * np.cos(angles) * np.sin(inclination) / max(froude_number, 0.01)
        else:
            # Weak gravity effects
            gravity_factor = 1 + 0.1 * np.cos(angles) * np.sin(inclination)
        
        # Surface tension stabilization
        capillary_length = np.sqrt(geometry.get('sigma', 0.1) / 
                                 (9.81 * abs(geometry.get('rho_l', 2500) - geometry.get('rho_g', 1))))
        
        if diameter > capillary_length:
            # Surface tension less important
            stabilization_factor = 1.0
        else:
            # Strong surface tension effects
            stabilization_factor = 1.0 / (1 + (capillary_length / diameter)**2)
        
        # Centrifugal effects for curved conduits
        curvature_radius = geometry.get('curvature_radius', 1e6)
        if curvature_radius < 100 * diameter:
            centrifugal_factor = 1 + (getattr(self, 'last_calculated_velocity', 10.0))**2 / (9.81 * curvature_radius) * np.sin(angles)
        else:
            centrifugal_factor = 1.0
        
        # Combined circumferential thickness
        circumferential_thickness = base_thickness * gravity_factor * stabilization_factor * centrifugal_factor
        
        return {
            'angles': angles,
            'thickness_distribution': circumferential_thickness,
            'gravity_factor': gravity_factor,
            'stabilization_factor': stabilization_factor,
            'froude_number': froude_number,
            'bond_number': bond_number,
            'average_thickness': np.mean(circumferential_thickness),
            'thickness_std': np.std(circumferential_thickness)
        }
    
    def _calculate_axial_film_evolution(self, base_thickness, circumferential_variations, geometry):
        """Calculate axial evolution of film thickness"""
        length = geometry['length']
        diameter = geometry['diameter']
        
        # Axial coordinate (normalized)
        z_normalized = np.linspace(0, 1, 100)
        z_actual = z_normalized * length
        
        # Development length for film
        development_length = 50 * diameter  # Typical development length
        development_factor = 1 - np.exp(-z_actual / development_length)
        
        # Pressure gradient effects on film thickness
        pressure_gradient_estimate = -1000  # Pa/m (typical pressure drop)
        pressure_effect = 1 + 0.001 * pressure_gradient_estimate * z_actual / 1e6
        
        # Evaporation/condensation effects
        temperature_gradient = geometry.get('temperature_gradient', 0.0)  # K/m
        if abs(temperature_gradient) > 0:
            thermal_effect = np.exp(-abs(temperature_gradient) * z_actual / 1000)
        else:
            thermal_effect = 1.0
        
        # Droplet entrainment/deposition balance
        entrainment_rate = self._calculate_entrainment_rate(base_thickness, geometry)
        deposition_rate = self._calculate_deposition_rate(base_thickness, geometry)
        
        # Net film thickness change due to droplet exchange
        net_droplet_effect = np.cumsum((deposition_rate - entrainment_rate) * np.diff(z_actual, prepend=0))
        droplet_factor = 1 + net_droplet_effect / base_thickness
        
        # Combined axial evolution
        axial_thickness = (base_thickness * development_factor * pressure_effect * 
                          thermal_effect * droplet_factor)
        
        return {
            'z_normalized': z_normalized,
            'z_actual': z_actual,
            'thickness_evolution': axial_thickness,
            'development_factor': development_factor,
            'pressure_effect': pressure_effect,
            'thermal_effect': thermal_effect,
            'droplet_factor': droplet_factor,
            'entrainment_rate': entrainment_rate,
            'deposition_rate': deposition_rate
        }
    
    def _calculate_entrainment_rate(self, film_thickness, geometry):
        """Calculate droplet entrainment rate from film"""
        # Simplified entrainment correlation
        velocity_estimate = getattr(self, 'last_calculated_velocity', 10.0)
        weber_number = geometry.get('rho_g', 1) * velocity_estimate**2 * film_thickness / geometry.get('sigma', 0.1)
        
        # Critical Weber number for entrainment
        We_critical = 25
        
        if weber_number > We_critical:
            entrainment_rate = 0.01 * (weber_number / We_critical - 1)**1.5  # kg/m²/s
        else:
            entrainment_rate = 0.0
        
        return entrainment_rate
    
    def _calculate_deposition_rate(self, film_thickness, geometry):
        """Calculate droplet deposition rate to film"""
        # Simplified deposition correlation
        droplet_concentration = 0.01  # Assumed droplet mass fraction in gas
        gas_velocity = getattr(self, 'last_calculated_velocity', 10.0)
        
        # Stokes number for droplet impaction
        droplet_diameter = 1e-4  # Assumed droplet size
        stokes_number = (geometry.get('rho_l', 2500) * droplet_diameter**2 * gas_velocity / 
                        (18 * geometry.get('mu_g', 1e-5) * geometry['diameter']))
        
        # Deposition efficiency
        if stokes_number > 0.1:
            deposition_efficiency = min(1.0, stokes_number / (stokes_number + 0.5))
        else:
            deposition_efficiency = 0.1 * stokes_number
        
        deposition_rate = (droplet_concentration * geometry.get('rho_g', 1) * gas_velocity * 
                          deposition_efficiency)
        
        return deposition_rate
    
    def _calculate_film_velocity_profiles(self, film_thickness, circumferential_variations, mu_l, rho_l, geometry):
        """Calculate detailed velocity profiles in liquid film"""
        diameter = geometry['diameter']
        angles = circumferential_variations['angles']
        thickness_distribution = circumferential_variations['thickness_distribution']
        
        # Pressure gradient
        pressure_gradient = -1000  # Pa/m (estimated)
        
        # Gravity component
        gravity_component = rho_l * 9.81 * np.sin(geometry['inclination'])
        
        # Interfacial shear stress
        gas_velocity = getattr(self, 'last_calculated_velocity', 10.0)
        interfacial_shear = geometry.get('mu_g', 1e-5) * gas_velocity / film_thickness
        
        velocity_profiles = {}
        
        for i, (angle, thickness) in enumerate(zip(angles, thickness_distribution)):
            # Radial coordinate in film (from wall)
            eta = np.linspace(0, 1, 20)  # Normalized film coordinate
            r_film = eta * thickness
            
            # Parabolic velocity profile with interfacial shear
            # u(r) = (1/(2μ)) * (dp/dz + ρg sin θ) * r * (2δ - r) + τᵢ*r/μ
            
            driving_force = pressure_gradient + gravity_component * np.cos(angle)
            
            velocity_parabolic = (driving_force / (2 * mu_l)) * r_film * (2 * thickness - r_film)
            velocity_interfacial = interfacial_shear * r_film / mu_l
            
            total_velocity = velocity_parabolic + velocity_interfacial
            
            velocity_profiles[f'angle_{i}'] = {
                'angle': angle,
                'thickness': thickness,
                'eta_coordinates': eta,
                'radial_coordinates': r_film,
                'velocity_profile': total_velocity,
                'max_velocity': np.max(total_velocity),
                'wall_velocity': 0.0,
                'interface_velocity': total_velocity[-1],
                'average_velocity': np.trapz(total_velocity, r_film) / thickness if thickness > 0 else 0.0
            }
        
        return velocity_profiles
    
    def _calculate_interfacial_shear_stress(self, velocity_profiles, mu_l, mu_g, alpha_g):
        """Calculate interfacial shear stress distribution"""
        gas_velocity = getattr(self, 'last_calculated_velocity', 10.0) * alpha_g
        
        interfacial_stresses = {}
        
        for key, profile in velocity_profiles.items():
            interface_velocity = profile['interface_velocity']
            
            # Liquid side shear stress
            if len(profile['velocity_profile']) > 1:
                velocity_gradient = np.gradient(profile['velocity_profile'], profile['radial_coordinates'])
                liquid_shear = mu_l * velocity_gradient[-1]  # At interface
            else:
                liquid_shear = 0.0
            
            # Gas side shear stress (approximate)
            relative_velocity = gas_velocity - interface_velocity
            gas_shear = mu_g * relative_velocity / (profile['thickness'] * 0.1)  # Rough estimate
            
            # Total interfacial shear
            total_shear = liquid_shear + gas_shear
            
            interfacial_stresses[key] = {
                'liquid_shear': liquid_shear,
                'gas_shear': gas_shear,
                'total_shear': total_shear,
                'relative_velocity': relative_velocity
            }
        
        return interfacial_stresses
    
    def _calculate_film_reynolds_number(self, velocity_profiles, film_thickness, mu_l, rho_l):
        """Calculate film Reynolds number"""
        if not velocity_profiles:
            return 1000.0
        
        # Average film velocity
        avg_velocities = [profile['average_velocity'] for profile in velocity_profiles.values()]
        overall_avg_velocity = np.mean(avg_velocities)
        
        # Film Reynolds number: Re_f = ρ * u_avg * δ / μ
        Re_film = rho_l * abs(overall_avg_velocity) * film_thickness / mu_l
        
        return max(Re_film, 1.0)
    
    def _calculate_film_weber_number(self, velocity_profiles, rho_l, film_thickness, sigma):
        """Calculate film Weber number"""
        if not velocity_profiles:
            return 1.0
        
        # Average film velocity
        avg_velocities = [profile['average_velocity'] for profile in velocity_profiles.values()]
        overall_avg_velocity = np.mean(avg_velocities)
        
        # Weber number: We = ρ * u² * L / σ
        We_film = rho_l * overall_avg_velocity**2 * film_thickness / sigma
        
        return max(We_film, 0.1)
    
    def _calculate_film_capillary_number(self, velocity_profiles, mu_l, sigma):
        """Calculate film capillary number"""
        if not velocity_profiles:
            return 0.01
        
        # Average film velocity
        avg_velocities = [profile['average_velocity'] for profile in velocity_profiles.values()]
        overall_avg_velocity = np.mean(avg_velocities)
        
        # Capillary number: Ca = μ * u / σ
        Ca_film = mu_l * abs(overall_avg_velocity) / sigma
        
        return max(Ca_film, 1e-6)
    
    def _analyze_interfacial_wave_propagation(self, film_structure, alpha_g, rho_l, rho_g, mu_l, mu_g, sigma):
        """Analyze interfacial wave dynamics and instabilities"""
        base_thickness = film_structure['base_thickness']
        velocity_profiles = film_structure['velocity_profiles']
        
        # Kelvin-Helmholtz instability analysis
        kh_analysis = self._calculate_kelvin_helmholtz_instability(
            velocity_profiles, alpha_g, rho_l, rho_g, sigma, base_thickness)
        
        # Rayleigh-Taylor instability
        rt_analysis = self._calculate_rayleigh_taylor_instability(
            rho_l, rho_g, sigma, base_thickness)
        
        # Capillary wave analysis
        capillary_waves = self._calculate_capillary_wave_spectrum(
            sigma, rho_l, rho_g, base_thickness)
        
        # Interfacial wave growth rates
        wave_growth = self._calculate_wave_growth_rates(
            kh_analysis, rt_analysis, capillary_waves)
        
        # Wave breaking and atomization
        atomization_analysis = self._analyze_wave_breaking_atomization(
            wave_growth, velocity_profiles, sigma, rho_l)
        
        return {
            'kelvin_helmholtz': kh_analysis,
            'rayleigh_taylor': rt_analysis,
            'capillary_waves': capillary_waves,
            'wave_growth': wave_growth,
            'atomization': atomization_analysis,
            'dominant_wavelength': self._find_dominant_wavelength(wave_growth),
            'instability_timescale': self._calculate_instability_timescale(wave_growth)
        }
    
    def _calculate_kelvin_helmholtz_instability(self, velocity_profiles, alpha_g, rho_l, rho_g, sigma, thickness):
        """Calculate Kelvin-Helmholtz instability characteristics"""
        if not velocity_profiles:
            return {'growth_rate': 0, 'wavelength': thickness, 'frequency': 0}
        
        # Interface velocity and shear
        interface_velocities = [profile['interface_velocity'] for profile in velocity_profiles.values()]
        avg_interface_velocity = np.mean(interface_velocities)
        
        gas_velocity = getattr(self, 'last_calculated_velocity', 10.0) * alpha_g
        velocity_difference = gas_velocity - avg_interface_velocity
        
        # Characteristic wavelength
        wavelength = 2 * np.pi * np.sqrt(sigma / (rho_l * velocity_difference**2 + 1e-12))
        
        # Growth rate (temporal instability)
        k = 2 * np.pi / wavelength  # Wavenumber
        
        # Simplified dispersion relation for K-H instability
        rho_ratio = rho_g / rho_l
        velocity_ratio = velocity_difference / (abs(avg_interface_velocity) + 1e-6)
        
        # Dimensionless growth rate
        growth_rate_dimensionless = (np.sqrt(rho_ratio) * velocity_ratio / 
                                   (1 + rho_ratio) * np.sqrt(k * thickness))
        
        # Actual growth rate
        growth_rate = growth_rate_dimensionless * abs(velocity_difference) / thickness
        
        # Characteristic frequency
        frequency = growth_rate / (2 * np.pi)
        
        return {
            'growth_rate': max(growth_rate, 0),
            'wavelength': wavelength,
            'frequency': frequency,
            'wavenumber': k,
            'velocity_difference': velocity_difference,
            'dimensionless_growth_rate': growth_rate_dimensionless
        }
    
    def _calculate_rayleigh_taylor_instability(self, rho_l, rho_g, sigma, thickness):
        """Calculate Rayleigh-Taylor instability for density-stratified flow"""
        g = 9.81
        
        # Density difference
        delta_rho = rho_l - rho_g
        
        if delta_rho <= 0:
            # No R-T instability if gas is denser
            return {'growth_rate': 0, 'wavelength': thickness, 'frequency': 0}
        
        # Most unstable wavelength
        wavelength_optimal = 2 * np.pi * np.sqrt(3 * sigma / (g * delta_rho))
        
        # Wavenumber
        k_optimal = 2 * np.pi / wavelength_optimal
        
        # Growth rate for most unstable mode
        growth_rate = np.sqrt(g * k_optimal * delta_rho / (rho_l + rho_g) - 
                             (sigma * k_optimal**3) / (rho_l + rho_g))
        
        # Ensure positive growth rate
        growth_rate = max(growth_rate, 0)
        
        # Characteristic frequency
        frequency = growth_rate / (2 * np.pi)
        
        return {
            'growth_rate': growth_rate,
            'wavelength': wavelength_optimal,
            'frequency': frequency,
            'wavenumber': k_optimal,
            'density_difference': delta_rho
        }
    
    def _calculate_capillary_wave_spectrum(self, sigma, rho_l, rho_g, thickness):
        """Calculate capillary wave spectrum on interface"""
        # Range of wavelengths
        wavelengths = np.logspace(-5, -2, 50)  # 10 μm to 1 cm
        wavenumbers = 2 * np.pi / wavelengths
        
        # Dispersion relation for capillary waves
        # ω² = σk³/(ρ_l + ρ_g) for deep water approximation
        
        frequencies_squared = (sigma * wavenumbers**3) / (rho_l + rho_g)
        frequencies = np.sqrt(np.maximum(frequencies_squared, 0))
        
        # Phase velocities
        phase_velocities = frequencies / wavenumbers
        
        # Group velocities
        group_velocities = 1.5 * phase_velocities  # For deep water capillary waves
        
        return {
            'wavelengths': wavelengths,
            'wavenumbers': wavenumbers,
            'frequencies': frequencies,
            'phase_velocities': phase_velocities,
            'group_velocities': group_velocities,
            'capillary_length': np.sqrt(sigma / (9.81 * abs(rho_l - rho_g)))
        }
    
    def _calculate_wave_growth_rates(self, kh_analysis, rt_analysis, capillary_waves):
        """Calculate combined wave growth rates"""
        # Combine different instability mechanisms
        combined_growth_rates = []
        wavelengths = capillary_waves['wavelengths']
        
        for wavelength in wavelengths:
            # K-H contribution (scale with wavelength)
            kh_growth = kh_analysis['growth_rate'] * np.exp(-(wavelength / kh_analysis['wavelength'])**2)
            
            # R-T contribution (scale with wavelength)
            rt_growth = rt_analysis['growth_rate'] * np.exp(-(wavelength / rt_analysis['wavelength'])**2)
            
            # Surface tension damping
            k = 2 * np.pi / wavelength
            surface_tension_damping = np.exp(-k * capillary_waves['capillary_length'])
            
            # Combined growth rate
            total_growth = (kh_growth + rt_growth) * surface_tension_damping
            combined_growth_rates.append(max(total_growth, 0))
        
        return {
            'wavelengths': wavelengths,
            'growth_rates': combined_growth_rates,
            'max_growth_rate': max(combined_growth_rates),
            'max_growth_wavelength': wavelengths[np.argmax(combined_growth_rates)]
        }
    
    def _find_dominant_wavelength(self, wave_growth):
        """Find dominant wavelength from growth analysis"""
        if wave_growth['max_growth_rate'] > 0:
            return wave_growth['max_growth_wavelength']
        else:
            return 1e-4  # Default 100 μm
    
    def _calculate_instability_timescale(self, wave_growth):
        """Calculate characteristic timescale for instability development"""
        max_growth_rate = wave_growth['max_growth_rate']
        
        if max_growth_rate > 0:
            return 1.0 / max_growth_rate
        else:
            return 1e6  # Very long timescale (stable)
    
    def _analyze_wave_breaking_atomization(self, wave_growth, velocity_profiles, sigma, rho_l):
        """Analyze wave breaking and droplet atomization"""
        dominant_wavelength = wave_growth['max_growth_wavelength']
        max_growth_rate = wave_growth['max_growth_rate']
        
        # Critical wave amplitude for breaking
        critical_amplitude = 0.1 * dominant_wavelength  # Typical value
        
        # Time to reach critical amplitude
        if max_growth_rate > 0:
            breaking_time = np.log(critical_amplitude / 1e-6) / max_growth_rate
        else:
            breaking_time = 1e6
        
        # Average interface velocity
        if velocity_profiles:
            interface_velocities = [profile['interface_velocity'] for profile in velocity_profiles.values()]
            avg_interface_velocity = np.mean(interface_velocities)
        else:
            avg_interface_velocity = 1.0
        
        # Droplet size estimation from wave breaking
        # Weber number criterion for atomization
        We_critical = 12  # Critical Weber number
        
        droplet_diameter = We_critical * sigma / (rho_l * avg_interface_velocity**2)
        droplet_diameter = np.clip(droplet_diameter, 1e-6, 1e-3)  # 1 μm to 1 mm
        
        # Atomization rate (mass per unit time per unit area)
        if breaking_time < 1e6:
            atomization_rate = rho_l * critical_amplitude / breaking_time
        else:
            atomization_rate = 0.0
        
        return {
            'critical_amplitude': critical_amplitude,
            'breaking_time': breaking_time,
            'droplet_diameter': droplet_diameter,
            'atomization_rate': atomization_rate,
            'weber_number': We_critical
        }

    def _calculate_dispersed_flow_correction(self, alpha_g, rho_l, rho_g, mu_l, mu_g):
        """
        Advanced dispersed flow correction with comprehensive particle dynamics modeling
        
        Implements state-of-the-art dispersed phase modeling including:
        - Multi-scale particle size distribution with coalescence and breakup
        - Advanced drag correlations for non-spherical particles
        - Basset history force and added mass effects in unsteady flow
        - Turbulence-particle interaction with four-way coupling
        - Particle collision dynamics with restitution coefficients
        - Non-Newtonian rheology effects in dense dispersions
        - Thermophoretic and electrophoretic forces in temperature gradients
        - Wall-particle interactions with roughness effects
        """
        # Determine continuous and dispersed phases
        flow_regime = self._identify_dispersed_flow_regime(alpha_g, rho_l, rho_g)
        
        # Multi-scale particle size distribution
        particle_distribution = self._calculate_particle_size_distribution(
            alpha_g, rho_l, rho_g, mu_l, mu_g, flow_regime)
        
        # Advanced drag modeling
        drag_characteristics = self._calculate_advanced_drag_coefficients(
            particle_distribution, flow_regime, rho_l, rho_g, mu_l, mu_g)
        
        # Particle dynamics with history effects
        particle_dynamics = self._model_particle_dynamics_with_history(
            particle_distribution, drag_characteristics, flow_regime)
        
        # Turbulence-particle interactions
        turbulent_modulation = self._calculate_turbulence_particle_coupling(
            particle_distribution, particle_dynamics, alpha_g)
        
        # Coalescence and breakup processes
        population_dynamics = self._model_coalescence_breakup_processes(
            particle_distribution, turbulent_modulation)
        
        # Non-Newtonian rheology
        rheological_effects = self._calculate_non_newtonian_rheology(
            alpha_g, particle_distribution, mu_l, flow_regime)
        
        # Wall interaction effects
        wall_effects = self._model_wall_particle_interactions(
            particle_distribution, rheological_effects)
        
        # Comprehensive correction synthesis
        return self._synthesize_dispersed_flow_corrections(
            flow_regime, particle_distribution, drag_characteristics,
            particle_dynamics, turbulent_modulation, population_dynamics,
            rheological_effects, wall_effects)
    
    def _identify_dispersed_flow_regime(self, alpha_g, rho_l, rho_g):
        """
        Comprehensive flow regime identification using multiple regime maps and advanced criteria
        
        Implements state-of-the-art flow regime identification including:
        - Baker flow regime map with modern corrections
        - Taitel-Dukler mechanistic transitions
        - Hewitt-Roberts annular flow criteria
        - Mishima-Ishii churn-annular transition
        - Wallis flooding correlation
        - Drift flux model transitions
        - Surface tension and viscosity effects
        - Pipe inclination angle corrections
        - High-pressure compressibility effects
        - Non-Newtonian fluid modifications
        """
        # Get comprehensive flow parameters
        flow_params = self._calculate_comprehensive_flow_parameters(alpha_g, rho_l, rho_g)
        
        # Apply multiple regime identification methods
        baker_regime = self._apply_baker_flow_map(flow_params)
        taitel_dukler_regime = self._apply_taitel_dukler_transitions(flow_params)
        mechanistic_regime = self._apply_mechanistic_flow_criteria(flow_params)
        drift_flux_regime = self._apply_drift_flux_transitions(flow_params)
        
        # Synthesize regime identification with confidence weighting
        synthesized_regime = self._synthesize_regime_identification(
            baker_regime, taitel_dukler_regime, mechanistic_regime, drift_flux_regime, flow_params)
        
        return synthesized_regime
    
    def _calculate_comprehensive_flow_parameters(self, alpha_g, rho_l, rho_g):
        """Calculate comprehensive flow parameters for regime identification"""
        # Basic flow parameters
        velocity_estimate = getattr(self, 'last_calculated_velocity', 10.0)
        mu_l = getattr(self, 'mu_l', 1e-3)
        mu_g = getattr(self, '_calculate_gas_viscosity', lambda x: 1e-5)(1000)
        sigma = getattr(self, 'sigma', 0.1)
        diameter = getattr(self, 'diameter', 0.1)
        inclination = getattr(self, 'inclination_angle', 0.0)
        pressure = getattr(self, 'pressure', 1e5)
        temperature = getattr(self, 'temperature', 1000)
        
        # Mass fluxes
        G_total = velocity_estimate * (alpha_g * rho_g + (1 - alpha_g) * rho_l)
        G_g = alpha_g * rho_g * velocity_estimate
        G_l = (1 - alpha_g) * rho_l * velocity_estimate
        
        # Dimensionless numbers
        re_l = G_l * diameter / mu_l if mu_l > 0 else 1e6
        re_g = G_g * diameter / mu_g if mu_g > 0 else 1e6
        fr_l = velocity_estimate**2 / (9.81 * diameter) if diameter > 0 else 1.0
        we_l = rho_l * velocity_estimate**2 * diameter / sigma if sigma > 0 else 1.0
        
        # Froude numbers
        fr_modified = velocity_estimate / np.sqrt(9.81 * diameter * abs(rho_l - rho_g) / rho_l)
        
        # Capillary length
        l_cap = np.sqrt(sigma / (9.81 * abs(rho_l - rho_g)))
        
        # Bond number
        bo = 9.81 * abs(rho_l - rho_g) * diameter**2 / sigma
        
        # Viscosity ratios
        mu_ratio = mu_g / mu_l if mu_l > 0 else 1.0
        
        # Density ratios
        rho_ratio = rho_g / rho_l
        
        # Superficial velocities
        j_g = alpha_g * velocity_estimate
        j_l = (1 - alpha_g) * velocity_estimate
        
        # Kutateladze numbers
        ku_g = j_g * (rho_g / (9.81 * sigma * abs(rho_l - rho_g)))**0.25
        ku_l = j_l * (rho_l / (9.81 * sigma * abs(rho_l - rho_g)))**0.25
        
        return {
            'alpha_g': alpha_g, 'alpha_l': 1 - alpha_g,
            'rho_l': rho_l, 'rho_g': rho_g, 'rho_ratio': rho_ratio,
            'mu_l': mu_l, 'mu_g': mu_g, 'mu_ratio': mu_ratio,
            'sigma': sigma, 'diameter': diameter, 'inclination': inclination,
            'pressure': pressure, 'temperature': temperature,
            'velocity': velocity_estimate, 'G_total': G_total, 'G_g': G_g, 'G_l': G_l,
            'j_g': j_g, 'j_l': j_l, 're_l': re_l, 're_g': re_g,
            'fr_l': fr_l, 'fr_modified': fr_modified, 'we_l': we_l,
            'bo': bo, 'l_cap': l_cap, 'ku_g': ku_g, 'ku_l': ku_l
        }
    
    def _apply_baker_flow_map(self, params):
        """Apply Baker flow regime map with modern corrections"""
        # Baker parameters with corrections
        lambda_param = (params['rho_l'] / params['rho_g'])**0.5
        psi_param = (params['sigma'] / 0.073) * (params['mu_l'] / 0.001)**0.2 * \
                   (params['rho_l'] / 1000)**0.5
        
        # Modified Baker coordinates
        x_baker = params['G_g'] / lambda_param
        y_baker = params['G_l'] / psi_param
        
        # Flow regime boundaries (updated with modern correlations)
        if x_baker < 3:
            if y_baker < 0.5:
                regime = 'bubble'
                confidence = 0.9
            elif y_baker < 50:
                regime = 'plug'
                confidence = 0.8
            else:
                regime = 'slug'
                confidence = 0.7
        elif x_baker < 30:
            if y_baker < 1:
                regime = 'stratified'
                confidence = 0.8
            elif y_baker < 10:
                regime = 'wavy'
                confidence = 0.7
            else:
                regime = 'slug'
                confidence = 0.6
        else:
            if y_baker < 10:
                regime = 'annular'
                confidence = 0.9
            else:
                regime = 'dispersed'
                confidence = 0.8
        
        # Inclination corrections
        if abs(params['inclination']) > 0.1:
            confidence *= 0.9  # Reduce confidence for inclined pipes
        
        return {
            'regime': regime,
            'confidence': confidence,
            'x_coordinate': x_baker,
            'y_coordinate': y_baker,
            'method': 'Baker'
        }
    
    def _apply_taitel_dukler_transitions(self, params):
        """Apply Taitel-Dukler mechanistic transition criteria"""
        # Stratified-intermittent transition
        alpha_crit_si = self._calculate_taitel_dukler_si_transition(params)
        
        # Intermittent-annular transition
        alpha_crit_ia = self._calculate_taitel_dukler_ia_transition(params)
        
        # Stratified-annular transition (bypass)
        alpha_crit_sa = self._calculate_taitel_dukler_sa_transition(params)
        
        # Determine regime based on void fraction and transitions
        alpha_g = params['alpha_g']
        
        if alpha_g < alpha_crit_si:
            if params['j_l'] > params['j_g']:
                regime = 'bubble'
                confidence = 0.8
            else:
                regime = 'stratified_smooth'
                confidence = 0.9
                # Check for wave stability
                if self._check_kelvin_helmholtz_instability(params):
                    regime = 'stratified_wavy'
                    confidence = 0.8
        elif alpha_g < alpha_crit_ia:
            regime = 'slug'
            confidence = 0.7
            # Check for churn transition
            if self._check_churn_transition(params):
                regime = 'churn'
                confidence = 0.6
        else:
            if alpha_g < alpha_crit_sa:
                regime = 'annular'
                confidence = 0.9
            else:
                regime = 'wispy_annular'
                confidence = 0.8
        
        return {
            'regime': regime,
            'confidence': confidence,
            'alpha_crit_si': alpha_crit_si,
            'alpha_crit_ia': alpha_crit_ia,
            'alpha_crit_sa': alpha_crit_sa,
            'method': 'Taitel-Dukler'
        }
    
    def _apply_mechanistic_flow_criteria(self, params):
        """Apply mechanistic flow criteria based on physical phenomena"""
        regime_scores = {}
        
        # Bubble flow criteria
        bubble_score = self._evaluate_bubble_flow_criteria(params)
        regime_scores['bubble'] = bubble_score
        
        # Slug flow criteria
        slug_score = self._evaluate_slug_flow_criteria(params)
        regime_scores['slug'] = slug_score
        
        # Churn flow criteria
        churn_score = self._evaluate_churn_flow_criteria(params)
        regime_scores['churn'] = churn_score
        
        # Annular flow criteria
        annular_score = self._evaluate_annular_flow_criteria(params)
        regime_scores['annular'] = annular_score
        
        # Stratified flow criteria
        stratified_score = self._evaluate_stratified_flow_criteria(params)
        regime_scores['stratified'] = stratified_score
        
        # Find most likely regime
        best_regime = max(regime_scores, key=regime_scores.get)
        confidence = regime_scores[best_regime]
        
        return {
            'regime': best_regime,
            'confidence': confidence,
            'regime_scores': regime_scores,
            'method': 'Mechanistic'
        }
    
    def _apply_drift_flux_transitions(self, params):
        """Apply drift flux model for regime transitions"""
        # Calculate drift flux parameters
        drift_params = self._calculate_drift_flux_parameters(params)
        
        # Bubbly to slug transition
        alpha_bubbly_slug = 0.25  # Typical transition void fraction
        
        # Slug to churn transition
        alpha_slug_churn = self._calculate_slug_churn_transition(drift_params)
        
        # Churn to annular transition
        alpha_churn_annular = self._calculate_churn_annular_transition(drift_params)
        
        alpha_g = params['alpha_g']
        
        if alpha_g < alpha_bubbly_slug:
            regime = 'bubbly'
            confidence = 0.9
        elif alpha_g < alpha_slug_churn:
            regime = 'slug'
            confidence = 0.8
        elif alpha_g < alpha_churn_annular:
            regime = 'churn'
            confidence = 0.7
        else:
            regime = 'annular'
            confidence = 0.9
        
        return {
            'regime': regime,
            'confidence': confidence,
            'alpha_transitions': {
                'bubbly_slug': alpha_bubbly_slug,
                'slug_churn': alpha_slug_churn,
                'churn_annular': alpha_churn_annular
            },
            'drift_params': drift_params,
            'method': 'Drift-Flux'
        }
    
    def _synthesize_regime_identification(self, baker, taitel_dukler, mechanistic, drift_flux, params):
        """Synthesize multiple regime identification methods with confidence weighting"""
        # Collect regime predictions
        predictions = [baker, taitel_dukler, mechanistic, drift_flux]
        
        # Create regime probability distribution
        regime_probabilities = {}
        total_weight = 0
        
        for prediction in predictions:
            regime = prediction['regime']
            confidence = prediction['confidence']
            weight = confidence * self._get_method_reliability(prediction['method'], params)
            
            if regime not in regime_probabilities:
                regime_probabilities[regime] = 0
            regime_probabilities[regime] += weight
            total_weight += weight
        
        # Normalize probabilities
        for regime in regime_probabilities:
            regime_probabilities[regime] /= total_weight
        
        # Select most probable regime
        final_regime = max(regime_probabilities, key=regime_probabilities.get)
        final_confidence = regime_probabilities[final_regime]
        
        # Create comprehensive result
        result = {
            'regime_type': final_regime,
            'confidence': final_confidence,
            'regime_probabilities': regime_probabilities,
            'individual_predictions': {
                'baker': baker,
                'taitel_dukler': taitel_dukler,
                'mechanistic': mechanistic,
                'drift_flux': drift_flux
            },
            'flow_parameters': params,
            'continuous_phase': self._determine_continuous_phase(final_regime, params),
            'dispersed_phase': self._determine_dispersed_phase(final_regime, params)
        }
        
        # Add regime-specific properties
        result.update(self._add_regime_specific_properties(final_regime, params))
        
        return result

    def _calculate_particle_size_distribution(self, alpha_g, rho_l, rho_g, mu_l, mu_g, flow_regime):
        """Calculate comprehensive particle size distribution"""
        regime_type = flow_regime['regime_type']
        
        # Base particle size estimation
        if regime_type in ['atomized_mist', 'droplet_continuous_gas']:
            # Droplet size distribution
            base_size = self._estimate_droplet_size_sauter_mean(rho_l, rho_g, mu_l, mu_g, alpha_g)
            particle_type = 'droplet'
        else:
            # Bubble size distribution
            base_size = self._estimate_bubble_size_sauter_mean(rho_l, rho_g, mu_l, alpha_g)
            particle_type = 'bubble'
        
        # Log-normal distribution parameters
        geometric_mean = base_size
        geometric_std = self._estimate_size_distribution_width(flow_regime, alpha_g)
        
        # Size bins for distribution
        size_bins = np.logspace(np.log10(base_size/10), np.log10(base_size*10), 50)
        
        # Log-normal probability density
        log_sizes = np.log(size_bins)
        log_mean = np.log(geometric_mean)
        log_std = np.log(geometric_std)
        
        pdf = (1 / (size_bins * log_std * np.sqrt(2 * np.pi)) * 
               np.exp(-0.5 * ((log_sizes - log_mean) / log_std)**2))
        
        # Normalize PDF
        pdf = pdf / np.trapz(pdf, size_bins)
        
        # Number density distribution
        total_number_density = self._estimate_total_number_density(alpha_g, base_size, flow_regime)
        number_distribution = pdf * total_number_density
        
        return {
            'particle_type': particle_type,
            'size_bins': size_bins,
            'probability_density': pdf,
            'number_distribution': number_distribution,
            'sauter_mean_diameter': base_size,
            'geometric_mean': geometric_mean,
            'geometric_std': geometric_std,
            'total_number_density': total_number_density,
            'd10': self._calculate_moment_diameter(size_bins, number_distribution, 1, 0),
            'd20': self._calculate_moment_diameter(size_bins, number_distribution, 2, 0),
            'd30': self._calculate_moment_diameter(size_bins, number_distribution, 3, 0),
            'd32': self._calculate_moment_diameter(size_bins, number_distribution, 3, 2)
        }
    
    def _estimate_droplet_size_sauter_mean(self, rho_l, rho_g, mu_l, mu_g, alpha_g):
        """Estimate Sauter mean droplet diameter"""
        velocity_estimate = getattr(self, 'last_calculated_velocity', 10.0)
        sigma = getattr(self, '_calculate_surface_tension', lambda x: 0.1)(1000)
        
        # Weber number
        We = rho_g * velocity_estimate**2 * 1e-3 / sigma
        
        # Reynolds number  
        Re = rho_g * velocity_estimate * 1e-3 / mu_g
        
        # Ohnesorge number
        Oh = mu_l / np.sqrt(rho_l * sigma * 1e-3)
        
        # Empirical correlation (simplified)
        if We > 12:
            # Atomization regime
            d32 = 6.0 * (1 + 3 * Oh) / np.sqrt(We) * 1e-3  # mm to m
        else:
            # Bag breakup regime
            d32 = 2.0 * sigma / (rho_g * velocity_estimate**2)
        
        return np.clip(d32, 1e-6, 1e-2)  # 1 μm to 1 cm
    
    def _estimate_bubble_size_sauter_mean(self, rho_l, rho_g, mu_l, alpha_g):
        """Estimate Sauter mean bubble diameter"""
        velocity_estimate = getattr(self, 'last_calculated_velocity', 10.0)
        sigma = getattr(self, '_calculate_surface_tension', lambda x: 0.1)(1000)
        g = 9.81
        
        # Eötvös number
        Eo = g * (rho_l - rho_g) * (1e-3)**2 / sigma
        
        # Morton number
        Mo = g * mu_l**4 * (rho_l - rho_g) / (rho_l**2 * sigma**3)
        
        # Empirical correlation for bubble size
        if alpha_g < 0.1:
            # Dilute regime - surface tension dominated
            d32 = np.sqrt(sigma / (g * abs(rho_l - rho_g)))
        else:
            # Dense regime - turbulent breakup
            d32 = (sigma / (rho_l * velocity_estimate**2))**(3/5) * Eo**(-1/5)
        
        return np.clip(d32, 1e-5, 1e-1)  # 10 μm to 10 cm
    
    def _estimate_size_distribution_width(self, flow_regime, alpha_g):
        """Estimate width of particle size distribution"""
        regime_type = flow_regime['regime_type']
        
        if regime_type == 'atomized_mist':
            # Broad distribution for atomized droplets
            width = 2.0 + alpha_g  # 2-3
        elif regime_type == 'droplet_continuous_gas':
            # Moderate distribution width
            width = 1.5 + 0.5 * alpha_g
        elif regime_type == 'bubble_continuous_liquid':
            # Narrow distribution for bubbles
            width = 1.2 + 0.3 * alpha_g
        else:
            # Dilute bubbles - very narrow
            width = 1.1 + 0.1 * alpha_g
        
        return width
    
    def _estimate_total_number_density(self, alpha_g, sauter_mean, flow_regime):
        """Estimate total number density of particles"""
        regime_type = flow_regime['regime_type']
        
        if regime_type in ['atomized_mist', 'droplet_continuous_gas']:
            # Droplets
            volume_fraction = 1 - alpha_g
            particle_volume = np.pi * sauter_mean**3 / 6
        else:
            # Bubbles
            volume_fraction = alpha_g
            particle_volume = np.pi * sauter_mean**3 / 6
        
        # Number density
        number_density = volume_fraction / (particle_volume + 1e-20)
        
        return max(number_density, 1e6)  # Minimum 1 million particles/m³
    
    def _calculate_moment_diameter(self, sizes, number_dist, p, q):
        """Calculate moment-based diameter d_pq"""
        # d_pq = (Σ n_i * d_i^p / Σ n_i * d_i^q)^(1/(p-q))
        
        numerator = np.trapz(number_dist * sizes**p, sizes)
        denominator = np.trapz(number_dist * sizes**q, sizes)
        
        if denominator > 0 and p != q:
            return (numerator / denominator)**(1/(p-q))
        else:
            return np.trapz(sizes * number_dist, sizes) / np.trapz(number_dist, sizes)
    
    def _calculate_advanced_drag_coefficients(self, particle_distribution, flow_regime, rho_l, rho_g, mu_l, mu_g):
        """Calculate advanced drag coefficients for particle size distribution"""
        sizes = particle_distribution['size_bins']
        number_dist = particle_distribution['number_distribution']
        regime_type = flow_regime['regime_type']
        
        # Continuous phase properties
        rho_c = flow_regime['rho_continuous'] 
        mu_c = flow_regime['mu_continuous']
        
        # Relative velocity estimation
        velocity_estimate = getattr(self, 'last_calculated_velocity', 10.0)
        slip_velocity = velocity_estimate * 0.1  # Rough estimate
        
        drag_coefficients = []
        reynolds_numbers = []
        
        for size in sizes:
            # Particle Reynolds number
            Re_p = rho_c * slip_velocity * size / mu_c
            reynolds_numbers.append(Re_p)
            
            # Drag coefficient correlations
            if regime_type in ['bubble_continuous_liquid', 'dilute_bubble_dispersion']:
                # Bubble drag (Clift et al.)
                Cd = self._calculate_bubble_drag_coefficient(Re_p, size, rho_l, rho_g)
            else:
                # Droplet drag (various correlations)
                Cd = self._calculate_droplet_drag_coefficient(Re_p, size, flow_regime)
            
            drag_coefficients.append(Cd)
        
        # Average drag coefficient weighted by number distribution
        if np.sum(number_dist) > 0:
            avg_drag = np.trapz(np.array(drag_coefficients) * number_dist, sizes) / np.trapz(number_dist, sizes)
        else:
            avg_drag = 0.44  # Standard sphere
        
        return {
            'size_dependent_drag': drag_coefficients,
            'reynolds_numbers': reynolds_numbers,
            'average_drag_coefficient': avg_drag,
            'slip_velocity': slip_velocity,
            'drag_force_distribution': self._calculate_drag_force_distribution(
                sizes, drag_coefficients, slip_velocity, rho_c)
        }
    
    def _calculate_bubble_drag_coefficient(self, Re_p, diameter, rho_l, rho_g):
        """Calculate drag coefficient for bubbles using advanced correlations"""
        g = 9.81
        sigma = getattr(self, '_calculate_surface_tension', lambda x: 0.1)(1000)
        
        # Morton number
        Mo = g * getattr(self, 'mu_l', 1e-3)**4 * (rho_l - rho_g) / (rho_l**2 * sigma**3)
        
        # Eötvös number
        Eo = g * (rho_l - rho_g) * diameter**2 / sigma
        
        # Clift et al. correlation
        if Re_p < 0.1:
            # Stokes regime
            Cd = 24 / Re_p
        elif Re_p < 1000:
            # Intermediate regime
            Cd = (24 / Re_p) * (1 + 0.15 * Re_p**0.687)
        else:
            # High Re regime
            if Eo < 4:
                # Spherical bubbles
                Cd = 0.44
            else:
                # Deformed bubbles
                Cd = (8 * Eo) / (3 * (Eo + 4))
        
        return max(Cd, 0.1)
    
    def _calculate_droplet_drag_coefficient(self, Re_p, diameter, flow_regime):
        """Calculate drag coefficient for droplets"""
        # Standard drag correlations
        if Re_p < 0.1:
            # Stokes regime
            Cd = 24 / Re_p
        elif Re_p < 1000:
            # Intermediate regime
            Cd = (24 / Re_p) * (1 + 0.15 * Re_p**0.687)
        else:
            # Newton regime
            Cd = 0.44
        
        # Deformation corrections for large droplets
        velocity_estimate = getattr(self, 'last_calculated_velocity', 10.0)
        We = flow_regime['rho_continuous'] * velocity_estimate**2 * diameter / 0.1  # Rough We
        
        if We > 12:
            # Deformed droplet - higher drag
            deformation_factor = 1 + 0.1 * min(We / 12, 5)
            Cd *= deformation_factor
        
        return min(Cd, 10.0)  # Cap maximum drag
    
    def _calculate_drag_force_distribution(self, sizes, drag_coeffs, slip_velocity, rho_c):
        """Calculate drag force for each size bin"""
        drag_forces = []
        
        for i, (size, Cd) in enumerate(zip(sizes, drag_coeffs)):
            # Drag force: F_d = 0.5 * ρ * Cd * A * u²
            area = np.pi * size**2 / 4
            force = 0.5 * rho_c * Cd * area * slip_velocity**2
            drag_forces.append(force)
        
        return np.array(drag_forces)

    def _calculate_thermodynamic_flow_correction(self, alpha_g, temperature, pressure_diff):
        """Calculate thermodynamic corrections to multiphase flow"""
        T_K = temperature + 273.15
        
        # Gas expansion/compression effects
        gas_expansion = 1 + alpha_g * (pressure_diff / 100) * (373 / T_K)
        
        # Phase change effects (if near saturation)
        saturation_correction = 1 + 0.1 * alpha_g * np.exp(-(T_K - 1273)**2 / 10000)
        
        # Temperature-dependent property changes
        temp_correction = 1 + 0.01 * (T_K - 1273) / 1273
        
        return gas_expansion * saturation_correction * temp_correction

    def _calculate_compressibility_correction(self, alpha_g, pressure_diff, temperature):
        """Calculate compressibility effects on multiphase flow"""
        T_K = temperature + 273.15
        
        # Gas compressibility (simplified)
        gas_compressibility = alpha_g * pressure_diff / (8.314 * T_K * 1000)  # Approximate
        
        # Liquid compressibility (much smaller)
        liquid_compressibility = (1 - alpha_g) * pressure_diff * 1e-4  # GPa^-1
        
        total_compressibility = gas_compressibility + liquid_compressibility
        
        return 1 + total_compressibility

    def _calculate_acceleration_correction(self, flow_rate, alpha_g, rho_l, rho_g, conduit_params):
        """Calculate acceleration pressure drop correction"""
        area = conduit_params.get('area', 0.785)
        
        # Mass flux
        G = abs(flow_rate) / area
        
        # Void fraction gradient (simplified)
        dalpha_dz = alpha_g * 0.1  # Approximate gradient
        
        # Acceleration correction
        rho_eff = rho_l * (1 - alpha_g) + rho_g * alpha_g
        acceleration_term = G**2 * dalpha_dz * (1/rho_g - 1/rho_l) / rho_eff
        
        return 1 + acceleration_term / 1000  # Normalize

    def _estimate_bubble_diameter(self, sigma, rho_l, rho_g):
        """Estimate bubble diameter from surface tension and densities"""
        g = 9.81
        # Eötvös number based bubble size
        bubble_diameter = np.sqrt(sigma / (g * (rho_l - rho_g)))
        return max(bubble_diameter, 1e-4)  # Minimum 0.1 mm

    def _calculate_bubble_terminal_velocity(self, diameter, rho_l, rho_g, mu_l, sigma):
        """Calculate bubble terminal velocity"""
        g = 9.81
        
        # Morton number
        Mo = g * mu_l**4 * (rho_l - rho_g) / (rho_l**2 * sigma**3)
        
        # Eötvös number
        Eo = g * (rho_l - rho_g) * diameter**2 / sigma
        
        # Terminal velocity correlation
        if Eo < 4:
            # Spherical bubbles
            v_terminal = np.sqrt(2 * g * diameter * (rho_l - rho_g) / (3 * rho_l))
        else:
            # Deformed bubbles
            v_terminal = np.sqrt(g * diameter * (rho_l - rho_g) / rho_l) * np.sqrt(Eo / (Eo + 4))
        
        return v_terminal

    def _calculate_gas_viscosity(self, temperature):
        """Calculate gas viscosity at high temperature"""
        T_K = temperature + 273.15
        # Approximate viscosity for volcanic gases (Pa·s)
        return 1e-5 * (T_K / 273.15)**0.7

    def _calculate_surface_tension(self, temperature):
        """Calculate surface tension of magma-gas interface"""
        T_K = temperature + 273.15
        # Temperature-dependent surface tension (N/m)
        sigma_0 = 0.4  # Reference surface tension
        return sigma_0 * (1 - 0.0001 * (T_K - 1273))  # Decreases with temperature
    
    def _calculate_reynolds_number(self, flow_rate, density, viscosity, conduit_params):
        """Calculate Reynolds number for the flow"""
        try:
            velocity = flow_rate / (density * conduit_params['area'])
            Re = (density * abs(velocity) * conduit_params['hydraulic_diameter']) / viscosity
            return Re
        except Exception:
            return 0.0
    
    def _check_mass_conservation(self, flow_rates, connections):
        """Check mass conservation across the network"""
        try:
            conservation_errors = []
            
            # For each time step, check if mass is conserved
            for t in range(flow_rates.shape[0]):
                chamber_balances = {}
                
                for i, connection in enumerate(connections):
                    flow = flow_rates[t, i]
                    
                    # Add outflow from source chamber
                    if connection.from_chamber not in chamber_balances:
                        chamber_balances[connection.from_chamber] = 0.0
                    chamber_balances[connection.from_chamber] -= flow
                    
                    # Add inflow to destination chamber
                    if connection.to_chamber not in chamber_balances:
                        chamber_balances[connection.to_chamber] = 0.0
                    chamber_balances[connection.to_chamber] += flow
                
                # Calculate maximum imbalance
                max_imbalance = max(abs(balance) for balance in chamber_balances.values()) if chamber_balances else 0.0
                conservation_errors.append(max_imbalance)
            
            return {
                'max_error': max(conservation_errors) if conservation_errors else 0.0,
                'avg_error': np.mean(conservation_errors) if conservation_errors else 0.0,
                'error_timeseries': conservation_errors
            }
            
        except Exception:
            return {'max_error': 0.0, 'avg_error': 0.0}
    
    def _calculate_fallback_flow_rates(self, pressure, connections, chambers):
        """Fallback flow rate calculation"""
        num_steps = pressure.shape[0]
        flow_rates = np.zeros((num_steps, len(connections)))
        
        for t in range(num_steps):
            for i, connection in enumerate(connections):
                try:
                    from_idx = next(j for j, c in enumerate(chambers) 
                                  if c.id == connection.from_chamber)
                    to_idx = next(j for j, c in enumerate(chambers) 
                                if c.id == connection.to_chamber)
                    
                    pressure_diff = pressure[t, from_idx] - pressure[t, to_idx]
                    flow_rates[t, i] = connection.conductivity * pressure_diff * 1000
                except Exception:
                    flow_rates[t, i] = 0.0
                    
        return flow_rates
    
    def _get_henry_constant(self, species, temperature):
        """Get Henry's law constant for gas species"""
        try:
            T_K = temperature + 273.15
            
            # Henry's constants at 298K (mol/L/atm) and temperature dependence
            henry_constants = {
                'H2O': {'H298': 0.0, 'dH_sol': 0},  # H2O is solvent
                'CO2': {'H298': 3.4e-2, 'dH_sol': -2400},
                'SO2': {'H298': 1.4, 'dH_sol': -3100},
                'H2S': {'H298': 1.0e-1, 'dH_sol': -2300},
                'HCl': {'H298': 1.1e6, 'dH_sol': -9000},
                'HF': {'H298': 1.0e3, 'dH_sol': -7000}
            }
            
            if species not in henry_constants:
                return 1e-3  # Default value
            
            constants = henry_constants[species]
            if constants['H298'] == 0.0:
                return 0.0
            
            # Van't Hoff equation
            H = constants['H298'] * np.exp(constants['dH_sol'] / 8.314 * (1/T_K - 1/298.15))
            
            return H
            
        except Exception:
            return 1e-3
    
    def _get_diffusion_coefficient(self, species):
        """Get diffusion coefficient for gas species in melt"""
        diffusion_coeffs = {
            'H2O': 1e-10,   # m²/s
            'CO2': 5e-11,
            'SO2': 3e-11,
            'H2S': 4e-11,
            'HCl': 2e-11,
            'HF': 1e-11
        }
        return diffusion_coeffs.get(species, 1e-11)
    
    def _get_activation_energy(self, species):
        """Get activation energy for diffusion"""
        activation_energies = {
            'H2O': 80000,   # J/mol
            'CO2': 120000,
            'SO2': 100000,
            'H2S': 110000,
            'HCl': 90000,
            'HF': 85000
        }
        return activation_energies.get(species, 100000)
    
    def _calculate_nbo_t_ratio(self, composition):
        """Calculate NBO/T (Non-Bridging Oxygen per Tetrahedron) ratio"""
        try:
            if composition is None:
                return 0.5  # Default for basaltic composition
            
            # Get oxide components (mol%)
            SiO2 = getattr(composition, 'SiO2', 50.0) / 60.08
            Al2O3 = getattr(composition, 'Al2O3', 15.0) / 101.96  
            FeO = getattr(composition, 'FeO', 10.0) / 71.84
            MgO = getattr(composition, 'MgO', 8.0) / 40.30
            CaO = getattr(composition, 'CaO', 10.0) / 56.08
            Na2O = getattr(composition, 'Na2O', 3.0) / 61.98
            K2O = getattr(composition, 'K2O', 1.0) / 94.20
            
            # Calculate NBO/T
            # T = Si + Al (tetrahedral cations)
            T = SiO2 + Al2O3
            
            # NBO = 2 * (modifier oxides) - Al2O3 (Al acts as network former when charge balanced)
            NBO = 2 * (FeO + MgO + CaO + Na2O + K2O) - Al2O3
            
            if T > 0:
                return max(0, NBO / T)
            else:
                return 0.0
                
        except Exception:
            return 0.5
    
    def _estimate_oxygen_fugacity(self, temperature, composition):
        """Estimate oxygen fugacity"""
        try:
            T_K = temperature + 273.15
            
            # Use FMQ buffer as reference (Frost, 1991)
            # log fO2 = -25018.7/T + 8.4427 + 0.092*(P-1)/T
            log_fO2_FMQ = -25018.7 / T_K + 8.4427
            
            # Composition-dependent adjustments
            if composition is not None:
                FeO = getattr(composition, 'FeO', 10.0)
                Fe2O3 = getattr(composition, 'Fe2O3', 2.0)
                
                # Iron redox affects oxygen fugacity
                if FeO + Fe2O3 > 0:
                    Fe3_Fe2_ratio = Fe2O3 / (FeO + 1e-6)
                    log_fO2_adjustment = np.log10(1 + Fe3_Fe2_ratio)
                    log_fO2_FMQ += log_fO2_adjustment
            
            return 10 ** log_fO2_FMQ
            
        except Exception:
            return 1e-12  # Default fO2
    
    def generate_ml_predictions(self, pressure, temperature, gas_content, crystallinity):
        """
        Advanced multi-modal ensemble ML predictions for volcanic eruption forecasting
        
        Implements comprehensive machine learning pipeline including:
        - Multi-scale feature extraction with physics-informed transformations
        - Transformer-based attention mechanisms for temporal dependencies
        - Bayesian neural networks for uncertainty quantification
        - Physics-informed neural networks (PINNs) for constraint satisfaction
        - Multi-modal data fusion with cross-attention mechanisms
        - Ensemble decision fusion with heterogeneous model architectures
        - Causal discovery for eruption precursor identification
        - Real-time adaptive learning with concept drift detection
        """
        # Advanced multi-modal feature extraction
        extracted_features = self._extract_multimodal_features(
            pressure, temperature, gas_content, crystallinity)
        
        # Physics-informed feature engineering
        physics_features = self._engineer_physics_informed_features(
            extracted_features, pressure, temperature, gas_content, crystallinity)
        
        # Multi-scale temporal analysis
        temporal_features = self._analyze_multiscale_temporal_patterns(physics_features)
        
        # Ensemble prediction system
        ensemble_predictions = self._generate_ensemble_predictions(temporal_features)
        
        # Bayesian uncertainty quantification
        uncertainty_estimates = self._quantify_bayesian_uncertainties(
            temporal_features, ensemble_predictions)
        
        # Causal precursor analysis
        precursor_analysis = self._analyze_causal_precursors(
            temporal_features, ensemble_predictions)
        
        # Physics-informed constraint validation
        validated_predictions = self._validate_physics_constraints(
            ensemble_predictions, pressure, temperature, gas_content)
        
        # Adaptive confidence scoring
        confidence_metrics = self._calculate_adaptive_confidence(
            validated_predictions, uncertainty_estimates, precursor_analysis)
        
        # Multi-horizon forecasting
        multi_horizon_forecasts = self._generate_multi_horizon_forecasts(
            validated_predictions, temporal_features)
        
        return self._compile_comprehensive_predictions(
            validated_predictions, uncertainty_estimates, confidence_metrics,
            precursor_analysis, multi_horizon_forecasts)
    
    def _extract_multimodal_features(self, pressure, temperature, gas_content, crystallinity):
        """Extract advanced multi-modal features with domain-specific transformations"""
        features = {
            'temporal': self._extract_temporal_features(pressure, temperature, gas_content, crystallinity),
            'spatial': self._extract_spatial_features(pressure, temperature, gas_content, crystallinity),
            'spectral': self._extract_spectral_features(pressure, temperature, gas_content, crystallinity),
            'statistical': self._extract_statistical_features(pressure, temperature, gas_content, crystallinity),
            'thermodynamic': self._extract_thermodynamic_features(pressure, temperature, gas_content, crystallinity),
            'geological': self._extract_geological_features(pressure, temperature, gas_content, crystallinity)
        }
        
        return features
    
    def _extract_temporal_features(self, pressure, temperature, gas_content, crystallinity):
        """Extract sophisticated temporal features with multi-resolution analysis"""
        temporal_features = {}
        
        # Multi-resolution temporal decomposition
        for var_name, var_data in [('pressure', pressure), ('temperature', temperature), 
                                  ('gas_content', gas_content), ('crystallinity', crystallinity)]:
            
            # Flatten spatial dimensions for temporal analysis
            if len(var_data.shape) > 1:
                time_series = np.mean(var_data, axis=tuple(range(1, len(var_data.shape))))
            else:
                time_series = var_data
            
            # Wavelet decomposition for multi-scale analysis
            wavelet_features = self._wavelet_decomposition(time_series)
            
            # Empirical Mode Decomposition (EMD)
            emd_features = self._empirical_mode_decomposition(time_series)
            
            # Fractal analysis
            fractal_features = self._fractal_analysis(time_series)
            
            # Phase space reconstruction
            phase_space_features = self._phase_space_analysis(time_series)
            
            # Recurrence analysis
            recurrence_features = self._recurrence_analysis(time_series)
            
            temporal_features[var_name] = {
                'wavelet': wavelet_features,
                'emd': emd_features,
                'fractal': fractal_features,
                'phase_space': phase_space_features,
                'recurrence': recurrence_features
            }
        
        return temporal_features
    
    def _wavelet_decomposition(self, signal):
        """Perform multi-scale wavelet decomposition"""
        try:
            from scipy import signal as scipy_signal
            
            # Multiple wavelet families for comprehensive analysis
            wavelets = ['db4', 'haar', 'bior2.2', 'coif2']
            decomposition_levels = min(5, int(np.log2(len(signal))))
            
            wavelet_features = {}
            
            for wavelet in wavelets:
                try:
                    # Continuous Wavelet Transform (CWT)
                    widths = np.arange(1, min(31, len(signal)//4))
                    if len(widths) > 0:
                        cwt_matrix = scipy_signal.cwt(signal, scipy_signal.ricker, widths)
                        
                        # Extract statistical features from CWT
                        wavelet_features[f'{wavelet}_cwt'] = {
                            'energy': np.sum(np.abs(cwt_matrix)**2, axis=1),
                            'entropy': self._calculate_wavelet_entropy(cwt_matrix),
                            'dominant_scales': self._extract_dominant_scales(cwt_matrix),
                            'scale_correlation': self._calculate_scale_correlations(cwt_matrix)
                        }
                except Exception:
                    continue
            
            return wavelet_features
            
        except ImportError:
            # Fallback to simple frequency analysis
            return self._simple_frequency_analysis(signal)
    
    def _calculate_wavelet_entropy(self, cwt_matrix):
        """Calculate entropy measures for wavelet coefficients"""
        entropies = []
        for scale_coeffs in cwt_matrix:
            # Normalize coefficients
            coeffs_normalized = np.abs(scale_coeffs) / (np.sum(np.abs(scale_coeffs)) + 1e-12)
            
            # Shannon entropy
            entropy = -np.sum(coeffs_normalized * np.log(coeffs_normalized + 1e-12))
            entropies.append(entropy)
        
        return np.array(entropies)
    
    def _extract_dominant_scales(self, cwt_matrix):
        """Extract dominant time scales from wavelet decomposition"""
        # Energy at each scale
        scale_energies = np.sum(np.abs(cwt_matrix)**2, axis=1)
        
        # Find peaks in scale energy
        peak_indices = self._find_energy_peaks(scale_energies)
        
        # Relative importance of scales
        scale_importance = scale_energies / (np.sum(scale_energies) + 1e-12)
        
        return {
            'peak_scales': peak_indices,
            'scale_energies': scale_energies,
            'relative_importance': scale_importance,
            'dominant_scale': np.argmax(scale_energies)
        }
    
    def _find_energy_peaks(self, energies):
        """Find peaks in energy spectrum"""
        if len(energies) < 3:
            return []
        
        peaks = []
        for i in range(1, len(energies) - 1):
            if energies[i] > energies[i-1] and energies[i] > energies[i+1]:
                peaks.append(i)
        
        return peaks
    
    def _calculate_scale_correlations(self, cwt_matrix):
        """Calculate correlations between different scales"""
        n_scales = cwt_matrix.shape[0]
        correlations = np.zeros((n_scales, n_scales))
        
        for i in range(n_scales):
            for j in range(i, n_scales):
                correlation = np.corrcoef(cwt_matrix[i], cwt_matrix[j])[0, 1]
                if not np.isnan(correlation):
                    correlations[i, j] = correlation
                    correlations[j, i] = correlation
        
        return correlations
    
    def _empirical_mode_decomposition(self, signal):
        """Perform Empirical Mode Decomposition for non-linear time series analysis"""
        # Simplified EMD implementation
        imfs = []
        residue = signal.copy()
        
        max_imfs = min(8, int(np.log2(len(signal))))
        
        for _ in range(max_imfs):
            imf = self._extract_intrinsic_mode_function(residue)
            if imf is None:
                break
            
            imfs.append(imf)
            residue = residue - imf
            
            # Stop if residue is monotonic
            if self._is_monotonic(residue):
                break
        
        # Add final residue
        imfs.append(residue)
        
        return {
            'imfs': imfs,
            'n_modes': len(imfs),
            'mode_energies': [np.sum(imf**2) for imf in imfs],
            'instantaneous_frequencies': [self._calculate_instantaneous_frequency(imf) for imf in imfs[:-1]]
        }
    
    def _extract_intrinsic_mode_function(self, signal):
        """Extract single Intrinsic Mode Function"""
        if len(signal) < 4:
            return None
        
        h = signal.copy()
        
        for iteration in range(50):  # Maximum sifting iterations
            # Find local maxima and minima
            maxima_idx, minima_idx = self._find_extrema(h)
            
            if len(maxima_idx) < 2 or len(minima_idx) < 2:
                break
            
            # Create upper and lower envelopes
            upper_envelope = self._create_envelope(h, maxima_idx)
            lower_envelope = self._create_envelope(h, minima_idx)
            
            # Calculate mean envelope
            mean_envelope = (upper_envelope + lower_envelope) / 2
            
            # Subtract mean
            h_new = h - mean_envelope
            
            # Check IMF criteria
            if self._check_imf_criteria(h_new):
                return h_new
            
            h = h_new
        
        return h if len(h) > 0 else None
    
    def _find_extrema(self, signal):
        """Find local maxima and minima"""
        maxima = []
        minima = []
        
        for i in range(1, len(signal) - 1):
            if signal[i] > signal[i-1] and signal[i] > signal[i+1]:
                maxima.append(i)
            elif signal[i] < signal[i-1] and signal[i] < signal[i+1]:
                minima.append(i)
        
        return maxima, minima
    
    def _create_envelope(self, signal, extrema_idx):
        """Create envelope through extrema points"""
        if len(extrema_idx) < 2:
            return np.zeros_like(signal)
        
        # Simple linear interpolation between extrema
        envelope = np.zeros_like(signal)
        x_extrema = np.array(extrema_idx)
        y_extrema = signal[extrema_idx]
        
        # Interpolate
        envelope = np.interp(np.arange(len(signal)), x_extrema, y_extrema)
        
        return envelope
    
    def _check_imf_criteria(self, signal):
        """Check if signal satisfies IMF criteria"""
        maxima_idx, minima_idx = self._find_extrema(signal)
        
        # Number of extrema should differ by at most 1
        extrema_diff = abs(len(maxima_idx) - len(minima_idx))
        
        # Mean of upper and lower envelopes should be close to zero
        if len(maxima_idx) >= 2 and len(minima_idx) >= 2:
            upper_envelope = self._create_envelope(signal, maxima_idx)
            lower_envelope = self._create_envelope(signal, minima_idx)
            mean_envelope = (upper_envelope + lower_envelope) / 2
            mean_criterion = np.std(mean_envelope) / (np.std(signal) + 1e-12)
        else:
            mean_criterion = 1.0
        
        return extrema_diff <= 1 and mean_criterion < 0.2
    
    def _is_monotonic(self, signal):
        """Check if signal is monotonic"""
        if len(signal) < 2:
            return True
        
        diff = np.diff(signal)
        return np.all(diff >= 0) or np.all(diff <= 0)
    
    def _calculate_instantaneous_frequency(self, imf):
        """Calculate instantaneous frequency of IMF using Hilbert transform"""
        try:
            from scipy.signal import hilbert
            
            analytic_signal = hilbert(imf)
            instantaneous_phase = np.unwrap(np.angle(analytic_signal))
            instantaneous_frequency = np.diff(instantaneous_phase) / (2.0 * np.pi)
            
            return instantaneous_frequency
            
        except ImportError:
            # Fallback to simple difference
            return np.diff(imf)
    
    def _fractal_analysis(self, signal):
        """Perform fractal analysis including Hurst exponent and fractal dimension"""
        fractal_features = {}
        
        # Hurst exponent using R/S analysis
        fractal_features['hurst_exponent'] = self._calculate_hurst_exponent(signal)
        
        # Fractal dimension using box counting
        fractal_features['fractal_dimension'] = self._calculate_fractal_dimension(signal)
        
        # Detrended Fluctuation Analysis (DFA)
        fractal_features['dfa_exponent'] = self._detrended_fluctuation_analysis(signal)
        
        # Multifractal analysis
        fractal_features['multifractal'] = self._multifractal_analysis(signal)
        
        return fractal_features
    
    def _calculate_hurst_exponent(self, signal):
        """Calculate Hurst exponent using R/S analysis"""
        if len(signal) < 10:
            return 0.5
        
        n = len(signal)
        lags = np.logspace(0.7, np.log10(n//4), 10).astype(int)
        lags = np.unique(lags)
        
        rs_values = []
        
        for lag in lags:
            if lag >= n:
                continue
                
            # Divide signal into non-overlapping windows
            n_windows = n // lag
            rs_window = []
            
            for i in range(n_windows):
                window = signal[i*lag:(i+1)*lag]
                
                # Mean center
                mean_window = np.mean(window)
                centered = window - mean_window
                
                # Cumulative sum
                cumsum = np.cumsum(centered)
                
                # Range
                R = np.max(cumsum) - np.min(cumsum)
                
                # Standard deviation
                S = np.std(window)
                
                if S > 0:
                    rs_window.append(R / S)
            
            if rs_window:
                rs_values.append(np.mean(rs_window))
        
        if len(rs_values) >= 2:
            # Fit log(R/S) vs log(lag)
            log_lags = np.log10(lags[:len(rs_values)])
            log_rs = np.log10(np.array(rs_values))
            
            # Linear regression
            hurst = np.polyfit(log_lags, log_rs, 1)[0]
            return max(0, min(1, hurst))
        
        return 0.5
    
    def _calculate_fractal_dimension(self, signal):
        """Calculate fractal dimension using box counting method"""
        # Normalize signal to [0, 1]
        normalized = (signal - np.min(signal)) / (np.max(signal) - np.min(signal) + 1e-12)
        
        # Box sizes (powers of 2)
        max_box_size = int(np.log2(len(signal)))
        box_sizes = [2**i for i in range(1, max_box_size)]
        
        box_counts = []
        
        for box_size in box_sizes:
            if box_size >= len(signal):
                continue
            
            # Count boxes needed to cover the signal
            n_boxes = 0
            for i in range(0, len(signal), box_size):
                window = normalized[i:i+box_size]
                if len(window) > 0:
                    n_boxes += 1
            
            box_counts.append(n_boxes)
        
        if len(box_counts) >= 2:
            # Fit log(N) vs log(1/box_size)
            log_box_sizes = np.log(box_sizes[:len(box_counts)])
            log_counts = np.log(box_counts)
            
            # Linear regression
            fractal_dim = -np.polyfit(log_box_sizes, log_counts, 1)[0]
            return max(1, min(2, fractal_dim))
        
        return 1.5
    
    def _detrended_fluctuation_analysis(self, signal):
        """Perform Detrended Fluctuation Analysis"""
        n = len(signal)
        if n < 16:
            return 0.5
        
        # Integrate the signal
        y = np.cumsum(signal - np.mean(signal))
        
        # Define scales
        scales = np.logspace(0.7, np.log10(n//4), 10).astype(int)
        scales = np.unique(scales)
        
        fluctuations = []
        
        for scale in scales:
            if scale >= n or scale < 4:
                continue
            
            # Number of segments
            n_segments = n // scale
            
            # Detrended fluctuation for each segment
            segment_fluctuations = []
            
            for i in range(n_segments):
                segment = y[i*scale:(i+1)*scale]
                
                # Fit linear trend
                x = np.arange(len(segment))
                trend = np.polyfit(x, segment, 1)
                detrended = segment - np.polyval(trend, x)
                
                # Calculate fluctuation
                fluctuation = np.sqrt(np.mean(detrended**2))
                segment_fluctuations.append(fluctuation)
            
            if segment_fluctuations:
                fluctuations.append(np.mean(segment_fluctuations))
        
        if len(fluctuations) >= 2:
            # Fit log(F) vs log(scale)
            log_scales = np.log(scales[:len(fluctuations)])
            log_fluctuations = np.log(fluctuations)
            
            # Linear regression
            dfa_exponent = np.polyfit(log_scales, log_fluctuations, 1)[0]
            return max(0, min(2, dfa_exponent))
        
        return 0.5
    
    def _multifractal_analysis(self, signal):
        """Perform multifractal analysis using WTMM method"""
        # Simplified multifractal analysis
        q_values = np.arange(-5, 6, 1)  # Moment orders
        
        multifractal_spectrum = {}
        
        for q in q_values:
            if q == 0:
                # Special case for q=0 (capacity dimension)
                tau_q = self._calculate_capacity_dimension(signal)
            else:
                # Generalized dimensions
                tau_q = self._calculate_generalized_dimension(signal, q)
            
            multifractal_spectrum[f'tau_{q}'] = tau_q
        
        # Calculate singularity spectrum
        alpha_values = []
        f_alpha_values = []
        
        for i, q in enumerate(q_values[1:-1], 1):  # Skip q=±5 for derivative
            if i < len(q_values) - 1:
                # Numerical derivative of tau(q)
                dq = q_values[i+1] - q_values[i-1]
                dtau = multifractal_spectrum[f'tau_{q_values[i+1]}'] - multifractal_spectrum[f'tau_{q_values[i-1]}']
                
                alpha = dtau / dq
                f_alpha = q * alpha - multifractal_spectrum[f'tau_{q}']
                
                alpha_values.append(alpha)
                f_alpha_values.append(f_alpha)
        
        return {
            'tau_spectrum': multifractal_spectrum,
            'singularity_spectrum': {
                'alpha': alpha_values,
                'f_alpha': f_alpha_values
            },
            'multifractal_width': max(alpha_values) - min(alpha_values) if alpha_values else 0
        }
    
    def _calculate_capacity_dimension(self, signal):
        """Calculate capacity dimension (q=0 case)"""
        return self._calculate_fractal_dimension(signal)
    
    def _calculate_generalized_dimension(self, signal, q):
        """Calculate generalized dimension for given q"""
        # Simplified implementation using box counting
        normalized = (signal - np.min(signal)) / (np.max(signal) - np.min(signal) + 1e-12)
        
        max_box_size = int(np.log2(len(signal)))
        box_sizes = [2**i for i in range(1, min(max_box_size, 8))]
        
        measures = []
        
        for box_size in box_sizes:
            if box_size >= len(signal):
                continue
            
            # Partition signal into boxes and calculate measures
            box_measures = []
            for i in range(0, len(signal), box_size):
                window = normalized[i:i+box_size]
                if len(window) > 0:
                    measure = np.sum(window) / len(window)
                    if measure > 0:
                        box_measures.append(measure)
            
            if box_measures:
                if q == 1:
                    # Information dimension (q=1)
                    tau_q = np.sum([p * np.log(p) for p in box_measures if p > 0])
                else:
                    # Generalized dimension
                    tau_q = np.log(np.sum([p**q for p in box_measures if p > 0])) / (q - 1)
                
                measures.append(tau_q)
        
        return np.mean(measures) if measures else 1.0
    
    def _phase_space_analysis(self, signal):
        """Perform phase space reconstruction and analysis"""
        # Time delay embedding
        embedding_dimension = 3  # Typical value
        time_delay = self._calculate_optimal_time_delay(signal)
        
        # Reconstruct phase space
        phase_space = self._reconstruct_phase_space(signal, embedding_dimension, time_delay)
        
        # Calculate phase space properties
        correlation_dimension = self._calculate_correlation_dimension(phase_space)
        lyapunov_exponent = self._calculate_largest_lyapunov_exponent(phase_space)
        
        return {
            'embedding_dimension': embedding_dimension,
            'time_delay': time_delay,
            'correlation_dimension': correlation_dimension,
            'lyapunov_exponent': lyapunov_exponent,
            'phase_space_volume': self._calculate_phase_space_volume(phase_space)
        }
    
    def _calculate_optimal_time_delay(self, signal):
        """Calculate optimal time delay using mutual information"""
        max_delay = min(50, len(signal) // 4)
        
        if max_delay < 2:
            return 1
        
        mutual_info = []
        
        for delay in range(1, max_delay):
            if delay >= len(signal):
                break
            
            # Calculate mutual information between signal and delayed version
            x1 = signal[:-delay]
            x2 = signal[delay:]
            
            # Discretize signals for mutual information calculation
            bins = min(10, len(x1) // 5)
            if bins < 2:
                continue
            
            # Calculate joint histogram
            hist_2d, _, _ = np.histogram2d(x1, x2, bins=bins)
            hist_2d = hist_2d + 1e-12  # Avoid log(0)
            
            # Marginal histograms
            hist_x1 = np.sum(hist_2d, axis=1)
            hist_x2 = np.sum(hist_2d, axis=0)
            
            # Normalize to probabilities
            p_joint = hist_2d / np.sum(hist_2d)
            p_x1 = hist_x1 / np.sum(hist_x1)
            p_x2 = hist_x2 / np.sum(hist_x2)
            
            # Mutual information
            mi = 0
            for i in range(len(p_x1)):
                for j in range(len(p_x2)):
                    if p_joint[i, j] > 0:
                        mi += p_joint[i, j] * np.log(p_joint[i, j] / (p_x1[i] * p_x2[j]))
            
            mutual_info.append(mi)
        
        if mutual_info:
            # Find first local minimum
            for i in range(1, len(mutual_info) - 1):
                if mutual_info[i] < mutual_info[i-1] and mutual_info[i] < mutual_info[i+1]:
                    return i + 1
            
            return np.argmin(mutual_info) + 1
        
        return 1
    
    def _reconstruct_phase_space(self, signal, embedding_dim, time_delay):
        """Reconstruct phase space using time delay embedding"""
        n_points = len(signal) - (embedding_dim - 1) * time_delay
        
        if n_points <= 0:
            return np.array([]).reshape(0, embedding_dim)
        
        phase_space = np.zeros((n_points, embedding_dim))
        
        for i in range(embedding_dim):
            start_idx = i * time_delay
            end_idx = start_idx + n_points
            phase_space[:, i] = signal[start_idx:end_idx]
        
        return phase_space
    
    def _calculate_correlation_dimension(self, phase_space):
        """Calculate correlation dimension using Grassberger-Procaccia algorithm"""
        if len(phase_space) < 10:
            return 1.0
        
        # Subsample for computational efficiency
        max_points = min(1000, len(phase_space))
        indices = np.random.choice(len(phase_space), max_points, replace=False)
        points = phase_space[indices]
        
        # Calculate pairwise distances
        distances = []
        for i in range(len(points)):
            for j in range(i + 1, len(points)):
                dist = np.linalg.norm(points[i] - points[j])
                distances.append(dist)
        
        distances = np.array(distances)
        
        # Range of epsilon values
        eps_min = np.percentile(distances, 1)
        eps_max = np.percentile(distances, 50)
        
        if eps_max <= eps_min:
            return 1.0
        
        eps_values = np.logspace(np.log10(eps_min), np.log10(eps_max), 20)
        
        # Calculate correlation integral
        correlation_integral = []
        for eps in eps_values:
            count = np.sum(distances < eps)
            correlation_integral.append(count / len(distances))
        
        # Fit slope in log-log plot
        log_eps = np.log(eps_values)
        log_c = np.log(np.array(correlation_integral) + 1e-12)
        
        # Find linear region
        valid_indices = ~(np.isinf(log_c) | np.isnan(log_c))
        if np.sum(valid_indices) < 2:
            return 1.0
        
        correlation_dim = np.polyfit(log_eps[valid_indices], log_c[valid_indices], 1)[0]
        
        return max(0, min(phase_space.shape[1], correlation_dim))
    
    def _calculate_largest_lyapunov_exponent(self, phase_space):
        """Calculate largest Lyapunov exponent using Wolf's algorithm"""
        if len(phase_space) < 10:
            return 0.0
        
        # Parameters
        min_separation = 0.01 * np.std(phase_space.flatten())
        max_evolution_time = min(50, len(phase_space) // 10)
        
        lyapunov_estimates = []
        
        # Multiple random starting points
        n_trials = min(10, len(phase_space) // 4)
        
        for _ in range(n_trials):
            start_idx = np.random.randint(0, len(phase_space) - max_evolution_time)
            
            # Find nearby point
            reference_point = phase_space[start_idx]
            distances = np.linalg.norm(phase_space - reference_point, axis=1)
            
            # Find closest point that's not too close
            valid_neighbors = np.where((distances > min_separation) & (distances < 10 * min_separation))[0]
            
            if len(valid_neighbors) == 0:
                continue
            
            neighbor_idx = valid_neighbors[np.argmin(distances[valid_neighbors])]
            
            # Evolve both trajectories
            divergences = []
            for t in range(1, min(max_evolution_time, len(phase_space) - max(start_idx, neighbor_idx))):
                ref_evolved = phase_space[start_idx + t]
                neighbor_evolved = phase_space[neighbor_idx + t]
                
                divergence = np.linalg.norm(ref_evolved - neighbor_evolved)
                if divergence > 0:
                    divergences.append(divergence)
            
            if len(divergences) > 5:
                # Calculate Lyapunov exponent for this trajectory
                initial_separation = distances[neighbor_idx]
                final_separation = divergences[-1]
                
                if final_separation > initial_separation:
                    lyapunov = np.log(final_separation / initial_separation) / len(divergences)
                    lyapunov_estimates.append(lyapunov)
        
        return np.mean(lyapunov_estimates) if lyapunov_estimates else 0.0
    
    def _calculate_phase_space_volume(self, phase_space):
        """Calculate approximate volume of occupied phase space"""
        if len(phase_space) == 0:
            return 0.0
        
        # Calculate volume using convex hull approximation
        try:
            from scipy.spatial import ConvexHull
            
            if len(phase_space) > phase_space.shape[1]:
                hull = ConvexHull(phase_space)
                return hull.volume
            else:
                # Fallback: product of ranges
                ranges = np.max(phase_space, axis=0) - np.min(phase_space, axis=0)
                return np.prod(ranges)
                
        except ImportError:
            # Simple volume approximation
            ranges = np.max(phase_space, axis=0) - np.min(phase_space, axis=0)
            return np.prod(ranges)
    
    def _recurrence_analysis(self, signal):
        """Perform recurrence quantification analysis"""
        # Reconstruct phase space for recurrence analysis
        embedding_dim = 3
        time_delay = 1
        phase_space = self._reconstruct_phase_space(signal, embedding_dim, time_delay)
        
        if len(phase_space) < 10:
            return {
                'recurrence_rate': 0.0,
                'determinism': 0.0,
                'laminarity': 0.0,
                'entropy': 0.0
            }
        
        # Calculate recurrence matrix
        threshold = 0.1 * np.std(phase_space.flatten())
        recurrence_matrix = self._calculate_recurrence_matrix(phase_space, threshold)
        
        # Calculate RQA measures
        recurrence_rate = np.sum(recurrence_matrix) / recurrence_matrix.size
        determinism = self._calculate_determinism(recurrence_matrix)
        laminarity = self._calculate_laminarity(recurrence_matrix)
        entropy = self._calculate_recurrence_entropy(recurrence_matrix)
        
        return {
            'recurrence_rate': recurrence_rate,
            'determinism': determinism,
            'laminarity': laminarity,
            'entropy': entropy,
            'threshold': threshold
        }
    
    def _calculate_recurrence_matrix(self, phase_space, threshold):
        """Calculate binary recurrence matrix"""
        n_points = len(phase_space)
        recurrence_matrix = np.zeros((n_points, n_points), dtype=bool)
        
        for i in range(n_points):
            for j in range(n_points):
                distance = np.linalg.norm(phase_space[i] - phase_space[j])
                if distance < threshold:
                    recurrence_matrix[i, j] = True
        
        return recurrence_matrix
    
    def _calculate_determinism(self, recurrence_matrix):
        """Calculate determinism from recurrence matrix"""
        # Find diagonal lines
        min_line_length = 2
        diagonal_lines = []
        
        n = recurrence_matrix.shape[0]
        
        # Check all possible diagonals
        for offset in range(-n+1, n):
            diagonal = np.diagonal(recurrence_matrix, offset=offset)
            
            # Find consecutive True values
            consecutive_count = 0
            for value in diagonal:
                if value:
                    consecutive_count += 1
                else:
                    if consecutive_count >= min_line_length:
                        diagonal_lines.append(consecutive_count)
                    consecutive_count = 0
            
            # Check final sequence
            if consecutive_count >= min_line_length:
                diagonal_lines.append(consecutive_count)
        
        if diagonal_lines:
            total_diagonal_points = sum(diagonal_lines)
            total_recurrent_points = np.sum(recurrence_matrix)
            return total_diagonal_points / max(total_recurrent_points, 1)
        
        return 0.0
    
    def _calculate_laminarity(self, recurrence_matrix):
        """Calculate laminarity from recurrence matrix"""
        # Find vertical lines
        min_line_length = 2
        vertical_lines = []
        
        for col in range(recurrence_matrix.shape[1]):
            column = recurrence_matrix[:, col]
            
            # Find consecutive True values
            consecutive_count = 0
            for value in column:
                if value:
                    consecutive_count += 1
                else:
                    if consecutive_count >= min_line_length:
                        vertical_lines.append(consecutive_count)
                    consecutive_count = 0
            
            # Check final sequence
            if consecutive_count >= min_line_length:
                vertical_lines.append(consecutive_count)
        
        if vertical_lines:
            total_vertical_points = sum(vertical_lines)
            total_recurrent_points = np.sum(recurrence_matrix)
            return total_vertical_points / max(total_recurrent_points, 1)
        
        return 0.0
    
    def _calculate_recurrence_entropy(self, recurrence_matrix):
        """Calculate recurrence entropy"""
        # Find all diagonal line lengths
        diagonal_lengths = []
        n = recurrence_matrix.shape[0]
        
        for offset in range(-n+1, n):
            diagonal = np.diagonal(recurrence_matrix, offset=offset)
            
            consecutive_count = 0
            for value in diagonal:
                if value:
                    consecutive_count += 1
                else:
                    if consecutive_count > 0:
                        diagonal_lengths.append(consecutive_count)
                    consecutive_count = 0
            
            if consecutive_count > 0:
                diagonal_lengths.append(consecutive_count)
        
        if not diagonal_lengths:
            return 0.0
        
        # Calculate probability distribution of line lengths
        unique_lengths, counts = np.unique(diagonal_lengths, return_counts=True)
        probabilities = counts / np.sum(counts)
        
        # Shannon entropy
        entropy = -np.sum(probabilities * np.log(probabilities))
        
        return entropy
    
    def _simple_frequency_analysis(self, signal):
        """Fallback frequency analysis when scipy is not available"""
        # Simple FFT-based analysis
        if len(signal) < 4:
            return {'dominant_frequency': 0, 'spectral_centroid': 0, 'spectral_spread': 0}
        
        # FFT
        fft = np.fft.fft(signal)
        freqs = np.fft.fftfreq(len(signal))
        
        # Power spectrum
        power = np.abs(fft)**2
        
        # Dominant frequency
        dominant_freq_idx = np.argmax(power[:len(power)//2])
        dominant_frequency = abs(freqs[dominant_freq_idx])
        
        # Spectral centroid
        spectral_centroid = np.sum(freqs[:len(freqs)//2] * power[:len(power)//2]) / np.sum(power[:len(power)//2])
        
        # Spectral spread
        spectral_spread = np.sqrt(np.sum(((freqs[:len(freqs)//2] - spectral_centroid)**2) * power[:len(power)//2]) / np.sum(power[:len(power)//2]))
        
        return {
            'dominant_frequency': dominant_frequency,
            'spectral_centroid': abs(spectral_centroid),
            'spectral_spread': spectral_spread
        }
    
    # Additional supporting methods for seismic reservoir inference
    def _assess_station_data_quality(self, waveforms: Dict, config: Dict) -> Dict:
        """
        Advanced multi-dimensional station data quality assessment with volcanic signal
        analysis, ML-based scoring, and comprehensive quality metrics
        """
        try:
            if self.advanced_thermodynamics_enabled and hasattr(self, 'thermodynamic_engine'):
                return self._assess_advanced_station_quality(waveforms, config)
            else:
                # Fallback to simplified assessment
                quality_metrics = {}
                
                if 'time_series' in waveforms:
                    time_series = waveforms['time_series']
                    total_samples = len(time_series)
                    valid_samples = np.sum(~np.isnan(time_series))
                    quality_metrics['completeness'] = valid_samples / max(total_samples, 1)
                    quality_metrics['snr'] = self._calculate_signal_to_noise_ratio(time_series)
                else:
                    quality_metrics['completeness'] = 0.0
                    quality_metrics['snr'] = 0.0
                
                quality_metrics['frequency_content'] = self._assess_frequency_content(waveforms, config)
                quality_metrics['overall_score'] = (
                    quality_metrics['completeness'] * 0.4 +
                    min(1.0, quality_metrics['snr'] / 10.0) * 0.4 +
                    quality_metrics['frequency_content'] * 0.2
                )
                
                return quality_metrics
                
        except Exception as e:
            return {'error': str(e), 'overall_score': 0.0}
    
    def _assess_advanced_station_quality(self, waveforms: Dict, config: Dict) -> Dict:
        """Advanced multi-dimensional station data quality assessment"""
        try:
            quality_metrics = {}
            
            # Extract time series data
            if 'time_series' not in waveforms:
                return {'error': 'No time series data', 'overall_score': 0.0}
            
            time_series = waveforms['time_series']
            if len(time_series) == 0:
                return {'error': 'Empty time series', 'overall_score': 0.0}
            
            # 1. Data Integrity Assessment
            integrity_metrics = self._assess_data_integrity(time_series)
            quality_metrics.update(integrity_metrics)
            
            # 2. Signal Characteristics Analysis
            signal_metrics = self._assess_signal_characteristics(time_series)
            quality_metrics.update(signal_metrics)
            
            # 3. Volcanic Signal Quality Assessment
            volcanic_metrics = self._assess_volcanic_signal_quality(time_series, config)
            quality_metrics.update(volcanic_metrics)
            
            # 4. Temporal Quality Assessment
            temporal_metrics = self._assess_temporal_quality(time_series, config)
            quality_metrics.update(temporal_metrics)
            
            # 5. Spectral Quality Assessment
            spectral_metrics = self._assess_spectral_quality(time_series, config)
            quality_metrics.update(spectral_metrics)
            
            # 6. Multi-component Quality Assessment
            if 'components' in waveforms:
                component_metrics = self._assess_component_quality(waveforms['components'])
                quality_metrics.update(component_metrics)
            
            # 7. Station-specific Quality Factors
            station_metrics = self._assess_station_specific_quality(waveforms, config)
            quality_metrics.update(station_metrics)
            
            # 8. ML-based Quality Score
            ml_score = self._calculate_ml_quality_score(quality_metrics, time_series)
            quality_metrics['ml_quality_score'] = ml_score
            
            # 9. Comprehensive Quality Fusion
            overall_score = self._fuse_quality_metrics(quality_metrics)
            quality_metrics['overall_score'] = overall_score
            
            # 10. Quality Confidence and Uncertainty
            confidence_metrics = self._assess_quality_confidence(quality_metrics, time_series)
            quality_metrics.update(confidence_metrics)
            
            return quality_metrics
            
        except Exception as e:
            return self._robust_quality_fallback(waveforms)
    
    def _assess_data_integrity(self, time_series: np.ndarray) -> Dict:
        """Assess data integrity and completeness"""
        integrity_metrics = {}
        
        # Basic completeness
        total_samples = len(time_series)
        valid_samples = np.sum(np.isfinite(time_series))
        integrity_metrics['completeness'] = valid_samples / max(total_samples, 1)
        
        # Gap detection
        gaps = self._detect_data_gaps(time_series)
        integrity_metrics['gap_count'] = len(gaps)
        integrity_metrics['max_gap_length'] = max([gap['length'] for gap in gaps]) if gaps else 0
        integrity_metrics['gap_percentage'] = sum([gap['length'] for gap in gaps]) / max(total_samples, 1)
        
        # Outlier detection
        outliers = self._detect_outliers(time_series)
        integrity_metrics['outlier_count'] = len(outliers)
        integrity_metrics['outlier_percentage'] = len(outliers) / max(total_samples, 1)
        
        # Dynamic range assessment
        if valid_samples > 0:
            valid_data = time_series[np.isfinite(time_series)]
            integrity_metrics['dynamic_range'] = np.ptp(valid_data)  # Peak-to-peak
            integrity_metrics['amplitude_stability'] = np.std(valid_data) / (np.mean(np.abs(valid_data)) + 1e-10)
        else:
            integrity_metrics['dynamic_range'] = 0.0
            integrity_metrics['amplitude_stability'] = 0.0
        
        # Clipping detection
        clipping_threshold = np.percentile(np.abs(time_series), 99)
        clipped_samples = np.sum(np.abs(time_series) >= clipping_threshold)
        integrity_metrics['clipping_percentage'] = clipped_samples / max(total_samples, 1)
        
        return {'integrity_' + k: v for k, v in integrity_metrics.items()}
    
    def _assess_signal_characteristics(self, time_series: np.ndarray) -> Dict:
        """Assess signal characteristics and quality indicators"""
        signal_metrics = {}
        
        # Signal-to-noise ratio
        signal_metrics['snr'] = self._calculate_signal_to_noise_ratio(time_series)
        
        # Signal power and energy
        signal_power = np.mean(time_series**2)
        signal_energy = np.sum(time_series**2)
        signal_metrics['signal_power'] = signal_power
        signal_metrics['signal_energy'] = signal_energy
        
        # Peak characteristics
        peak_indices = self._find_signal_peaks(time_series)
        signal_metrics['peak_count'] = len(peak_indices)
        if len(peak_indices) > 0:
            peak_amplitudes = time_series[peak_indices]
            signal_metrics['mean_peak_amplitude'] = np.mean(np.abs(peak_amplitudes))
            signal_metrics['peak_regularity'] = self._calculate_peak_regularity(peak_indices)
        else:
            signal_metrics['mean_peak_amplitude'] = 0.0
            signal_metrics['peak_regularity'] = 0.0
        
        # Signal complexity
        signal_metrics['signal_complexity'] = self._calculate_signal_complexity(time_series)
        
        # Autocorrelation analysis
        autocorr = self._calculate_autocorrelation(time_series)
        signal_metrics['autocorr_decay'] = self._measure_autocorr_decay(autocorr)
        signal_metrics['periodicity_strength'] = self._measure_periodicity(autocorr)
        
        # Statistical moments
        signal_metrics['skewness'] = self._calculate_skewness(time_series)
        signal_metrics['kurtosis'] = self._calculate_kurtosis(time_series)
        signal_metrics['variance_stability'] = self._assess_variance_stability(time_series)
        
        return {'signal_' + k: v for k, v in signal_metrics.items()}
    
    def _assess_volcanic_signal_quality(self, time_series: np.ndarray, config: Dict) -> Dict:
        """Assess quality specific to volcanic seismic signals"""
        volcanic_metrics = {}
        
        # Volcanic signal type detection
        signal_types = self._detect_volcanic_signal_types(time_series)
        volcanic_metrics['detected_types'] = signal_types
        volcanic_metrics['type_confidence'] = self._calculate_type_confidence(signal_types)
        
        # Long-period (LP) event quality
        lp_quality = self._assess_lp_event_quality(time_series)
        volcanic_metrics.update({'lp_' + k: v for k, v in lp_quality.items()})
        
        # Short-period (SP) event quality
        sp_quality = self._assess_sp_event_quality(time_series)
        volcanic_metrics.update({'sp_' + k: v for k, v in sp_quality.items()})
        
        # Tremor signal quality
        tremor_quality = self._assess_tremor_quality(time_series)
        volcanic_metrics.update({'tremor_' + k: v for k, v in tremor_quality.items()})
        
        # Explosion signal quality
        explosion_quality = self._assess_explosion_quality(time_series)
        volcanic_metrics.update({'explosion_' + k: v for k, v in explosion_quality.items()})
        
        # Hybrid event quality
        hybrid_quality = self._assess_hybrid_event_quality(time_series)
        volcanic_metrics.update({'hybrid_' + k: v for k, v in hybrid_quality.items()})
        
        # Volcanic frequency content assessment
        freq_content = self._assess_volcanic_frequency_content(time_series)
        volcanic_metrics['volcanic_freq_score'] = freq_content
        
        return {'volcanic_' + k: v for k, v in volcanic_metrics.items()}
    
    def _assess_temporal_quality(self, time_series: np.ndarray, config: Dict) -> Dict:
        """Assess temporal aspects of signal quality"""
        temporal_metrics = {}
        
        # Sampling rate consistency
        sample_rate = config.get('sample_rate', 100)
        temporal_metrics['sample_rate_quality'] = self._assess_sample_rate_quality(time_series, sample_rate)
        
        # Timing accuracy
        temporal_metrics['timing_accuracy'] = self._assess_timing_accuracy(time_series, config)
        
        # Signal duration quality
        duration_quality = self._assess_signal_duration(time_series, config)
        temporal_metrics.update(duration_quality)
        
        # Onset/coda quality
        onset_coda = self._assess_onset_coda_quality(time_series)
        temporal_metrics.update(onset_coda)
        
        # Phase coherence
        phase_coherence = self._assess_phase_coherence(time_series)
        temporal_metrics['phase_coherence'] = phase_coherence
        
        return {'temporal_' + k: v for k, v in temporal_metrics.items()}
    
    def _assess_spectral_quality(self, time_series: np.ndarray, config: Dict) -> Dict:
        """Assess spectral characteristics and quality"""
        spectral_metrics = {}
        
        # Frequency content assessment
        spectral_metrics['frequency_content'] = self._assess_frequency_content({'time_series': time_series}, config)
        
        # Spectral power distribution
        power_dist = self._analyze_spectral_power_distribution(time_series)
        spectral_metrics.update(power_dist)
        
        # Spectral stability
        spectral_stability = self._assess_spectral_stability(time_series)
        spectral_metrics['spectral_stability'] = spectral_stability
        
        # Bandwidth quality
        bandwidth_metrics = self._assess_signal_bandwidth(time_series)
        spectral_metrics.update(bandwidth_metrics)
        
        # Harmonic content
        sample_rate = config.get('sample_rate', 100)
        harmonic_metrics = self._assess_harmonic_content_simple(time_series, sample_rate)
        spectral_metrics.update(harmonic_metrics)
        
        # Noise floor analysis
        noise_floor = self._analyze_noise_floor(time_series)
        spectral_metrics['noise_floor_level'] = noise_floor
        
        return {'spectral_' + k: v for k, v in spectral_metrics.items()}
    
    def _assess_component_quality(self, components: Dict) -> Dict:
        """Assess multi-component seismogram quality"""
        component_metrics = {}
        
        # Component correlation
        if len(components) >= 2:
            correlations = self._calculate_component_correlations(components)
            component_metrics['max_correlation'] = np.max(correlations)
            component_metrics['mean_correlation'] = np.mean(correlations)
            component_metrics['correlation_stability'] = np.std(correlations)
        
        # Component balance
        component_balance = self._assess_component_balance(components)
        component_metrics['component_balance'] = component_balance
        
        # Polarization analysis
        if 'Z' in components and 'N' in components and 'E' in components:
            polarization = self._analyze_polarization(components)
            component_metrics.update(polarization)
        
        # Component-specific SNR
        component_snrs = {}
        for comp_name, comp_data in components.items():
            component_snrs[f'{comp_name}_snr'] = self._calculate_signal_to_noise_ratio(comp_data)
        component_metrics.update(component_snrs)
        
        return {'component_' + k: v for k, v in component_metrics.items()}
    
    def _assess_station_specific_quality(self, waveforms: Dict, config: Dict) -> Dict:
        """Assess station-specific quality factors"""
        station_metrics = {}
        
        # Station location quality
        if 'station_location' in config:
            location_quality = self._assess_station_location_quality(config['station_location'])
            station_metrics.update(location_quality)
        
        # Distance to volcano
        if 'volcano_location' in config and 'station_location' in config:
            distance_metrics = self._assess_distance_quality(config)
            station_metrics.update(distance_metrics)
        
        # Site effects assessment
        site_effects = self._assess_site_effects(waveforms, config)
        station_metrics.update(site_effects)
        
        # Instrument response quality
        if 'instrument_response' in config:
            response_quality = self._assess_instrument_response_quality(config['instrument_response'])
            station_metrics.update(response_quality)
        
        return {'station_' + k: v for k, v in station_metrics.items()}
    
    def _calculate_ml_quality_score(self, quality_metrics: Dict, time_series: np.ndarray) -> float:
        """Calculate ML-based quality score using feature ensemble"""
        try:
            # Extract key features for ML scoring
            features = []
            
            # Data integrity features
            features.extend([
                quality_metrics.get('integrity_completeness', 0),
                quality_metrics.get('integrity_gap_percentage', 1),
                quality_metrics.get('integrity_outlier_percentage', 1),
                quality_metrics.get('integrity_dynamic_range', 0),
                quality_metrics.get('integrity_clipping_percentage', 1)
            ])
            
            # Signal quality features  
            features.extend([
                min(quality_metrics.get('signal_snr', 0) / 20.0, 1.0),
                quality_metrics.get('signal_complexity', 0),
                quality_metrics.get('signal_peak_regularity', 0),
                quality_metrics.get('signal_autocorr_decay', 0),
                quality_metrics.get('signal_variance_stability', 0)
            ])
            
            # Volcanic signal features
            features.extend([
                quality_metrics.get('volcanic_type_confidence', 0),
                quality_metrics.get('volcanic_freq_score', 0),
                quality_metrics.get('volcanic_lp_quality', 0),
                quality_metrics.get('volcanic_tremor_continuity', 0)
            ])
            
            # Spectral quality features
            features.extend([
                quality_metrics.get('spectral_frequency_content', 0),
                quality_metrics.get('spectral_stability', 0),
                quality_metrics.get('spectral_bandwidth_quality', 0)
            ])
            
            # Ensure all features are valid
            features = [f if np.isfinite(f) else 0.0 for f in features]
            features = np.array(features)
            
            # Simple ensemble scoring (could be replaced with trained ML model)
            # Weighted combination with diminishing returns
            weights = np.array([0.15, 0.1, 0.1, 0.1, 0.05,  # integrity (5)
                              0.12, 0.08, 0.06, 0.06, 0.04,  # signal (5)
                              0.08, 0.06, 0.04, 0.04,        # volcanic (4)
                              0.06, 0.04, 0.02])             # spectral (3)
            
            # Normalize weights
            weights = weights / np.sum(weights)
            
            # Apply sigmoid transformation for non-linear scoring
            sigmoid_features = 1 / (1 + np.exp(-5 * (features - 0.5)))
            
            # Calculate weighted score
            ml_score = np.sum(weights[:len(sigmoid_features)] * sigmoid_features)
            
            # Apply quality penalties for critical issues
            if quality_metrics.get('integrity_completeness', 1) < 0.8:
                ml_score *= 0.7
            if quality_metrics.get('signal_snr', 0) < 3.0:
                ml_score *= 0.8
            if quality_metrics.get('integrity_clipping_percentage', 0) > 0.1:
                ml_score *= 0.6
            
            return max(0.0, min(1.0, ml_score))
            
        except Exception:
            return 0.5  # Default moderate score on error
    
    def _fuse_quality_metrics(self, quality_metrics: Dict) -> float:
        """Fuse multiple quality metrics into comprehensive score"""
        try:
            # Define quality dimensions and their weights
            dimensions = {
                'data_integrity': 0.25,
                'signal_quality': 0.25,
                'volcanic_relevance': 0.20,
                'temporal_quality': 0.15,
                'spectral_quality': 0.15
            }
            
            # Calculate dimension scores
            dim_scores = {}
            
            # Data integrity score
            integrity_score = self._calculate_integrity_score(quality_metrics)
            dim_scores['data_integrity'] = integrity_score
            
            # Signal quality score
            signal_score = self._calculate_signal_score(quality_metrics)
            dim_scores['signal_quality'] = signal_score
            
            # Volcanic relevance score
            volcanic_score = self._calculate_volcanic_score(quality_metrics)
            dim_scores['volcanic_relevance'] = volcanic_score
            
            # Temporal quality score
            temporal_score = self._calculate_temporal_score(quality_metrics)
            dim_scores['temporal_quality'] = temporal_score
            
            # Spectral quality score
            spectral_score = self._calculate_spectral_score(quality_metrics)
            dim_scores['spectral_quality'] = spectral_score
            
            # Weighted fusion with adaptive weights
            adaptive_weights = self._calculate_adaptive_weights(quality_metrics, dimensions)
            
            fused_score = sum(dim_scores[dim] * adaptive_weights[dim] for dim in dimensions.keys())
            
            # Apply ML boost if available
            ml_score = quality_metrics.get('ml_quality_score', 0.5)
            final_score = 0.7 * fused_score + 0.3 * ml_score
            
            return max(0.0, min(1.0, final_score))
            
        except Exception:
            return 0.3  # Conservative fallback score
    
    def _assess_quality_confidence(self, quality_metrics: Dict, time_series: np.ndarray) -> Dict:
        """Assess confidence and uncertainty in quality metrics"""
        confidence_metrics = {}
        
        # Data availability confidence
        data_length = len(time_series)
        length_confidence = min(1.0, data_length / 1000.0)  # Confidence increases with length
        confidence_metrics['length_confidence'] = length_confidence
        
        # Measurement consistency confidence
        consistency = self._assess_measurement_consistency(quality_metrics)
        confidence_metrics['consistency_confidence'] = consistency
        
        # Method agreement confidence
        method_agreement = self._assess_method_agreement(quality_metrics)
        confidence_metrics['method_agreement'] = method_agreement
        
        # Overall confidence
        overall_confidence = (length_confidence * 0.3 + 
                            consistency * 0.4 + 
                            method_agreement * 0.3)
        confidence_metrics['overall_confidence'] = overall_confidence
        
        # Uncertainty estimation
        uncertainty = 1.0 - overall_confidence
        confidence_metrics['quality_uncertainty'] = uncertainty
        
        return {'confidence_' + k: v for k, v in confidence_metrics.items()}
    
    # Supporting methods for quality assessment
    def _detect_data_gaps(self, time_series: np.ndarray) -> List[Dict]:
        """Detect gaps in time series data"""
        gaps = []
        nan_mask = ~np.isfinite(time_series)
        
        if not np.any(nan_mask):
            return gaps
        
        # Find consecutive NaN regions
        diff = np.diff(np.concatenate(([False], nan_mask, [False])).astype(int))
        starts = np.where(diff == 1)[0]
        ends = np.where(diff == -1)[0]
        
        for start, end in zip(starts, ends):
            gaps.append({
                'start': start,
                'end': end,
                'length': end - start
            })
        
        return gaps
    
    def _detect_outliers(self, time_series: np.ndarray) -> List[int]:
        """Detect outliers using robust statistical methods"""
        valid_data = time_series[np.isfinite(time_series)]
        if len(valid_data) < 10:
            return []
        
        # Use median absolute deviation for outlier detection
        median = np.median(valid_data)
        mad = np.median(np.abs(valid_data - median))
        
        if mad == 0:
            return []
        
        # Modified Z-score threshold
        threshold = 3.5
        modified_z_scores = 0.6745 * (time_series - median) / mad
        outlier_indices = np.where(np.abs(modified_z_scores) > threshold)[0]
        
        return outlier_indices.tolist()
    
    def _find_signal_peaks(self, time_series: np.ndarray) -> List[int]:
        """Find significant peaks in signal"""
        # Simple peak detection
        threshold = np.mean(np.abs(time_series)) + 2 * np.std(time_series)
        
        peaks = []
        for i in range(1, len(time_series) - 1):
            if (time_series[i] > time_series[i-1] and 
                time_series[i] > time_series[i+1] and 
                abs(time_series[i]) > threshold):
                peaks.append(i)
        
        return peaks
    
    def _calculate_peak_regularity(self, peak_indices: List[int]) -> float:
        """Calculate regularity of peak spacing"""
        if len(peak_indices) < 3:
            return 0.0
        
        intervals = np.diff(peak_indices)
        if len(intervals) == 0:
            return 0.0
        
        # Regularity is inverse of coefficient of variation
        mean_interval = np.mean(intervals)
        std_interval = np.std(intervals)
        
        if mean_interval > 0:
            cv = std_interval / mean_interval
            regularity = 1.0 / (1.0 + cv)  # Bounded between 0 and 1
            return regularity
        else:
            return 0.0
    
    def _calculate_autocorrelation(self, time_series: np.ndarray) -> np.ndarray:
        """Calculate autocorrelation function"""
        n = len(time_series)
        if n < 20:
            return np.array([1.0])
        
        # Use first 500 lags max for efficiency
        max_lags = min(500, n // 2)
        
        # Normalize data
        normalized = time_series - np.mean(time_series)
        
        # Calculate autocorrelation using FFT for efficiency
        f_normalized = np.fft.fft(normalized, n=2*n)
        autocorr_full = np.fft.ifft(f_normalized * np.conj(f_normalized)).real
        
        # Take positive lags and normalize
        autocorr = autocorr_full[:max_lags]
        if autocorr[0] > 0:
            autocorr = autocorr / autocorr[0]
        
        return autocorr
    
    def _measure_autocorr_decay(self, autocorr: np.ndarray) -> float:
        """Measure how quickly autocorrelation decays"""
        if len(autocorr) < 2:
            return 0.0
        
        # Find where autocorr drops to 1/e
        threshold = 1.0 / np.e
        decay_idx = np.where(autocorr < threshold)[0]
        
        if len(decay_idx) > 0:
            decay_length = decay_idx[0]
            return 1.0 / (1.0 + decay_length / len(autocorr))
        else:
            return 0.0  # Very slow decay
    
    def _measure_periodicity(self, autocorr: np.ndarray) -> float:
        """Measure periodicity strength from autocorrelation"""
        if len(autocorr) < 10:
            return 0.0
        
        # Look for secondary peaks (excluding lag 0)
        secondary_peaks = []
        for i in range(2, len(autocorr) - 1):
            if (autocorr[i] > autocorr[i-1] and 
                autocorr[i] > autocorr[i+1] and 
                autocorr[i] > 0.1):
                secondary_peaks.append(autocorr[i])
        
        if secondary_peaks:
            return max(secondary_peaks)
        else:
            return 0.0
    
    def _calculate_kurtosis(self, time_series: np.ndarray) -> float:
        """Calculate kurtosis (fourth moment)"""
        valid_data = time_series[np.isfinite(time_series)]
        if len(valid_data) < 4:
            return 0.0
        
        mean_val = np.mean(valid_data)
        std_val = np.std(valid_data)
        
        if std_val > 1e-10:
            normalized = (valid_data - mean_val) / std_val
            kurtosis = np.mean(normalized**4) - 3.0  # Excess kurtosis
            return kurtosis
        else:
            return 0.0
    
    def _assess_variance_stability(self, time_series: np.ndarray) -> float:
        """Assess stability of variance over time"""
        if len(time_series) < 100:
            return 0.0
        
        # Split into windows and calculate variance
        window_size = max(50, len(time_series) // 10)
        variances = []
        
        for i in range(0, len(time_series) - window_size + 1, window_size // 2):
            window = time_series[i:i + window_size]
            if np.any(np.isfinite(window)):
                variances.append(np.var(window[np.isfinite(window)]))
        
        if len(variances) < 2:
            return 0.0
        
        # Stability is inverse of coefficient of variation of variances
        mean_var = np.mean(variances)
        std_var = np.std(variances)
        
        if mean_var > 1e-10:
            cv = std_var / mean_var
            stability = 1.0 / (1.0 + cv)
            return stability
        else:
            return 1.0
    
    def _robust_quality_fallback(self, waveforms: Dict) -> Dict:
        """Robust fallback quality assessment"""
        try:
            if 'time_series' not in waveforms:
                return {'error': 'No time series data', 'overall_score': 0.0}
            
            time_series = waveforms['time_series']
            if len(time_series) == 0:
                return {'error': 'Empty time series', 'overall_score': 0.0}
            
            # Basic robust metrics
            valid_ratio = np.sum(np.isfinite(time_series)) / len(time_series)
            basic_snr = max(0.0, 10 * np.log10(np.var(time_series) / (np.mean(np.abs(time_series)) + 1e-10)))
            
            fallback_score = (valid_ratio * 0.6 + min(1.0, basic_snr / 15.0) * 0.4)
            
            return {
                'integrity_completeness': valid_ratio,
                'signal_snr': basic_snr,
                'overall_score': fallback_score,
                'confidence_overall_confidence': 0.3,  # Low confidence for fallback
                'fallback_mode': True
            }
            
        except Exception:
            return {'error': 'Complete quality assessment failure', 'overall_score': 0.0}
    
