    # Quality score calculation methods
    def _calculate_integrity_score(self, quality_metrics: Dict) -> float:
        """Calculate data integrity dimension score"""
        completeness = quality_metrics.get('integrity_completeness', 0)
        gap_penalty = 1.0 - quality_metrics.get('integrity_gap_percentage', 0)
        outlier_penalty = 1.0 - quality_metrics.get('integrity_outlier_percentage', 0)
        clipping_penalty = 1.0 - quality_metrics.get('integrity_clipping_percentage', 0)
        
        integrity_score = (completeness * 0.4 + gap_penalty * 0.3 + 
                         outlier_penalty * 0.15 + clipping_penalty * 0.15)
        return max(0.0, min(1.0, integrity_score))
    
    def _calculate_signal_score(self, quality_metrics: Dict) -> float:
        """Calculate signal quality dimension score"""
        snr_score = min(1.0, quality_metrics.get('signal_snr', 0) / 15.0)
        complexity_score = quality_metrics.get('signal_complexity', 0)
        peak_score = quality_metrics.get('signal_peak_regularity', 0)
        stability_score = quality_metrics.get('signal_variance_stability', 0)
        
        signal_score = (snr_score * 0.4 + complexity_score * 0.2 + 
                       peak_score * 0.2 + stability_score * 0.2)
        return max(0.0, min(1.0, signal_score))
    
    def _calculate_volcanic_score(self, quality_metrics: Dict) -> float:
        """Calculate volcanic relevance dimension score"""
        type_confidence = quality_metrics.get('volcanic_type_confidence', 0)
        freq_score = quality_metrics.get('volcanic_freq_score', 0)
        lp_quality = quality_metrics.get('volcanic_lp_quality', 0)
        tremor_quality = quality_metrics.get('volcanic_tremor_continuity', 0)
        
        volcanic_score = (type_confidence * 0.3 + freq_score * 0.3 + 
                         lp_quality * 0.2 + tremor_quality * 0.2)
        return max(0.0, min(1.0, volcanic_score))
    
    def _calculate_temporal_score(self, quality_metrics: Dict) -> float:
        """Calculate temporal quality dimension score"""
        sample_rate_quality = quality_metrics.get('temporal_sample_rate_quality', 0)
        timing_accuracy = quality_metrics.get('temporal_timing_accuracy', 0)
        duration_adequacy = quality_metrics.get('temporal_duration_adequacy', 0)
        phase_coherence = quality_metrics.get('temporal_phase_coherence', 0)
        
        temporal_score = (sample_rate_quality * 0.3 + timing_accuracy * 0.3 + 
                         duration_adequacy * 0.2 + phase_coherence * 0.2)
        return max(0.0, min(1.0, temporal_score))
    
    def _calculate_spectral_score(self, quality_metrics: Dict) -> float:
        """Calculate spectral quality dimension score"""
        freq_content = quality_metrics.get('spectral_frequency_content', 0)
        spectral_stability = quality_metrics.get('spectral_spectral_stability', 0)
        bandwidth_quality = quality_metrics.get('spectral_bandwidth_quality', 0)
        
        spectral_score = (freq_content * 0.4 + spectral_stability * 0.3 + 
                         bandwidth_quality * 0.3)
        return max(0.0, min(1.0, spectral_score))
    
    def _calculate_adaptive_weights(self, quality_metrics: Dict, base_weights: Dict) -> Dict:
        """Calculate adaptive weights based on signal characteristics"""
        adaptive_weights = base_weights.copy()
        
        # Boost volcanic weight if strong volcanic signals detected
        volcanic_confidence = quality_metrics.get('volcanic_type_confidence', 0)
        if volcanic_confidence > 0.7:
            adaptive_weights['volcanic_relevance'] *= 1.3
            adaptive_weights['spectral_quality'] *= 1.1
        
        # Boost signal quality weight if high SNR
        snr = quality_metrics.get('signal_snr', 0)
        if snr > 15.0:
            adaptive_weights['signal_quality'] *= 1.2
        
        # Boost integrity weight if data issues detected
        completeness = quality_metrics.get('integrity_completeness', 1)
        if completeness < 0.8:
            adaptive_weights['data_integrity'] *= 1.4
        
        # Normalize weights
        total_weight = sum(adaptive_weights.values())
        for key in adaptive_weights:
            adaptive_weights[key] /= total_weight
        
        return adaptive_weights
    
    def _assess_measurement_consistency(self, quality_metrics: Dict) -> float:
        """Assess consistency between different measurements"""
        # Check for consistency between related metrics
        consistency_score = 0.7  # Default moderate consistency
        
        # Check SNR consistency with signal characteristics
        snr = quality_metrics.get('signal_snr', 0)
        signal_power = quality_metrics.get('signal_signal_power', 0)
        
        if snr > 10 and signal_power < 0.1:
            consistency_score *= 0.8  # Inconsistent high SNR with low power
        
        return consistency_score
    
    def _assess_method_agreement(self, quality_metrics: Dict) -> float:
        """Assess agreement between different quality assessment methods"""
        # Compare different SNR and quality estimates
        ml_score = quality_metrics.get('ml_quality_score', 0.5)
        
        # Calculate other composite scores
        integrity_score = self._calculate_integrity_score(quality_metrics)
        signal_score = self._calculate_signal_score(quality_metrics)
        
        # Measure agreement as inverse of variance
        scores = [ml_score, integrity_score, signal_score]
        if len(scores) > 1:
            score_variance = np.var(scores)
            agreement = 1.0 / (1.0 + 5 * score_variance)  # High variance = low agreement
            return agreement
        else:
            return 0.5
    
    def _apply_seismic_preprocessing_pipeline(self, waveforms: Dict, config: Dict) -> Dict:
        """Apply comprehensive seismic preprocessing pipeline"""
        try:
            processed = {}
            
            if 'time_series' in waveforms:
                data = waveforms['time_series']
                
                # Detrend and demean
                data = data - np.mean(data)
                
                # Bandpass filter
                freq_range = config.get('frequency_range', [0.5, 25.0])
                filtered_data = self._apply_bandpass_filter(data, freq_range, config)
                
                # Normalize
                max_amplitude = np.max(np.abs(filtered_data))
                if max_amplitude > 0:
                    filtered_data = filtered_data / max_amplitude
                
                processed['time_series'] = filtered_data
                processed['preprocessing_applied'] = True
                
            return processed
            
        except Exception as e:
            return {'error': str(e), 'preprocessing_applied': False}
    
    def _analyze_events_with_transformer(self, processed_data: Dict, event_catalog: List[Dict], config: Dict) -> Dict:
        """Analyze events using seismic transformer module"""
        try:
            if not self._is_module_available('seismic_transformer'):
                return {'error': 'seismic_transformer module not available'}
            
            # Import and use seismic transformer
            from . import seismic_transformer
            
            transformer_config = seismic_transformer.SeismicConfig()
            processor = seismic_transformer.SeismicProcessor(transformer_config)
            
            analysis_results = {}
            station_results = []
            
            # Process each station's data
            for station_id, station_data in processed_data.get('processed_stations', {}).items():
                if 'waveforms' in station_data and 'time_series' in station_data['waveforms']:
                    # Convert to 3-component format expected by transformer
                    time_series = station_data['waveforms']['time_series']
                    if len(time_series.shape) == 1:
                        # Create 3-component from single component
                        three_comp_data = np.array([time_series, time_series * 0.7, time_series * 0.5])
                    else:
                        three_comp_data = time_series
                    
                    # Detect phases
                    phase_results = processor.detect_phases(three_comp_data)
                    
                    # Estimate magnitude
                    magnitude_results = processor.estimate_magnitude(three_comp_data)
                    
                    station_results.append({
                        'station_id': station_id,
                        'phases': phase_results,
                        'magnitude': magnitude_results
                    })
            
            # Aggregate results
            all_p_picks = []
            all_s_picks = []
            all_magnitudes = []
            
            for result in station_results:
                all_p_picks.extend(result['phases'].get('p_picks', []))
                all_s_picks.extend(result['phases'].get('s_picks', []))
                if 'magnitude' in result['magnitude']:
                    all_magnitudes.append(result['magnitude']['magnitude'])
            
            analysis_results.update({
                'total_p_picks': len(all_p_picks),
                'total_s_picks': len(all_s_picks),
                'mean_magnitude': np.mean(all_magnitudes) if all_magnitudes else None,
                'station_results': station_results,
                'lp_event_rate': len([e for e in event_catalog if e.get('type') == 'LP']),
                'tremor_amplitude': self._calculate_tremor_amplitude(processed_data),
                'seismicity_rate': len(event_catalog)
            })
            
            return analysis_results
            
        except Exception as e:
            return {'error': str(e)}
    
    def _calculate_signal_to_noise_ratio(self, time_series: np.ndarray) -> float:
        """
        Advanced signal-to-noise ratio estimation using multiple methods,
        adaptive windowing, and volcanic seismic signal characteristics
        """
        try:
            if self.advanced_thermodynamics_enabled and hasattr(self, 'thermodynamic_engine'):
                return self._calculate_advanced_snr(time_series)
            else:
                # Fallback to simplified calculation
                if len(time_series) < 100:
                    return 0.0
                
                noise_window = time_series[:len(time_series)//10]
                signal_window = time_series[len(time_series)//10:]
                
                noise_power = np.var(noise_window)
                signal_power = np.var(signal_window)
                
                if noise_power > 0:
                    snr = 10 * np.log10(signal_power / noise_power)
                    return max(0.0, snr)
                else:
                    return 20.0
                    
        except Exception:
            return 0.0
    
    def _calculate_advanced_snr(self, time_series: np.ndarray) -> float:
        """Advanced multi-method SNR estimation with volcanic signal characterization"""
        try:
            # Multi-method SNR estimation
            snr_results = {}
            
            # Method 1: Adaptive windowing SNR
            snr_results['adaptive'] = self._adaptive_windowing_snr(time_series)
            
            # Method 2: Spectral domain SNR
            snr_results['spectral'] = self._spectral_domain_snr(time_series)
            
            # Method 3: Kurtosis-based signal detection
            snr_results['kurtosis'] = self._kurtosis_based_snr(time_series)
            
            # Method 4: Moving window variance SNR
            snr_results['moving_variance'] = self._moving_variance_snr(time_series)
            
            # Method 5: Energy ratio SNR
            snr_results['energy_ratio'] = self._energy_ratio_snr(time_series)
            
            # Method 6: Volcanic signal specific SNR
            snr_results['volcanic'] = self._volcanic_signal_snr(time_series)
            
            # Combine results using weighted average based on signal characteristics
            weights = self._calculate_snr_method_weights(time_series, snr_results)
            
            # Calculate weighted SNR
            weighted_snr = sum(snr_results[method] * weights[method] 
                             for method in snr_results.keys())
            
            # Apply volcanic signal corrections
            corrected_snr = self._apply_volcanic_corrections(weighted_snr, time_series)
            
            return max(0.0, corrected_snr)
            
        except Exception as e:
            # Robust fallback
            return self._robust_fallback_snr(time_series)
    
    def _adaptive_windowing_snr(self, time_series: np.ndarray) -> float:
        """Adaptive windowing for optimal noise/signal separation"""
        n = len(time_series)
        if n < 200:
            return 0.0
        
        # Find optimal noise window using change point detection
        cumsum = np.cumsum(np.abs(time_series))
        normalized_cumsum = (cumsum - np.min(cumsum)) / (np.max(cumsum) - np.min(cumsum))
        
        # Find inflection point (simplified change point)
        diffs = np.diff(normalized_cumsum)
        change_point = np.argmax(diffs) + 1
        
        # Ensure reasonable window sizes
        noise_end = min(max(change_point, n//20), n//3)
        signal_start = max(noise_end, n//4)
        
        if noise_end <= 10 or signal_start >= n - 10:
            noise_end = n//10
            signal_start = n//4
        
        noise_window = time_series[:noise_end]
        signal_window = time_series[signal_start:]
        
        if len(noise_window) == 0 or len(signal_window) == 0:
            return 0.0
        
        noise_power = np.var(noise_window)
        signal_power = np.var(signal_window)
        
        if noise_power > 1e-10:
            return 10 * np.log10(max(signal_power / noise_power, 0.001))
        return 20.0
    
    def _spectral_domain_snr(self, time_series: np.ndarray) -> float:
        """SNR estimation in frequency domain"""
        n = len(time_series)
        if n < 64:
            return 0.0
        
        # FFT analysis
        fft_data = np.fft.fft(time_series)
        power_spectrum = np.abs(fft_data)**2
        freqs = np.fft.fftfreq(n)
        
        # Define frequency bands for volcanic signals
        low_freq_mask = (np.abs(freqs) >= 0.01) & (np.abs(freqs) <= 0.1)    # 1-10 Hz
        high_freq_mask = (np.abs(freqs) >= 0.15) & (np.abs(freqs) <= 0.4)   # 15-40 Hz
        
        if not np.any(low_freq_mask) or not np.any(high_freq_mask):
            return 0.0
        
        signal_power = np.mean(power_spectrum[low_freq_mask])
        noise_power = np.mean(power_spectrum[high_freq_mask])
        
        if noise_power > 1e-10:
            return 10 * np.log10(max(signal_power / noise_power, 0.001))
        return 15.0
    
    def _kurtosis_based_snr(self, time_series: np.ndarray) -> float:
        """Kurtosis-based signal detection and SNR estimation"""
        from scipy import stats
        
        n = len(time_series)
        if n < 100:
            return 0.0
        
        window_size = max(50, n // 20)
        kurtosis_values = []
        
        for i in range(0, n - window_size, window_size // 2):
            window = time_series[i:i + window_size]
            if len(window) == window_size:
                kurt = stats.kurtosis(window)
                kurtosis_values.append(kurt)
        
        if len(kurtosis_values) < 2:
            return 0.0
        
        kurtosis_values = np.array(kurtosis_values)
        
        # High kurtosis indicates signal presence
        signal_threshold = np.mean(kurtosis_values) + np.std(kurtosis_values)
        signal_indices = kurtosis_values > signal_threshold
        
        if not np.any(signal_indices) or not np.any(~signal_indices):
            return 5.0
        
        signal_power = np.mean(kurtosis_values[signal_indices])
        noise_power = np.mean(kurtosis_values[~signal_indices])
        
        if noise_power > 1e-6:
            return 5 * np.log10(max(signal_power / noise_power, 0.1))
        return 10.0
    
    def _moving_variance_snr(self, time_series: np.ndarray) -> float:
        """Moving window variance for SNR estimation"""
        n = len(time_series)
        if n < 100:
            return 0.0
        
        window_size = max(20, n // 50)
        variances = []
        
        for i in range(n - window_size + 1):
            window = time_series[i:i + window_size]
            variances.append(np.var(window))
        
        variances = np.array(variances)
        
        # Use percentiles to separate noise from signal
        noise_threshold = np.percentile(variances, 25)
        signal_threshold = np.percentile(variances, 75)
        
        noise_mask = variances <= noise_threshold
        signal_mask = variances >= signal_threshold
        
        if not np.any(noise_mask) or not np.any(signal_mask):
            return np.std(variances) * 5  # Fallback based on variance spread
        
        noise_power = np.mean(variances[noise_mask])
        signal_power = np.mean(variances[signal_mask])
        
        if noise_power > 1e-10:
            return 10 * np.log10(max(signal_power / noise_power, 0.001))
        return 15.0
    
    def _energy_ratio_snr(self, time_series: np.ndarray) -> float:
        """Energy-based SNR using sliding window analysis"""
        n = len(time_series)
        if n < 100:
            return 0.0
        
        # Calculate local energy using sliding window
        window_size = max(25, n // 40)
        energies = []
        
        for i in range(0, n - window_size + 1, window_size // 4):
            window = time_series[i:i + window_size]
            energy = np.sum(window**2)
            energies.append(energy)
        
        energies = np.array(energies)
        
        if len(energies) < 3:
            return np.std(time_series) * 10
        
        # Detect signal onset using energy threshold
        energy_threshold = np.mean(energies) + 0.5 * np.std(energies)
        signal_indices = energies > energy_threshold
        
        if not np.any(signal_indices) or not np.any(~signal_indices):
            return np.max(energies) / (np.mean(energies) + 1e-10) * 5
        
        signal_energy = np.mean(energies[signal_indices])
        noise_energy = np.mean(energies[~signal_indices])
        
        if noise_energy > 1e-10:
            return 10 * np.log10(max(signal_energy / noise_energy, 0.001))
        return 18.0
    
    def _volcanic_signal_snr(self, time_series: np.ndarray) -> float:
        """Volcanic signal-specific SNR estimation"""
        n = len(time_series)
        if n < 150:
            return 0.0
        
        # Analyze volcanic signal characteristics
        # 1. Long-period vs short-period content
        lp_content = self._analyze_lp_content(time_series)
        sp_content = self._analyze_sp_content(time_series)
        
        # 2. Tremor characteristics
        tremor_score = self._analyze_tremor_characteristics(time_series)
        
        # 3. Explosion signal characteristics
        explosion_score = self._analyze_explosion_characteristics(time_series)
        
        # Combine volcanic signal indicators
        volcanic_signal_strength = (lp_content * 0.3 + sp_content * 0.25 + 
                                  tremor_score * 0.25 + explosion_score * 0.2)
        
        # Background noise estimation using statistical methods
        noise_level = self._estimate_background_noise(time_series)
        
        if noise_level > 1e-10:
            volcanic_snr = 10 * np.log10(max(volcanic_signal_strength / noise_level, 0.001))
            return volcanic_snr
        return 12.0
    
    def _analyze_lp_content(self, time_series: np.ndarray) -> float:
        """Analyze long-period volcanic signal content"""
        # Simple spectral analysis for LP signals (0.5-5 Hz)
        fft_data = np.fft.fft(time_series)
        freqs = np.fft.fftfreq(len(time_series))
        power_spectrum = np.abs(fft_data)**2
        
        lp_mask = (np.abs(freqs) >= 0.005) & (np.abs(freqs) <= 0.05)  # 0.5-5 Hz
        if np.any(lp_mask):
            return np.mean(power_spectrum[lp_mask])
        return 0.0
    
    def _analyze_sp_content(self, time_series: np.ndarray) -> float:
        """Analyze short-period volcanic signal content"""
        # SP signals typically 5-25 Hz
        fft_data = np.fft.fft(time_series)
        freqs = np.fft.fftfreq(len(time_series))
        power_spectrum = np.abs(fft_data)**2
        
        sp_mask = (np.abs(freqs) >= 0.05) & (np.abs(freqs) <= 0.25)  # 5-25 Hz
        if np.any(sp_mask):
            return np.mean(power_spectrum[sp_mask])
        return 0.0
    
    def _analyze_tremor_characteristics(self, time_series: np.ndarray) -> float:
        """Analyze tremor signal characteristics"""
        # Tremor is characterized by sustained amplitude
        window_size = max(50, len(time_series) // 20)
        amplitudes = []
        
        for i in range(0, len(time_series) - window_size + 1, window_size // 2):
            window = time_series[i:i + window_size]
            amplitudes.append(np.sqrt(np.mean(window**2)))
        
        if len(amplitudes) < 2:
            return 0.0
        
        # Tremor has relatively stable amplitude
        stability = 1.0 / (1.0 + np.std(amplitudes) / (np.mean(amplitudes) + 1e-10))
        sustained_amplitude = np.mean(amplitudes)
        
        return stability * sustained_amplitude * 100
    
    def _analyze_explosion_characteristics(self, time_series: np.ndarray) -> float:
        """Analyze explosion signal characteristics"""
        # Explosions have sharp onsets and exponential decay
        
        # Find potential onset using gradient
        gradient = np.gradient(np.abs(time_series))
        sharp_onsets = gradient > np.percentile(gradient, 95)
        
        if not np.any(sharp_onsets):
            return 0.0
        
        # Analyze decay characteristics after onset
        onset_indices = np.where(sharp_onsets)[0]
        explosion_score = 0.0
        
        for onset_idx in onset_indices[:3]:  # Check first 3 potential explosions
            if onset_idx + 100 < len(time_series):
                decay_window = time_series[onset_idx:onset_idx + 100]
                
                # Fit exponential decay
                try:
                    x = np.arange(len(decay_window))
                    log_decay = np.log(np.abs(decay_window) + 1e-10)
                    if len(x) > 10:
                        fit_coeff = np.polyfit(x[:50], log_decay[:50], 1)
                        if fit_coeff[0] < 0:  # Negative slope indicates decay
                            explosion_score += abs(fit_coeff[0]) * np.max(np.abs(decay_window))
                except:
                    continue
        
        return explosion_score
    
    def _estimate_background_noise(self, time_series: np.ndarray) -> float:
        """Estimate background noise level using robust statistics"""
        # Use median absolute deviation for robust noise estimation
        median_val = np.median(time_series)
        mad = np.median(np.abs(time_series - median_val))
        
        # Convert MAD to standard deviation equivalent
        noise_std = mad * 1.4826
        
        # Also consider minimum energy windows
        window_size = max(20, len(time_series) // 100)
        min_energy = float('inf')
        
        for i in range(0, len(time_series) - window_size + 1, window_size):
            window = time_series[i:i + window_size]
            energy = np.mean(window**2)
            min_energy = min(min_energy, energy)
        
        # Combine both estimates
        return (noise_std**2 + min_energy) / 2
    
    def _calculate_snr_method_weights(self, time_series: np.ndarray, snr_results: dict) -> dict:
        """Calculate adaptive weights for different SNR methods"""
        weights = {}
        n = len(time_series)
        
        # Base weights
        base_weights = {
            'adaptive': 0.2,
            'spectral': 0.18,
            'kurtosis': 0.15,
            'moving_variance': 0.17,
            'energy_ratio': 0.15,
            'volcanic': 0.15
        }
        
        # Adjust weights based on signal characteristics
        signal_variance = np.var(time_series)
        signal_skewness = self._calculate_skewness(time_series)
        
        # High variance signals favor energy-based methods
        if signal_variance > np.percentile([np.var(time_series[i:i+50]) 
                                          for i in range(0, n-50, 25)], 75):
            base_weights['energy_ratio'] *= 1.3
            base_weights['moving_variance'] *= 1.2
        
        # Highly skewed signals favor kurtosis-based methods
        if abs(signal_skewness) > 1.0:
            base_weights['kurtosis'] *= 1.4
        
        # Check for volcanic signal characteristics
        if self._has_volcanic_characteristics(time_series):
            base_weights['volcanic'] *= 1.5
            base_weights['spectral'] *= 1.2
        
        # Normalize weights
        total_weight = sum(base_weights.values())
        for key in base_weights:
            weights[key] = base_weights[key] / total_weight
        
        return weights
    
    def _calculate_skewness(self, data: np.ndarray) -> float:
        """Calculate skewness of data"""
        mean_val = np.mean(data)
        std_val = np.std(data)
        if std_val > 1e-10:
            return np.mean(((data - mean_val) / std_val) ** 3)
        return 0.0
    
    def _has_volcanic_characteristics(self, time_series: np.ndarray) -> bool:
        """Check if signal has volcanic characteristics"""
        # Simple heuristics for volcanic signals
        
        # 1. Check for sustained energy (tremor-like)
        energy_windows = []
        window_size = max(50, len(time_series) // 20)
        
        for i in range(0, len(time_series) - window_size + 1, window_size // 2):
            window = time_series[i:i + window_size]
            energy_windows.append(np.mean(window**2))
        
        if len(energy_windows) > 3:
            energy_stability = np.std(energy_windows) / (np.mean(energy_windows) + 1e-10)
            sustained_energy = energy_stability < 1.0  # Relatively stable energy
        else:
            sustained_energy = False
        
        # 2. Check for long-period content
        fft_data = np.fft.fft(time_series)
        freqs = np.fft.fftfreq(len(time_series))
        power_spectrum = np.abs(fft_data)**2
        
        lp_mask = (np.abs(freqs) >= 0.005) & (np.abs(freqs) <= 0.05)
        total_mask = np.abs(freqs) <= 0.5
        
        if np.any(lp_mask) and np.any(total_mask):
            lp_ratio = np.sum(power_spectrum[lp_mask]) / np.sum(power_spectrum[total_mask])
            has_lp_content = lp_ratio > 0.1
        else:
            has_lp_content = False
        
        return sustained_energy or has_lp_content
    
    def _apply_volcanic_corrections(self, snr: float, time_series: np.ndarray) -> float:
        """Apply volcanic signal-specific corrections to SNR"""
        
        # Correction factor based on signal duration
        signal_length = len(time_series)
        if signal_length > 1000:  # Long signals might be tremor
            duration_factor = min(1.2, 1.0 + 0.0002 * signal_length)
        else:
            duration_factor = 1.0
        
        # Correction for volcanic frequency content
        volcanic_factor = 1.0
        if self._has_volcanic_characteristics(time_series):
            volcanic_factor = 1.1  # Boost SNR for volcanic signals
        
        # Correction for signal complexity
        complexity = self._calculate_signal_complexity(time_series)
        complexity_factor = min(1.15, 1.0 + 0.1 * complexity)
        
        corrected_snr = snr * duration_factor * volcanic_factor * complexity_factor
        
        return corrected_snr
    
    def _calculate_signal_complexity(self, time_series: np.ndarray) -> float:
        """Calculate signal complexity measure"""
        # Use approximate entropy as complexity measure
        m = 2  # Pattern length
        r = 0.2 * np.std(time_series)  # Tolerance
        
        def _maxdist(xi, xj, m):
            return max([abs(ua - va) for ua, va in zip(xi, xj)])
        
        def _approximate_entropy(U, m, r):
            def _run_length(data, m):
                N = len(data)
                patterns = []
                for i in range(N - m + 1):
                    patterns.append(data[i:i + m])
                return patterns
            
            patterns = _run_length(U, m)
            C = np.zeros(len(patterns))
            
            for i in range(len(patterns)):
                template = patterns[i]
                matches = 0
                for j in range(len(patterns)):
                    if _maxdist(template, patterns[j], m) <= r:
                        matches += 1
                C[i] = matches / float(len(patterns))
            
            phi_m = np.mean(np.log(C + 1e-10))
            
            patterns_m1 = _run_length(U, m + 1)
            C_m1 = np.zeros(len(patterns_m1))
            
            for i in range(len(patterns_m1)):
                template = patterns_m1[i]
                matches = 0
                for j in range(len(patterns_m1)):
                    if _maxdist(template, patterns_m1[j], m + 1) <= r:
                        matches += 1
                C_m1[i] = matches / float(len(patterns_m1))
            
            phi_m1 = np.mean(np.log(C_m1 + 1e-10))
            
            return phi_m - phi_m1
        
        try:
            if len(time_series) > 100:
                # Sample if too long
                if len(time_series) > 500:
                    indices = np.linspace(0, len(time_series)-1, 500, dtype=int)
                    sampled_series = time_series[indices]
                else:
                    sampled_series = time_series
                
                apen = _approximate_entropy(sampled_series, m, r)
                return min(max(apen, 0.0), 2.0)  # Clamp between 0 and 2
            else:
                return 0.5  # Default complexity for short signals
        except:
            return 0.5
    
    def _robust_fallback_snr(self, time_series: np.ndarray) -> float:
        """Robust fallback SNR calculation"""
        try:
            if len(time_series) < 10:
                return 0.0
            
            # Use robust statistics
            q75, q25 = np.percentile(time_series, [75, 25])
            iqr = q75 - q25
            
            median_val = np.median(time_series)
            mad = np.median(np.abs(time_series - median_val))
            
            if mad > 1e-10:
                robust_snr = 20 * np.log10(max(iqr / mad, 0.001))
                return max(0.0, min(robust_snr, 30.0))
            else:
                return 15.0
                
        except Exception:
            return 0.0
    
    def _assess_frequency_content(self, waveforms: Dict, config: Dict) -> float:
        """
        Advanced frequency content assessment using multi-scale spectral analysis,
        time-frequency decomposition, and volcanic seismic signal characterization
        """
        try:
            if self.advanced_thermodynamics_enabled and hasattr(self, 'thermodynamic_engine'):
                return self._calculate_advanced_frequency_assessment(waveforms, config)
            else:
                return self._calculate_basic_frequency_assessment(waveforms, config)
        except Exception as e:
            print(f"Frequency content assessment error: {e}")
            return self._calculate_basic_frequency_assessment(waveforms, config)

    def _calculate_advanced_frequency_assessment(self, waveforms: Dict, config: Dict) -> float:
        """Advanced multi-scale frequency content analysis"""
        if 'time_series' not in waveforms:
            return 0.0
        
        data = waveforms['time_series']
        if len(data) < 10:
            return 0.0
        
        # Ensure data is properly shaped
        if data.ndim == 1:
            data = data.reshape(-1, 1)
        
        sample_rate = config.get('sample_rate', 100.0)
        freq_range = config.get('frequency_range', [0.5, 25.0])
        
        # Multi-component analysis
        frequency_scores = []
        
        for channel in range(data.shape[1]):
            channel_data = data[:, channel]
            
            # 1. Power Spectral Density Analysis
            psd_score = self._calculate_psd_quality(channel_data, sample_rate, freq_range)
            
            # 2. Time-Frequency Analysis (Spectrogram)
            tf_score = self._calculate_timefrequency_quality(channel_data, sample_rate, freq_range)
            
            # 3. Wavelet Transform Analysis
            wavelet_score = self._calculate_wavelet_quality(channel_data, sample_rate, freq_range)
            
            # 4. Volcanic Signal Characteristics
            volcanic_score = self._assess_volcanic_frequency_signatures(channel_data, sample_rate, config)
            
            # 5. Spectral Coherence Analysis
            coherence_score = self._calculate_spectral_coherence(channel_data, sample_rate)
            
            # 6. Harmonic Content Analysis
            harmonic_score = self._assess_harmonic_content(channel_data, sample_rate, freq_range)
            
            # Combine scores with weights
            weights = {
                'psd': 0.25,
                'timefreq': 0.20,
                'wavelet': 0.20,
                'volcanic': 0.15,
                'coherence': 0.10,
                'harmonic': 0.10
            }
            
            combined_score = (
                weights['psd'] * psd_score +
                weights['timefreq'] * tf_score +
                weights['wavelet'] * wavelet_score +
                weights['volcanic'] * volcanic_score +
                weights['coherence'] * coherence_score +
                weights['harmonic'] * harmonic_score
            )
            
            frequency_scores.append(combined_score)
        
        # Multi-channel combination
        if len(frequency_scores) == 1:
            return min(1.0, max(0.0, frequency_scores[0]))
        else:
            # For multi-channel data, use weighted average with cross-channel coherence
            cross_coherence = self._calculate_cross_channel_coherence(data, sample_rate)
            base_score = np.mean(frequency_scores)
            return min(1.0, max(0.0, base_score * (1 + 0.2 * cross_coherence)))

    def _calculate_basic_frequency_assessment(self, waveforms: Dict, config: Dict) -> float:
        """Basic frequency content assessment (fallback)"""
        if 'time_series' not in waveforms:
            return 0.0
        
        data = waveforms['time_series']
        
        # Simple spectral analysis
        fft_data = np.abs(np.fft.fft(data.flatten() if data.ndim > 1 else data))
        freq_range = config.get('frequency_range', [0.5, 25.0])
        
        # Check if there's significant energy in the frequency range of interest
        total_energy = np.sum(fft_data**2)
        if total_energy > 0:
            return min(1.0, total_energy / len(fft_data) / 100.0)
        else:
            return 0.0

    def _calculate_psd_quality(self, data: np.ndarray, sample_rate: float, freq_range: List[float]) -> float:
        """Calculate Power Spectral Density quality metrics"""
        # Welch's method for PSD estimation
        n_fft = min(1024, len(data) // 4) if len(data) > 1024 else len(data)
        
        # Simple PSD calculation (in practice would use scipy.signal.welch)
        fft_data = np.fft.fft(data, n=n_fft)
        psd = np.abs(fft_data)**2 / (sample_rate * n_fft)
        freqs = np.fft.fftfreq(n_fft, 1/sample_rate)
        
        # Focus on positive frequencies
        pos_mask = freqs >= 0
        psd = psd[pos_mask]
        freqs = freqs[pos_mask]
        
        # Energy in frequency range of interest
        freq_mask = (freqs >= freq_range[0]) & (freqs <= freq_range[1])
        if np.sum(freq_mask) == 0:
            return 0.0
        
        signal_energy = np.sum(psd[freq_mask])
        total_energy = np.sum(psd)
        
        if total_energy > 0:
            # Relative energy in frequency band
            relative_energy = signal_energy / total_energy
            
            # Spectral flatness (measure of tonal vs noise-like character)
            spectral_flatness = self._calculate_spectral_flatness(psd[freq_mask])
            
            # Spectral centroid (measure of spectral center of mass)
            spectral_centroid = self._calculate_spectral_centroid(psd[freq_mask], freqs[freq_mask])
            centroid_score = 1.0 - abs(spectral_centroid - np.mean(freq_range)) / (freq_range[1] - freq_range[0])
            
            return 0.6 * relative_energy + 0.2 * spectral_flatness + 0.2 * max(0, centroid_score)
        
        return 0.0

    def _calculate_timefrequency_quality(self, data: np.ndarray, sample_rate: float, freq_range: List[float]) -> float:
        """Calculate time-frequency domain quality using spectrogram analysis"""
        # Simple spectrogram calculation
        window_size = min(256, len(data) // 8) if len(data) > 256 else len(data) // 2
        if window_size < 4:
            return 0.0
        
        hop_size = window_size // 4
        n_windows = (len(data) - window_size) // hop_size + 1
        
        if n_windows < 2:
            return 0.0
        
        # Calculate spectrogram
        spectrogram = np.zeros((window_size // 2 + 1, n_windows))
        freqs = np.fft.fftfreq(window_size, 1/sample_rate)[:window_size // 2 + 1]
        
        for i in range(n_windows):
            start_idx = i * hop_size
            end_idx = start_idx + window_size
            window_data = data[start_idx:end_idx]
            
            # Apply window function (Hann window approximation)
            window_func = 0.5 * (1 - np.cos(2 * np.pi * np.arange(len(window_data)) / len(window_data)))
            windowed_data = window_data * window_func
            
            fft_data = np.fft.fft(windowed_data, n=window_size)
            spectrogram[:, i] = np.abs(fft_data[:window_size // 2 + 1])**2
        
        # Frequency range mask
        freq_mask = (freqs >= freq_range[0]) & (freqs <= freq_range[1])
        if np.sum(freq_mask) == 0:
            return 0.0
        
        # Time-frequency quality metrics
        signal_spectrogram = spectrogram[freq_mask, :]
        
        # Temporal consistency
        temporal_variance = np.var(np.mean(signal_spectrogram, axis=0))
        temporal_score = 1.0 / (1.0 + temporal_variance / np.mean(signal_spectrogram))
        
        # Frequency consistency
        frequency_variance = np.var(np.mean(signal_spectrogram, axis=1))
        frequency_score = 1.0 / (1.0 + frequency_variance / np.mean(signal_spectrogram))
        
        # Overall energy concentration
        energy_concentration = np.sum(signal_spectrogram) / np.sum(spectrogram)
        
        return 0.4 * temporal_score + 0.3 * frequency_score + 0.3 * energy_concentration

    def _calculate_wavelet_quality(self, data: np.ndarray, sample_rate: float, freq_range: List[float]) -> float:
        """Advanced multi-wavelet quality assessment with volcanic signal characterization"""
        try:
            # Multi-wavelet approach with different wavelet families
            wavelet_results = {}
            
            # 1. Morlet wavelet analysis (complex-valued)
            morlet_quality = self._morlet_wavelet_analysis(data, sample_rate, freq_range)
            wavelet_results['morlet'] = morlet_quality
            
            # 2. Daubechies wavelet analysis (real-valued)
            daubechies_quality = self._daubechies_wavelet_analysis(data, sample_rate, freq_range)
            wavelet_results['daubechies'] = daubechies_quality
            
            # 3. Mexican hat wavelet analysis
            mexican_hat_quality = self._mexican_hat_wavelet_analysis(data, sample_rate, freq_range)
            wavelet_results['mexican_hat'] = mexican_hat_quality
            
            # 4. Gabor wavelet analysis
            gabor_quality = self._gabor_wavelet_analysis(data, sample_rate, freq_range)
            wavelet_results['gabor'] = gabor_quality
            
            # 5. Time-frequency resolution assessment
            tf_resolution = self._assess_time_frequency_resolution(data, sample_rate, freq_range)
            wavelet_results['tf_resolution'] = tf_resolution
            
            # 6. Volcanic signal coherence analysis
            volcanic_coherence = self._assess_volcanic_wavelet_coherence(data, sample_rate, freq_range)
            wavelet_results['volcanic_coherence'] = volcanic_coherence
            
            # 7. Multi-scale energy distribution
            energy_distribution = self._assess_multiscale_energy_distribution(data, sample_rate, freq_range)
            wavelet_results['energy_distribution'] = energy_distribution
            
            # 8. Phase coherence across scales
            phase_coherence = self._assess_phase_coherence_multiscale(data, sample_rate, freq_range)
            wavelet_results['phase_coherence'] = phase_coherence
            
            # 9. Wavelet entropy analysis
            wavelet_entropy = self._calculate_wavelet_entropy_quality(data, sample_rate, freq_range)
            wavelet_results['wavelet_entropy'] = wavelet_entropy
            
            # 10. Singularity detection quality
            singularity_quality = self._assess_singularity_detection_quality(data, sample_rate)
            wavelet_results['singularity'] = singularity_quality
            
            # Adaptive weight calculation based on signal characteristics
            weights = self._calculate_wavelet_analysis_weights(data, sample_rate, wavelet_results)
            
            # Weighted combination of all quality metrics
            weighted_quality = sum(wavelet_results[method] * weights[method] 
                                 for method in wavelet_results.keys())
            
            # Apply volcanic-specific corrections
            corrected_quality = self._apply_volcanic_wavelet_corrections(weighted_quality, data, sample_rate)
            
            return max(0.0, min(1.0, corrected_quality))
            
        except Exception as e:
            # Fallback to simplified wavelet quality
            return self._calculate_wavelet_quality_simple(data, sample_rate, freq_range)
    
    def _morlet_wavelet_analysis(self, data: np.ndarray, sample_rate: float, freq_range: List[float]) -> float:
        """Advanced Morlet wavelet analysis with optimal parameter selection"""
        try:
            # Dynamic scale selection based on frequency range
            min_freq, max_freq = freq_range[0], freq_range[1]
            min_scale = sample_rate / (2 * max_freq)
            max_scale = sample_rate / (2 * min_freq)
            
            # Logarithmic scale distribution with higher density in frequency range of interest
            n_scales = min(100, max(20, int(len(data) / 50)))
            scales = np.logspace(np.log10(min_scale), np.log10(max_scale), n_scales)
            
            # Advanced Morlet wavelet parameters
            omega0 = 6.0  # Central frequency parameter
            cwt_matrix = np.zeros((len(scales), len(data)), dtype=complex)
            
            for i, scale in enumerate(scales):
                # Morlet wavelet construction
                sigma_t = scale / omega0
                wavelet_length = min(int(10 * sigma_t), len(data) // 2)
                
                if wavelet_length > 5:
                    t = np.arange(-wavelet_length//2, wavelet_length//2) / sample_rate
                    
                    # Normalized Morlet wavelet
                    norm_factor = 1.0 / np.sqrt(np.pi * sigma_t)
                    wavelet = norm_factor * np.exp(-t**2 / (2 * sigma_t**2)) * np.exp(1j * omega0 * t / sigma_t)
                    
                    # Efficient convolution using FFT
                    if len(data) > 1000:
                        padded_data = np.pad(data, (wavelet_length//2, wavelet_length//2), 'reflect')
                        cwt_coeff = np.convolve(padded_data, np.conj(wavelet), mode='valid')
                        cwt_matrix[i, :] = cwt_coeff[:len(data)]
                    else:
                        # Direct convolution for short signals
                        for j in range(len(data) - len(wavelet) + 1):
                            cwt_matrix[i, j] = np.sum(data[j:j+len(wavelet)] * np.conj(wavelet))
            
            # Quality metrics from Morlet analysis
            quality_metrics = {}
            
            # 1. Time-frequency energy concentration
            energy_matrix = np.abs(cwt_matrix)**2
            if np.sum(energy_matrix) > 0:
                max_energy = np.max(energy_matrix)
                mean_energy = np.mean(energy_matrix[energy_matrix > 0])
                energy_concentration = max_energy / (mean_energy + 1e-10)
                quality_metrics['energy_concentration'] = min(1.0, energy_concentration / 20.0)
            else:
                quality_metrics['energy_concentration'] = 0.0
            
            # 2. Phase consistency across scales
            phase_matrix = np.angle(cwt_matrix)
            phase_consistency = self._calculate_phase_consistency(phase_matrix)
            quality_metrics['phase_consistency'] = phase_consistency
            
            # 3. Scale-wise SNR
            scale_snr = self._calculate_scale_wise_snr(energy_matrix)
            quality_metrics['scale_snr'] = scale_snr
            
            # 4. Instantaneous frequency stability
            inst_freq_stability = self._calculate_instantaneous_frequency_stability(cwt_matrix, scales, sample_rate)
            quality_metrics['inst_freq_stability'] = inst_freq_stability
            
            # Combine Morlet-specific quality metrics
            morlet_quality = (0.3 * quality_metrics['energy_concentration'] + 
                            0.25 * quality_metrics['phase_consistency'] +
                            0.25 * quality_metrics['scale_snr'] +
                            0.2 * quality_metrics['inst_freq_stability'])
            
            return max(0.0, min(1.0, morlet_quality))
            
        except Exception:
            return 0.3
    
    def _daubechies_wavelet_analysis(self, data: np.ndarray, sample_rate: float, freq_range: List[float]) -> float:
        """Daubechies wavelet analysis for edge and discontinuity detection"""
        try:
            # Multi-resolution analysis using Daubechies wavelets
            max_levels = min(8, int(np.log2(len(data))) - 2)
            if max_levels < 2:
                return 0.3
            
            # Daubechies-4 wavelet approximation
            coeffs_list = []
            current_data = data.copy()
            
            for level in range(max_levels):
                # Simple approximation of Daubechies-4 decomposition
                h = np.array([0.4830, 0.8365, 0.2241, -0.1294])  # Daubechies-4 filter
                
                # Convolution and downsampling
                if len(current_data) >= len(h) * 2:
                    conv_result = np.convolve(current_data, h, mode='valid')
                    detail_coeffs = conv_result[::2]  # Downsampling
                    
                    # Approximation coefficients (low-pass)
                    g = h[::-1] * np.array([1, -1, 1, -1])  # High-pass filter
                    approx_coeffs = np.convolve(current_data, g, mode='valid')[::2]
                    
                    coeffs_list.append(detail_coeffs)
                    current_data = approx_coeffs
                else:
                    break
            
            if not coeffs_list:
                return 0.3
            
            # Quality assessment from wavelet coefficients
            quality_metrics = {}
            
            # 1. Edge detection quality
            edge_quality = 0.0
            for i, coeffs in enumerate(coeffs_list):
                if len(coeffs) > 0:
                    # Edge strength at this scale
                    edge_strength = np.std(coeffs) / (np.mean(np.abs(coeffs)) + 1e-10)
                    edge_quality += edge_strength / (i + 1)  # Weight by scale
            
            quality_metrics['edge_quality'] = min(1.0, edge_quality / len(coeffs_list))
            
            # 2. Multi-resolution energy distribution
            energy_distribution = []
            total_energy = 0
            for coeffs in coeffs_list:
                energy = np.sum(coeffs**2)
                energy_distribution.append(energy)
                total_energy += energy
            
            if total_energy > 0:
                energy_distribution = np.array(energy_distribution) / total_energy
                # Prefer concentrated energy in relevant scales
                concentration_score = np.max(energy_distribution) / (np.mean(energy_distribution) + 1e-10)
                quality_metrics['energy_concentration'] = min(1.0, concentration_score / 5.0)
            else:
                quality_metrics['energy_concentration'] = 0.0
            
            # 3. Regularity assessment
            regularity_score = self._assess_wavelet_regularity(coeffs_list)
            quality_metrics['regularity'] = regularity_score
            
            # 4. Frequency selectivity
            freq_selectivity = self._assess_frequency_selectivity_daubechies(coeffs_list, sample_rate, freq_range)
            quality_metrics['freq_selectivity'] = freq_selectivity
            
            # Combine Daubechies-specific quality metrics
            daubechies_quality = (0.3 * quality_metrics['edge_quality'] + 
                                0.3 * quality_metrics['energy_concentration'] +
                                0.2 * quality_metrics['regularity'] +
                                0.2 * quality_metrics['freq_selectivity'])
            
            return max(0.0, min(1.0, daubechies_quality))
            
        except Exception:
            return 0.3
    
    def _mexican_hat_wavelet_analysis(self, data: np.ndarray, sample_rate: float, freq_range: List[float]) -> float:
        """Mexican hat (Ricker) wavelet analysis for peak detection"""
        try:
            # Mexican hat wavelet parameters
            min_freq, max_freq = freq_range[0], freq_range[1]
            center_freq = np.sqrt(min_freq * max_freq)
            
            # Scale range for Mexican hat wavelet
            scales = np.logspace(np.log10(sample_rate / (4 * max_freq)), 
                               np.log10(sample_rate / (2 * min_freq)), 50)
            
            cwt_matrix = np.zeros((len(scales), len(data)))
            
            for i, scale in enumerate(scales):
                # Mexican hat wavelet (second derivative of Gaussian)
                sigma = scale / (2 * np.pi)
                wavelet_length = min(int(12 * sigma), len(data) // 2)
                
                if wavelet_length > 3:
                    t = np.arange(-wavelet_length//2, wavelet_length//2)
                    
                    # Normalized Mexican hat wavelet
                    norm_factor = 2 / (np.sqrt(3 * sigma) * (np.pi**0.25))
                    gaussian = np.exp(-t**2 / (2 * sigma**2))
                    mexican_hat = norm_factor * (1 - t**2 / sigma**2) * gaussian
                    
                    # Convolution
                    for j in range(len(data) - len(mexican_hat) + 1):
                        cwt_matrix[i, j] = np.sum(data[j:j+len(mexican_hat)] * mexican_hat)
            
            # Quality metrics from Mexican hat analysis
            quality_metrics = {}
            
            # 1. Peak detection quality
            peak_quality = self._assess_peak_detection_quality(cwt_matrix)
            quality_metrics['peak_detection'] = peak_quality
            
            # 2. Zero-crossing analysis
            zero_crossing_quality = self._assess_zero_crossing_quality(cwt_matrix)
            quality_metrics['zero_crossing'] = zero_crossing_quality
            
            # 3. Symmetry assessment
            symmetry_quality = self._assess_wavelet_symmetry(cwt_matrix)
            quality_metrics['symmetry'] = symmetry_quality
            
            # 4. Local extrema consistency
            extrema_consistency = self._assess_extrema_consistency(cwt_matrix)
            quality_metrics['extrema_consistency'] = extrema_consistency
            
            # Combine Mexican hat quality metrics
            mexican_hat_quality = (0.4 * quality_metrics['peak_detection'] + 
                                 0.3 * quality_metrics['zero_crossing'] +
                                 0.2 * quality_metrics['symmetry'] +
                                 0.1 * quality_metrics['extrema_consistency'])
            
            return max(0.0, min(1.0, mexican_hat_quality))
            
        except Exception:
            return 0.3
    
    def _gabor_wavelet_analysis(self, data: np.ndarray, sample_rate: float, freq_range: List[float]) -> float:
        """Gabor wavelet analysis for time-frequency localization"""
        try:
            # Gabor wavelet parameters
            min_freq, max_freq = freq_range[0], freq_range[1]
            n_frequencies = min(30, max(10, int((max_freq - min_freq) / 1.0)))
            frequencies = np.linspace(min_freq, max_freq, n_frequencies)
            
            # Time-frequency representation
            tf_matrix = np.zeros((len(frequencies), len(data)))
            
            for i, freq in enumerate(frequencies):
                # Gabor wavelet (Gaussian-modulated sinusoid)
                sigma_t = 1.0 / (2 * np.pi * freq)  # Time standard deviation
                wavelet_length = min(int(8 * sigma_t * sample_rate), len(data) // 3)
                
                if wavelet_length > 5:
                    t = np.arange(-wavelet_length//2, wavelet_length//2) / sample_rate
                    
                    # Normalized Gabor wavelet
                    norm_factor = 1.0 / np.sqrt(np.sqrt(np.pi) * sigma_t)
                    gabor_real = norm_factor * np.exp(-t**2 / (2 * sigma_t**2)) * np.cos(2 * np.pi * freq * t)
                    gabor_imag = norm_factor * np.exp(-t**2 / (2 * sigma_t**2)) * np.sin(2 * np.pi * freq * t)
                    
                    # Complex Gabor transform
                    for j in range(len(data) - len(gabor_real) + 1):
                        real_part = np.sum(data[j:j+len(gabor_real)] * gabor_real)
                        imag_part = np.sum(data[j:j+len(gabor_imag)] * gabor_imag)
                        tf_matrix[i, j] = np.sqrt(real_part**2 + imag_part**2)
            
            # Quality metrics from Gabor analysis
            quality_metrics = {}
            
            # 1. Time-frequency localization
            tf_localization = self._assess_tf_localization(tf_matrix)
            quality_metrics['tf_localization'] = tf_localization
            
            # 2. Frequency resolution
            freq_resolution = self._assess_frequency_resolution(tf_matrix, frequencies)
            quality_metrics['freq_resolution'] = freq_resolution
            
            # 3. Temporal resolution
            temporal_resolution = self._assess_temporal_resolution_gabor(tf_matrix)
            quality_metrics['temporal_resolution'] = temporal_resolution
            
            # 4. Signal-to-noise in time-frequency domain
            tf_snr = self._assess_tf_domain_snr(tf_matrix)
            quality_metrics['tf_snr'] = tf_snr
            
            # Combine Gabor quality metrics
            gabor_quality = (0.35 * quality_metrics['tf_localization'] + 
                           0.25 * quality_metrics['freq_resolution'] +
                           0.25 * quality_metrics['temporal_resolution'] +
                           0.15 * quality_metrics['tf_snr'])
            
            return max(0.0, min(1.0, gabor_quality))
            
        except Exception:
            return 0.3
    
    def _assess_time_frequency_resolution(self, data: np.ndarray, sample_rate: float, freq_range: List[float]) -> float:
        """Assess time-frequency resolution trade-off quality"""
        try:
            # Heisenberg uncertainty principle considerations
            signal_duration = len(data) / sample_rate
            freq_bandwidth = freq_range[1] - freq_range[0]
            
            # Theoretical minimum uncertainty product
            min_uncertainty = 1.0 / (4 * np.pi)
            
            # Empirical uncertainty assessment
            time_spread = self._calculate_time_spread(data, sample_rate)
            freq_spread = self._calculate_frequency_spread(data, sample_rate, freq_range)
            
            if time_spread > 0 and freq_spread > 0:
                uncertainty_product = time_spread * freq_spread
                uncertainty_ratio = min_uncertainty / uncertainty_product
                
                # Quality score based on proximity to theoretical minimum
                resolution_quality = min(1.0, uncertainty_ratio)
            else:
                resolution_quality = 0.3
            
            # Additional resolution metrics
            resolution_metrics = {
                'time_resolution': min(1.0, 1.0 / (time_spread + 1e-6)),
                'freq_resolution': min(1.0, 1.0 / (freq_spread + 1e-6)),
                'uncertainty_optimality': resolution_quality
            }
            
            # Weighted combination
            tf_resolution = (0.4 * resolution_metrics['uncertainty_optimality'] +
                           0.3 * resolution_metrics['time_resolution'] +
                           0.3 * resolution_metrics['freq_resolution'])
            
            return max(0.0, min(1.0, tf_resolution))
            
        except Exception:
            return 0.3
    
    def _assess_volcanic_wavelet_coherence(self, data: np.ndarray, sample_rate: float, freq_range: List[float]) -> float:
        """Assess wavelet coherence for volcanic signal types"""
        try:
            # Volcanic signal frequency signatures
            volcanic_signatures = {
                'vt_earthquakes': {'freq_range': [5.0, 25.0], 'duration': [0.1, 2.0]},
                'lp_events': {'freq_range': [0.5, 5.0], 'duration': [5.0, 30.0]},
                'tremor': {'freq_range': [1.0, 8.0], 'duration': [60.0, 3600.0]},
                'explosions': {'freq_range': [0.1, 20.0], 'duration': [1.0, 10.0]}
            }
            
            coherence_scores = {}
            signal_duration = len(data) / sample_rate
            
            for signal_type, characteristics in volcanic_signatures.items():
                sig_freq_range = characteristics['freq_range']
                sig_duration_range = characteristics['duration']
                
                # Check if signal characteristics match
                freq_overlap = max(0, min(freq_range[1], sig_freq_range[1]) - 
                                 max(freq_range[0], sig_freq_range[0]))
                freq_match = freq_overlap / (freq_range[1] - freq_range[0] + 1e-6)
                
                duration_match = 0.0
                if sig_duration_range[0] <= signal_duration <= sig_duration_range[1]:
                    duration_match = 1.0
                elif signal_duration < sig_duration_range[0]:
                    duration_match = signal_duration / sig_duration_range[0]
                else:
                    duration_match = sig_duration_range[1] / signal_duration
                
                # Combined coherence score for this volcanic signal type
                coherence_scores[signal_type] = 0.7 * freq_match + 0.3 * duration_match
            
            # Select best matching volcanic signature
            best_coherence = max(coherence_scores.values()) if coherence_scores else 0.0
            
            # Additional volcanic-specific quality checks
            volcanic_quality_checks = {
                'amplitude_modulation': self._assess_amplitude_modulation(data),
                'frequency_modulation': self._assess_frequency_modulation_quality(data, sample_rate),
                'onset_sharpness': self._assess_onset_sharpness(data),
                'coda_characteristics': self._assess_coda_quality(data, sample_rate)
            }
            
            volcanic_coherence = (0.4 * best_coherence +
                                0.2 * volcanic_quality_checks['amplitude_modulation'] +
                                0.2 * volcanic_quality_checks['frequency_modulation'] +
                                0.1 * volcanic_quality_checks['onset_sharpness'] +
                                0.1 * volcanic_quality_checks['coda_characteristics'])
            
            return max(0.0, min(1.0, volcanic_coherence))
            
        except Exception:
            return 0.3
    
    def _calculate_wavelet_analysis_weights(self, data: np.ndarray, sample_rate: float, 
                                          wavelet_results: Dict) -> Dict[str, float]:
        """Calculate adaptive weights for different wavelet analysis methods"""
        try:
            weights = {}
            
            # Signal characteristics
            signal_length = len(data)
            signal_duration = signal_length / sample_rate
            signal_complexity = np.std(np.diff(data)) / (np.std(data) + 1e-10)
            
            # Base weights
            base_weights = {
                'morlet': 0.20,
                'daubechies': 0.15,
                'mexican_hat': 0.15,
                'gabor': 0.15,
                'tf_resolution': 0.10,
                'volcanic_coherence': 0.10,
                'energy_distribution': 0.05,
                'phase_coherence': 0.05,
                'wavelet_entropy': 0.03,
                'singularity': 0.02
            }
            
            # Adaptive adjustments based on signal characteristics
            if signal_duration > 60.0:  # Long signals - favor tremor analysis
                base_weights['morlet'] += 0.05
                base_weights['volcanic_coherence'] += 0.05
                base_weights['gabor'] -= 0.05
                base_weights['mexican_hat'] -= 0.05
            
            if signal_complexity > 2.0:  # Complex signals - favor multi-resolution
                base_weights['daubechies'] += 0.05
                base_weights['wavelet_entropy'] += 0.03
                base_weights['morlet'] -= 0.04
                base_weights['gabor'] -= 0.04
            
            if signal_length < 1000:  # Short signals - favor time-frequency methods
                base_weights['gabor'] += 0.08
                base_weights['tf_resolution'] += 0.05
                base_weights['energy_distribution'] -= 0.06
                base_weights['phase_coherence'] -= 0.07
            
            # Performance-based weight adjustment
            for method, quality in wavelet_results.items():
                if method in base_weights:
                    # Boost weights for high-performing methods
                    if quality > 0.8:
                        base_weights[method] *= 1.2
                    elif quality < 0.3:
                        base_weights[method] *= 0.8
            
            # Normalize weights
            total_weight = sum(base_weights.values())
            if total_weight > 0:
                weights = {method: weight / total_weight for method, weight in base_weights.items()}
            else:
                # Equal weights fallback
                weights = {method: 1.0 / len(base_weights) for method in base_weights.keys()}
            
            return weights
            
        except Exception:
            # Equal weights fallback
            n_methods = len(wavelet_results)
            return {method: 1.0 / n_methods for method in wavelet_results.keys()}
    
    def _apply_volcanic_wavelet_corrections(self, quality_score: float, data: np.ndarray, sample_rate: float) -> float:
        """Apply volcanic signal-specific corrections to wavelet quality score"""
        try:
            corrections = []
            
            # 1. Volcanic frequency content correction
            volcanic_freq_correction = self._assess_volcanic_frequency_content(data, sample_rate)
            corrections.append(('freq_content', volcanic_freq_correction, 0.3))
            
            # 2. Signal onset characteristics
            onset_correction = self._assess_volcanic_onset_characteristics(data, sample_rate)
            corrections.append(('onset', onset_correction, 0.2))
            
            # 3. Duration-based correction
            duration_correction = self._assess_volcanic_duration_characteristics(data, sample_rate)
            corrections.append(('duration', duration_correction, 0.2))
            
            # 4. Amplitude characteristics
            amplitude_correction = self._assess_volcanic_amplitude_characteristics(data)
            corrections.append(('amplitude', amplitude_correction, 0.15))
            
            # 5. Spectral evolution correction
            spectral_evolution_correction = self._assess_spectral_evolution(data, sample_rate)
            corrections.append(('spectral_evolution', spectral_evolution_correction, 0.15))
            
            # Apply weighted corrections
            total_correction = sum(correction * weight for _, correction, weight in corrections)
            
            # Combine original quality with corrections
            corrected_quality = 0.7 * quality_score + 0.3 * total_correction
            
            return max(0.0, min(1.0, corrected_quality))
            
        except Exception:
            return quality_score
    
    def _calculate_wavelet_quality_simple(self, data: np.ndarray, sample_rate: float, freq_range: List[float]) -> float:
        """Simplified wavelet quality calculation (fallback)"""
        try:
            # Basic Morlet-like wavelet analysis
            scales = np.logspace(0, 3, 30)
            cwt_matrix = np.zeros((len(scales), len(data)))
            
            for i, scale in enumerate(scales):
                freq = sample_rate / (2 * scale)
                if freq_range[0] <= freq <= freq_range[1]:
                    sigma = scale / (2 * np.pi)
                    wavelet_length = min(int(6 * sigma), len(data) // 2)
                    
                    if wavelet_length > 3:
                        t = np.arange(-wavelet_length//2, wavelet_length//2)
                        wavelet = np.exp(-t**2 / (2 * sigma**2)) * np.exp(2j * np.pi * freq * t / sample_rate)
                        
                        for j in range(len(data) - len(wavelet) + 1):
                            cwt_matrix[i, j] = np.abs(np.sum(data[j:j+len(wavelet)] * np.conj(wavelet)))
            
            if np.sum(cwt_matrix) > 0:
                max_energy = np.max(cwt_matrix)
                mean_energy = np.mean(cwt_matrix[cwt_matrix > 0])
                if mean_energy > 0:
                    concentration_score = min(1.0, max_energy / (10 * mean_energy))
                    return concentration_score
            
            return 0.2
            
        except Exception:
            return 0.1
    
    # Supporting methods for advanced wavelet quality assessment
    def _calculate_phase_consistency(self, phase_matrix: np.ndarray) -> float:
        """Calculate phase consistency across scales"""
        try:
            if phase_matrix.size == 0:
                return 0.0
            
            # Phase differences between adjacent scales
            phase_diffs = np.diff(phase_matrix, axis=0)
            
            # Circular statistics for phase consistency
            consistency_scores = []
            for i in range(phase_diffs.shape[1]):
                if np.any(~np.isnan(phase_diffs[:, i])):
                    # Circular variance (lower is better)
                    complex_phases = np.exp(1j * phase_diffs[:, i])
                    mean_complex = np.mean(complex_phases[~np.isnan(complex_phases)])
                    circular_variance = 1 - np.abs(mean_complex)
                    consistency_scores.append(1 - circular_variance)
            
            return np.mean(consistency_scores) if consistency_scores else 0.0
        except:
            return 0.3
    
    def _calculate_scale_wise_snr(self, energy_matrix: np.ndarray) -> float:
        """Calculate SNR across different scales"""
        try:
            if energy_matrix.size == 0:
                return 0.0
            
            scale_snrs = []
            for scale_idx in range(energy_matrix.shape[0]):
                scale_energy = energy_matrix[scale_idx, :]
                if len(scale_energy) > 10:
                    # Signal: maximum energy in scale
                    signal = np.max(scale_energy)
                    # Noise: median energy in scale
                    noise = np.median(scale_energy) + 1e-10
                    snr = signal / noise
                    scale_snrs.append(min(1.0, snr / 20.0))
            
            return np.mean(scale_snrs) if scale_snrs else 0.0
        except:
            return 0.3
    
    def _calculate_instantaneous_frequency_stability(self, cwt_matrix: np.ndarray, scales: np.ndarray, sample_rate: float) -> float:
        """Calculate instantaneous frequency stability"""
        try:
            if cwt_matrix.size == 0:
                return 0.0
            
            # Instantaneous frequency from phase derivative
            inst_freq_stability = []
            
            for i, scale in enumerate(scales):
                if i < cwt_matrix.shape[0]:
                    # Phase of complex CWT coefficients
                    phase = np.angle(cwt_matrix[i, :])
                    
                    # Unwrap phase and calculate derivative
                    unwrapped_phase = np.unwrap(phase)
                    if len(unwrapped_phase) > 3:
                        phase_derivative = np.gradient(unwrapped_phase)
                        inst_freq = phase_derivative * sample_rate / (2 * np.pi)
                        
                        # Stability as inverse of standard deviation
                        freq_std = np.std(inst_freq)
                        if freq_std > 0:
                            stability = 1.0 / (1.0 + freq_std)
                            inst_freq_stability.append(stability)
            
            return np.mean(inst_freq_stability) if inst_freq_stability else 0.0
        except:
            return 0.3
    
    def _assess_wavelet_regularity(self, coeffs_list: List[np.ndarray]) -> float:
        """Assess regularity from wavelet coefficients"""
        try:
            regularity_scores = []
            
            for coeffs in coeffs_list:
                if len(coeffs) > 5:
                    # Regularity based on coefficient decay
                    sorted_coeffs = np.sort(np.abs(coeffs))[::-1]
                    
                    # Power law decay assessment
                    if len(sorted_coeffs) > 10:
                        x = np.arange(1, len(sorted_coeffs) + 1)
                        log_coeffs = np.log(sorted_coeffs + 1e-10)
                        log_x = np.log(x)
                        
                        # Linear fit in log-log space
                        slope, _ = np.polyfit(log_x[:10], log_coeffs[:10], 1)
                        regularity = min(1.0, abs(slope) / 3.0)
                        regularity_scores.append(regularity)
            
            return np.mean(regularity_scores) if regularity_scores else 0.0
        except:
            return 0.3
    
    def _assess_frequency_selectivity_daubechies(self, coeffs_list: List[np.ndarray], sample_rate: float, freq_range: List[float]) -> float:
        """Assess frequency selectivity for Daubechies analysis"""
        try:
            selectivity_scores = []
            
            for level, coeffs in enumerate(coeffs_list):
                if len(coeffs) > 0:
                    # Effective frequency range for this level
                    level_freq_range = [sample_rate / (2**(level + 2)), sample_rate / (2**(level + 1))]
                    
                    # Overlap with target frequency range
                    overlap = max(0, min(freq_range[1], level_freq_range[1]) - 
                                max(freq_range[0], level_freq_range[0]))
                    range_width = level_freq_range[1] - level_freq_range[0]
                    
                    if range_width > 0:
                        selectivity = overlap / range_width
                        
                        # Weight by coefficient energy
                        energy_weight = np.sum(coeffs**2)
                        selectivity_scores.append(selectivity * energy_weight)
            
            if selectivity_scores:
                total_energy = sum(selectivity_scores)
                return total_energy / len(selectivity_scores) if total_energy > 0 else 0.0
            return 0.0
        except:
            return 0.3
    
    def _assess_peak_detection_quality(self, cwt_matrix: np.ndarray) -> float:
        """Assess peak detection quality from Mexican hat analysis"""
        try:
            if cwt_matrix.size == 0:
                return 0.0
            
            peak_quality_scores = []
            
            for scale_idx in range(cwt_matrix.shape[0]):
                scale_coeffs = cwt_matrix[scale_idx, :]
                
                if len(scale_coeffs) > 5:
                    # Find peaks and valleys
                    peaks = []
                    valleys = []
                    
                    for i in range(1, len(scale_coeffs) - 1):
                        if scale_coeffs[i] > scale_coeffs[i-1] and scale_coeffs[i] > scale_coeffs[i+1]:
                            peaks.append(i)
                        elif scale_coeffs[i] < scale_coeffs[i-1] and scale_coeffs[i] < scale_coeffs[i+1]:
                            valleys.append(i)
                    
                    # Quality based on peak prominence and spacing
                    if peaks:
                        peak_values = scale_coeffs[peaks]
                        peak_prominence = np.std(peak_values) / (np.mean(np.abs(scale_coeffs)) + 1e-10)
                        peak_quality_scores.append(min(1.0, peak_prominence))
            
            return np.mean(peak_quality_scores) if peak_quality_scores else 0.0
        except:
            return 0.3
    
    def _assess_zero_crossing_quality(self, cwt_matrix: np.ndarray) -> float:
        """Assess zero crossing quality"""
        try:
            if cwt_matrix.size == 0:
                return 0.0
            
            zero_crossing_scores = []
            
            for scale_idx in range(cwt_matrix.shape[0]):
                scale_coeffs = cwt_matrix[scale_idx, :]
                
                if len(scale_coeffs) > 3:
                    # Zero crossings
                    zero_crossings = np.where(np.diff(np.signbit(scale_coeffs)))[0]
                    
                    if len(zero_crossings) > 1:
                        # Regularity of zero crossings
                        crossing_intervals = np.diff(zero_crossings)
                        interval_regularity = 1.0 / (1.0 + np.std(crossing_intervals) / (np.mean(crossing_intervals) + 1e-10))
                        zero_crossing_scores.append(interval_regularity)
            
            return np.mean(zero_crossing_scores) if zero_crossing_scores else 0.0
        except:
            return 0.3
    
    def _assess_wavelet_symmetry(self, cwt_matrix: np.ndarray) -> float:
        """Assess symmetry in wavelet transform"""
        try:
            if cwt_matrix.size == 0:
                return 0.0
            
            symmetry_scores = []
            
            for scale_idx in range(cwt_matrix.shape[0]):
                scale_coeffs = cwt_matrix[scale_idx, :]
                
                if len(scale_coeffs) > 10:
                    # Assess left-right symmetry
                    mid_point = len(scale_coeffs) // 2
                    left_half = scale_coeffs[:mid_point]
                    right_half = scale_coeffs[-mid_point:][::-1]  # Reverse for symmetry check
                    
                    if len(left_half) == len(right_half):
                        correlation = np.corrcoef(left_half, right_half)[0, 1]
                        if not np.isnan(correlation):
                            symmetry_scores.append(abs(correlation))
            
            return np.mean(symmetry_scores) if symmetry_scores else 0.0
        except:
            return 0.3
    
    def _assess_extrema_consistency(self, cwt_matrix: np.ndarray) -> float:
        """Assess consistency of local extrema across scales"""
        try:
            if cwt_matrix.size == 0:
                return 0.0
            
            extrema_positions = []
            
            for scale_idx in range(cwt_matrix.shape[0]):
                scale_coeffs = cwt_matrix[scale_idx, :]
                
                if len(scale_coeffs) > 5:
                    # Find local maxima
                    maxima = []
                    for i in range(1, len(scale_coeffs) - 1):
                        if scale_coeffs[i] > scale_coeffs[i-1] and scale_coeffs[i] > scale_coeffs[i+1]:
                            maxima.append(i)
                    extrema_positions.append(maxima)
            
            # Assess consistency across scales
            if len(extrema_positions) > 1:
                consistency_scores = []
                for i in range(len(extrema_positions) - 1):
                    current_extrema = extrema_positions[i]
                    next_extrema = extrema_positions[i + 1]
                    
                    if current_extrema and next_extrema:
                        # Simple consistency measure based on position overlap
                        overlap_count = 0
                        for pos in current_extrema:
                            # Allow for slight position shifts between scales
                            if any(abs(pos - next_pos) <= 2 for next_pos in next_extrema):
                                overlap_count += 1
                        
                        consistency = overlap_count / max(len(current_extrema), len(next_extrema))
                        consistency_scores.append(consistency)
                
                return np.mean(consistency_scores) if consistency_scores else 0.0
            
            return 0.0
        except:
            return 0.3
    
    def _assess_tf_localization(self, tf_matrix: np.ndarray) -> float:
        """Assess time-frequency localization quality"""
        try:
            if tf_matrix.size == 0:
                return 0.0
            
            # Concentration in time-frequency domain
            max_energy = np.max(tf_matrix)
            mean_energy = np.mean(tf_matrix[tf_matrix > 0])
            
            if mean_energy > 0:
                concentration = max_energy / mean_energy
                localization_score = min(1.0, concentration / 10.0)
            else:
                localization_score = 0.0
            
            return localization_score
        except:
            return 0.3
    
    def _assess_frequency_resolution(self, tf_matrix: np.ndarray, frequencies: np.ndarray) -> float:
        """Assess frequency resolution from time-frequency matrix"""
        try:
            if tf_matrix.size == 0:
                return 0.0
            
            # Frequency resolution based on spectral peak width
            freq_profile = np.mean(tf_matrix, axis=1)  # Average over time
            
            if len(freq_profile) > 3 and np.max(freq_profile) > 0:
                # Find main spectral peak
                peak_idx = np.argmax(freq_profile)
                peak_value = freq_profile[peak_idx]
                
                # Find half-maximum points
                half_max = peak_value / 2
                left_idx = peak_idx
                right_idx = peak_idx
                
                # Search left
                while left_idx > 0 and freq_profile[left_idx] > half_max:
                    left_idx -= 1
                
                # Search right
                while right_idx < len(freq_profile) - 1 and freq_profile[right_idx] > half_max:
                    right_idx += 1
                
                # Resolution based on inverse of peak width
                peak_width = right_idx - left_idx + 1
                resolution = 1.0 / (peak_width + 1)
                return min(1.0, resolution * 10)
            
            return 0.0
        except:
            return 0.3
    
    def _assess_temporal_resolution_gabor(self, tf_matrix: np.ndarray) -> float:
        """Assess temporal resolution from Gabor analysis"""
        try:
            if tf_matrix.size == 0:
                return 0.0
            
            # Temporal resolution based on time localization
            time_profile = np.mean(tf_matrix, axis=0)  # Average over frequency
            
            if len(time_profile) > 3 and np.max(time_profile) > 0:
                # Temporal spread assessment
                max_idx = np.argmax(time_profile)
                max_value = time_profile[max_idx]
                
                # Effective temporal width
                threshold = max_value * 0.1  # 10% threshold
                above_threshold = time_profile > threshold
                
                if np.any(above_threshold):
                    temporal_width = np.sum(above_threshold)
                    resolution = 1.0 / (temporal_width + 1)
                    return min(1.0, resolution * len(time_profile) / 10)
            
            return 0.0
        except:
            return 0.3
    
    def _assess_tf_domain_snr(self, tf_matrix: np.ndarray) -> float:
        """Assess SNR in time-frequency domain"""
        try:
            if tf_matrix.size == 0:
                return 0.0
            
            # Signal: maximum energy
            signal = np.max(tf_matrix)
            
            # Noise: lower percentile of energy distribution
            noise = np.percentile(tf_matrix[tf_matrix > 0], 25) if np.any(tf_matrix > 0) else 1e-10
            
            snr = signal / (noise + 1e-10)
            return min(1.0, snr / 20.0)
        except:
            return 0.3
    
    def _calculate_time_spread(self, data: np.ndarray, sample_rate: float) -> float:
        """Calculate temporal spread of signal"""
        try:
            # Energy-weighted temporal spread
            energy = data**2
            time_indices = np.arange(len(data))
            
            if np.sum(energy) > 0:
                # Centroid
                centroid = np.sum(time_indices * energy) / np.sum(energy)
                
                # Second moment (spread)
                spread = np.sqrt(np.sum((time_indices - centroid)**2 * energy) / np.sum(energy))
                return spread / sample_rate
            
            return len(data) / sample_rate
        except:
            return 1.0
    
    def _calculate_frequency_spread(self, data: np.ndarray, sample_rate: float, freq_range: List[float]) -> float:
        """Calculate frequency spread of signal"""
        try:
            # FFT and frequency domain analysis
            fft_data = np.fft.fft(data)
            freqs = np.fft.fftfreq(len(data), 1/sample_rate)
            psd = np.abs(fft_data)**2
            
            # Focus on positive frequencies in range
            pos_mask = (freqs >= freq_range[0]) & (freqs <= freq_range[1])
            if not np.any(pos_mask):
                return freq_range[1] - freq_range[0]
            
            freqs_pos = freqs[pos_mask]
            psd_pos = psd[pos_mask]
            
            if np.sum(psd_pos) > 0:
                # Frequency centroid
                freq_centroid = np.sum(freqs_pos * psd_pos) / np.sum(psd_pos)
                
                # Frequency spread
                freq_spread = np.sqrt(np.sum((freqs_pos - freq_centroid)**2 * psd_pos) / np.sum(psd_pos))
                return freq_spread
            
            return freq_range[1] - freq_range[0]
        except:
            return 1.0
    
    # Additional supporting methods for volcanic signal analysis
    def _assess_multiscale_energy_distribution(self, data: np.ndarray, sample_rate: float, freq_range: List[float]) -> float:
        """Assess energy distribution across multiple scales"""
        try:
            # Multi-scale energy analysis using different window sizes
            scales = [int(0.1 * sample_rate), int(0.5 * sample_rate), int(2.0 * sample_rate)]
            energy_distributions = []
            
            for scale in scales:
                if scale < len(data):
                    # Windowed energy analysis
                    window_energies = []
                    step = max(1, scale // 4)
                    
                    for i in range(0, len(data) - scale + 1, step):
                        window = data[i:i + scale]
                        energy = np.sum(window**2)
                        window_energies.append(energy)
                    
                    if window_energies:
                        # Energy distribution quality
                        energy_std = np.std(window_energies)
                        energy_mean = np.mean(window_energies)
                        if energy_mean > 0:
                            energy_cv = energy_std / energy_mean
                            distribution_quality = 1.0 / (1.0 + energy_cv)
                            energy_distributions.append(distribution_quality)
            
            return np.mean(energy_distributions) if energy_distributions else 0.0
        except:
            return 0.3
    
    def _assess_phase_coherence_multiscale(self, data: np.ndarray, sample_rate: float, freq_range: List[float]) -> float:
        """Assess phase coherence across multiple scales"""
        try:
            # Hilbert transform for phase analysis
            from scipy.signal import hilbert
            
            # Multiple frequency bands within the range
            n_bands = min(5, max(2, int((freq_range[1] - freq_range[0]) / 2)))
            freq_bands = np.linspace(freq_range[0], freq_range[1], n_bands + 1)
            
            phase_coherences = []
            
            for i in range(len(freq_bands) - 1):
                band_low, band_high = freq_bands[i], freq_bands[i + 1]
                
                # Simple bandpass filtering (approximate)
                fft_data = np.fft.fft(data)
                freqs = np.fft.fftfreq(len(data), 1/sample_rate)
                
                # Create bandpass filter
                filter_mask = (np.abs(freqs) >= band_low) & (np.abs(freqs) <= band_high)
                filtered_fft = fft_data * filter_mask
                filtered_signal = np.real(np.fft.ifft(filtered_fft))
                
                if np.std(filtered_signal) > 1e-10:
                    # Analytic signal and phase
                    analytic_signal = hilbert(filtered_signal)
                    phase = np.angle(analytic_signal)
                    
                    # Phase coherence as consistency of phase derivatives
                    phase_diff = np.diff(np.unwrap(phase))
                    if len(phase_diff) > 1:
                        phase_std = np.std(phase_diff)
                        coherence = 1.0 / (1.0 + phase_std)
                        phase_coherences.append(coherence)
            
            return np.mean(phase_coherences) if phase_coherences else 0.0
        except:
            return 0.3
    
    def _calculate_wavelet_entropy_quality(self, data: np.ndarray, sample_rate: float, freq_range: List[float]) -> float:
        """Calculate wavelet entropy-based quality metrics"""
        try:
            # Simple multi-resolution entropy analysis
            max_levels = min(6, int(np.log2(len(data))) - 1)
            if max_levels < 2:
                return 0.3
            
            entropies = []
            current_data = data.copy()
            
            for level in range(max_levels):
                if len(current_data) > 4:
                    # Simple wavelet-like decomposition
                    # Approximate detail coefficients
                    detail = np.diff(current_data[::2])  # High-pass approximation
                    
                    if len(detail) > 0:
                        # Energy distribution entropy
                        energy = detail**2
                        energy_normalized = energy / (np.sum(energy) + 1e-10)
                        energy_normalized = energy_normalized[energy_normalized > 1e-10]
                        
                        if len(energy_normalized) > 1:
                            entropy = -np.sum(energy_normalized * np.log(energy_normalized))
                            entropies.append(entropy)
                    
                    # Decimation for next level
                    current_data = current_data[::2]
                else:
                    break
            
            if entropies:
                # Entropy quality: prefer moderate entropy (structured but not too regular)
                mean_entropy = np.mean(entropies)
                optimal_entropy = np.log(10)  # Reference entropy
                entropy_quality = np.exp(-abs(mean_entropy - optimal_entropy) / optimal_entropy)
                return min(1.0, entropy_quality)
            
            return 0.0
        except:
            return 0.3
    
    def _assess_singularity_detection_quality(self, data: np.ndarray, sample_rate: float) -> float:
        """Assess quality of singularity detection using wavelets"""
        try:
            # Simple singularity detection using local maxima of wavelet transform modulus
            scales = np.logspace(0, 2, 20)
            singularity_measures = []
            
            for scale in scales:
                if scale < len(data) / 4:
                    # Approximate Mexican hat wavelet for singularity detection
                    sigma = scale / (2 * np.pi)
                    wavelet_length = min(int(8 * sigma), len(data) // 2)
                    
                    if wavelet_length > 3:
                        t = np.arange(-wavelet_length//2, wavelet_length//2)
                        mexican_hat = (1 - t**2 / sigma**2) * np.exp(-t**2 / (2 * sigma**2))
                        
                        # Convolution
                        convolution = np.convolve(data, mexican_hat, mode='valid')
                        
                        if len(convolution) > 5:
                            # Local maxima detection
                            maxima_count = 0
                            for i in range(1, len(convolution) - 1):
                                if (convolution[i] > convolution[i-1] and 
                                    convolution[i] > convolution[i+1] and 
                                    abs(convolution[i]) > 0.1 * np.max(np.abs(convolution))):
                                    maxima_count += 1
                            
                            # Singularity quality based on maxima density
                            maxima_density = maxima_count / len(convolution)
                            singularity_measures.append(min(1.0, maxima_density * 50))
            
            return np.mean(singularity_measures) if singularity_measures else 0.0
        except:
            return 0.3
    
    def _assess_amplitude_modulation(self, data: np.ndarray) -> float:
        """Assess amplitude modulation characteristics"""
        try:
            from scipy.signal import hilbert
            
            # Envelope extraction using Hilbert transform
            analytic_signal = hilbert(data)
            envelope = np.abs(analytic_signal)
            
            if len(envelope) > 10 and np.std(envelope) > 1e-10:
                # Amplitude modulation index
                am_index = np.std(envelope) / np.mean(envelope)
                am_quality = min(1.0, am_index)
                
                # Envelope regularity
                envelope_smoothness = 1.0 / (1.0 + np.std(np.diff(envelope)) / (np.mean(envelope) + 1e-10))
                
                return 0.7 * am_quality + 0.3 * envelope_smoothness
            
            return 0.0
        except:
            return 0.3
    
    def _assess_frequency_modulation_quality(self, data: np.ndarray, sample_rate: float) -> float:
        """Assess frequency modulation quality"""
        try:
            from scipy.signal import hilbert
            
            # Instantaneous frequency using Hilbert transform
            analytic_signal = hilbert(data)
            phase = np.angle(analytic_signal)
            unwrapped_phase = np.unwrap(phase)
            
            if len(unwrapped_phase) > 3:
                inst_freq = np.diff(unwrapped_phase) * sample_rate / (2 * np.pi)
                
                # Frequency modulation characteristics
                freq_range = np.max(inst_freq) - np.min(inst_freq)
                freq_stability = 1.0 / (1.0 + np.std(inst_freq) / (np.mean(np.abs(inst_freq)) + 1e-10))
                
                # Combined FM quality
                fm_quality = 0.6 * min(1.0, freq_range / 10.0) + 0.4 * freq_stability
                return fm_quality
            
            return 0.0
        except:
            return 0.3
    
    def _assess_onset_sharpness(self, data: np.ndarray) -> float:
        """Assess onset sharpness for volcanic signals"""
        try:
            # Find potential onset using energy-based method
            energy = np.cumsum(data**2)
            energy_normalized = energy / (energy[-1] + 1e-10)
            
            # Find 10% and 90% energy points
            onset_10 = np.argmax(energy_normalized >= 0.1)
            onset_90 = np.argmax(energy_normalized >= 0.9)
            
            if onset_90 > onset_10:
                # Onset sharpness as inverse of rise time
                rise_time = onset_90 - onset_10
                sharpness = min(1.0, len(data) / (4 * rise_time + 1))
                return sharpness
            
            return 0.0
        except:
            return 0.3
    
    def _assess_coda_quality(self, data: np.ndarray, sample_rate: float) -> float:
        """Assess coda quality for volcanic signals"""
        try:
            # Assume coda is in the latter half of the signal
            coda_start = len(data) // 2
            coda = data[coda_start:]
            
            if len(coda) > 10:
                # Exponential decay assessment
                envelope = np.abs(coda)
                
                # Fit exponential decay
                time_indices = np.arange(len(envelope))
                if np.max(envelope) > 1e-10:
                    log_envelope = np.log(envelope + 1e-10)
                    
                    # Simple linear fit to log envelope
                    decay_rate, _ = np.polyfit(time_indices, log_envelope, 1)
                    
                    # Quality based on exponential nature of decay
                    if decay_rate < 0:  # Should be decaying
                        decay_quality = min(1.0, abs(decay_rate) * 100)
                    else:
                        decay_quality = 0.0
                    
                    # Smoothness of decay
                    smoothness = 1.0 / (1.0 + np.std(np.diff(log_envelope)))
                    
                    return 0.7 * decay_quality + 0.3 * smoothness
            
            return 0.0
        except:
            return 0.3
    
    def _assess_volcanic_frequency_content(self, data: np.ndarray, sample_rate: float) -> float:
        """Assess volcanic frequency content characteristics"""
        try:
            # FFT analysis
            fft_data = np.fft.fft(data)
            freqs = np.fft.fftfreq(len(data), 1/sample_rate)
            psd = np.abs(fft_data)**2
            
            # Focus on positive frequencies
            pos_mask = freqs > 0
            freqs_pos = freqs[pos_mask]
            psd_pos = psd[pos_mask]
            
            # Volcanic frequency characteristics
            volcanic_bands = {
                'low_freq': [0.1, 2.0],      # LP events, tremor
                'mid_freq': [2.0, 10.0],     # Mixed signals
                'high_freq': [10.0, 50.0]    # VT earthquakes
            }
            
            band_energies = {}
            total_energy = np.sum(psd_pos)
            
            for band_name, (f_low, f_high) in volcanic_bands.items():
                band_mask = (freqs_pos >= f_low) & (freqs_pos <= f_high)
                band_energy = np.sum(psd_pos[band_mask])
                band_energies[band_name] = band_energy / (total_energy + 1e-10)
            
            # Assess volcanic character based on frequency distribution
            volcanic_score = 0.0
            
            # LP/tremor character (low frequency dominance)
            if band_energies['low_freq'] > 0.3:
                volcanic_score += 0.4 * band_energies['low_freq']
            
            # VT character (high frequency content)
            if band_energies['high_freq'] > 0.2:
                volcanic_score += 0.3 * band_energies['high_freq']
            
            # Balanced character
            volcanic_score += 0.3 * band_energies['mid_freq']
            
            return min(1.0, volcanic_score)
        except:
            return 0.3
    
    def _assess_volcanic_onset_characteristics(self, data: np.ndarray, sample_rate: float) -> float:
        """Assess volcanic-specific onset characteristics"""
        try:
            # Multiple onset detection methods
            onset_scores = []
            
            # 1. Energy-based onset
            energy = data**2
            cumulative_energy = np.cumsum(energy)
            if cumulative_energy[-1] > 0:
                energy_onset = np.argmax(cumulative_energy >= 0.05 * cumulative_energy[-1])
                energy_sharpness = min(1.0, 100.0 / (energy_onset + 1))
                onset_scores.append(energy_sharpness)
            
            # 2. Amplitude-based onset
            abs_data = np.abs(data)
            max_amp = np.max(abs_data)
            if max_amp > 0:
                amp_onset = np.argmax(abs_data >= 0.1 * max_amp)
                amp_sharpness = min(1.0, 100.0 / (amp_onset + 1))
                onset_scores.append(amp_sharpness)
            
            # 3. Gradient-based onset
            gradient = np.abs(np.gradient(data))
            max_grad = np.max(gradient)
            if max_grad > 0:
                grad_onset = np.argmax(gradient >= 0.3 * max_grad)
                grad_sharpness = min(1.0, 100.0 / (grad_onset + 1))
                onset_scores.append(grad_sharpness)
            
            return np.mean(onset_scores) if onset_scores else 0.0
        except:
            return 0.3
    
    def _assess_volcanic_duration_characteristics(self, data: np.ndarray, sample_rate: float) -> float:
        """Assess volcanic signal duration characteristics"""
        try:
            signal_duration = len(data) / sample_rate
            
            # Volcanic signal duration preferences
            duration_scores = {}
            
            # VT earthquakes: short duration (0.1 - 5 seconds)
            if 0.1 <= signal_duration <= 5.0:
                duration_scores['vt'] = 1.0
            elif signal_duration < 0.1:
                duration_scores['vt'] = signal_duration / 0.1
            else:
                duration_scores['vt'] = 5.0 / signal_duration
            
            # LP events: medium duration (5 - 60 seconds)
            if 5.0 <= signal_duration <= 60.0:
                duration_scores['lp'] = 1.0
            elif signal_duration < 5.0:
                duration_scores['lp'] = signal_duration / 5.0
            else:
                duration_scores['lp'] = 60.0 / signal_duration
            
            # Tremor: long duration (60+ seconds)
            if signal_duration >= 60.0:
                duration_scores['tremor'] = min(1.0, signal_duration / 300.0)
            else:
                duration_scores['tremor'] = signal_duration / 60.0
            
            # Return best match
            return max(duration_scores.values())
        except:
            return 0.3
    
    def _assess_volcanic_amplitude_characteristics(self, data: np.ndarray) -> float:
        """Assess volcanic signal amplitude characteristics"""
        try:
            # Amplitude distribution analysis
            abs_data = np.abs(data)
            max_amp = np.max(abs_data)
            
            if max_amp > 0:
                # Dynamic range
                min_amp = np.min(abs_data[abs_data > 0]) if np.any(abs_data > 0) else max_amp
                dynamic_range = max_amp / (min_amp + 1e-10)
                dynamic_score = min(1.0, np.log10(dynamic_range) / 3.0)
                
                # Amplitude distribution shape
                normalized_amps = abs_data / max_amp
                
                # Kurtosis as measure of amplitude distribution shape
                kurtosis = np.mean((normalized_amps - np.mean(normalized_amps))**4) / (np.var(normalized_amps)**2 + 1e-10)
                kurtosis_score = min(1.0, kurtosis / 10.0)
                
                # Peak-to-RMS ratio
                rms = np.sqrt(np.mean(data**2))
                peak_to_rms = max_amp / (rms + 1e-10)
                peak_score = min(1.0, peak_to_rms / 5.0)
                
                return 0.4 * dynamic_score + 0.3 * kurtosis_score + 0.3 * peak_score
            
            return 0.0
        except:
            return 0.3
    
    def _assess_spectral_evolution(self, data: np.ndarray, sample_rate: float) -> float:
        """Assess spectral evolution characteristics"""
        try:
            # Time-frequency analysis using short-time FFT
            window_size = min(256, len(data) // 4)
            if window_size < 8:
                return 0.3
            
            step_size = window_size // 2
            n_windows = (len(data) - window_size) // step_size + 1
            
            if n_windows < 2:
                return 0.3
            
            spectrograms = []
            for i in range(n_windows):
                start_idx = i * step_size
                window = data[start_idx:start_idx + window_size]
                
                # FFT of window
                fft_window = np.fft.fft(window)
                psd_window = np.abs(fft_window[:window_size//2])**2
                spectrograms.append(psd_window)
            
            spectrograms = np.array(spectrograms)
            
            # Spectral evolution metrics
            evolution_scores = []
            
            # 1. Spectral centroid evolution
            freqs = np.fft.fftfreq(window_size, 1/sample_rate)[:window_size//2]
            centroids = []
            
            for i in range(len(spectrograms)):
                psd = spectrograms[i]
                if np.sum(psd) > 0:
                    centroid = np.sum(freqs * psd) / np.sum(psd)
                    centroids.append(centroid)
            
            if len(centroids) > 1:
                centroid_evolution = np.std(centroids) / (np.mean(centroids) + 1e-10)
                evolution_scores.append(min(1.0, centroid_evolution))
            
            # 2. Spectral rolloff evolution
            rolloffs = []
            for i in range(len(spectrograms)):
                psd = spectrograms[i]
                cumsum_psd = np.cumsum(psd)
                if cumsum_psd[-1] > 0:
                    rolloff_idx = np.argmax(cumsum_psd >= 0.85 * cumsum_psd[-1])
                    rolloffs.append(freqs[rolloff_idx])
            
            if len(rolloffs) > 1:
                rolloff_evolution = np.std(rolloffs) / (np.mean(rolloffs) + 1e-10)
                evolution_scores.append(min(1.0, rolloff_evolution))
            
            return np.mean(evolution_scores) if evolution_scores else 0.0
        except:
            return 0.3

    def _assess_volcanic_frequency_signatures(self, data: np.ndarray, sample_rate: float, config: Dict) -> float:
        """Assess volcanic-specific frequency signatures"""
        # Volcanic earthquake frequency characteristics
        volcanic_bands = {
            'vt_earthquakes': [1.0, 15.0],      # Volcano-tectonic
            'lp_events': [0.5, 5.0],            # Long-period events
            'tremor': [0.5, 3.0],               # Volcanic tremor
            'explosion': [0.1, 10.0],           # Explosion signals
            'rockfall': [5.0, 50.0]             # Rockfall signals
        }
        
        # Calculate FFT
        fft_data = np.fft.fft(data)
        freqs = np.fft.fftfreq(len(data), 1/sample_rate)
        psd = np.abs(fft_data)**2
        
        pos_mask = freqs >= 0
        freqs = freqs[pos_mask]
        psd = psd[pos_mask]
        
        volcanic_scores = []
        
        for event_type, freq_band in volcanic_bands.items():
            band_mask = (freqs >= freq_band[0]) & (freqs <= freq_band[1])
            if np.sum(band_mask) > 0:
                band_energy = np.sum(psd[band_mask])
                total_energy = np.sum(psd)
                
                if total_energy > 0:
                    relative_energy = band_energy / total_energy
                    
                    # Spectral shape characteristic of this event type
                    if event_type == 'lp_events':
                        # Long-period events have characteristic spectral decay
                        shape_score = self._assess_lp_spectral_shape(psd[band_mask], freqs[band_mask])
                    elif event_type == 'tremor':
                        # Tremor has characteristic harmonic structure
                        shape_score = self._assess_tremor_harmonics(psd[band_mask], freqs[band_mask])
                    else:
                        shape_score = 0.5  # Default
                    
                    volcanic_scores.append(relative_energy * (1 + shape_score))
        
        return np.mean(volcanic_scores) if volcanic_scores else 0.0

    def _calculate_spectral_coherence(self, data: np.ndarray, sample_rate: float) -> float:
        """Calculate spectral coherence and stability"""
        # Split data into segments for coherence analysis
        n_segments = min(8, len(data) // 128)
        if n_segments < 2:
            return 0.5
        
        segment_length = len(data) // n_segments
        segment_psds = []
        
        for i in range(n_segments):
            start_idx = i * segment_length
            end_idx = start_idx + segment_length
            segment = data[start_idx:end_idx]
            
            fft_data = np.fft.fft(segment)
            psd = np.abs(fft_data)**2
            segment_psds.append(psd[:len(psd)//2])
        
        # Calculate cross-correlation between segment PSDs
        correlations = []
        for i in range(n_segments - 1):
            for j in range(i + 1, n_segments):
                corr = np.corrcoef(segment_psds[i], segment_psds[j])[0, 1]
                if not np.isnan(corr):
                    correlations.append(corr)
        
        return np.mean(correlations) if correlations else 0.5

    def _assess_harmonic_content(self, data: np.ndarray, sample_rate: float, freq_range: List[float]) -> float:
        """Assess harmonic content and tonal characteristics"""
        fft_data = np.fft.fft(data)
        freqs = np.fft.fftfreq(len(data), 1/sample_rate)
        magnitude = np.abs(fft_data)
        
        pos_mask = freqs >= 0
        freqs = freqs[pos_mask]
        magnitude = magnitude[pos_mask]
        
        # Find peaks in frequency domain
        peaks = []
        for i in range(1, len(magnitude) - 1):
            if magnitude[i] > magnitude[i-1] and magnitude[i] > magnitude[i+1]:
                if freq_range[0] <= freqs[i] <= freq_range[1]:
                    peaks.append((freqs[i], magnitude[i]))
        
        if len(peaks) < 2:
            return 0.0
        
        # Sort peaks by magnitude
        peaks.sort(key=lambda x: x[1], reverse=True)
        
        # Check for harmonic relationships
        harmonic_score = 0.0
        fundamental_freq = peaks[0][0]
        
        for i, (freq, mag) in enumerate(peaks[1:6]):  # Check first 5 harmonics
            expected_harmonic = fundamental_freq * (i + 2)
            
            # Find closest peak to expected harmonic
            freq_tolerance = fundamental_freq * 0.1  # 10% tolerance
            if abs(freq - expected_harmonic) < freq_tolerance:
                harmonic_score += mag / peaks[0][1]  # Normalize by fundamental
        
        return min(1.0, harmonic_score / 5.0)

    def _calculate_cross_channel_coherence(self, data: np.ndarray, sample_rate: float) -> float:
        """Calculate coherence between channels for multi-channel data"""
        if data.shape[1] < 2:
            return 1.0  # Single channel, perfect "coherence"
        
        coherences = []
        
        for i in range(data.shape[1]):
            for j in range(i + 1, data.shape[1]):
                # Simple cross-correlation in frequency domain
                fft1 = np.fft.fft(data[:, i])
                fft2 = np.fft.fft(data[:, j])
                
                cross_psd = fft1 * np.conj(fft2)
                auto_psd1 = np.abs(fft1)**2
                auto_psd2 = np.abs(fft2)**2
                
                # Coherence calculation
                coherence = np.abs(cross_psd)**2 / (auto_psd1 * auto_psd2 + 1e-10)
                mean_coherence = np.mean(coherence[:len(coherence)//2])
                coherences.append(mean_coherence)
        
        return np.mean(coherences) if coherences else 1.0

    def _calculate_spectral_flatness(self, psd: np.ndarray) -> float:
        """Calculate spectral flatness (Wiener entropy)"""
        # Geometric mean / Arithmetic mean
        if len(psd) == 0 or np.any(psd <= 0):
            return 0.0
        
        geometric_mean = np.exp(np.mean(np.log(psd + 1e-10)))
        arithmetic_mean = np.mean(psd)
        
        if arithmetic_mean > 0:
            return geometric_mean / arithmetic_mean
        else:
            return 0.0

    def _calculate_spectral_centroid(self, psd: np.ndarray, freqs: np.ndarray) -> float:
        """Calculate spectral centroid (center of mass of spectrum)"""
        if len(psd) == 0 or np.sum(psd) == 0:
            return 0.0
        
        return np.sum(freqs * psd) / np.sum(psd)

    def _assess_lp_spectral_shape(self, psd: np.ndarray, freqs: np.ndarray) -> float:
        """Assess spectral shape characteristic of long-period events"""
        if len(psd) < 3:
            return 0.0
        
        # LP events typically have peak at low frequency with decay
        peak_idx = np.argmax(psd)
        peak_freq = freqs[peak_idx]
        
        # Check if peak is in low-frequency part
        if peak_freq > np.mean(freqs):
            return 0.0
        
        # Check spectral decay after peak
        if peak_idx < len(psd) - 2:
            decay_slope = np.polyfit(freqs[peak_idx:], np.log(psd[peak_idx:] + 1e-10), 1)[0]
            return max(0.0, min(1.0, -decay_slope))  # Negative slope is good
        
        return 0.5

    def _assess_tremor_harmonics(self, psd: np.ndarray, freqs: np.ndarray) -> float:
        """Assess harmonic structure characteristic of volcanic tremor"""
        if len(psd) < 10:
            return 0.0
        
        # Find the fundamental frequency (strongest peak)
        peak_idx = np.argmax(psd)
        fundamental = freqs[peak_idx]
        
        # Look for harmonics
        harmonic_strength = 0.0
        
        for harmonic in [2, 3, 4]:  # Check 2nd, 3rd, 4th harmonics
            target_freq = fundamental * harmonic
            
            # Find closest frequency bin
            freq_diffs = np.abs(freqs - target_freq)
            closest_idx = np.argmin(freq_diffs)
            
            if freq_diffs[closest_idx] < fundamental * 0.1:  # Within 10% tolerance
                harmonic_strength += psd[closest_idx] / psd[peak_idx]
        
        return min(1.0, harmonic_strength / 3.0)  # Normalize by number of harmonics checked
    
    def _apply_bandpass_filter(self, data: np.ndarray, freq_range: List[float], config: Dict) -> np.ndarray:
        """Advanced multi-filter bandpass implementation with volcanic signal optimization"""
        try:
            sample_rate = config.get('sample_rate', 100.0)
            filter_type = config.get('filter_type', 'adaptive')
            
            # Multi-filter approach with different filter types
            filter_results = {}
            
            # 1. Butterworth filter (smooth passband)
            butterworth_filtered = self._apply_butterworth_filter(data, freq_range, sample_rate, config)
            filter_results['butterworth'] = butterworth_filtered
            
            # 2. Chebyshev Type I filter (sharp cutoff, passband ripple)
            chebyshev1_filtered = self._apply_chebyshev1_filter(data, freq_range, sample_rate, config)
            filter_results['chebyshev1'] = chebyshev1_filtered
            
            # 3. Chebyshev Type II filter (sharp cutoff, stopband ripple)
            chebyshev2_filtered = self._apply_chebyshev2_filter(data, freq_range, sample_rate, config)
            filter_results['chebyshev2'] = chebyshev2_filtered
            
            # 4. Elliptic filter (sharpest cutoff, both passband and stopband ripple)
            elliptic_filtered = self._apply_elliptic_filter(data, freq_range, sample_rate, config)
            filter_results['elliptic'] = elliptic_filtered
            
            # 5. Bessel filter (maximally flat group delay)
            bessel_filtered = self._apply_bessel_filter(data, freq_range, sample_rate, config)
            filter_results['bessel'] = bessel_filtered
            
            # 6. FIR filter (linear phase response)
            fir_filtered = self._apply_fir_filter(data, freq_range, sample_rate, config)
            filter_results['fir'] = fir_filtered
            
            # 7. Notch filter for power line interference
            notch_filtered = self._apply_notch_filter(data, sample_rate, config)
            filter_results['notch'] = notch_filtered
            
            # 8. Adaptive Wiener filter
            wiener_filtered = self._apply_wiener_filter(data, freq_range, sample_rate, config)
            filter_results['wiener'] = wiener_filtered
            
            # 9. Volcanic signal-specific filter
            volcanic_filtered = self._apply_volcanic_optimized_filter(data, freq_range, sample_rate, config)
            filter_results['volcanic'] = volcanic_filtered
            
            # 10. Zero-phase filter (forward-backward filtering)
            zero_phase_filtered = self._apply_zero_phase_filter(data, freq_range, sample_rate, config)
            filter_results['zero_phase'] = zero_phase_filtered
            
            # Adaptive filter selection based on signal characteristics
            if filter_type == 'adaptive':
                optimal_filter = self._select_optimal_filter(data, filter_results, freq_range, sample_rate, config)
                filtered_data = optimal_filter
            else:
                # Use specified filter type or default to Butterworth
                filtered_data = filter_results.get(filter_type, filter_results['butterworth'])
            
            # Post-processing and quality enhancement
            enhanced_data = self._enhance_filtered_signal(filtered_data, data, freq_range, sample_rate, config)
            
            # Volcanic signal-specific post-processing
            final_data = self._apply_volcanic_postprocessing(enhanced_data, freq_range, sample_rate, config)
            
            return final_data
            
        except Exception as e:
            # Fallback to simplified filtering
            return self._apply_bandpass_filter_simple(data, freq_range, config)
    
    def _apply_butterworth_filter(self, data: np.ndarray, freq_range: List[float], sample_rate: float, config: Dict) -> np.ndarray:
        """Apply Butterworth bandpass filter with optimal order selection"""
        try:
            # Adaptive order selection based on signal characteristics
            signal_complexity = np.std(np.diff(data)) / (np.std(data) + 1e-10)
            
            if signal_complexity > 2.0:
                filter_order = 6  # Higher order for complex signals
            elif signal_complexity > 1.0:
                filter_order = 4  # Medium order
            else:
                filter_order = 2  # Lower order for simple signals
            
            # Frequency normalization
            nyquist = sample_rate / 2.0
            low_norm = max(0.01, freq_range[0] / nyquist)
            high_norm = min(0.99, freq_range[1] / nyquist)
            
            if high_norm <= low_norm:
                return data
            
            # Butterworth filter design using frequency domain implementation
            filtered_data = self._frequency_domain_butterworth(data, low_norm, high_norm, filter_order)
            
            return filtered_data
            
        except Exception:
            return data
    
    def _apply_chebyshev1_filter(self, data: np.ndarray, freq_range: List[float], sample_rate: float, config: Dict) -> np.ndarray:
        """Apply Chebyshev Type I filter with controlled passband ripple"""
        try:
            # Chebyshev I parameters
            passband_ripple = config.get('passband_ripple', 1.0)  # dB
            filter_order = config.get('chebyshev_order', 4)
            
            nyquist = sample_rate / 2.0
            low_norm = max(0.01, freq_range[0] / nyquist)
            high_norm = min(0.99, freq_range[1] / nyquist)
            
            if high_norm <= low_norm:
                return data
            
            # Frequency domain Chebyshev Type I implementation
            filtered_data = self._frequency_domain_chebyshev1(data, low_norm, high_norm, filter_order, passband_ripple)
            
            return filtered_data
            
        except Exception:
            return data
    
    def _apply_chebyshev2_filter(self, data: np.ndarray, freq_range: List[float], sample_rate: float, config: Dict) -> np.ndarray:
        """Apply Chebyshev Type II filter with controlled stopband attenuation"""
        try:
            # Chebyshev II parameters
            stopband_attenuation = config.get('stopband_attenuation', 40.0)  # dB
            filter_order = config.get('chebyshev2_order', 4)
            
            nyquist = sample_rate / 2.0
            low_norm = max(0.01, freq_range[0] / nyquist)
            high_norm = min(0.99, freq_range[1] / nyquist)
            
            if high_norm <= low_norm:
                return data
            
            # Frequency domain Chebyshev Type II implementation
            filtered_data = self._frequency_domain_chebyshev2(data, low_norm, high_norm, filter_order, stopband_attenuation)
            
            return filtered_data
            
        except Exception:
            return data
    
    def _apply_elliptic_filter(self, data: np.ndarray, freq_range: List[float], sample_rate: float, config: Dict) -> np.ndarray:
        """Apply elliptic filter with sharp transition and minimal filter length"""
        try:
            # Elliptic filter parameters
            passband_ripple = config.get('elliptic_passband_ripple', 0.5)  # dB
            stopband_attenuation = config.get('elliptic_stopband_attenuation', 50.0)  # dB
            filter_order = config.get('elliptic_order', 4)
            
            nyquist = sample_rate / 2.0
            low_norm = max(0.01, freq_range[0] / nyquist)
            high_norm = min(0.99, freq_range[1] / nyquist)
            
            if high_norm <= low_norm:
                return data
            
            # Frequency domain elliptic filter implementation
            filtered_data = self._frequency_domain_elliptic(data, low_norm, high_norm, filter_order, 
                                                          passband_ripple, stopband_attenuation)
            
            return filtered_data
            
        except Exception:
            return data
    
    def _apply_bessel_filter(self, data: np.ndarray, freq_range: List[float], sample_rate: float, config: Dict) -> np.ndarray:
        """Apply Bessel filter with maximally flat group delay"""
        try:
            # Bessel filter for minimal phase distortion
            filter_order = config.get('bessel_order', 4)
            
            nyquist = sample_rate / 2.0
            low_norm = max(0.01, freq_range[0] / nyquist)
            high_norm = min(0.99, freq_range[1] / nyquist)
            
            if high_norm <= low_norm:
                return data
            
            # Frequency domain Bessel filter implementation
            filtered_data = self._frequency_domain_bessel(data, low_norm, high_norm, filter_order)
            
            return filtered_data
            
        except Exception:
            return data
    
    def _apply_fir_filter(self, data: np.ndarray, freq_range: List[float], sample_rate: float, config: Dict) -> np.ndarray:
        """Apply FIR filter with linear phase response"""
        try:
            # FIR filter parameters
            filter_length = config.get('fir_length', min(256, len(data) // 4))
            window_type = config.get('fir_window', 'hamming')
            
            if filter_length < 3 or filter_length >= len(data):
                return data
            
            nyquist = sample_rate / 2.0
            low_norm = max(0.01, freq_range[0] / nyquist)
            high_norm = min(0.99, freq_range[1] / nyquist)
            
            if high_norm <= low_norm:
                return data
            
            # Design FIR bandpass filter using windowing method
            filtered_data = self._design_fir_bandpass(data, low_norm, high_norm, filter_length, window_type)
            
            return filtered_data
            
        except Exception:
            return data
    
    def _apply_notch_filter(self, data: np.ndarray, sample_rate: float, config: Dict) -> np.ndarray:
        """Apply notch filter for power line interference removal"""
        try:
            # Common power line frequencies
            power_freqs = config.get('power_line_freqs', [50.0, 60.0])  # Hz
            notch_bandwidth = config.get('notch_bandwidth', 2.0)  # Hz
            
            filtered_data = data.copy()
            
            for power_freq in power_freqs:
                if power_freq < sample_rate / 2:
                    # Apply notch filter for this frequency
                    filtered_data = self._apply_single_notch_filter(filtered_data, power_freq, 
                                                                  notch_bandwidth, sample_rate)
            
            return filtered_data
            
        except Exception:
            return data
    
    def _apply_wiener_filter(self, data: np.ndarray, freq_range: List[float], sample_rate: float, config: Dict) -> np.ndarray:
        """Apply adaptive Wiener filter for noise reduction"""
        try:
            # Estimate noise characteristics
            noise_estimate = self._estimate_noise_characteristics(data, sample_rate)
            
            # Wiener filter parameters
            noise_variance = noise_estimate.get('variance', np.var(data) * 0.1)
            signal_variance = np.var(data)
            
            # Frequency domain Wiener filtering
            filtered_data = self._frequency_domain_wiener(data, freq_range, sample_rate, 
                                                        signal_variance, noise_variance)
            
            return filtered_data
            
        except Exception:
            return data
    
    def _apply_volcanic_optimized_filter(self, data: np.ndarray, freq_range: List[float], sample_rate: float, config: Dict) -> np.ndarray:
        """Apply filter optimized for volcanic seismic signals"""
        try:
            # Detect volcanic signal type and apply appropriate filtering
            signal_type = self._detect_volcanic_signal_type(data, sample_rate)
            
            if signal_type == 'vt_earthquake':
                # High-frequency emphasis for VT earthquakes
                filtered_data = self._apply_vt_optimized_filter(data, freq_range, sample_rate)
            elif signal_type == 'lp_event':
                # Low-frequency preservation for LP events
                filtered_data = self._apply_lp_optimized_filter(data, freq_range, sample_rate)
            elif signal_type == 'tremor':
                # Harmonic preservation for tremor
                filtered_data = self._apply_tremor_optimized_filter(data, freq_range, sample_rate)
            elif signal_type == 'explosion':
                # Broadband preservation for explosions
                filtered_data = self._apply_explosion_optimized_filter(data, freq_range, sample_rate)
            else:
                # General volcanic signal filter
                filtered_data = self._apply_general_volcanic_filter(data, freq_range, sample_rate)
            
            return filtered_data
            
        except Exception:
            return data
    
    def _apply_zero_phase_filter(self, data: np.ndarray, freq_range: List[float], sample_rate: float, config: Dict) -> np.ndarray:
        """Apply zero-phase filter using forward-backward filtering"""
        try:
            # Forward filtering
            forward_filtered = self._apply_butterworth_filter(data, freq_range, sample_rate, config)
            
            # Backward filtering (reverse, filter, reverse again)
            reversed_data = forward_filtered[::-1]
            backward_filtered = self._apply_butterworth_filter(reversed_data, freq_range, sample_rate, config)
            zero_phase_filtered = backward_filtered[::-1]
            
            return zero_phase_filtered
            
        except Exception:
            return data
    
    def _select_optimal_filter(self, data: np.ndarray, filter_results: Dict, freq_range: List[float], 
                             sample_rate: float, config: Dict) -> np.ndarray:
        """Select optimal filter based on signal characteristics and quality metrics"""
        try:
            filter_scores = {}
            
            for filter_name, filtered_data in filter_results.items():
                # Calculate quality metrics for each filtered result
                quality_score = self._evaluate_filter_quality(data, filtered_data, freq_range, sample_rate)
                filter_scores[filter_name] = quality_score
            
            # Select filter with highest quality score
            best_filter = max(filter_scores.keys(), key=lambda k: filter_scores[k])
            
            # Apply additional criteria for volcanic signals
            volcanic_preference = self._get_volcanic_filter_preference(data, sample_rate)
            
            # Combine quality score with volcanic preference
            combined_scores = {}
            for filter_name, quality in filter_scores.items():
                volcanic_weight = volcanic_preference.get(filter_name, 1.0)
                combined_scores[filter_name] = quality * volcanic_weight
            
            optimal_filter = max(combined_scores.keys(), key=lambda k: combined_scores[k])
            
            return filter_results[optimal_filter]
            
        except Exception:
            # Fallback to Butterworth filter
            return filter_results.get('butterworth', data)
    
    def _enhance_filtered_signal(self, filtered_data: np.ndarray, original_data: np.ndarray, 
                                freq_range: List[float], sample_rate: float, config: Dict) -> np.ndarray:
        """Apply post-processing enhancement to filtered signal"""
        try:
            enhanced_data = filtered_data.copy()
            
            # 1. Amplitude preservation
            original_rms = np.sqrt(np.mean(original_data**2))
            filtered_rms = np.sqrt(np.mean(filtered_data**2))
            
            if filtered_rms > 0:
                amplitude_correction = original_rms / filtered_rms
                # Limit correction to reasonable range
                amplitude_correction = np.clip(amplitude_correction, 0.5, 2.0)
                enhanced_data *= amplitude_correction
            
            # 2. Edge artifact removal
            edge_length = min(int(0.1 * len(enhanced_data)), 100)
            if edge_length > 0:
                # Taper edges to reduce artifacts
                taper = np.ones(len(enhanced_data))
                taper[:edge_length] = np.linspace(0, 1, edge_length)
                taper[-edge_length:] = np.linspace(1, 0, edge_length)
                enhanced_data *= taper
            
            # 3. DC component removal
            enhanced_data -= np.mean(enhanced_data)
            
            # 4. Outlier suppression
            enhanced_data = self._suppress_filter_outliers(enhanced_data, config)
            
            return enhanced_data
            
        except Exception:
            return filtered_data
    
    def _apply_volcanic_postprocessing(self, data: np.ndarray, freq_range: List[float], 
                                     sample_rate: float, config: Dict) -> np.ndarray:
        """Apply volcanic signal-specific post-processing"""
        try:
            processed_data = data.copy()
            
            # 1. Volcanic frequency emphasis
            processed_data = self._emphasize_volcanic_frequencies(processed_data, sample_rate)
            
            # 2. Onset preservation
            processed_data = self._preserve_signal_onset(processed_data, config)
            
            # 3. Coda enhancement for volcano-tectonic events
            processed_data = self._enhance_vt_coda(processed_data, sample_rate)
            
            # 4. Harmonic structure preservation for tremor
            processed_data = self._preserve_tremor_harmonics(processed_data, sample_rate)
            
            return processed_data
            
        except Exception:
            return data
    
    def _apply_bandpass_filter_simple(self, data: np.ndarray, freq_range: List[float], config: Dict) -> np.ndarray:
        """Simplified bandpass filter implementation (fallback)"""
        try:
            sample_rate = config.get('sample_rate', 100.0)
            
            # Simple frequency domain filtering
            fft_data = np.fft.fft(data)
            freqs = np.fft.fftfreq(len(data), 1/sample_rate)
            
            # Create bandpass mask
            mask = np.zeros_like(freqs, dtype=bool)
            mask |= (np.abs(freqs) >= freq_range[0]) & (np.abs(freqs) <= freq_range[1])
            
            # Apply filter
            filtered_fft = fft_data * mask
            filtered_data = np.real(np.fft.ifft(filtered_fft))
            
            return filtered_data
            
        except Exception:
            return data
    
    # Supporting methods for advanced filtering implementation
    def _frequency_domain_butterworth(self, data: np.ndarray, low_norm: float, high_norm: float, order: int) -> np.ndarray:
        """Frequency domain Butterworth filter implementation"""
        try:
            # FFT of input signal
            fft_data = np.fft.fft(data)
            freqs = np.fft.fftfreq(len(data))
            
            # Butterworth frequency response
            H = np.ones_like(freqs, dtype=complex)
            
            for i, f in enumerate(freqs):
                f_abs = abs(f)
                
                if f_abs < low_norm:
                    # High-pass component
                    H[i] = 1.0 / (1.0 + (low_norm / (f_abs + 1e-10))**(2 * order))
                elif f_abs > high_norm:
                    # Low-pass component
                    H[i] = 1.0 / (1.0 + (f_abs / high_norm)**(2 * order))
                else:
                    # Passband
                    H[i] = 1.0
            
            # Apply filter and inverse FFT
            filtered_fft = fft_data * H
            filtered_data = np.real(np.fft.ifft(filtered_fft))
            
            return filtered_data
        except:
            return data
    
    def _frequency_domain_chebyshev1(self, data: np.ndarray, low_norm: float, high_norm: float, 
                                   order: int, ripple: float) -> np.ndarray:
        """Frequency domain Chebyshev Type I filter implementation"""
        try:
            fft_data = np.fft.fft(data)
            freqs = np.fft.fftfreq(len(data))
            
            # Chebyshev polynomial approximation
            epsilon = np.sqrt(10**(ripple/10) - 1)
            H = np.ones_like(freqs, dtype=complex)
            
            for i, f in enumerate(freqs):
                f_abs = abs(f)
                
                if low_norm <= f_abs <= high_norm:
                    # Passband with ripple
                    omega = (f_abs - (low_norm + high_norm)/2) / ((high_norm - low_norm)/2)
                    if abs(omega) <= 1:
                        Tn = np.cos(order * np.arccos(abs(omega)))
                        H[i] = 1.0 / np.sqrt(1 + epsilon**2 * Tn**2)
                else:
                    # Stopband
                    if f_abs < low_norm:
                        ratio = low_norm / (f_abs + 1e-10)
                    else:
                        ratio = f_abs / high_norm
                    H[i] = 1.0 / (1.0 + ratio**(2 * order))
            
            filtered_fft = fft_data * H
            filtered_data = np.real(np.fft.ifft(filtered_fft))
            
            return filtered_data
        except:
            return data
    
    def _frequency_domain_chebyshev2(self, data: np.ndarray, low_norm: float, high_norm: float, 
                                   order: int, attenuation: float) -> np.ndarray:
        """Frequency domain Chebyshev Type II filter implementation"""
        try:
            fft_data = np.fft.fft(data)
            freqs = np.fft.fftfreq(len(data))
            
            H = np.ones_like(freqs, dtype=complex)
            
            for i, f in enumerate(freqs):
                f_abs = abs(f)
                
                if low_norm <= f_abs <= high_norm:
                    # Passband (flat)
                    H[i] = 1.0
                else:
                    # Stopband with controlled attenuation
                    if f_abs < low_norm:
                        ratio = (f_abs + 1e-10) / low_norm
                    else:
                        ratio = high_norm / f_abs
                    
                    attenuation_factor = 10**(-attenuation/20)
                    H[i] = attenuation_factor / (1.0 + (1/ratio)**(2 * order))
            
            filtered_fft = fft_data * H
            filtered_data = np.real(np.fft.ifft(filtered_fft))
            
            return filtered_data
        except:
            return data
    
    def _frequency_domain_elliptic(self, data: np.ndarray, low_norm: float, high_norm: float, 
                                 order: int, passband_ripple: float, stopband_attenuation: float) -> np.ndarray:
        """Frequency domain elliptic filter implementation"""
        try:
            fft_data = np.fft.fft(data)
            freqs = np.fft.fftfreq(len(data))
            
            epsilon = np.sqrt(10**(passband_ripple/10) - 1)
            H = np.ones_like(freqs, dtype=complex)
            
            for i, f in enumerate(freqs):
                f_abs = abs(f)
                
                if low_norm <= f_abs <= high_norm:
                    # Passband with ripple
                    omega = (f_abs - (low_norm + high_norm)/2) / ((high_norm - low_norm)/2)
                    if abs(omega) <= 1:
                        # Simplified elliptic function approximation
                        elliptic_factor = 1.0 + epsilon**2 * np.sin(order * np.pi * omega)**2
                        H[i] = 1.0 / np.sqrt(elliptic_factor)
                else:
                    # Stopband with high attenuation
                    attenuation_factor = 10**(-stopband_attenuation/20)
                    if f_abs < low_norm:
                        ratio = (f_abs + 1e-10) / low_norm
                    else:
                        ratio = high_norm / f_abs
                    H[i] = attenuation_factor * ratio**order
            
            filtered_fft = fft_data * H
            filtered_data = np.real(np.fft.ifft(filtered_fft))
            
            return filtered_data
        except:
            return data
    
    def _frequency_domain_bessel(self, data: np.ndarray, low_norm: float, high_norm: float, order: int) -> np.ndarray:
        """Frequency domain Bessel filter implementation"""
        try:
            fft_data = np.fft.fft(data)
            freqs = np.fft.fftfreq(len(data))
            
            H = np.ones_like(freqs, dtype=complex)
            
            for i, f in enumerate(freqs):
                f_abs = abs(f)
                
                # Bessel filter has maximally flat group delay
                # Approximation using modified Butterworth response
                if f_abs < low_norm:
                    ratio = low_norm / (f_abs + 1e-10)
                    H[i] = 1.0 / (1.0 + ratio**(order))
                elif f_abs > high_norm:
                    ratio = f_abs / high_norm
                    H[i] = 1.0 / (1.0 + ratio**(order))
                else:
                    H[i] = 1.0
            
            filtered_fft = fft_data * H
            filtered_data = np.real(np.fft.ifft(filtered_fft))
            
            return filtered_data
        except:
            return data
    
    def _design_fir_bandpass(self, data: np.ndarray, low_norm: float, high_norm: float, 
                           filter_length: int, window_type: str) -> np.ndarray:
        """Design and apply FIR bandpass filter using windowing method"""
        try:
            # Create ideal bandpass filter
            n = np.arange(filter_length) - filter_length // 2
            
            # Sinc functions for ideal filters
            h_low = 2 * low_norm * np.sinc(2 * low_norm * n)
            h_high = 2 * high_norm * np.sinc(2 * high_norm * n)
            
            # Bandpass = highpass - lowpass
            h_bandpass = h_high - h_low
            
            # Apply window
            if window_type == 'hamming':
                window = 0.54 - 0.46 * np.cos(2 * np.pi * np.arange(filter_length) / (filter_length - 1))
            elif window_type == 'hanning':
                window = 0.5 - 0.5 * np.cos(2 * np.pi * np.arange(filter_length) / (filter_length - 1))
            elif window_type == 'blackman':
                alpha = 0.16
                a0 = (1 - alpha) / 2
                a1 = 0.5
                a2 = alpha / 2
                n_win = np.arange(filter_length)
                window = a0 - a1 * np.cos(2 * np.pi * n_win / (filter_length - 1)) + a2 * np.cos(4 * np.pi * n_win / (filter_length - 1))
            else:
                window = np.ones(filter_length)  # Rectangular window
            
            h_windowed = h_bandpass * window
            
            # Normalize
            h_windowed /= np.sum(h_windowed)
            
            # Apply filter using convolution
            filtered_data = np.convolve(data, h_windowed, mode='same')
            
            return filtered_data
        except:
            return data
    
    def _apply_single_notch_filter(self, data: np.ndarray, notch_freq: float, bandwidth: float, sample_rate: float) -> np.ndarray:
        """Apply single notch filter for specific frequency"""
        try:
            fft_data = np.fft.fft(data)
            freqs = np.fft.fftfreq(len(data), 1/sample_rate)
            
            # Create notch filter
            H = np.ones_like(freqs)
            
            for i, f in enumerate(freqs):
                if abs(abs(f) - notch_freq) <= bandwidth / 2:
                    # Notch depth (adjustable)
                    depth = 0.01  # 1% of original amplitude
                    H[i] = depth
            
            filtered_fft = fft_data * H
            filtered_data = np.real(np.fft.ifft(filtered_fft))
            
            return filtered_data
        except:
            return data
    
    def _estimate_noise_characteristics(self, data: np.ndarray, sample_rate: float) -> Dict:
        """Estimate noise characteristics for Wiener filtering"""
        try:
            # Assume noise is in the first and last 10% of the signal
            noise_length = max(10, len(data) // 10)
            noise_start = data[:noise_length]
            noise_end = data[-noise_length:]
            noise_combined = np.concatenate([noise_start, noise_end])
            
            noise_variance = np.var(noise_combined)
            noise_mean = np.mean(noise_combined)
            noise_std = np.std(noise_combined)
            
            # Spectral characteristics of noise
            fft_noise = np.fft.fft(noise_combined)
            noise_psd = np.abs(fft_noise)**2
            
            return {
                'variance': noise_variance,
                'mean': noise_mean,
                'std': noise_std,
                'psd': noise_psd
            }
        except:
            return {'variance': np.var(data) * 0.1, 'mean': 0.0, 'std': np.std(data) * 0.1}
    
    def _frequency_domain_wiener(self, data: np.ndarray, freq_range: List[float], sample_rate: float,
                               signal_variance: float, noise_variance: float) -> np.ndarray:
        """Apply Wiener filter in frequency domain"""
        try:
            fft_data = np.fft.fft(data)
            freqs = np.fft.fftfreq(len(data), 1/sample_rate)
            
            # Wiener filter transfer function
            snr = signal_variance / (noise_variance + 1e-10)
            H = np.ones_like(freqs, dtype=complex)
            
            for i, f in enumerate(freqs):
                # Estimate local SNR
                f_abs = abs(f)
                if freq_range[0] <= f_abs <= freq_range[1]:
                    # In passband, use estimated SNR
                    local_snr = snr
                else:
                    # Outside passband, assume lower SNR
                    local_snr = snr * 0.1
                
                # Wiener filter formula
                H[i] = local_snr / (1.0 + local_snr)
            
            filtered_fft = fft_data * H
            filtered_data = np.real(np.fft.ifft(filtered_fft))
            
            return filtered_data
        except:
            return data
    
    def _detect_volcanic_signal_type(self, data: np.ndarray, sample_rate: float) -> str:
        """Detect type of volcanic signal for optimized filtering"""
        try:
            # Calculate signal characteristics
            signal_duration = len(data) / sample_rate
            
            # FFT for frequency analysis
            fft_data = np.fft.fft(data)
            freqs = np.fft.fftfreq(len(data), 1/sample_rate)
            psd = np.abs(fft_data)**2
            
            # Focus on positive frequencies
            pos_mask = freqs > 0
            freqs_pos = freqs[pos_mask]
            psd_pos = psd[pos_mask]
            
            if len(psd_pos) == 0:
                return 'unknown'
            
            # Frequency characteristics
            total_energy = np.sum(psd_pos)
            low_freq_energy = np.sum(psd_pos[(freqs_pos >= 0.5) & (freqs_pos <= 5.0)])
            mid_freq_energy = np.sum(psd_pos[(freqs_pos >= 5.0) & (freqs_pos <= 15.0)])
            high_freq_energy = np.sum(psd_pos[(freqs_pos >= 15.0) & (freqs_pos <= 50.0)])
            
            low_ratio = low_freq_energy / (total_energy + 1e-10)
            mid_ratio = mid_freq_energy / (total_energy + 1e-10)
            high_ratio = high_freq_energy / (total_energy + 1e-10)
            
            # Classification based on frequency content and duration
            if high_ratio > 0.4 and signal_duration < 5.0:
                return 'vt_earthquake'
            elif low_ratio > 0.5 and 5.0 <= signal_duration <= 60.0:
                return 'lp_event'
            elif signal_duration > 60.0 and low_ratio > 0.3:
                return 'tremor'
            elif mid_ratio > 0.3 and signal_duration < 10.0:
                return 'explosion'
            else:
                return 'unknown'
                
        except:
            return 'unknown'
    
    def _apply_vt_optimized_filter(self, data: np.ndarray, freq_range: List[float], sample_rate: float) -> np.ndarray:
        """Apply filter optimized for volcano-tectonic earthquakes"""
        try:
            # VT earthquakes: emphasize high frequencies (5-25 Hz)
            vt_freq_range = [max(5.0, freq_range[0]), min(25.0, freq_range[1])]
            return self._frequency_domain_butterworth(data, vt_freq_range[0]/(sample_rate/2), 
                                                    vt_freq_range[1]/(sample_rate/2), 4)
        except:
            return data
    
    def _apply_lp_optimized_filter(self, data: np.ndarray, freq_range: List[float], sample_rate: float) -> np.ndarray:
        """Apply filter optimized for long-period events"""
        try:
            # LP events: emphasize low frequencies (0.5-5 Hz)
            lp_freq_range = [max(0.5, freq_range[0]), min(5.0, freq_range[1])]
            return self._frequency_domain_butterworth(data, lp_freq_range[0]/(sample_rate/2), 
                                                    lp_freq_range[1]/(sample_rate/2), 6)
        except:
            return data
    
    def _apply_tremor_optimized_filter(self, data: np.ndarray, freq_range: List[float], sample_rate: float) -> np.ndarray:
        """Apply filter optimized for volcanic tremor"""
        try:
            # Tremor: preserve harmonic structure (1-8 Hz)
            tremor_freq_range = [max(1.0, freq_range[0]), min(8.0, freq_range[1])]
            return self._frequency_domain_bessel(data, tremor_freq_range[0]/(sample_rate/2), 
                                               tremor_freq_range[1]/(sample_rate/2), 4)
        except:
            return data
    
    def _apply_explosion_optimized_filter(self, data: np.ndarray, freq_range: List[float], sample_rate: float) -> np.ndarray:
        """Apply filter optimized for volcanic explosions"""
        try:
            # Explosions: broadband preservation (0.1-20 Hz)
            explosion_freq_range = [max(0.1, freq_range[0]), min(20.0, freq_range[1])]
            return self._frequency_domain_butterworth(data, explosion_freq_range[0]/(sample_rate/2), 
                                                    explosion_freq_range[1]/(sample_rate/2), 3)
        except:
            return data
    
    def _apply_general_volcanic_filter(self, data: np.ndarray, freq_range: List[float], sample_rate: float) -> np.ndarray:
        """Apply general volcanic signal filter"""
        try:
            # General filter for unknown volcanic signals
            return self._frequency_domain_butterworth(data, freq_range[0]/(sample_rate/2), 
                                                    freq_range[1]/(sample_rate/2), 4)
        except:
            return data
    
    def _evaluate_filter_quality(self, original_data: np.ndarray, filtered_data: np.ndarray, 
                                freq_range: List[float], sample_rate: float) -> float:
        """Evaluate quality of filtered signal"""
        try:
            quality_metrics = []
            
            # 1. Passband preservation
            passband_preservation = self._assess_passband_preservation(original_data, filtered_data, freq_range, sample_rate)
            quality_metrics.append(passband_preservation)
            
            # 2. Stopband attenuation
            stopband_attenuation = self._assess_stopband_attenuation(filtered_data, freq_range, sample_rate)
            quality_metrics.append(stopband_attenuation)
            
            # 3. Signal-to-noise ratio improvement
            snr_improvement = self._assess_snr_improvement(original_data, filtered_data)
            quality_metrics.append(snr_improvement)
            
            # 4. Phase distortion
            phase_distortion = self._assess_phase_distortion(original_data, filtered_data)
            quality_metrics.append(1.0 - phase_distortion)  # Lower distortion = higher quality
            
            # 5. Amplitude preservation
            amplitude_preservation = self._assess_amplitude_preservation(original_data, filtered_data)
            quality_metrics.append(amplitude_preservation)
            
            return np.mean(quality_metrics)
        except:
            return 0.5
    
    def _get_volcanic_filter_preference(self, data: np.ndarray, sample_rate: float) -> Dict[str, float]:
        """Get preference weights for different filters based on volcanic signal characteristics"""
        try:
            signal_type = self._detect_volcanic_signal_type(data, sample_rate)
            
            preferences = {
                'butterworth': 1.0,
                'chebyshev1': 1.0,
                'chebyshev2': 1.0,
                'elliptic': 1.0,
                'bessel': 1.0,
                'fir': 1.0,
                'notch': 1.0,
                'wiener': 1.0,
                'volcanic': 1.0,
                'zero_phase': 1.0
            }
            
            if signal_type == 'vt_earthquake':
                preferences['elliptic'] = 1.3  # Sharp cutoff good for VT
                preferences['volcanic'] = 1.4
                preferences['zero_phase'] = 1.2
            elif signal_type == 'lp_event':
                preferences['bessel'] = 1.3   # Minimal phase distortion good for LP
                preferences['volcanic'] = 1.4
                preferences['butterworth'] = 1.2
            elif signal_type == 'tremor':
                preferences['bessel'] = 1.4   # Preserve harmonic structure
                preferences['volcanic'] = 1.5
                preferences['fir'] = 1.2
            elif signal_type == 'explosion':
                preferences['butterworth'] = 1.2  # Broadband preservation
                preferences['volcanic'] = 1.3
                preferences['zero_phase'] = 1.1
            
            return preferences
        except:
            return {key: 1.0 for key in ['butterworth', 'chebyshev1', 'chebyshev2', 'elliptic', 
                                       'bessel', 'fir', 'notch', 'wiener', 'volcanic', 'zero_phase']}
    
    # Additional supporting methods for filter quality assessment and post-processing
    def _assess_passband_preservation(self, original_data: np.ndarray, filtered_data: np.ndarray,
                                    freq_range: List[float], sample_rate: float) -> float:
        """Assess how well the filter preserves passband frequencies"""
        try:
            # FFT of both signals
            fft_orig = np.fft.fft(original_data)
            fft_filt = np.fft.fft(filtered_data)
            freqs = np.fft.fftfreq(len(original_data), 1/sample_rate)
            
            # Focus on passband frequencies
            passband_mask = (np.abs(freqs) >= freq_range[0]) & (np.abs(freqs) <= freq_range[1])
            
            if not np.any(passband_mask):
                return 0.0
            
            orig_passband = np.abs(fft_orig[passband_mask])
            filt_passband = np.abs(fft_filt[passband_mask])
            
            # Calculate preservation ratio
            if np.sum(orig_passband) > 0:
                preservation = np.sum(filt_passband) / np.sum(orig_passband)
                return min(1.0, preservation)
            
            return 0.0
        except:
            return 0.5
    
    def _assess_stopband_attenuation(self, filtered_data: np.ndarray, freq_range: List[float], sample_rate: float) -> float:
        """Assess stopband attenuation quality"""
        try:
            fft_filt = np.fft.fft(filtered_data)
            freqs = np.fft.fftfreq(len(filtered_data), 1/sample_rate)
            
            # Stopband frequencies (outside passband)
            stopband_mask = (np.abs(freqs) < freq_range[0]) | (np.abs(freqs) > freq_range[1])
            passband_mask = (np.abs(freqs) >= freq_range[0]) & (np.abs(freqs) <= freq_range[1])
            
            if not np.any(stopband_mask) or not np.any(passband_mask):
                return 0.5
            
            stopband_energy = np.sum(np.abs(fft_filt[stopband_mask])**2)
            passband_energy = np.sum(np.abs(fft_filt[passband_mask])**2)
            
            if passband_energy > 0:
                attenuation_ratio = stopband_energy / passband_energy
                # Good attenuation should have low ratio
                attenuation_quality = 1.0 / (1.0 + attenuation_ratio)
                return attenuation_quality
            
            return 0.0
        except:
            return 0.5
    
    def _assess_snr_improvement(self, original_data: np.ndarray, filtered_data: np.ndarray) -> float:
        """Assess SNR improvement from filtering"""
        try:
            # Estimate signal and noise components
            # Assume signal is the coherent part, noise is the random part
            
            # Original SNR estimation
            orig_signal = np.var(original_data)
            orig_noise = np.var(np.diff(original_data))  # High-frequency content as noise proxy
            orig_snr = orig_signal / (orig_noise + 1e-10)
            
            # Filtered SNR estimation
            filt_signal = np.var(filtered_data)
            filt_noise = np.var(np.diff(filtered_data))
            filt_snr = filt_signal / (filt_noise + 1e-10)
            
            # SNR improvement ratio
            if orig_snr > 0:
                improvement = filt_snr / orig_snr
                return min(1.0, improvement / 2.0)  # Normalize to [0, 1]
            
            return 0.0
        except:
            return 0.5
    
    def _assess_phase_distortion(self, original_data: np.ndarray, filtered_data: np.ndarray) -> float:
        """Assess phase distortion introduced by filtering"""
        try:
            # Cross-correlation to assess phase alignment
            if len(original_data) != len(filtered_data):
                return 1.0  # Maximum distortion if lengths don't match
            
            # Normalize signals
            orig_norm = (original_data - np.mean(original_data)) / (np.std(original_data) + 1e-10)
            filt_norm = (filtered_data - np.mean(filtered_data)) / (np.std(filtered_data) + 1e-10)
            
            # Cross-correlation
            correlation = np.correlate(orig_norm, filt_norm, mode='full')
            max_corr = np.max(np.abs(correlation))
            
            # Phase distortion as 1 - normalized max correlation
            if max_corr > 0:
                phase_distortion = 1.0 - min(1.0, max_corr / len(original_data))
                return max(0.0, phase_distortion)
            
            return 1.0
        except:
            return 0.5
    
    def _assess_amplitude_preservation(self, original_data: np.ndarray, filtered_data: np.ndarray) -> float:
        """Assess amplitude preservation quality"""
        try:
            orig_rms = np.sqrt(np.mean(original_data**2))
            filt_rms = np.sqrt(np.mean(filtered_data**2))
            
            if orig_rms > 0:
                amplitude_ratio = filt_rms / orig_rms
                # Good preservation should have ratio close to 1
                preservation = 1.0 - abs(1.0 - amplitude_ratio)
                return max(0.0, preservation)
            
            return 0.0
        except:
            return 0.5
    
    def _suppress_filter_outliers(self, data: np.ndarray, config: Dict) -> np.ndarray:
        """Suppress outliers that may be introduced by filtering"""
        try:
            outlier_threshold = config.get('outlier_threshold', 5.0)  # Standard deviations
            
            # Calculate statistics
            data_mean = np.mean(data)
            data_std = np.std(data)
            
            if data_std > 0:
                # Identify outliers
                z_scores = np.abs(data - data_mean) / data_std
                outlier_mask = z_scores > outlier_threshold
                
                # Replace outliers with clipped values
                suppressed_data = data.copy()
                upper_limit = data_mean + outlier_threshold * data_std
                lower_limit = data_mean - outlier_threshold * data_std
                
                suppressed_data[outlier_mask & (data > data_mean)] = upper_limit
                suppressed_data[outlier_mask & (data < data_mean)] = lower_limit
                
                return suppressed_data
            
            return data
        except:
            return data
    
    def _emphasize_volcanic_frequencies(self, data: np.ndarray, sample_rate: float) -> np.ndarray:
        """Emphasize frequencies characteristic of volcanic signals"""
        try:
            # Volcanic frequency bands of interest
            volcanic_bands = {
                'lp_events': [0.5, 5.0],     # Long-period events
                'vt_earthquakes': [5.0, 25.0], # Volcano-tectonic
                'tremor': [1.0, 8.0]         # Volcanic tremor
            }
            
            fft_data = np.fft.fft(data)
            freqs = np.fft.fftfreq(len(data), 1/sample_rate)
            
            # Create emphasis filter
            emphasis_factor = np.ones_like(freqs)
            
            for band_name, (f_low, f_high) in volcanic_bands.items():
                band_mask = (np.abs(freqs) >= f_low) & (np.abs(freqs) <= f_high)
                emphasis_factor[band_mask] *= 1.2  # 20% emphasis
            
            # Apply emphasis
            emphasized_fft = fft_data * emphasis_factor
            emphasized_data = np.real(np.fft.ifft(emphasized_fft))
            
            return emphasized_data
        except:
            return data
    
    def _preserve_signal_onset(self, data: np.ndarray, config: Dict) -> np.ndarray:
        """Preserve signal onset characteristics"""
        try:
            onset_length = config.get('onset_preservation_length', min(100, len(data) // 10))
            
            if onset_length <= 0 or onset_length >= len(data):
                return data
            
            # Find signal onset using energy-based method
            energy = np.cumsum(data**2)
            energy_normalized = energy / (energy[-1] + 1e-10)
            
            # Find 5% energy point as onset
            onset_idx = np.argmax(energy_normalized >= 0.05)
            
            # Preserve original data around onset
            preserved_data = data.copy()
            onset_start = max(0, onset_idx - onset_length // 2)
            onset_end = min(len(data), onset_idx + onset_length // 2)
            
            # Apply gentle tapering at onset boundaries
            if onset_start > 0:
                taper_length = min(20, onset_start)
                taper = np.linspace(0, 1, taper_length)
                preserved_data[onset_start - taper_length:onset_start] *= taper
            
            if onset_end < len(data):
                taper_length = min(20, len(data) - onset_end)
                taper = np.linspace(1, 0, taper_length)
                preserved_data[onset_end:onset_end + taper_length] *= taper
            
            return preserved_data
        except:
            return data
    
    def _enhance_vt_coda(self, data: np.ndarray, sample_rate: float) -> np.ndarray:
        """Enhance coda for volcano-tectonic events"""
        try:
            # VT events typically have exponentially decaying coda
            # Enhance this characteristic
            
            # Find potential coda start (after main energy)
            energy = np.cumsum(data**2)
            energy_normalized = energy / (energy[-1] + 1e-10)
            
            # Coda starts around 80% energy point
            coda_start = np.argmax(energy_normalized >= 0.8)
            
            if coda_start < len(data) - 10:
                coda = data[coda_start:]
                
                # Apply gentle exponential weighting to enhance decay
                time_indices = np.arange(len(coda))
                decay_factor = np.exp(-time_indices / (sample_rate * 2.0))  # 2-second decay
                
                enhanced_coda = coda * (1.0 + 0.1 * decay_factor)  # 10% enhancement
                
                enhanced_data = data.copy()
                enhanced_data[coda_start:] = enhanced_coda
                
                return enhanced_data
            
            return data
        except:
            return data
    
    def _preserve_tremor_harmonics(self, data: np.ndarray, sample_rate: float) -> np.ndarray:
        """Preserve harmonic structure in tremor signals"""
        try:
            # Tremor often has harmonic structure
            # Identify and preserve dominant frequencies and their harmonics
            
            fft_data = np.fft.fft(data)
            freqs = np.fft.fftfreq(len(data), 1/sample_rate)
            psd = np.abs(fft_data)**2
            
            # Focus on tremor frequency range (1-8 Hz)
            tremor_mask = (np.abs(freqs) >= 1.0) & (np.abs(freqs) <= 8.0)
            if not np.any(tremor_mask):
                return data
            
            tremor_freqs = freqs[tremor_mask]
            tremor_psd = psd[tremor_mask]
            
            # Find dominant frequency
            if len(tremor_psd) > 0:
                dominant_idx = np.argmax(tremor_psd)
                dominant_freq = abs(tremor_freqs[dominant_idx])
                
                # Enhance harmonics
                enhancement_factor = np.ones_like(freqs)
                
                for harmonic in range(1, 5):  # First 4 harmonics
                    harmonic_freq = harmonic * dominant_freq
                    if harmonic_freq <= sample_rate / 2:
                        # Find frequencies close to harmonic
                        harmonic_mask = np.abs(np.abs(freqs) - harmonic_freq) <= 0.5
                        enhancement_factor[harmonic_mask] *= 1.1  # 10% enhancement
                
                # Apply enhancement
                enhanced_fft = fft_data * enhancement_factor
                enhanced_data = np.real(np.fft.ifft(enhanced_fft))
                
                return enhanced_data
            
            return data
        except:
            return data

    def _calculate_tremor_amplitude(self, processed_data: Dict) -> float:
        """Calculate tremor amplitude from processed seismic data"""
        try:
            amplitudes = []
            
            for station_id, station_data in processed_data.get('processed_stations', {}).items():
                if 'waveforms' in station_data and 'time_series' in station_data['waveforms']:
                    time_series = station_data['waveforms']['time_series']
                    # Calculate RMS amplitude
                    rms_amplitude = np.sqrt(np.mean(time_series**2))
                    amplitudes.append(rms_amplitude)
            
            return np.mean(amplitudes) if amplitudes else 0.0
            
        except Exception:
            return 0.0
    
    def _refine_temperature_estimate(self, initial_temp: float, pressure_Pa: float, melt_fraction: float) -> float:
        """Refine temperature estimate using thermodynamic constraints"""
        try:
            # Simple refinement based on pressure and melt fraction
            # In reality, would use full thermodynamic modeling
            
            # Pressure effect on melting temperature (Clausius-Clapeyron)
            pressure_correction = (pressure_Pa - 101325) / 1e6 * 10  # Rough approximation
            
            # Melt fraction effect
            melt_correction = melt_fraction * 50  # Higher melt fraction = higher temperature
            
            refined_temp = initial_temp + pressure_correction + melt_correction
            
            # Reasonable bounds for magmatic temperatures
            return max(1000, min(1500, refined_temp))
            
        except Exception:
            return initial_temp
    
    def _extract_ml_features(self, seismic_analysis: Dict, velocity_structure: Dict, melt_characteristics: Dict) -> np.ndarray:
        """Extract features for machine learning models"""
        try:
            features = []
            
            # Seismic features
            features.append(seismic_analysis.get('seismicity_rate', 0))
            features.append(seismic_analysis.get('lp_event_rate', 0))
            features.append(seismic_analysis.get('tremor_amplitude', 0))
            features.append(seismic_analysis.get('total_p_picks', 0))
            features.append(seismic_analysis.get('total_s_picks', 0))
            
            # Velocity structure features
            features.append(velocity_structure.get('magma_depth_km', 5.0))
            if 'vp_vs_ratios' in velocity_structure:
                features.append(np.mean(velocity_structure['vp_vs_ratios'].get('ratios', [1.73])))
            else:
                features.append(1.73)
            
            # Melt characteristics features
            features.append(melt_characteristics.get('melt_fraction', 0.0))
            features.append(melt_characteristics.get('temperature_estimate_K', 1200))
            
            return np.array(features)
            
        except Exception:
            return np.zeros(9)  # Return default feature vector
    
    def _classify_reservoir_type(self, features: np.ndarray, config: Dict) -> Dict:
        """Advanced multi-model reservoir classification with machine learning ensemble"""
        try:
            # Comprehensive feature extraction and validation
            feature_analysis = self._analyze_classification_features(features, config)
            
            # Multi-model ensemble classification
            classification_results = {}
            
            # 1. Physics-based classification model
            physics_classification = self._physics_based_reservoir_classification(features, config)
            classification_results['physics_based'] = physics_classification
            
            # 2. Machine learning ensemble classification
            ml_ensemble_classification = self._ml_ensemble_reservoir_classification(features, config)
            classification_results['ml_ensemble'] = ml_ensemble_classification
            
            # 3. Bayesian classification with uncertainty quantification
            bayesian_classification = self._bayesian_reservoir_classification(features, config)
            classification_results['bayesian'] = bayesian_classification
            
            # 4. Multi-criteria decision analysis
            mcda_classification = self._mcda_reservoir_classification(features, config)
            classification_results['mcda'] = mcda_classification
            
            # 5. Temporal evolution-based classification
            temporal_classification = self._temporal_reservoir_classification(features, config)
            classification_results['temporal'] = temporal_classification
            
            # 6. Geophysical signature classification
            geophysical_classification = self._geophysical_signature_classification(features, config)
            classification_results['geophysical'] = geophysical_classification
            
            # 7. Thermodynamic state classification
            thermodynamic_classification = self._thermodynamic_state_classification(features, config)
            classification_results['thermodynamic'] = thermodynamic_classification
            
            # Advanced ensemble fusion and consensus building
            consensus_result = self._build_classification_consensus(classification_results, features, config)
            
            # Uncertainty quantification and confidence assessment
            uncertainty_analysis = self._assess_classification_uncertainty(classification_results, features, config)
            
            # Volcanic hazard implications
            hazard_implications = self._assess_volcanic_hazard_implications(consensus_result, features, config)
            
            # Comprehensive result synthesis
            return {
                'primary_classification': consensus_result['primary_type'],
                'classification_confidence': consensus_result['confidence'],
                'alternative_classifications': consensus_result['alternatives'],
                'model_results': classification_results,
                'feature_analysis': feature_analysis,
                'uncertainty_analysis': uncertainty_analysis,
                'hazard_implications': hazard_implications,
                'classification_metadata': {
                    'feature_vector_size': len(features),
                    'models_used': len(classification_results),
                    'consensus_strength': consensus_result.get('consensus_strength', 0.0),
                    'analysis_timestamp': config.get('timestamp', 0)
                }
            }
            
        except Exception as e:
            # Fallback to simplified classification
            return self._classify_reservoir_type_simple(features, config)
    
