    def _analyze_focal_mechanisms_simple(self, event_catalog: List[Dict], config: Dict) -> Dict:
        """Simplified focal mechanism analysis (fallback)"""
        try:
            mechanisms = []
            for event in event_catalog:
                if 'focal_mechanism' in event:
                    mechanisms.append(event['focal_mechanism'])
            
            if not mechanisms:
                return {'mechanism_count': 0, 'analysis_quality': 'no_mechanisms'}
            
            # Simple mechanism type counting
            mechanism_types = {'normal': 0, 'reverse': 0, 'strike_slip': 0, 'unknown': 0}
            
            for mech in mechanisms:
                rake = mech.get('rake', 0)
                if -45 <= rake <= 45 or 135 <= rake <= 225:
                    mechanism_types['strike_slip'] += 1
                elif 45 < rake < 135:
                    mechanism_types['reverse'] += 1
                elif -135 < rake < -45:
                    mechanism_types['normal'] += 1
                else:
                    mechanism_types['unknown'] += 1
            
            dominant_type = max(mechanism_types.keys(), key=lambda k: mechanism_types[k])
            
            return {
                'mechanism_count': len(mechanisms),
                'focal_analysis': {'volcanic_classification': {'dominant_type': dominant_type}},
                'summary': {
                    'dominant_mechanism_type': dominant_type,
                    'stress_regime': 'unknown',
                    'volcanic_activity_type': 'mixed',
                    'chamber_interaction_level': 'moderate',
                    'mechanism_diversity': 0.5,
                    'temporal_stability': 0.5,
                    'spatial_coherence': 0.5,
                    'analysis_confidence': 0.3
                }
            }
        except:
            return {'mechanism_count': 0, 'error': 'simple_analysis_failed'}
    
    def _analyze_velocity_structure(self, velocity_results: Dict, config: Dict) -> Dict:
        """Analyze velocity structure from multiple methods"""
        try:
            all_ratios = []
            quality_weights = []
            
            for method_name, method_result in velocity_results.items():
                if isinstance(method_result, dict) and 'ratios' in method_result:
                    ratios = method_result['ratios']
                    quality = method_result.get('quality_score', 0.5)
                    
                    if ratios:
                        all_ratios.extend(ratios)
                        quality_weights.extend([quality] * len(ratios))
            
            if all_ratios:
                weighted_mean = np.average(all_ratios, weights=quality_weights) if quality_weights else np.mean(all_ratios)
                return {
                    'mean_ratio': weighted_mean,
                    'std_ratio': np.std(all_ratios),
                    'median_ratio': np.median(all_ratios),
                    'min_ratio': np.min(all_ratios),
                    'max_ratio': np.max(all_ratios),
                    'ratio_range': np.max(all_ratios) - np.min(all_ratios),
                    'num_measurements': len(all_ratios)
                }
            
            return {'mean_ratio': 1.73, 'std_ratio': 0.05, 'num_measurements': 0}
        except:
            return {'mean_ratio': 1.73, 'std_ratio': 0.05, 'error': 'analysis_failed'}
    
    def _detect_partial_melt(self, velocity_results: Dict, config: Dict) -> Dict:
        """Detect partial melt from velocity analysis"""
        try:
            # Threshold for partial melt detection
            melt_threshold = config.get('melt_detection_threshold', 1.85)
            
            anomalous_zones = []
            melt_indicators = []
            
            for method_name, method_result in velocity_results.items():
                if isinstance(method_result, dict) and 'ratios' in method_result:
                    ratios = method_result['ratios']
                    
                    for i, ratio in enumerate(ratios):
                        if ratio > melt_threshold:
                            anomalous_zones.append(i)
                            melt_indicators.append(ratio)
            
            # Estimate melt fraction based on anomalous ratios
            melt_fraction = 0.0
            if melt_indicators:
                # Simple empirical relationship
                avg_anomalous_ratio = np.mean(melt_indicators)
                melt_fraction = min(0.3, (avg_anomalous_ratio - 1.73) / 0.5)
            
            return {
                'anomalous_zones': list(set(anomalous_zones)),
                'melt_fraction': max(0.0, melt_fraction),
                'melt_indicators': melt_indicators,
                'melt_detection_confidence': 0.7 if len(melt_indicators) > 2 else 0.3
            }
        except:
            return {'anomalous_zones': [], 'melt_fraction': 0.0}
    
    def _characterize_magma_chamber_velocities(self, velocity_results: Dict, melt_analysis: Dict, config: Dict) -> Dict:
        """Characterize magma chamber from velocity data"""
        try:
            # Depth estimation based on velocity structure
            depth_range = [2.0, 8.0]  # Default km
            
            # Adjust based on melt fraction
            melt_fraction = melt_analysis.get('melt_fraction', 0.0)
            if melt_fraction > 0.1:
                depth_range = [1.5, 6.0]  # Shallower for higher melt content
            elif melt_fraction > 0.05:
                depth_range = [2.5, 7.0]
            
            return {
                'depth_range': depth_range,
                'estimated_volume': 5.0 + melt_fraction * 20.0,  # km³
                'velocity_contrast': 0.1 + melt_fraction * 0.3,
                'chamber_shape': 'ellipsoidal' if melt_fraction > 0.1 else 'spherical'
            }
        except:
            return {'depth_range': [2, 8], 'estimated_volume': 5.0}
    
    def _assess_velocity_analysis_quality(self, velocity_results: Dict, config: Dict) -> Dict:
        """Assess quality of velocity analysis"""
        try:
            quality_scores = []
            method_qualities = {}
            
            for method_name, method_result in velocity_results.items():
                if isinstance(method_result, dict):
                    quality = method_result.get('quality_score', 0.0)
                    quality_scores.append(quality)
                    method_qualities[method_name] = quality
            
            overall_confidence = np.mean(quality_scores) if quality_scores else 0.0
            
            return {
                'overall_confidence': overall_confidence,
                'method_qualities': method_qualities,
                'num_successful_methods': len([q for q in quality_scores if q > 0.3]),
                'reliability_grade': 'high' if overall_confidence > 0.7 else 'medium' if overall_confidence > 0.4 else 'low'
            }
        except:
            return {'overall_confidence': 0.0}
    
    def _perform_velocity_statistics(self, velocity_results: Dict, config: Dict) -> Dict:
        """Perform statistical analysis of velocity measurements"""
        try:
            all_ratios = []
            for method_result in velocity_results.values():
                if isinstance(method_result, dict) and 'ratios' in method_result:
                    all_ratios.extend(method_result['ratios'])
            
            if all_ratios:
                return {
                    'mean': np.mean(all_ratios),
                    'median': np.median(all_ratios),
                    'std': np.std(all_ratios),
                    'variance': np.var(all_ratios),
                    'skewness': float(np.mean(((np.array(all_ratios) - np.mean(all_ratios)) / np.std(all_ratios))**3)),
                    'kurtosis': float(np.mean(((np.array(all_ratios) - np.mean(all_ratios)) / np.std(all_ratios))**4))
                }
            
            return {'mean': 1.73, 'std': 0.05}
        except:
            return {'mean': 1.73, 'std': 0.05}
    
