    def _extract_comprehensive_lp_features(self, lp_events: List[Dict], config: Dict) -> Dict:
        """Extract comprehensive features from LP events for gas content analysis"""
        try:
            features = {}
            
            # Temporal features
            temporal_features = self._extract_lp_temporal_features(lp_events, config)
            features['temporal'] = temporal_features
            
            # Spectral features
            spectral_features = self._extract_lp_spectral_features(lp_events, config)
            features['spectral'] = spectral_features
            
            # Amplitude features
            amplitude_features = self._extract_lp_amplitude_features(lp_events, config)
            features['amplitude'] = amplitude_features
            
            # Duration features
            duration_features = self._extract_lp_duration_features(lp_events, config)
            features['duration'] = duration_features
            
            # Gas-specific features
            gas_features = self._extract_lp_gas_features(lp_events, config)
            features['gas_signatures'] = gas_features
            
            return features
            
        except Exception as e:
            return {'error': f'LP feature extraction failed: {str(e)}'}
    
    def _extract_lp_temporal_features(self, lp_events: List[Dict], config: Dict) -> Dict:
        """Extract temporal features from LP events"""
        try:
            times = [event.get('time', 0) for event in lp_events]
            intervals = np.diff(sorted(times)) if len(times) > 1 else [0]
            
            return {
                'event_rate': len(lp_events) / config.get('time_window', 3600) * 3600,
                'mean_interval': float(np.mean(intervals)) if intervals else 0,
                'interval_std': float(np.std(intervals)) if intervals else 0,
                'interval_cv': float(np.std(intervals) / np.mean(intervals)) if intervals and np.mean(intervals) > 0 else 0,
                'temporal_clustering': self._calculate_temporal_clustering(times),
                'periodicity_score': self._calculate_periodicity_score(intervals)
            }
        except Exception as e:
            return {'error': f'Temporal feature extraction failed: {str(e)}'}
    
    def _extract_lp_spectral_features(self, lp_events: List[Dict], config: Dict) -> Dict:
        """Extract spectral features from LP events"""
        try:
            frequencies = []
            peak_frequencies = []
            bandwidths = []
            
            for event in lp_events:
                freq_data = event.get('frequency_content', {})
                frequencies.extend(freq_data.get('frequencies', []))
                peak_frequencies.append(freq_data.get('peak_frequency', 2.0))
                bandwidths.append(freq_data.get('bandwidth', 1.0))
            
            return {
                'mean_peak_frequency': float(np.mean(peak_frequencies)) if peak_frequencies else 2.0,
                'frequency_std': float(np.std(peak_frequencies)) if peak_frequencies else 0.5,
                'mean_bandwidth': float(np.mean(bandwidths)) if bandwidths else 1.0,
                'frequency_range': float(np.ptp(peak_frequencies)) if peak_frequencies else 1.0,
                'spectral_centroid': self._calculate_spectral_centroid(frequencies),
                'spectral_rolloff': self._calculate_spectral_rolloff(frequencies)
            }
        except Exception as e:
            return {'error': f'Spectral feature extraction failed: {str(e)}'}
    
    def _extract_lp_amplitude_features(self, lp_events: List[Dict], config: Dict) -> Dict:
        """Extract amplitude features from LP events"""
        try:
            amplitudes = [event.get('amplitude', 1.0) for event in lp_events]
            
            return {
                'mean_amplitude': float(np.mean(amplitudes)),
                'amplitude_std': float(np.std(amplitudes)),
                'max_amplitude': float(np.max(amplitudes)),
                'min_amplitude': float(np.min(amplitudes)),
                'amplitude_skewness': float(self._calculate_skewness(amplitudes)),
                'amplitude_kurtosis': float(self._calculate_kurtosis(amplitudes))
            }
        except Exception as e:
            return {'error': f'Amplitude feature extraction failed: {str(e)}'}
    
    def _extract_lp_duration_features(self, lp_events: List[Dict], config: Dict) -> Dict:
        """Extract duration features from LP events"""
        try:
            durations = [event.get('duration', 10.0) for event in lp_events]
            
            return {
                'mean_duration': float(np.mean(durations)),
                'duration_std': float(np.std(durations)),
                'max_duration': float(np.max(durations)),
                'min_duration': float(np.min(durations)),
                'duration_trend': self._calculate_duration_trend(durations),
                'duration_variability': float(np.std(durations) / np.mean(durations)) if np.mean(durations) > 0 else 0
            }
        except Exception as e:
            return {'error': f'Duration feature extraction failed: {str(e)}'}
    
    def _extract_lp_gas_features(self, lp_events: List[Dict], config: Dict) -> Dict:
        """Extract gas-specific features from LP events"""
        try:
            q_factors = [event.get('q_factor', 50) for event in lp_events]
            resonance_frequencies = [event.get('resonance_frequency', 2.0) for event in lp_events]
            
            return {
                'mean_q_factor': float(np.mean(q_factors)),
                'q_factor_variability': float(np.std(q_factors)),
                'resonance_stability': float(np.std(resonance_frequencies)),
                'gas_signature_strength': self._calculate_gas_signature_strength(lp_events),
                'degassing_indicator': self._calculate_degassing_indicator(lp_events),
                'bubble_resonance_score': self._calculate_bubble_resonance_score(lp_events)
            }
        except Exception as e:
            return {'error': f'Gas feature extraction failed: {str(e)}'}
    
    def _thermodynamic_gas_modeling(self, lp_events: List[Dict], config: Dict) -> Dict:
        """Thermodynamic modeling of gas content from LP events"""
        try:
            # Get thermodynamic properties
            thermo_engine = getattr(self, 'thermodynamic_engine', None)
            if not thermo_engine:
                return self._simple_thermodynamic_gas_estimate(lp_events, config)
            
            # LP event characteristics
            mean_frequency = np.mean([event.get('frequency_content', {}).get('peak_frequency', 2.0) 
                                    for event in lp_events])
            mean_q_factor = np.mean([event.get('q_factor', 50) for event in lp_events])
            event_rate = len(lp_events) / config.get('time_window', 3600) * 3600
            
            # Thermodynamic gas content estimation
            bubble_radius = self._estimate_bubble_radius_from_frequency(mean_frequency)
            gas_pressure = self._estimate_gas_pressure_from_q_factor(mean_q_factor)
            
            # Solubility modeling
            solubility_model = self._calculate_gas_solubility(gas_pressure, config)
            
            # Gas flux estimation
            gas_flux = self._estimate_gas_flux_from_lp_rate(event_rate, bubble_radius)
            
            # Gas content calculation
            gas_content = self._calculate_thermodynamic_gas_content(
                solubility_model, gas_flux, config)
            
            return {
                'gas_content_h2o': gas_content.get('h2o_content', 3.0),
                'gas_content_co2': gas_content.get('co2_content', 0.5),
                'bubble_radius': bubble_radius,
                'gas_pressure': gas_pressure,
                'gas_flux': gas_flux,
                'solubility_model': solubility_model,
                'confidence': 0.8,
                'method': 'thermodynamic_modeling'
            }
            
        except Exception as e:
            return {'error': f'Thermodynamic gas modeling failed: {str(e)}'}
    
    def _spectral_gas_content_analysis(self, lp_events: List[Dict], config: Dict) -> Dict:
        """Spectral analysis-based gas content estimation"""
        try:
            # Extract spectral characteristics
            spectral_data = []
            for event in lp_events:
                freq_content = event.get('frequency_content', {})
                spectral_data.append({
                    'peak_freq': freq_content.get('peak_frequency', 2.0),
                    'bandwidth': freq_content.get('bandwidth', 1.0),
                    'spectral_power': freq_content.get('total_power', 1.0)
                })
            
            if not spectral_data:
                return {'error': 'No spectral data available'}
            
            # Gas content indicators from spectral analysis
            mean_peak_freq = np.mean([d['peak_freq'] for d in spectral_data])
            freq_stability = 1.0 / (1.0 + np.std([d['peak_freq'] for d in spectral_data]))
            
            # Empirical relationships for gas content
            # Lower frequencies often indicate higher gas content
            frequency_gas_indicator = max(0, (5.0 - mean_peak_freq) / 3.0)
            
            # Spectral bandwidth indicates gas bubble size distribution
            mean_bandwidth = np.mean([d['bandwidth'] for d in spectral_data])
            bandwidth_gas_indicator = min(5.0, mean_bandwidth * 2.0)
            
            # Combined spectral gas estimate
            spectral_gas_content = (frequency_gas_indicator + bandwidth_gas_indicator) / 2.0
            
            return {
                'spectral_gas_content': min(8.0, spectral_gas_content),
                'frequency_indicator': frequency_gas_indicator,
                'bandwidth_indicator': bandwidth_gas_indicator,
                'frequency_stability': freq_stability,
                'confidence': min(0.9, freq_stability * 0.8),
                'method': 'spectral_analysis'
            }
            
        except Exception as e:
            return {'error': f'Spectral gas analysis failed: {str(e)}'}
    
    def _ml_gas_content_prediction(self, lp_features: Dict, config: Dict) -> Dict:
        """Machine learning-based gas content prediction"""
        try:
            # Extract features for ML model
            feature_vector = self._create_ml_feature_vector(lp_features)
            
            # Simulated ML prediction (would use trained model in production)
            # Features: temporal patterns, spectral characteristics, amplitude distributions
            temporal_weight = 0.3
            spectral_weight = 0.4
            amplitude_weight = 0.3
            
            # Temporal contribution
            temporal_features = lp_features.get('temporal', {})
            event_rate = temporal_features.get('event_rate', 10)
            temporal_score = min(5.0, event_rate * 0.3)
            
            # Spectral contribution
            spectral_features = lp_features.get('spectral', {})
            peak_freq = spectral_features.get('mean_peak_frequency', 2.0)
            spectral_score = max(0, (6.0 - peak_freq) / 2.0) * 3.0
            
            # Amplitude contribution
            amplitude_features = lp_features.get('amplitude', {})
            amplitude_variability = amplitude_features.get('amplitude_std', 0.5)
            amplitude_score = min(4.0, amplitude_variability * 4.0)
            
            # Combined ML prediction
            ml_gas_content = (temporal_score * temporal_weight + 
                            spectral_score * spectral_weight + 
                            amplitude_score * amplitude_weight)
            
            # Uncertainty estimation
            feature_completeness = len([f for f in [temporal_features, spectral_features, amplitude_features] 
                                      if f and not f.get('error')])
            confidence = min(0.95, feature_completeness / 3.0 * 0.9)
            
            return {
                'ml_gas_content': min(7.0, ml_gas_content),
                'temporal_contribution': temporal_score,
                'spectral_contribution': spectral_score,
                'amplitude_contribution': amplitude_score,
                'feature_importance': {
                    'temporal': temporal_weight,
                    'spectral': spectral_weight,
                    'amplitude': amplitude_weight
                },
                'confidence': confidence,
                'method': 'machine_learning'
            }
            
        except Exception as e:
            return {'error': f'ML gas prediction failed: {str(e)}'}
    
    def _wavelet_gas_signature_analysis(self, lp_events: List[Dict], config: Dict) -> Dict:
        """Wavelet-based gas signature analysis"""
        try:
            # Analyze gas signatures using wavelet decomposition
            gas_signatures = []
            
            for event in lp_events:
                # Simulate wavelet analysis of LP event
                duration = event.get('duration', 10.0)
                amplitude = event.get('amplitude', 1.0)
                frequency = event.get('frequency_content', {}).get('peak_frequency', 2.0)
                
                # Gas signature indicators from wavelet analysis
                low_freq_energy = max(0, (5.0 - frequency) / 5.0) * amplitude
                sustained_energy = min(1.0, duration / 20.0) * amplitude
                
                gas_signatures.append({
                    'low_freq_energy': low_freq_energy,
                    'sustained_energy': sustained_energy,
                    'gas_score': (low_freq_energy + sustained_energy) / 2.0
                })
            
            if not gas_signatures:
                return {'error': 'No gas signatures detected'}
            
            # Aggregate wavelet gas content estimate
            mean_gas_score = np.mean([sig['gas_score'] for sig in gas_signatures])
            gas_score_stability = 1.0 / (1.0 + np.std([sig['gas_score'] for sig in gas_signatures]))
            
            wavelet_gas_content = mean_gas_score * 5.0  # Scale to weight percent
            
            return {
                'wavelet_gas_content': min(6.0, wavelet_gas_content),
                'gas_signature_strength': mean_gas_score,
                'signature_stability': gas_score_stability,
                'low_frequency_dominance': np.mean([sig['low_freq_energy'] for sig in gas_signatures]),
                'sustained_energy_ratio': np.mean([sig['sustained_energy'] for sig in gas_signatures]),
                'confidence': min(0.85, gas_score_stability * 0.9),
                'method': 'wavelet_analysis'
            }
            
        except Exception as e:
            return {'error': f'Wavelet gas analysis failed: {str(e)}'}
    
    def _statistical_gas_content_modeling(self, lp_events: List[Dict], config: Dict) -> Dict:
        """Statistical modeling of gas content from LP events"""
        try:
            # Statistical parameters
            event_count = len(lp_events)
            time_window = config.get('time_window', 3600)
            
            # Event rate statistics
            event_rate = event_count / time_window * 3600  # events/hour
            
            # Amplitude statistics
            amplitudes = [event.get('amplitude', 1.0) for event in lp_events]
            amplitude_stats = {
                'mean': np.mean(amplitudes),
                'std': np.std(amplitudes),
                'skewness': self._calculate_skewness(amplitudes),
                'kurtosis': self._calculate_kurtosis(amplitudes)
            }
            
            # Frequency statistics
            frequencies = [event.get('frequency_content', {}).get('peak_frequency', 2.0) 
                         for event in lp_events]
            frequency_stats = {
                'mean': np.mean(frequencies),
                'std': np.std(frequencies),
                'median': np.median(frequencies)
            }
            
            # Statistical gas content models
            # Model 1: Rate-based estimation
            rate_gas_content = min(6.0, event_rate * 0.4)
            
            # Model 2: Amplitude distribution-based
            amplitude_gas_content = min(5.0, amplitude_stats['mean'] * 3.0 + amplitude_stats['std'])
            
            # Model 3: Frequency distribution-based
            freq_gas_content = max(0, (4.0 - frequency_stats['mean']) / 2.0) * 4.0
            
            # Combined statistical estimate
            statistical_weights = [0.4, 0.3, 0.3]
            statistical_gas_content = (rate_gas_content * statistical_weights[0] + 
                                     amplitude_gas_content * statistical_weights[1] + 
                                     freq_gas_content * statistical_weights[2])
            
            # Confidence based on data quality
            data_quality = min(1.0, event_count / 20.0)  # Better confidence with more events
            confidence = min(0.9, data_quality * 0.8)
            
            return {
                'statistical_gas_content': min(7.0, statistical_gas_content),
                'rate_based_estimate': rate_gas_content,
                'amplitude_based_estimate': amplitude_gas_content,
                'frequency_based_estimate': freq_gas_content,
                'statistical_confidence': confidence,
                'data_quality_score': data_quality,
                'event_statistics': {
                    'count': event_count,
                    'rate': event_rate,
                    'amplitude_stats': amplitude_stats,
                    'frequency_stats': frequency_stats
                },
                'method': 'statistical_modeling'
            }
            
        except Exception as e:
            return {'error': f'Statistical gas modeling failed: {str(e)}'}
    
    def _process_based_gas_estimation(self, lp_events: List[Dict], config: Dict) -> Dict:
        """Physical process-based gas content estimation"""
        try:
            # Physical process parameters
            magma_properties = config.get('magma_properties', {})
            
            # Bubble dynamics analysis
            bubble_analysis = self._analyze_bubble_dynamics(lp_events, config)
            
            # Degassing process modeling
            degassing_analysis = self._analyze_degassing_processes(lp_events, config)
            
            # Conduit flow modeling
            conduit_analysis = self._analyze_conduit_flow(lp_events, config)
            
            # Gas transport modeling
            transport_analysis = self._analyze_gas_transport(lp_events, config)
            
            # Integrated process-based estimate
            process_estimates = [
                bubble_analysis.get('gas_content_estimate', 3.0),
                degassing_analysis.get('gas_content_estimate', 3.0),
                conduit_analysis.get('gas_content_estimate', 3.0),
                transport_analysis.get('gas_content_estimate', 3.0)
            ]
            
            process_gas_content = np.mean(process_estimates)
            process_uncertainty = np.std(process_estimates)
            
            return {
                'process_gas_content': min(8.0, process_gas_content),
                'bubble_dynamics': bubble_analysis,
                'degassing_processes': degassing_analysis,
                'conduit_flow': conduit_analysis,
                'gas_transport': transport_analysis,
                'process_uncertainty': process_uncertainty,
                'confidence': max(0.6, 1.0 - process_uncertainty / 3.0),
                'method': 'physical_processes'
            }
            
        except Exception as e:
            return {'error': f'Process-based gas estimation failed: {str(e)}'}
    
    def _ensemble_gas_content_fusion(self, gas_results: Dict, config: Dict) -> Dict:
        """Ensemble fusion of gas content estimates"""
        try:
            # Extract estimates from different methods
            estimates = {}
            confidences = {}
            
            for method, result in gas_results.items():
                if isinstance(result, dict) and not result.get('error'):
                    # Extract gas content estimate
                    if 'gas_content_h2o' in result:
                        estimates[method] = result['gas_content_h2o']
                    elif 'spectral_gas_content' in result:
                        estimates[method] = result['spectral_gas_content']
                    elif 'ml_gas_content' in result:
                        estimates[method] = result['ml_gas_content']
                    elif 'wavelet_gas_content' in result:
                        estimates[method] = result['wavelet_gas_content']
                    elif 'statistical_gas_content' in result:
                        estimates[method] = result['statistical_gas_content']
                    elif 'process_gas_content' in result:
                        estimates[method] = result['process_gas_content']
                    
                    # Extract confidence
                    confidences[method] = result.get('confidence', 0.5)
            
            if not estimates:
                return {'error': 'No valid estimates for fusion'}
            
            # Weighted ensemble fusion
            total_weight = sum(confidences.values())
            if total_weight > 0:
                weighted_estimate = sum(est * confidences[method] for method, est in estimates.items()) / total_weight
            else:
                weighted_estimate = np.mean(list(estimates.values()))
            
            # Calculate ensemble uncertainty
            estimate_std = np.std(list(estimates.values()))
            confidence_std = np.std(list(confidences.values()))
            
            ensemble_confidence = min(0.95, np.mean(list(confidences.values())) * 
                                    (1.0 - estimate_std / max(weighted_estimate, 1.0)))
            
            # Method agreement analysis
            method_agreement = 1.0 - (estimate_std / max(weighted_estimate, 1.0))
            
            return {
                'ensemble_gas_content': min(8.0, weighted_estimate),
                'individual_estimates': estimates,
                'method_confidences': confidences,
                'ensemble_uncertainty': estimate_std,
                'ensemble_confidence': ensemble_confidence,
                'method_agreement': max(0, method_agreement),
                'fusion_weights': {method: conf/total_weight for method, conf in confidences.items()},
                'consensus_strength': len(estimates),
                'method': 'ensemble_fusion'
            }
            
        except Exception as e:
            return {'error': f'Ensemble fusion failed: {str(e)}'}
    
