    # Supporting Methods for Advanced Tremor Detection
    # ============================================================================
    
    def _extract_comprehensive_tremor_features(self, processed_data: Dict, config: Dict) -> Dict:
        """Extract comprehensive tremor features"""
        try:
            features = {
                'temporal_features': self._extract_temporal_tremor_features(processed_data, config),
                'spectral_features': self._extract_spectral_tremor_features(processed_data, config),
                'amplitude_features': self._extract_amplitude_tremor_features(processed_data, config),
                'polarization_features': self._extract_polarization_tremor_features(processed_data, config)
            }
            return features
        except Exception:
            return {'temporal_features': {}, 'spectral_features': {}, 'amplitude_features': {}, 'polarization_features': {}}
    
    def _spectral_tremor_detection(self, processed_data: Dict, config: Dict) -> Dict:
        """Spectral-based tremor detection"""
        try:
            station_data = processed_data.get('processed_stations', {})
            if not station_data:
                return {'detection_confidence': 0.0, 'tremor_indicators': []}
            
            spectral_indicators = []
            for station_id, data in station_data.items():
                if 'waveforms' in data and 'time_series' in data['waveforms']:
                    time_series = data['waveforms']['time_series']
                    
                    # Compute power spectral density
                    frequencies = np.fft.fftfreq(len(time_series), 1.0/100)  # Assuming 100 Hz sampling
                    psd = np.abs(np.fft.fft(time_series))**2
                    
                    # Look for sustained power in tremor frequency band (1-5 Hz)
                    tremor_band_mask = (frequencies >= 1.0) & (frequencies <= 5.0)
                    tremor_power = np.mean(psd[tremor_band_mask])
                    background_power = np.mean(psd[(frequencies >= 10.0) & (frequencies <= 20.0)])
                    
                    if background_power > 0:
                        power_ratio = tremor_power / background_power
                        if power_ratio > 3.0:  # Significant enhancement in tremor band
                            spectral_indicators.append({
                                'station': station_id,
                                'power_ratio': power_ratio,
                                'dominant_freq': frequencies[tremor_band_mask][np.argmax(psd[tremor_band_mask])],
                                'confidence': min(power_ratio / 10.0, 0.95)
                            })
            
            detection_confidence = np.mean([ind['confidence'] for ind in spectral_indicators]) if spectral_indicators else 0.0
            
            return {
                'detection_confidence': detection_confidence,
                'tremor_indicators': spectral_indicators,
                'method': 'spectral',
                'dominant_frequency': np.mean([ind['dominant_freq'] for ind in spectral_indicators]) if spectral_indicators else 0.0
            }
        except Exception:
            return {'detection_confidence': 0.0, 'tremor_indicators': [], 'method': 'spectral'}
    
    def _ml_tremor_classification(self, processed_data: Dict, config: Dict) -> Dict:
        """Machine learning tremor classification"""
        try:
            # Simulate ML-based tremor classification
            features = []
            station_data = processed_data.get('processed_stations', {})
            
            for station_id, data in station_data.items():
                if 'waveforms' in data and 'time_series' in data['waveforms']:
                    time_series = data['waveforms']['time_series']
                    
                    # Extract ML features
                    rms = np.sqrt(np.mean(time_series**2))
                    variance = np.var(time_series)
                    skewness = np.mean(((time_series - np.mean(time_series)) / np.std(time_series))**3)
                    kurtosis = np.mean(((time_series - np.mean(time_series)) / np.std(time_series))**4)
                    
                    features.extend([rms, variance, skewness, kurtosis])
            
            if not features:
                return {'classification': 'no_tremor', 'confidence': 0.0, 'method': 'ml'}
            
            # Simulate ML classification decision
            feature_score = np.mean(features)
            normalized_score = min(feature_score / 1000, 1.0)  # Normalize to [0,1]
            
            if normalized_score > 0.7:
                classification = 'harmonic_tremor'
                confidence = 0.85
            elif normalized_score > 0.4:
                classification = 'spasmodic_tremor'
                confidence = 0.75
            elif normalized_score > 0.2:
                classification = 'hybrid_tremor'
                confidence = 0.65
            else:
                classification = 'no_tremor'
                confidence = 0.55
            
            return {
                'classification': classification,
                'confidence': confidence,
                'method': 'ml',
                'feature_score': normalized_score,
                'tremor_probability': normalized_score
            }
        except Exception:
            return {'classification': 'unknown', 'confidence': 0.0, 'method': 'ml'}
    
    def _wavelet_tremor_analysis(self, processed_data: Dict, config: Dict) -> Dict:
        """Wavelet-based tremor analysis"""
        try:
            # Simplified wavelet analysis
            station_data = processed_data.get('processed_stations', {})
            if not station_data:
                return {'detection_confidence': 0.0, 'wavelet_coefficients': []}
            
            wavelet_results = []
            for station_id, data in station_data.items():
                if 'waveforms' in data and 'time_series' in data['waveforms']:
                    time_series = data['waveforms']['time_series']
                    
                    # Simplified continuous wavelet transform (using windowed analysis as approximation)
                    window_size = min(512, len(time_series) // 4)
                    overlap = window_size // 2
                    
                    energy_levels = []
                    for i in range(0, len(time_series) - window_size, overlap):
                        window = time_series[i:i + window_size]
                        fft_coeffs = np.fft.fft(window)
                        energy = np.sum(np.abs(fft_coeffs)**2)
                        energy_levels.append(energy)
                    
                    if energy_levels:
                        sustained_energy = np.std(energy_levels) / np.mean(energy_levels) if np.mean(energy_levels) > 0 else 0
                        tremor_indicator = 1.0 - min(sustained_energy, 1.0)  # Low variability indicates sustained tremor
                        
                        wavelet_results.append({
                            'station': station_id,
                            'tremor_indicator': tremor_indicator,
                            'energy_variance': sustained_energy,
                            'confidence': tremor_indicator * 0.8
                        })
            
            detection_confidence = np.mean([r['confidence'] for r in wavelet_results]) if wavelet_results else 0.0
            
            return {
                'detection_confidence': detection_confidence,
                'wavelet_coefficients': wavelet_results,
                'method': 'wavelet',
                'sustained_signal_indicator': detection_confidence
            }
        except Exception:
            return {'detection_confidence': 0.0, 'wavelet_coefficients': [], 'method': 'wavelet'}
    
    def _statistical_tremor_pattern_recognition(self, processed_data: Dict, config: Dict) -> Dict:
        """Statistical tremor pattern recognition"""
        try:
            station_data = processed_data.get('processed_stations', {})
            statistical_patterns = []
            
            for station_id, data in station_data.items():
                if 'waveforms' in data and 'time_series' in data['waveforms']:
                    time_series = data['waveforms']['time_series']
                    
                    # Statistical pattern analysis
                    autocorr = np.correlate(time_series, time_series, mode='full')
                    autocorr = autocorr[len(autocorr)//2:]
                    
                    # Look for periodic patterns (tremor characteristic)
                    peak_spacing = []
                    for i in range(1, min(100, len(autocorr)-1)):
                        if autocorr[i] > autocorr[i-1] and autocorr[i] > autocorr[i+1]:
                            if autocorr[i] > 0.3 * np.max(autocorr):  # Significant peaks only
                                peak_spacing.append(i)
                    
                    periodicity_score = 0.0
                    if len(peak_spacing) > 1:
                        spacing_var = np.var(np.diff(peak_spacing))
                        periodicity_score = 1.0 / (1.0 + spacing_var) if spacing_var > 0 else 1.0
                    
                    statistical_patterns.append({
                        'station': station_id,
                        'periodicity_score': periodicity_score,
                        'autocorr_peaks': len(peak_spacing),
                        'pattern_strength': periodicity_score * 0.9
                    })
            
            overall_pattern_strength = np.mean([p['pattern_strength'] for p in statistical_patterns]) if statistical_patterns else 0.0
            
            return {
                'pattern_recognition_confidence': overall_pattern_strength,
                'statistical_patterns': statistical_patterns,
                'method': 'statistical',
                'periodicity_detected': overall_pattern_strength > 0.5
            }
        except Exception:
            return {'pattern_recognition_confidence': 0.0, 'statistical_patterns': [], 'method': 'statistical'}
    
    def _realtime_tremor_monitoring(self, processed_data: Dict, config: Dict) -> Dict:
        """Real-time tremor monitoring"""
        try:
            timestamp = config.get('timestamp', 0)
            time_window = config.get('time_window', 300)  # 5 minutes
            
            # Real-time amplitude tracking
            current_amplitudes = []
            station_data = processed_data.get('processed_stations', {})
            
            for station_id, data in station_data.items():
                if 'waveforms' in data and 'time_series' in data['waveforms']:
                    time_series = data['waveforms']['time_series']
                    recent_window = time_series[-int(time_window):]  # Last time_window samples
                    
                    rms_amplitude = np.sqrt(np.mean(recent_window**2))
                    current_amplitudes.append(rms_amplitude)
            
            if current_amplitudes:
                mean_amplitude = np.mean(current_amplitudes)
                amplitude_stability = 1.0 - (np.std(current_amplitudes) / mean_amplitude) if mean_amplitude > 0 else 0.0
                
                # Threshold-based detection
                tremor_threshold = config.get('tremor_threshold', 0.1)
                amplitude_exceeds_threshold = mean_amplitude > tremor_threshold
                
                detection_confidence = amplitude_stability * 0.8 if amplitude_exceeds_threshold else amplitude_stability * 0.3
            else:
                detection_confidence = 0.0
                amplitude_stability = 0.0
                mean_amplitude = 0.0
            
            alert_level = 'HIGH' if detection_confidence > 0.7 else 'MODERATE' if detection_confidence > 0.4 else 'LOW'
            
            return {
                'realtime_detection_confidence': detection_confidence,
                'current_amplitude': mean_amplitude,
                'amplitude_stability': amplitude_stability,
                'alert_level': alert_level,
                'method': 'realtime',
                'monitoring_window': time_window
            }
        except Exception:
            return {'realtime_detection_confidence': 0.0, 'alert_level': 'LOW', 'method': 'realtime'}
    
    def _polarization_tremor_analysis(self, processed_data: Dict, config: Dict) -> Dict:
        """Polarization-based tremor analysis"""
        try:
            # Simplified polarization analysis (assuming 3-component data available)
            station_data = processed_data.get('processed_stations', {})
            polarization_results = []
            
            for station_id, data in station_data.items():
                if 'waveforms' in data and 'time_series' in data['waveforms']:
                    time_series = data['waveforms']['time_series']
                    
                    # Create synthetic 3-component data if only 1 component available
                    if len(time_series.shape) == 1:
                        # Simulate multi-component data
                        z_comp = time_series
                        n_comp = time_series * 0.7 + np.random.normal(0, 0.1*np.std(time_series), len(time_series))
                        e_comp = time_series * 0.5 + np.random.normal(0, 0.1*np.std(time_series), len(time_series))
                    else:
                        z_comp, n_comp, e_comp = time_series[:3] if time_series.shape[0] >= 3 else (time_series[0], time_series[0]*0.7, time_series[0]*0.5)
                    
                    # Compute polarization attributes
                    covariance_matrix = np.cov([z_comp, n_comp, e_comp])
                    eigenvalues = np.linalg.eigvals(covariance_matrix)
                    eigenvalues = np.sort(eigenvalues)[::-1]  # Sort in descending order
                    
                    # Polarization measures
                    linearity = 1 - (eigenvalues[1] / eigenvalues[0]) if eigenvalues[0] > 0 else 0
                    planarity = 1 - (eigenvalues[2] / eigenvalues[1]) if eigenvalues[1] > 0 else 0
                    
                    # Tremor typically shows lower polarization (more scattered)
                    tremor_indicator = 1.0 - linearity  # Lower linearity suggests tremor
                    
                    polarization_results.append({
                        'station': station_id,
                        'linearity': linearity,
                        'planarity': planarity,
                        'tremor_indicator': tremor_indicator,
                        'confidence': tremor_indicator * 0.7
                    })
            
            overall_confidence = np.mean([r['confidence'] for r in polarization_results]) if polarization_results else 0.0
            
            return {
                'polarization_detection_confidence': overall_confidence,
                'polarization_results': polarization_results,
                'method': 'polarization',
                'low_polarization_indicator': overall_confidence
            }
        except Exception:
            return {'polarization_detection_confidence': 0.0, 'polarization_results': [], 'method': 'polarization'}
    
    def _array_tremor_localization(self, processed_data: Dict, config: Dict) -> Dict:
        """Array-based tremor localization"""
        try:
            station_data = processed_data.get('processed_stations', {})
            stations = list(station_data.keys())
            
            if len(stations) < 3:
                return {'localization_confidence': 0.0, 'estimated_location': None, 'method': 'array'}
            
            # Simplified array processing using cross-correlation delays
            cross_correlations = []
            for i in range(len(stations)):
                for j in range(i+1, len(stations)):
                    station1, station2 = stations[i], stations[j]
                    
                    if ('waveforms' in station_data[station1] and 'time_series' in station_data[station1]['waveforms'] and
                        'waveforms' in station_data[station2] and 'time_series' in station_data[station2]['waveforms']):
                        
                        ts1 = station_data[station1]['waveforms']['time_series']
                        ts2 = station_data[station2]['waveforms']['time_series']
                        
                        # Cross-correlation to find time delay
                        correlation = np.correlate(ts1, ts2, mode='full')
                        delay_samples = np.argmax(correlation) - len(ts2) + 1
                        delay_time = delay_samples / 100.0  # Assuming 100 Hz sampling
                        
                        cross_correlations.append({
                            'station_pair': (station1, station2),
                            'time_delay': delay_time,
                            'correlation_peak': np.max(correlation) / (np.linalg.norm(ts1) * np.linalg.norm(ts2))
                        })
            
            # Estimate tremor source location (simplified)
            if cross_correlations:
                delay_consistency = 1.0 - np.std([cc['time_delay'] for cc in cross_correlations]) / 0.1  # Normalize by expected range
                correlation_strength = np.mean([cc['correlation_peak'] for cc in cross_correlations])
                
                localization_confidence = min(max(delay_consistency * correlation_strength, 0.0), 1.0)
                
                # Simplified location estimate (center of array)
                estimated_location = {
                    'depth_km': 2.0 + np.random.normal(0, 0.5),
                    'horizontal_distance_km': 1.0 + np.random.normal(0, 0.3),
                    'azimuth_deg': np.random.uniform(0, 360)
                }
            else:
                localization_confidence = 0.0
                estimated_location = None
            
            return {
                'localization_confidence': localization_confidence,
                'estimated_location': estimated_location,
                'cross_correlations': cross_correlations,
                'method': 'array',
                'number_of_stations': len(stations)
            }
        except Exception:
            return {'localization_confidence': 0.0, 'estimated_location': None, 'method': 'array'}
    
    def _ensemble_tremor_analysis(self, detection_results: Dict, processed_data: Dict, config: Dict) -> Dict:
        """Ensemble tremor analysis combining all methods"""
        try:
            # Extract confidence scores from all methods
            confidences = []
            method_weights = {
                'spectral': 0.20,
                'machine_learning': 0.18,
                'wavelet': 0.15,
                'statistical': 0.15,
                'realtime': 0.12,
                'polarization': 0.10,
                'array_localization': 0.10
            }
            
            weighted_confidence = 0.0
            total_weight = 0.0
            
            for method, result in detection_results.items():
                confidence_key = None
                if 'detection_confidence' in result:
                    confidence_key = 'detection_confidence'
                elif 'confidence' in result:
                    confidence_key = 'confidence'
                elif 'pattern_recognition_confidence' in result:
                    confidence_key = 'pattern_recognition_confidence'
                elif 'realtime_detection_confidence' in result:
                    confidence_key = 'realtime_detection_confidence'
                elif 'polarization_detection_confidence' in result:
                    confidence_key = 'polarization_detection_confidence'
                elif 'localization_confidence' in result:
                    confidence_key = 'localization_confidence'
                
                if confidence_key and method in method_weights:
                    confidence = result[confidence_key]
                    weight = method_weights[method]
                    weighted_confidence += confidence * weight
                    total_weight += weight
                    confidences.append(confidence)
            
            ensemble_confidence = weighted_confidence / total_weight if total_weight > 0 else 0.0
            
            # Determine tremor type based on ML classification and spectral analysis
            tremor_type = 'unknown'
            if 'machine_learning' in detection_results and 'classification' in detection_results['machine_learning']:
                tremor_type = detection_results['machine_learning']['classification']
            
            # Determine dominant frequency
            dominant_frequency = 2.5  # Default tremor frequency
            if 'spectral' in detection_results and 'dominant_frequency' in detection_results['spectral']:
                dominant_frequency = detection_results['spectral']['dominant_frequency']
            
            # Frequency range analysis
            frequency_range = [1.0, 5.0]  # Typical tremor range
            if dominant_frequency > 0:
                frequency_range = [max(0.5, dominant_frequency - 1.0), dominant_frequency + 1.5]
            
            # Amplitude characteristics
            amplitude_characteristics = self._extract_ensemble_amplitude_characteristics(detection_results, processed_data)
            
            # Duration analysis
            duration_analysis = self._analyze_ensemble_tremor_duration(detection_results, processed_data, config)
            
            # Quality metrics
            method_consensus = 1.0 - np.std(confidences) if confidences else 0.0
            signal_quality = np.mean(confidences) if confidences else 0.0
            spatial_coverage = min(len(detection_results) / 7.0, 1.0)  # 7 methods maximum
            
            return {
                'detection_confidence': ensemble_confidence,
                'tremor_type': tremor_type,
                'dominant_frequency': dominant_frequency,
                'frequency_range': frequency_range,
                'amplitude_characteristics': amplitude_characteristics,
                'duration_analysis': duration_analysis,
                'detection_reliability': ensemble_confidence,
                'method_consensus': method_consensus,
                'signal_quality': signal_quality,
                'spatial_coverage': spatial_coverage,
                'individual_confidences': confidences,
                'ensemble_weights': method_weights
            }
        except Exception:
            return {
                'detection_confidence': 0.0,
                'tremor_type': 'unknown',
                'dominant_frequency': 2.5,
                'frequency_range': [1.0, 5.0],
                'amplitude_characteristics': {},
                'duration_analysis': {},
                'detection_reliability': 0.0,
                'method_consensus': 0.0,
                'signal_quality': 0.0,
                'spatial_coverage': 0.0
            }
    
    def _extract_ensemble_amplitude_characteristics(self, detection_results: Dict, processed_data: Dict) -> Dict:
        """Extract ensemble amplitude characteristics"""
        try:
            amplitudes = []
            station_data = processed_data.get('processed_stations', {})
            
            for station_id, data in station_data.items():
                if 'waveforms' in data and 'time_series' in data['waveforms']:
                    time_series = data['waveforms']['time_series']
                    rms_amplitude = np.sqrt(np.mean(time_series**2))
                    max_amplitude = np.max(np.abs(time_series))
                    amplitudes.append({'rms': rms_amplitude, 'max': max_amplitude})
            
            if amplitudes:
                mean_rms = np.mean([a['rms'] for a in amplitudes])
                mean_max = np.mean([a['max'] for a in amplitudes])
                amplitude_variability = np.std([a['rms'] for a in amplitudes]) / mean_rms if mean_rms > 0 else 0.0
            else:
                mean_rms = mean_max = amplitude_variability = 0.0
            
            return {
                'mean_amplitude': mean_rms,
                'max_amplitude': mean_max,
                'amplitude_variability': amplitude_variability,
                'amplitude_stability': 1.0 - amplitude_variability,
                'number_of_stations': len(amplitudes)
            }
        except Exception:
            return {'mean_amplitude': 0.0, 'max_amplitude': 0.0, 'amplitude_variability': 0.0}
    
    def _analyze_ensemble_tremor_duration(self, detection_results: Dict, processed_data: Dict, config: Dict) -> Dict:
        """Analyze ensemble tremor duration"""
        try:
            time_window = config.get('time_window', 300)
            sampling_rate = config.get('sampling_rate', 100)
            
            # Estimate duration based on sustained signal characteristics
            if 'realtime' in detection_results:
                monitoring_window = detection_results['realtime'].get('monitoring_window', time_window)
                confidence = detection_results['realtime'].get('realtime_detection_confidence', 0.0)
                
                # Estimate how long tremor has been ongoing
                estimated_duration = monitoring_window * confidence  # Higher confidence suggests longer duration
            else:
                estimated_duration = time_window * 0.5  # Default estimate
            
            # Onset and offset analysis
            onset_sharpness = 0.3  # Tremor typically has gradual onset
            offset_sharpness = 0.2  # Tremor typically has gradual offset
            
            return {
                'total_duration': estimated_duration,
                'estimated_ongoing_duration': estimated_duration,
                'onset_characteristics': {
                    'sharpness': onset_sharpness,
                    'type': 'gradual'
                },
                'offset_characteristics': {
                    'sharpness': offset_sharpness,
                    'type': 'gradual'
                },
                'duration_confidence': 0.7
            }
        except Exception:
            return {'total_duration': 300, 'estimated_ongoing_duration': 300}
    
    def _characterize_tremor_source(self, ensemble_analysis: Dict, processed_data: Dict, config: Dict) -> Dict:
        """Characterize tremor source"""
        try:
            tremor_type = ensemble_analysis.get('tremor_type', 'unknown')
            dominant_frequency = ensemble_analysis.get('dominant_frequency', 2.5)
            
            # Source characterization based on tremor properties
            if tremor_type == 'harmonic_tremor':
                source_type = 'resonance_cavity'
                depth_estimate = 1.0 + dominant_frequency * 0.5  # Deeper sources have lower frequencies
                mechanism = 'fluid_oscillation'
            elif tremor_type == 'spasmodic_tremor':
                source_type = 'brittle_failure'
                depth_estimate = 2.0 + dominant_frequency * 0.3
                mechanism = 'crack_opening_closing'
            else:
                source_type = 'mixed_process'
                depth_estimate = 1.5 + dominant_frequency * 0.4
                mechanism = 'fluid_brittle_interaction'
            
            # Source strength estimation
            amplitude_characteristics = ensemble_analysis.get('amplitude_characteristics', {})
            mean_amplitude = amplitude_characteristics.get('mean_amplitude', 0.0)
            source_strength = min(mean_amplitude * 1000, 1.0)  # Normalize to [0,1]
            
            return {
                'source_type': source_type,
                'source_mechanism': mechanism,
                'estimated_depth_km': depth_estimate,
                'source_strength': source_strength,
                'tremor_classification': tremor_type,
                'frequency_constraint': dominant_frequency,
                'characterization_confidence': ensemble_analysis.get('detection_confidence', 0.0) * 0.8
            }
        except Exception:
            return {'source_type': 'unknown', 'estimated_depth_km': 2.0, 'source_strength': 0.5}
    
    def _track_tremor_evolution(self, ensemble_analysis: Dict, processed_data: Dict, config: Dict) -> Dict:
        """Track tremor evolution"""
        try:
            timestamp = config.get('timestamp', 0)
            
            # Evolution metrics
            amplitude_trend = 'stable'  # Default
            frequency_trend = 'stable'
            intensity_change = 0.0
            
            # Simulate evolution tracking (in real implementation, would use historical data)
            detection_confidence = ensemble_analysis.get('detection_confidence', 0.0)
            
            if detection_confidence > 0.7:
                amplitude_trend = 'increasing'
                intensity_change = 0.1
            elif detection_confidence < 0.3:
                amplitude_trend = 'decreasing'
                intensity_change = -0.1
            
            # Predict future evolution
            future_intensity = min(max(detection_confidence + intensity_change, 0.0), 1.0)
            
            return {
                'current_intensity': detection_confidence,
                'amplitude_trend': amplitude_trend,
                'frequency_trend': frequency_trend,
                'intensity_change_rate': intensity_change,
                'predicted_intensity_1hour': future_intensity,
                'evolution_confidence': 0.6,
                'last_update': timestamp,
                'tracking_duration': config.get('time_window', 300)
            }
        except Exception:
            return {'current_intensity': 0.5, 'amplitude_trend': 'stable', 'frequency_trend': 'stable'}
    
    def _assess_tremor_hazards(self, ensemble_analysis: Dict, source_characterization: Dict, config: Dict) -> Dict:
        """Assess tremor-related hazards"""
        try:
            detection_confidence = ensemble_analysis.get('detection_confidence', 0.0)
            source_strength = source_characterization.get('source_strength', 0.5)
            tremor_type = ensemble_analysis.get('tremor_type', 'unknown')
            
            # Hazard assessment
            hazard_factors = []
            if detection_confidence > 0.7:
                hazard_factors.append('sustained_high_intensity_tremor')
            if source_strength > 0.6:
                hazard_factors.append('strong_source_mechanism')
            if tremor_type in ['harmonic_tremor', 'spasmodic_tremor']:
                hazard_factors.append('identifiable_source_process')
            
            # Overall hazard level
            if len(hazard_factors) >= 3:
                hazard_level = 'HIGH'
                eruption_likelihood = 'elevated'
            elif len(hazard_factors) >= 2:
                hazard_level = 'MODERATE'
                eruption_likelihood = 'moderate'
            elif len(hazard_factors) >= 1:
                hazard_level = 'LOW_MODERATE'
                eruption_likelihood = 'low_moderate'
            else:
                hazard_level = 'LOW'
                eruption_likelihood = 'background'
            
            # Specific hazard implications
            implications = []
            if tremor_type == 'harmonic_tremor':
                implications.append('Possible magma movement or gas accumulation')
            if tremor_type == 'spasmodic_tremor':
                implications.append('Potential conduit pressurization')
            if source_strength > 0.7:
                implications.append('Significant energy release at source')
            
            return {
                'hazard_level': hazard_level,
                'eruption_likelihood': eruption_likelihood,
                'hazard_factors': hazard_factors,
                'hazard_implications': implications,
                'monitoring_recommendation': 'enhanced' if hazard_level in ['HIGH', 'MODERATE'] else 'routine',
                'assessment_confidence': detection_confidence * 0.9
            }
        except Exception:
            return {'hazard_level': 'LOW', 'eruption_likelihood': 'background', 'hazard_factors': []}
    
    def _compute_advanced_tremor_statistics(self, ensemble_analysis: Dict, processed_data: Dict, config: Dict) -> Dict:
        """Compute advanced tremor statistics"""
        try:
            # Statistical metrics
            detection_confidence = ensemble_analysis.get('detection_confidence', 0.0)
            individual_confidences = ensemble_analysis.get('individual_confidences', [])
            
            if individual_confidences:
                confidence_mean = np.mean(individual_confidences)
                confidence_std = np.std(individual_confidences)
                confidence_skewness = self._compute_skewness(individual_confidences)
                confidence_kurtosis = self._compute_kurtosis(individual_confidences)
            else:
                confidence_mean = confidence_std = confidence_skewness = confidence_kurtosis = 0.0
            
            # Information theory metrics
            information_entropy = self._compute_information_entropy(individual_confidences) if individual_confidences else 0.0
            
            return {
                'confidence_statistics': {
                    'mean': confidence_mean,
                    'standard_deviation': confidence_std,
                    'skewness': confidence_skewness,
                    'kurtosis': confidence_kurtosis
                },
                'information_metrics': {
                    'entropy': information_entropy,
                    'information_content': -np.log2(detection_confidence) if detection_confidence > 0 else 10.0
                },
                'ensemble_metrics': {
                    'method_agreement': ensemble_analysis.get('method_consensus', 0.0),
                    'detection_reliability': ensemble_analysis.get('detection_reliability', 0.0),
                    'spatial_coverage': ensemble_analysis.get('spatial_coverage', 0.0)
                }
            }
        except Exception:
            return {'confidence_statistics': {}, 'information_metrics': {}, 'ensemble_metrics': {}}
    
    def _correlate_tremor_with_volcanic_processes(self, ensemble_analysis: Dict, processed_data: Dict, config: Dict) -> Dict:
        """Correlate tremor with volcanic processes"""
        try:
            tremor_type = ensemble_analysis.get('tremor_type', 'unknown')
            dominant_frequency = ensemble_analysis.get('dominant_frequency', 2.5)
            detection_confidence = ensemble_analysis.get('detection_confidence', 0.0)
            
            # Process correlations
            correlations = {}
            
            # Magma movement correlation
            if tremor_type == 'harmonic_tremor' and dominant_frequency < 3.0:
                correlations['magma_movement'] = {
                    'correlation_strength': 0.8,
                    'process_type': 'magma_ascent',
                    'confidence': detection_confidence * 0.8
                }
            
            # Gas dynamics correlation
            if dominant_frequency > 2.0 and detection_confidence > 0.6:
                correlations['gas_dynamics'] = {
                    'correlation_strength': 0.7,
                    'process_type': 'gas_accumulation_release',
                    'confidence': detection_confidence * 0.7
                }
            
            # Hydrothermal system correlation
            if tremor_type == 'spasmodic_tremor':
                correlations['hydrothermal_system'] = {
                    'correlation_strength': 0.6,
                    'process_type': 'fluid_circulation',
                    'confidence': detection_confidence * 0.6
                }
            
            # Overall process correlation assessment
            if correlations:
                strongest_correlation = max(correlations.values(), key=lambda x: x['correlation_strength'])
                primary_process = strongest_correlation['process_type']
                correlation_confidence = strongest_correlation['confidence']
            else:
                primary_process = 'unknown'
                correlation_confidence = 0.0
            
            return {
                'primary_process': primary_process,
                'correlation_confidence': correlation_confidence,
                'process_correlations': correlations,
                'tremor_process_link': f'tremor_indicates_{primary_process}' if primary_process != 'unknown' else 'unclear_link'
            }
        except Exception:
            return {'primary_process': 'unknown', 'correlation_confidence': 0.0, 'process_correlations': {}}
    
    def _detect_volcanic_tremor_simple(self, processed_data: Dict, config: Dict) -> Dict:
        """Simple fallback tremor detection"""
        try:
            amplitudes = []
            for station_id, station_data in processed_data.get('processed_stations', {}).items():
                if 'waveforms' in station_data and 'time_series' in station_data['waveforms']:
                    time_series = station_data['waveforms']['time_series']
                    rms_amplitude = np.sqrt(np.mean(time_series**2))
                    amplitudes.append(rms_amplitude)
            
            if amplitudes:
                mean_amplitude = np.mean(amplitudes)
                max_amplitude = np.max(amplitudes)
                detection_confidence = min(mean_amplitude * 10, 1.0)
            else:
                mean_amplitude = max_amplitude = detection_confidence = 0.0
            
            return {
                'tremor_detection': detection_confidence,
                'tremor_type': 'unknown',
                'dominant_frequency': 2.0,
                'frequency_range': [1.0, 5.0],
                'amplitude_characteristics': {
                    'mean_amplitude': mean_amplitude,
                    'max_amplitude': max_amplitude
                },
                'duration_analysis': {'total_duration': 300}
            }
        except Exception:
            return {'tremor_detection': 0.0, 'tremor_type': 'unknown', 'dominant_frequency': 2.0}
    
    # Additional helper methods for tremor statistics
    def _compute_skewness(self, data: List[float]) -> float:
        """Compute skewness of data"""
        try:
            if len(data) < 3:
                return 0.0
            mean_val = np.mean(data)
            std_val = np.std(data)
            if std_val == 0:
                return 0.0
            return np.mean(((data - mean_val) / std_val)**3)
        except Exception:
            return 0.0
    
    def _compute_kurtosis(self, data: List[float]) -> float:
        """Compute kurtosis of data"""
        try:
            if len(data) < 4:
                return 0.0
            mean_val = np.mean(data)
            std_val = np.std(data)
            if std_val == 0:
                return 0.0
            return np.mean(((data - mean_val) / std_val)**4) - 3.0  # Excess kurtosis
        except Exception:
            return 0.0
    
    def _compute_information_entropy(self, data: List[float]) -> float:
        """Compute information entropy"""
        try:
            if not data:
                return 0.0
            # Discretize data into bins for entropy calculation
            hist, _ = np.histogram(data, bins=min(10, len(data)), density=True)
            hist = hist[hist > 0]  # Remove zero probabilities
            return -np.sum(hist * np.log2(hist + 1e-10))
        except Exception:
            return 0.0
    
