    # Advanced supporting methods for tremor feature extraction
    def _analyze_tremor_duration_patterns(self, seismic_data: Dict, sample_rate: float, config: Dict) -> Dict:
        """Analyze tremor duration patterns and variability"""
        try:
            amplitude = seismic_data.get('amplitude', [])
            if not amplitude:
                return {'duration_variability': 0.0, 'mean_duration': 0.0, 'duration_distribution': 'unknown'}
            
            # Detect tremor episodes
            threshold = np.percentile(amplitude, 75)
            tremor_mask = np.array(amplitude) > threshold
            
            # Find episode durations
            episodes = []
            in_episode = False
            start_idx = 0
            
            for i, is_tremor in enumerate(tremor_mask):
                if is_tremor and not in_episode:
                    start_idx = i
                    in_episode = True
                elif not is_tremor and in_episode:
                    duration = (i - start_idx) / sample_rate
                    episodes.append(duration)
                    in_episode = False
            
            if not episodes:
                return {'duration_variability': 0.0, 'mean_duration': 0.0, 'duration_distribution': 'no_episodes'}
            
            episodes = np.array(episodes)
            
            return {
                'mean_duration': float(np.mean(episodes)),
                'duration_std': float(np.std(episodes)),
                'duration_variability': float(np.std(episodes) / np.mean(episodes)) if np.mean(episodes) > 0 else 0.0,
                'duration_range': float(np.max(episodes) - np.min(episodes)),
                'duration_distribution': 'log_normal' if len(episodes) > 5 else 'insufficient_data',
                'num_episodes': len(episodes)
            }
            
        except Exception:
            return {'duration_variability': 0.0, 'mean_duration': 0.0, 'duration_distribution': 'error'}
    
    def _analyze_tremor_onset_offset(self, seismic_data: Dict, sample_rate: float, config: Dict) -> Dict:
        """Analyze tremor onset and offset characteristics"""
        try:
            amplitude = seismic_data.get('amplitude', [])
            if len(amplitude) < 100:
                return {'onset_rate': 0.0, 'offset_rate': 0.0, 'onset_sharpness': 0.0}
            
            # Calculate envelope
            envelope = np.abs(amplitude)
            
            # Smooth envelope for better onset/offset detection
            window_size = max(1, int(sample_rate * 0.1))  # 0.1 second window
            if len(envelope) > window_size:
                smoothed_envelope = np.convolve(envelope, np.ones(window_size)/window_size, mode='same')
            else:
                smoothed_envelope = envelope
            
            # Find onsets and offsets
            threshold = np.percentile(smoothed_envelope, 70)
            gradient = np.gradient(smoothed_envelope)
            
            # Onset detection (positive gradients above threshold)
            onset_candidates = np.where((gradient > 0) & (smoothed_envelope > threshold))[0]
            offset_candidates = np.where((gradient < 0) & (smoothed_envelope > threshold))[0]
            
            # Calculate rates
            onset_rate = len(onset_candidates) / len(gradient) * sample_rate if len(gradient) > 0 else 0.0
            offset_rate = len(offset_candidates) / len(gradient) * sample_rate if len(gradient) > 0 else 0.0
            
            # Calculate onset sharpness
            onset_sharpness = np.mean(np.abs(gradient[onset_candidates])) if len(onset_candidates) > 0 else 0.0
            
            return {
                'onset_rate': float(onset_rate),
                'offset_rate': float(offset_rate),
                'onset_sharpness': float(onset_sharpness),
                'onset_offset_ratio': float(onset_rate / offset_rate) if offset_rate > 0 else 0.0,
                'num_onsets': len(onset_candidates),
                'num_offsets': len(offset_candidates)
            }
            
        except Exception:
            return {'onset_rate': 0.0, 'offset_rate': 0.0, 'onset_sharpness': 0.0}
    
    def _analyze_tremor_temporal_evolution(self, seismic_data: Dict, sample_rate: float, config: Dict) -> Dict:
        """Analyze temporal evolution patterns in tremor"""
        try:
            amplitude = seismic_data.get('amplitude', [])
            if len(amplitude) < 50:
                return {'evolution_trend': 'insufficient_data', 'evolution_rate': 0.0}
            
            # Divide signal into temporal segments
            n_segments = min(10, len(amplitude) // 20)
            segment_size = len(amplitude) // n_segments
            
            segment_energies = []
            for i in range(n_segments):
                start_idx = i * segment_size
                end_idx = (i + 1) * segment_size
                segment = amplitude[start_idx:end_idx]
                energy = np.sum(np.array(segment) ** 2)
                segment_energies.append(energy)
            
            # Analyze evolution trend
            if len(segment_energies) > 2:
                correlation = np.corrcoef(range(len(segment_energies)), segment_energies)[0, 1]
                evolution_rate = np.gradient(segment_energies).mean()
                
                if correlation > 0.5:
                    trend = 'increasing'
                elif correlation < -0.5:
                    trend = 'decreasing'
                else:
                    trend = 'stable'
            else:
                trend = 'insufficient_data'
                correlation = 0.0
                evolution_rate = 0.0
            
            return {
                'evolution_trend': trend,
                'evolution_rate': float(evolution_rate),
                'trend_correlation': float(correlation),
                'segment_energies': segment_energies,
                'energy_variability': float(np.std(segment_energies) / np.mean(segment_energies)) if np.mean(segment_energies) > 0 else 0.0
            }
            
        except Exception:
            return {'evolution_trend': 'error', 'evolution_rate': 0.0}
    
    def _analyze_tremor_periodicity(self, seismic_data: Dict, sample_rate: float, config: Dict) -> Dict:
        """Analyze periodicity and cyclicity in tremor"""
        try:
            amplitude = seismic_data.get('amplitude', [])
            if len(amplitude) < 100:
                return {'dominant_period': 0.0, 'periodicity_strength': 0.0}
            
            # Calculate autocorrelation
            signal = np.array(amplitude)
            signal = signal - np.mean(signal)
            
            # FFT-based autocorrelation
            fft_signal = np.fft.fft(signal, n=2*len(signal))
            autocorr = np.fft.ifft(fft_signal * np.conj(fft_signal)).real
            autocorr = autocorr[:len(signal)]
            autocorr = autocorr / autocorr[0]  # Normalize
            
            # Find dominant periods
            lags = np.arange(len(autocorr)) / sample_rate
            
            # Exclude zero lag and find peaks
            min_period = 1.0  # Minimum 1 second period
            min_lag_idx = int(min_period * sample_rate)
            
            if len(autocorr) > min_lag_idx:
                autocorr_subset = autocorr[min_lag_idx:]
                peaks = np.where(autocorr_subset > 0.3)[0]  # Significant peaks
                
                if len(peaks) > 0:
                    dominant_peak = peaks[np.argmax(autocorr_subset[peaks])]
                    dominant_period = (dominant_peak + min_lag_idx) / sample_rate
                    periodicity_strength = autocorr_subset[dominant_peak]
                else:
                    dominant_period = 0.0
                    periodicity_strength = 0.0
            else:
                dominant_period = 0.0
                periodicity_strength = 0.0
            
            return {
                'dominant_period': float(dominant_period),
                'periodicity_strength': float(periodicity_strength),
                'autocorr_decay_rate': float(np.mean(np.gradient(autocorr[:len(autocorr)//4]))),
                'cyclicity_index': float(periodicity_strength * (1.0 / (dominant_period + 1e-6)))
            }
            
        except Exception:
            return {'dominant_period': 0.0, 'periodicity_strength': 0.0}
    
    def _analyze_tremor_bursts_gaps(self, seismic_data: Dict, sample_rate: float, config: Dict) -> Dict:
        """Analyze burst and gap patterns in tremor"""
        try:
            amplitude = seismic_data.get('amplitude', [])
            if len(amplitude) < 50:
                return {'burst_rate': 0.0, 'gap_rate': 0.0, 'burst_gap_ratio': 0.0}
            
            # Define burst and gap thresholds
            high_threshold = np.percentile(amplitude, 80)
            low_threshold = np.percentile(amplitude, 20)
            
            # Identify bursts and gaps
            burst_mask = np.array(amplitude) > high_threshold
            gap_mask = np.array(amplitude) < low_threshold
            
            # Count transitions
            burst_transitions = np.sum(np.diff(burst_mask.astype(int)) == 1)
            gap_transitions = np.sum(np.diff(gap_mask.astype(int)) == 1)
            
            # Calculate rates (per second)
            total_time = len(amplitude) / sample_rate
            burst_rate = burst_transitions / total_time if total_time > 0 else 0.0
            gap_rate = gap_transitions / total_time if total_time > 0 else 0.0
            
            # Calculate burst and gap durations
            burst_durations = self._calculate_state_durations(burst_mask, sample_rate)
            gap_durations = self._calculate_state_durations(gap_mask, sample_rate)
            
            return {
                'burst_rate': float(burst_rate),
                'gap_rate': float(gap_rate),
                'burst_gap_ratio': float(burst_rate / gap_rate) if gap_rate > 0 else float('inf'),
                'mean_burst_duration': float(np.mean(burst_durations)) if burst_durations else 0.0,
                'mean_gap_duration': float(np.mean(gap_durations)) if gap_durations else 0.0,
                'burst_intensity': float(np.sum(burst_mask) / len(burst_mask)),
                'gap_intensity': float(np.sum(gap_mask) / len(gap_mask))
            }
            
        except Exception:
            return {'burst_rate': 0.0, 'gap_rate': 0.0, 'burst_gap_ratio': 0.0}
    
    def _analyze_tremor_temporal_stability(self, seismic_data: Dict, sample_rate: float, config: Dict) -> Dict:
        """Analyze temporal stability of tremor characteristics"""
        try:
            amplitude = seismic_data.get('amplitude', [])
            if len(amplitude) < 100:
                return {'stability_index': 0.0, 'temporal_coherence': 0.0}
            
            # Divide into overlapping windows
            window_size = int(sample_rate * 10)  # 10-second windows
            overlap = window_size // 2
            
            if len(amplitude) < window_size:
                return {'stability_index': 0.0, 'temporal_coherence': 0.0}
            
            window_features = []
            for i in range(0, len(amplitude) - window_size + 1, overlap):
                window = amplitude[i:i + window_size]
                
                # Calculate features for each window
                features = {
                    'rms': np.sqrt(np.mean(np.array(window) ** 2)),
                    'peak': np.max(np.abs(window)),
                    'mean_freq': self._estimate_mean_frequency(window, sample_rate)
                }
                window_features.append(features)
            
            if len(window_features) < 2:
                return {'stability_index': 0.0, 'temporal_coherence': 0.0}
            
            # Calculate stability metrics
            rms_values = [f['rms'] for f in window_features]
            peak_values = [f['peak'] for f in window_features]
            freq_values = [f['mean_freq'] for f in window_features]
            
            # Stability index (inverse of coefficient of variation)
            rms_stability = 1.0 / (np.std(rms_values) / np.mean(rms_values) + 1e-6) if np.mean(rms_values) > 0 else 0.0
            peak_stability = 1.0 / (np.std(peak_values) / np.mean(peak_values) + 1e-6) if np.mean(peak_values) > 0 else 0.0
            freq_stability = 1.0 / (np.std(freq_values) / np.mean(freq_values) + 1e-6) if np.mean(freq_values) > 0 else 0.0
            
            stability_index = (rms_stability + peak_stability + freq_stability) / 3.0
            
            # Temporal coherence (cross-correlation between adjacent windows)
            coherences = []
            for i in range(len(window_features) - 1):
                w1 = amplitude[i*overlap:i*overlap + window_size]
                w2 = amplitude[(i+1)*overlap:(i+1)*overlap + window_size]
                
                if len(w1) == len(w2) and len(w1) > 0:
                    correlation = np.corrcoef(w1, w2)[0, 1]
                    if not np.isnan(correlation):
                        coherences.append(abs(correlation))
            
            temporal_coherence = np.mean(coherences) if coherences else 0.0
            
            return {
                'stability_index': float(min(stability_index, 10.0)),  # Cap at reasonable value
                'temporal_coherence': float(temporal_coherence),
                'rms_stability': float(min(rms_stability, 10.0)),
                'peak_stability': float(min(peak_stability, 10.0)),
                'frequency_stability': float(min(freq_stability, 10.0))
            }
            
        except Exception:
            return {'stability_index': 0.0, 'temporal_coherence': 0.0}
    
    def _analyze_tremor_rate_features(self, seismic_data: Dict, sample_rate: float, config: Dict) -> Dict:
        """Analyze rate-based temporal features"""
        try:
            amplitude = seismic_data.get('amplitude', [])
            if len(amplitude) < 50:
                return {'event_rate': 0.0, 'activity_rate': 0.0}
            
            # Calculate derivatives for rate analysis
            signal = np.array(amplitude)
            velocity = np.gradient(signal) * sample_rate
            acceleration = np.gradient(velocity) * sample_rate
            
            # Event detection based on signal changes
            threshold = np.std(signal) * 2
            events = np.where(np.abs(velocity) > threshold)[0]
            
            total_time = len(amplitude) / sample_rate
            event_rate = len(events) / total_time if total_time > 0 else 0.0
            
            # Activity rate (proportion of time with significant activity)
            activity_threshold = np.percentile(np.abs(signal), 75)
            active_samples = np.sum(np.abs(signal) > activity_threshold)
            activity_rate = active_samples / len(signal)
            
            # Rate variability
            window_size = max(1, int(sample_rate * 5))  # 5-second windows
            n_windows = len(amplitude) // window_size
            
            window_rates = []
            for i in range(n_windows):
                start_idx = i * window_size
                end_idx = (i + 1) * window_size
                window_signal = signal[start_idx:end_idx]
                window_events = np.sum(np.abs(np.gradient(window_signal)) > threshold)
                window_rates.append(window_events / (window_size / sample_rate))
            
            rate_variability = np.std(window_rates) / np.mean(window_rates) if np.mean(window_rates) > 0 else 0.0
            
            return {
                'event_rate': float(event_rate),
                'activity_rate': float(activity_rate),
                'rate_variability': float(rate_variability),
                'mean_velocity': float(np.mean(np.abs(velocity))),
                'mean_acceleration': float(np.mean(np.abs(acceleration))),
                'velocity_stability': float(1.0 / (np.std(velocity) / np.mean(np.abs(velocity)) + 1e-6))
            }
            
        except Exception:
            return {'event_rate': 0.0, 'activity_rate': 0.0}
    
    # Advanced supporting methods for spectral tremor analysis
    def _multitaper_tremor_spectral_analysis(self, seismic_data: Dict, sample_rate: float, config: Dict) -> Dict:
        """Multi-taper spectral analysis for tremor"""
        try:
            amplitude = seismic_data.get('amplitude', [])
            if len(amplitude) < 100:
                return {'spectral_centroid': 0.0, 'spectral_bandwidth': 0.0}
            
            # Simple spectral analysis (fallback for multitaper)
            fft_result = np.fft.fft(amplitude)
            frequencies = np.fft.fftfreq(len(amplitude), 1/sample_rate)
            power_spectrum = np.abs(fft_result) ** 2
            
            # Positive frequencies only
            pos_freq_mask = frequencies >= 0
            frequencies = frequencies[pos_freq_mask]
            power_spectrum = power_spectrum[pos_freq_mask]
            
            # Spectral centroid
            if np.sum(power_spectrum) > 0:
                spectral_centroid = np.sum(frequencies * power_spectrum) / np.sum(power_spectrum)
            else:
                spectral_centroid = 0.0
            
            # Spectral bandwidth
            if spectral_centroid > 0:
                spectral_bandwidth = np.sqrt(np.sum(((frequencies - spectral_centroid) ** 2) * power_spectrum) / np.sum(power_spectrum))
            else:
                spectral_bandwidth = 0.0
            
            return {
                'spectral_centroid': float(spectral_centroid),
                'spectral_bandwidth': float(spectral_bandwidth),
                'dominant_frequency': float(frequencies[np.argmax(power_spectrum)]) if len(power_spectrum) > 0 else 0.0,
                'spectral_peak_power': float(np.max(power_spectrum)) if len(power_spectrum) > 0 else 0.0
            }
            
        except Exception:
            return {'spectral_centroid': 0.0, 'spectral_bandwidth': 0.0}
    
    def _analyze_tremor_timefreq_evolution(self, seismic_data: Dict, sample_rate: float, config: Dict) -> Dict:
        """Analyze time-frequency evolution of tremor"""
        try:
            amplitude = seismic_data.get('amplitude', [])
            if len(amplitude) < 200:
                return {'frequency_drift': 0.0, 'spectral_stability': 0.0}
            
            # Simple time-frequency analysis using sliding window FFT
            window_size = min(128, len(amplitude) // 4)
            hop_size = window_size // 2
            
            spectrograms = []
            for i in range(0, len(amplitude) - window_size + 1, hop_size):
                window = amplitude[i:i + window_size]
                fft_result = np.abs(np.fft.fft(window))
                spectrograms.append(fft_result[:window_size//2])
            
            if len(spectrograms) < 2:
                return {'frequency_drift': 0.0, 'spectral_stability': 0.0}
            
            spectrograms = np.array(spectrograms)
            
            # Calculate frequency drift
            peak_frequencies = []
            for spectrum in spectrograms:
                if np.max(spectrum) > 0:
                    peak_freq_idx = np.argmax(spectrum)
                    peak_frequencies.append(peak_freq_idx * sample_rate / (2 * window_size))
                else:
                    peak_frequencies.append(0.0)
            
            frequency_drift = np.gradient(peak_frequencies).mean() if len(peak_frequencies) > 1 else 0.0
            
            # Spectral stability
            spectral_correlations = []
            for i in range(len(spectrograms) - 1):
                correlation = np.corrcoef(spectrograms[i], spectrograms[i+1])[0, 1]
                if not np.isnan(correlation):
                    spectral_correlations.append(correlation)
            
            spectral_stability = np.mean(spectral_correlations) if spectral_correlations else 0.0
            
            return {
                'frequency_drift': float(frequency_drift),
                'spectral_stability': float(spectral_stability),
                'frequency_variability': float(np.std(peak_frequencies)) if len(peak_frequencies) > 0 else 0.0,
                'spectral_evolution_rate': float(np.mean(np.abs(np.gradient(peak_frequencies)))) if len(peak_frequencies) > 1 else 0.0
            }
            
        except Exception:
            return {'frequency_drift': 0.0, 'spectral_stability': 0.0}
    
    def _analyze_tremor_spectral_peaks(self, seismic_data: Dict, sample_rate: float, config: Dict) -> Dict:
        """Analyze spectral peaks in tremor"""
        try:
            amplitude = seismic_data.get('amplitude', [])
            if len(amplitude) < 100:
                return {'num_peaks': 0, 'peak_sharpness': 0.0}
            
            # FFT analysis
            fft_result = np.fft.fft(amplitude)
            frequencies = np.fft.fftfreq(len(amplitude), 1/sample_rate)
            power_spectrum = np.abs(fft_result) ** 2
            
            # Positive frequencies only
            pos_freq_mask = frequencies >= 0
            frequencies = frequencies[pos_freq_mask]
            power_spectrum = power_spectrum[pos_freq_mask]
            
            # Find peaks
            if len(power_spectrum) < 3:
                return {'num_peaks': 0, 'peak_sharpness': 0.0}
            
            # Simple peak detection
            threshold = np.percentile(power_spectrum, 90)
            peaks = []
            
            for i in range(1, len(power_spectrum) - 1):
                if (power_spectrum[i] > power_spectrum[i-1] and 
                    power_spectrum[i] > power_spectrum[i+1] and 
                    power_spectrum[i] > threshold):
                    peaks.append(i)
            
            # Calculate peak sharpness
            peak_sharpness = 0.0
            if len(peaks) > 0:
                sharpness_values = []
                for peak_idx in peaks:
                    if peak_idx > 1 and peak_idx < len(power_spectrum) - 2:
                        # Calculate local sharpness
                        peak_val = power_spectrum[peak_idx]
                        left_val = power_spectrum[peak_idx - 1]
                        right_val = power_spectrum[peak_idx + 1]
                        local_sharpness = peak_val / (0.5 * (left_val + right_val) + 1e-10)
                        sharpness_values.append(local_sharpness)
                
                peak_sharpness = np.mean(sharpness_values) if sharpness_values else 0.0
            
            return {
                'num_peaks': len(peaks),
                'peak_sharpness': float(peak_sharpness),
                'peak_frequencies': [float(frequencies[i]) for i in peaks][:5],  # Top 5 peaks
                'peak_powers': [float(power_spectrum[i]) for i in peaks][:5]
            }
            
        except Exception:
            return {'num_peaks': 0, 'peak_sharpness': 0.0}
    
    def _analyze_tremor_harmonic_content(self, seismic_data: Dict, sample_rate: float, config: Dict) -> Dict:
        """Analyze harmonic content in tremor"""
        try:
            amplitude = seismic_data.get('amplitude', [])
            if len(amplitude) < 200:
                return {'harmonic_ratio': 0.0, 'fundamental_frequency': 0.0}
            
            # FFT analysis
            fft_result = np.fft.fft(amplitude)
            frequencies = np.fft.fftfreq(len(amplitude), 1/sample_rate)
            power_spectrum = np.abs(fft_result) ** 2
            
            # Positive frequencies only
            pos_freq_mask = frequencies > 0
            frequencies = frequencies[pos_freq_mask]
            power_spectrum = power_spectrum[pos_freq_mask]
            
            # Find fundamental frequency
            if len(power_spectrum) == 0:
                return {'harmonic_ratio': 0.0, 'fundamental_frequency': 0.0}
            
            fundamental_idx = np.argmax(power_spectrum)
            fundamental_frequency = frequencies[fundamental_idx]
            
            # Look for harmonics
            harmonic_power = power_spectrum[fundamental_idx]
            total_power = np.sum(power_spectrum)
            
            # Check for 2nd and 3rd harmonics
            harmonic_frequencies = [2 * fundamental_frequency, 3 * fundamental_frequency]
            for harm_freq in harmonic_frequencies:
                # Find closest frequency bin
                freq_diff = np.abs(frequencies - harm_freq)
                if len(freq_diff) > 0:
                    closest_idx = np.argmin(freq_diff)
                    if freq_diff[closest_idx] < sample_rate / len(amplitude):  # Within one frequency bin
                        harmonic_power += power_spectrum[closest_idx]
            
            harmonic_ratio = harmonic_power / total_power if total_power > 0 else 0.0
            
            return {
                'harmonic_ratio': float(harmonic_ratio),
                'fundamental_frequency': float(fundamental_frequency),
                'harmonic_strength': float(harmonic_power),
                'total_spectral_power': float(total_power)
            }
            
        except Exception:
            return {'harmonic_ratio': 0.0, 'fundamental_frequency': 0.0}
    
    # Advanced supporting methods for amplitude tremor analysis  
    def _analyze_tremor_amplitude_modulation(self, seismic_data: Dict, sample_rate: float, config: Dict) -> Dict:
        """Analyze amplitude modulation in tremor"""
        try:
            amplitude = seismic_data.get('amplitude', [])
            if len(amplitude) < 100:
                return {'modulation_depth': 0.0, 'modulation_frequency': 0.0}
            
            # Calculate envelope using Hilbert transform approximation
            signal = np.array(amplitude)
            envelope = np.abs(signal)
            
            # Smooth envelope
            window_size = max(1, int(sample_rate * 0.1))
            if len(envelope) > window_size:
                smoothed_envelope = np.convolve(envelope, np.ones(window_size)/window_size, mode='same')
            else:
                smoothed_envelope = envelope
            
            # Calculate modulation depth
            if np.mean(smoothed_envelope) > 0:
                modulation_depth = np.std(smoothed_envelope) / np.mean(smoothed_envelope)
            else:
                modulation_depth = 0.0
            
            # Find modulation frequency
            if len(smoothed_envelope) > 10:
                envelope_fft = np.fft.fft(smoothed_envelope - np.mean(smoothed_envelope))
                envelope_freqs = np.fft.fftfreq(len(smoothed_envelope), 1/sample_rate)
                envelope_power = np.abs(envelope_fft) ** 2
                
                # Look at positive frequencies only
                pos_mask = envelope_freqs > 0
                if np.any(pos_mask):
                    envelope_freqs = envelope_freqs[pos_mask]
                    envelope_power = envelope_power[pos_mask]
                    
                    if len(envelope_power) > 0:
                        modulation_frequency = envelope_freqs[np.argmax(envelope_power)]
                    else:
                        modulation_frequency = 0.0
                else:
                    modulation_frequency = 0.0
            else:
                modulation_frequency = 0.0
            
            return {
                'modulation_depth': float(modulation_depth),
                'modulation_frequency': float(modulation_frequency),
                'envelope_variability': float(np.std(smoothed_envelope)),
                'amplitude_stability': float(1.0 / (modulation_depth + 1e-6))
            }
            
        except Exception:
            return {'modulation_depth': 0.0, 'modulation_frequency': 0.0}
    
    def _analyze_tremor_amplitude_envelope(self, seismic_data: Dict, sample_rate: float, config: Dict) -> Dict:
        """Analyze amplitude envelope characteristics"""
        try:
            amplitude = seismic_data.get('amplitude', [])
            if len(amplitude) < 50:
                return {'envelope_shape': 'unknown', 'envelope_skewness': 0.0}
            
            # Calculate envelope
            envelope = np.abs(amplitude)
            
            # Envelope statistics
            envelope_mean = np.mean(envelope)
            envelope_std = np.std(envelope)
            envelope_skewness = self._calculate_skewness(envelope)
            envelope_kurtosis = self._calculate_kurtosis(envelope)
            
            # Envelope shape classification
            if envelope_skewness > 0.5:
                envelope_shape = 'right_skewed'
            elif envelope_skewness < -0.5:
                envelope_shape = 'left_skewed'
            else:
                envelope_shape = 'symmetric'
            
            # Envelope dynamics
            envelope_gradient = np.gradient(envelope)
            envelope_curvature = np.gradient(envelope_gradient)
            
            return {
                'envelope_shape': envelope_shape,
                'envelope_skewness': float(envelope_skewness),
                'envelope_kurtosis': float(envelope_kurtosis),
                'envelope_mean': float(envelope_mean),
                'envelope_std': float(envelope_std),
                'envelope_gradient_mean': float(np.mean(np.abs(envelope_gradient))),
                'envelope_curvature_mean': float(np.mean(np.abs(envelope_curvature)))
            }
            
        except Exception:
            return {'envelope_shape': 'unknown', 'envelope_skewness': 0.0}
    
    def _analyze_tremor_amplitude_dynamics(self, seismic_data: Dict, sample_rate: float, config: Dict) -> Dict:
        """Analyze amplitude dynamics and range"""
        try:
            amplitude = seismic_data.get('amplitude', [])
            if len(amplitude) < 10:
                return {'dynamic_range': 0.0, 'amplitude_stability': 0.0}
            
            amplitude_array = np.array(amplitude)
            
            # Dynamic range
            max_amplitude = np.max(np.abs(amplitude_array))
            min_amplitude = np.min(np.abs(amplitude_array))
            dynamic_range = 20 * np.log10(max_amplitude / (min_amplitude + 1e-10))  # dB
            
            # Amplitude stability
            rms_amplitude = np.sqrt(np.mean(amplitude_array ** 2))
            amplitude_std = np.std(np.abs(amplitude_array))
            amplitude_stability = 1.0 / (amplitude_std / rms_amplitude + 1e-6) if rms_amplitude > 0 else 0.0
            
            # Amplitude distribution percentiles
            amplitude_abs = np.abs(amplitude_array)
            percentiles = np.percentile(amplitude_abs, [25, 50, 75, 90, 95])
            
            return {
                'dynamic_range': float(min(dynamic_range, 120.0)),  # Cap at reasonable dB value
                'amplitude_stability': float(min(amplitude_stability, 10.0)),
                'rms_amplitude': float(rms_amplitude),
                'peak_amplitude': float(max_amplitude),
                'amplitude_percentiles': {
                    'p25': float(percentiles[0]),
                    'p50': float(percentiles[1]),
                    'p75': float(percentiles[2]),
                    'p90': float(percentiles[3]),
                    'p95': float(percentiles[4])
                }
            }
            
        except Exception:
            return {'dynamic_range': 0.0, 'amplitude_stability': 0.0}
    
    # Helper methods for tremor analysis
    def _calculate_state_durations(self, state_mask: np.ndarray, sample_rate: float) -> List[float]:
        """Calculate durations of continuous states"""
        try:
            durations = []
            in_state = False
            start_idx = 0
            
            for i, is_active in enumerate(state_mask):
                if is_active and not in_state:
                    start_idx = i
                    in_state = True
                elif not is_active and in_state:
                    duration = (i - start_idx) / sample_rate
                    durations.append(duration)
                    in_state = False
            
            # Handle case where signal ends in active state
            if in_state:
                duration = (len(state_mask) - start_idx) / sample_rate
                durations.append(duration)
            
            return durations
            
        except Exception:
            return []
    
    def _estimate_mean_frequency(self, signal: List, sample_rate: float) -> float:
        """Estimate mean frequency of signal"""
        try:
            if len(signal) < 10:
                return 0.0
            
            # Simple zero-crossing rate as frequency estimate
            signal_array = np.array(signal)
            signal_array = signal_array - np.mean(signal_array)
            
            zero_crossings = np.where(np.diff(np.signbit(signal_array)))[0]
            zero_crossing_rate = len(zero_crossings) / (2.0 * len(signal) / sample_rate)
            
            return float(zero_crossing_rate)
            
        except Exception:
            return 0.0
    
    def _calculate_skewness(self, data: np.ndarray) -> float:
        """Calculate skewness of data"""
        try:
            if len(data) < 3:
                return 0.0
            
            mean_val = np.mean(data)
            std_val = np.std(data)
            
            if std_val == 0:
                return 0.0
            
            skewness = np.mean(((data - mean_val) / std_val) ** 3)
            return float(skewness)
            
        except Exception:
            return 0.0
    
    def _calculate_kurtosis(self, data: np.ndarray) -> float:
        """Calculate kurtosis of data"""
        try:
            if len(data) < 4:
                return 0.0
            
            mean_val = np.mean(data)
            std_val = np.std(data)
            
            if std_val == 0:
                return 0.0
            
            kurtosis = np.mean(((data - mean_val) / std_val) ** 4) - 3.0  # Excess kurtosis
            return float(kurtosis)
            
        except Exception:
            return 0.0
    
