@app.post("/api/v1/volcanic/multi-chamber/simulate")
async def run_simulation(params: SimulationParameters):
    """
    Run multi-chamber volcanic system simulation
    """
    try:
        # Check if advanced thermodynamics is requested
        use_advanced = params.physics.get('use_advanced_thermodynamics', True)
        
        if use_advanced and simulator.advanced_thermodynamics_enabled:
            # Run advanced simulation with thermodynamic integration
            results, ml_predictions = simulator.simulate_with_advanced_thermodynamics(params)
        else:
            # Run basic simulation
            results, ml_predictions = simulator.simulate(params)
        
        # Generate simulation ID
        simulation_id = f"sim_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
        
        return {
            "simulation_id": simulation_id,
            "results": results,
            "ml_predictions": ml_predictions,
            "advanced_features_used": use_advanced and simulator.advanced_thermodynamics_enabled,
            "status": "completed"
        }
        
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.post("/api/v1/volcanic/multi-chamber/thermodynamic-analysis")
async def run_thermodynamic_analysis(chambers: List[MagmaChamber]):
    """
    Run detailed thermodynamic analysis for chamber system
    """
    try:
        if not simulator.advanced_thermodynamics_enabled:
            raise HTTPException(
                status_code=501, 
                detail="Advanced thermodynamic analysis not available. Thermodynamic engine modules required."
            )
        
        analysis_results = {}
        
        for chamber in chambers:
            # Individual chamber thermodynamics
            chamber_analysis = simulator.physics.calculate_chamber_thermodynamics(chamber)
            
            # Integration with magmatic system modeling
            if simulator.physics.thermo_integrator:
                magmatic_data = {
                    'melt_composition': simulator.physics._convert_chamber_composition(chamber.composition),
                    'temperature': chamber.temperature + 273.15,  # Convert to Kelvin
                    'pressure': chamber.pressure * 10  # Convert to bar
                }
                
                magmatic_integration = simulator.physics.thermo_integrator.integrate_with_magmatic_system(magmatic_data)
                chamber_analysis['magmatic_integration'] = magmatic_integration
                
                # Integration with hydrothermal system modeling
                hydrothermal_data = {
                    'fluid_composition': simulator.physics._convert_chamber_composition(chamber.composition),
                    'temperature': chamber.temperature + 273.15,
                    'pressure': chamber.pressure * 10
                }
                
                hydrothermal_integration = simulator.physics.thermo_integrator.integrate_with_hydrothermal_system(hydrothermal_data)
                chamber_analysis['hydrothermal_integration'] = hydrothermal_integration
            
            analysis_results[chamber.id] = chamber_analysis
        
        # Calculate inter-chamber thermodynamic interactions if multiple chambers
        if len(chambers) > 1:
            # Create dummy connections for analysis
            connections = []
            for i in range(len(chambers) - 1):
                connections.append(ChamberConnection(
                    from_chamber=chambers[i].id,
                    to_chamber=chambers[i+1].id,
                    conductivity=1e-6  # Default conductivity
                ))
            
            interaction_analysis = simulator.physics.calculate_chamber_interactions(chambers, connections)
            analysis_results['inter_chamber_interactions'] = interaction_analysis
        
        return {
            "analysis_id": f"thermo_{datetime.now().strftime('%Y%m%d_%H%M%S')}",
            "thermodynamic_analysis": analysis_results,
            "analysis_type": "comprehensive_thermodynamic",
            "status": "completed"
        }
        
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.post("/api/v1/volcanic/multi-chamber/phase-equilibrium")
async def calculate_phase_equilibrium(chamber: MagmaChamber, 
                                    temperature_range: Optional[Dict[str, float]] = None,
                                    pressure_range: Optional[Dict[str, float]] = None):
    """
    Calculate phase equilibrium diagrams for chamber compositions
    """
    try:
        if not simulator.advanced_thermodynamics_enabled:
            raise HTTPException(
                status_code=501, 
                detail="Phase equilibrium calculation not available. Thermodynamic engine modules required."
            )
        
        composition = simulator.physics._convert_chamber_composition(chamber.composition)
        
        results = {}
        
        # Single point equilibrium
        single_point = simulator.physics.thermo_engine.solve_multicomponent_equilibrium(
            composition, chamber.temperature + 273.15, chamber.pressure * 10
        )
        results['single_point_equilibrium'] = single_point
        
        # P-T diagram if ranges provided
        if temperature_range and pressure_range:
            t_range = (temperature_range['min'] + 273.15, temperature_range['max'] + 273.15)
            p_range = (pressure_range['min'] * 10, pressure_range['max'] * 10)
            
            pt_diagram = simulator.physics.thermo_engine.generate_pt_diagram(
                composition, t_range, p_range
            )
            results['pt_diagram'] = pt_diagram
        
        # Crystallization path
        if hasattr(simulator.physics.thermo_engine, 'calculate_reaction_path'):
            crystalline_assemblage = simulator.physics._get_crystalline_assemblage(composition)
            crystal_path = simulator.physics.thermo_engine.calculate_reaction_path(
                composition, crystalline_assemblage, 
                chamber.temperature + 273.15, chamber.pressure * 10
            )
            results['crystallization_path'] = crystal_path
        
        return {
            "equilibrium_id": f"eq_{datetime.now().strftime('%Y%m%d_%H%M%S')}",
            "chamber_id": chamber.id,
            "phase_equilibrium_results": results,
            "status": "completed"
        }
        
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.websocket("/ws/volcanic-monitoring")
async def websocket_monitoring(websocket: WebSocket):
    """
    WebSocket endpoint for real-time monitoring
    """
    await websocket.accept()
    active_connections.append(websocket)
    
    try:
        while True:
            # Receive messages from client
            data = await websocket.receive_text()
            message = json.loads(data)
            
            if message['type'] == 'subscribe':
                # Handle subscription to specific topics
                await websocket.send_text(json.dumps({
                    "type": "subscription_confirmed",
                    "topics": message['topics']
                }))
                
                # Start sending real-time updates
                asyncio.create_task(send_monitoring_updates(websocket, message['topics']))
                
    except WebSocketDisconnect:
        active_connections.remove(websocket)
    except Exception as e:
        print(f"WebSocket error: {e}")
        if websocket in active_connections:
            active_connections.remove(websocket)

async def send_monitoring_updates(websocket: WebSocket, topics: List[str]):
    """
    Send real-time monitoring updates to connected clients
    """
    while websocket in active_connections:
        try:
            # Generate mock real-time data
            for topic in topics:
                if topic == 'chamber_pressure':
                    update = {
                        "type": "chamber_pressure",
                        "chamber_id": np.random.choice(['upper', 'middle', 'lower']),
                        "pressure": np.random.normal(250, 50),
                        "timestamp": datetime.now().isoformat()
                    }
                elif topic == 'temperature':
                    update = {
                        "type": "temperature",
                        "chamber_id": np.random.choice(['upper', 'middle', 'lower']),
                        "temperature": np.random.normal(950, 100),
                        "timestamp": datetime.now().isoformat()
                    }
                elif topic == 'seismic':
                    update = {
                        "type": "seismic",
                        "magnitude": np.random.exponential(0.5),
                        "depth": np.random.normal(5000, 2000),
                        "timestamp": datetime.now().isoformat()
                    }
                else:
                    continue
                    
                await websocket.send_text(json.dumps(update))
                
            # Send updates every 5 seconds
            await asyncio.sleep(5)
            
        except Exception as e:
            print(f"Error sending updates: {e}")
            break

    # ============================================================================
    # Helper Functions for Advanced Gas Analysis
    # ============================================================================
    
    def _compute_thermodynamic_equilibrium(self, h2o: float, co2: float, so2: float, h2s: float, 
                                         temp: float, pressure: float) -> Dict:
        """Compute thermodynamic equilibrium properties"""
        try:
            # Simplified equilibrium calculations
            k_h2o = np.exp(-4000/temp + 10)  # Simplified equilibrium constant
            k_co2 = np.exp(-3500/temp + 8)
            k_so2 = np.exp(-5000/temp + 12)
            
            # Gas density using ideal gas law with corrections
            R = 8.314  # J/mol/K
            total_moles = h2o/18 + co2/44 + so2/64 + h2s/34
            density = (pressure * total_moles) / (R * temp) if total_moles > 0 else 1.0
            
            # Compressibility factor (simplified)
            z_factor = 1.0 - 0.001 * pressure / 1e6  # Simple correction
            
            # Heat capacity (simplified)
            cp = 1000 + 0.5 * temp  # J/kg/K
            
            return {
                'k_h2o': k_h2o,
                'k_co2': k_co2,
                'k_so2': k_so2,
                'gas_density': density,
                'compressibility_factor': z_factor,
                'heat_capacity': cp,
                'deviation_from_equilibrium': abs(k_h2o - k_co2) / max(k_h2o, k_co2)
            }
        except:
            return {
                'k_h2o': 1.5, 'k_co2': 1.2, 'k_so2': 0.8,
                'gas_density': 2.5, 'compressibility_factor': 0.95,
                'heat_capacity': 1200, 'deviation_from_equilibrium': 0.2
            }
    
    def _compute_gas_speciation(self, h2o: float, co2: float, so2: float, h2s: float,
                              temp: float, pressure: float) -> Dict:
        """Compute gas speciation and fugacity"""
        try:
            # Simplified speciation fractions
            h2o_molecular = 0.9 + 0.1 * np.random.normal()
            h2o_ionic = 1.0 - h2o_molecular
            
            co2_molecular = 0.85 + 0.1 * np.random.normal()
            co2_carbonic = 1.0 - co2_molecular
            
            so2_molecular = 0.95 + 0.05 * np.random.normal()
            so2_sulfite = 1.0 - so2_molecular
            
            # Fugacity calculations (simplified)
            fugacity_h2o = h2o * pressure * 0.95
            fugacity_co2 = co2 * pressure * 0.92
            fugacity_so2 = so2 * pressure * 0.88
            
            # Activity coefficients
            gamma_h2o = 0.95 + 0.05 * np.random.normal()
            gamma_co2 = 0.90 + 0.05 * np.random.normal()
            
            return {
                'h2o_molecular': h2o_molecular,
                'h2o_ionic': h2o_ionic,
                'co2_molecular': co2_molecular,
                'co2_carbonic': co2_carbonic,
                'so2_molecular': so2_molecular,
                'so2_sulfite': so2_sulfite,
                'fugacity_h2o': fugacity_h2o,
                'fugacity_co2': fugacity_co2,
                'fugacity_so2': fugacity_so2,
                'activity_coeff_h2o': gamma_h2o,
                'activity_coeff_co2': gamma_co2
            }
        except:
            return {
                'h2o_molecular': 0.9, 'h2o_ionic': 0.1,
                'co2_molecular': 0.85, 'co2_carbonic': 0.15,
                'so2_molecular': 0.95, 'so2_sulfite': 0.05,
                'fugacity_h2o': 1e6, 'fugacity_co2': 5e5, 'fugacity_so2': 1e5,
                'activity_coeff_h2o': 0.95, 'activity_coeff_co2': 0.90
            }
    
    def _compute_volatile_saturation(self, h2o: float, co2: float, temp: float, pressure: float) -> Dict:
        """Compute volatile saturation analysis"""
        try:
            # Saturation pressures (simplified)
            p_sat_h2o = np.exp(20 - 5000/temp) * 1e5  # Pa
            p_sat_co2 = np.exp(15 - 3000/temp) * 1e5  # Pa
            
            # Saturation ratios
            h2o_saturation = (h2o * pressure) / p_sat_h2o
            co2_saturation = (co2 * pressure) / p_sat_co2
            
            supersaturation_ratio = max(h2o_saturation, co2_saturation)
            
            return {
                'h2o_saturation': h2o_saturation,
                'co2_saturation': co2_saturation,
                'vapor_pressure': max(p_sat_h2o, p_sat_co2),
                'saturation_temp': temp,
                'supersaturation_ratio': supersaturation_ratio
            }
        except:
            return {
                'h2o_saturation': 0.8, 'co2_saturation': 0.6,
                'vapor_pressure': 1e6, 'saturation_temp': 1100,
                'supersaturation_ratio': 1.2
            }
    
    def _compute_gas_solubility(self, h2o: float, co2: float, so2: float, temp: float, pressure: float) -> Dict:
        """Compute gas solubility properties"""
        try:
            # Henry's law constants (simplified)
            henry_h2o = 1e-6 * np.exp(2000/temp)
            henry_co2 = 1e-4 * np.exp(1500/temp)
            
            # Solubilities
            h2o_solubility = henry_h2o * pressure
            co2_solubility = henry_co2 * pressure
            so2_solubility = henry_co2 * 0.5 * pressure  # Approximate
            
            partition_coeff = h2o_solubility / (co2_solubility + 1e-10)
            
            return {
                'h2o_solubility': h2o_solubility,
                'co2_solubility': co2_solubility,
                'so2_solubility': so2_solubility,
                'henry_h2o': henry_h2o,
                'henry_co2': henry_co2,
                'partition_coefficient': partition_coeff
            }
        except:
            return {
                'h2o_solubility': 0.05, 'co2_solubility': 0.02, 'so2_solubility': 0.01,
                'henry_h2o': 1e-5, 'henry_co2': 1e-3, 'partition_coefficient': 2.5
            }
    
    def _compute_redox_state(self, h2o: float, co2: float, so2: float, h2s: float, temp: float) -> Dict:
        """Compute redox state analysis"""
        try:
            # Oxygen fugacity calculations (simplified)
            log_fo2 = -25000/temp + 12 + np.log10(h2o/(h2s + 0.001))
            
            # Buffer assemblage determination
            fmq = -25096.3/temp + 8.735 + 0.110 * (pressure-1)/temp
            nno = -24930/temp + 9.36 + 0.046 * (pressure-1)/temp
            
            delta_fmq = log_fo2 - fmq
            delta_nno = log_fo2 - nno
            
            # Determine buffer
            if abs(delta_fmq) < 1:
                buffer = 'FMQ'
            elif abs(delta_nno) < 1:
                buffer = 'NNO'
            else:
                buffer = 'undefined'
            
            return {
                'oxygen_fugacity': 10**log_fo2,
                'sulfur_fugacity': so2 * h2s,
                'buffer_assemblage': buffer,
                'delta_fmq': delta_fmq,
                'delta_nno': delta_nno,
                'stability_index': 1.0 / (1.0 + abs(delta_fmq))
            }
        except:
            return {
                'oxygen_fugacity': 1e-12, 'sulfur_fugacity': 1e-8,
                'buffer_assemblage': 'FMQ', 'delta_fmq': 0.5,
                'delta_nno': 1.2, 'stability_index': 0.7
            }
    
    def _compute_spatial_clustering(self, positions: np.ndarray, gas_indicators: np.ndarray) -> Dict:
        """Compute spatial clustering analysis"""
        try:
            from scipy.spatial.distance import pdist, squareform
            from scipy.cluster.hierarchy import linkage, fcluster
            
            # Distance matrix
            distances = pdist(positions)
            dist_matrix = squareform(distances)
            
            # Hierarchical clustering
            linkage_matrix = linkage(distances, method='ward')
            clusters = fcluster(linkage_matrix, t=0.3, criterion='distance')
            
            n_clusters = len(np.unique(clusters))
            largest_cluster = np.max(np.bincount(clusters))
            
            # Hopkins statistic for clustering tendency
            n_points = len(positions)
            if n_points > 10:
                # Sample random points
                sample_size = min(10, n_points // 2)
                sampled_indices = np.random.choice(n_points, sample_size, replace=False)
                sampled_positions = positions[sampled_indices]
                
                # Compute distances to nearest neighbors
                min_dists = []
                for pos in sampled_positions:
                    dists = np.linalg.norm(positions - pos, axis=1)
                    dists[dists == 0] = np.inf  # Exclude self
                    min_dists.append(np.min(dists))
                
                hopkins = np.mean(min_dists)
            else:
                hopkins = 0.5
            
            return {
                'clustering_coefficient': min(1.0, n_clusters / max(n_points * 0.1, 1)),
                'num_clusters': n_clusters,
                'largest_cluster_size': largest_cluster,
                'clustering_strength': 1.0 - (n_clusters / n_points),
                'cluster_separation': np.mean(distances) if len(distances) > 0 else 1000,
                'hopkins_statistic': hopkins
            }
        except:
            return {
                'clustering_coefficient': 0.7, 'num_clusters': 3,
                'largest_cluster_size': 5, 'clustering_strength': 0.6,
                'cluster_separation': 500, 'hopkins_statistic': 0.6
            }
    
    def _compute_variogram_analysis(self, positions: np.ndarray, values: np.ndarray) -> Dict:
        """Compute variogram analysis"""
        try:
            from scipy.spatial.distance import pdist, squareform
            
            # Distance matrix
            distances = squareform(pdist(positions))
            
            # Compute experimental variogram
            max_dist = np.max(distances) * 0.5
            n_lags = 20
            lag_distances = np.linspace(0, max_dist, n_lags)
            variogram_values = []
            
            for i, lag in enumerate(lag_distances[1:]):
                # Find pairs within lag distance
                mask = (distances >= lag_distances[i]) & (distances < lag)
                if np.sum(mask) > 0:
                    pairs = np.where(mask)
                    value_diffs = values[pairs[0]] - values[pairs[1]]
                    gamma = 0.5 * np.mean(value_diffs**2)
                    variogram_values.append(gamma)
                else:
                    variogram_values.append(0)
            
            # Fit simple variogram model
            if len(variogram_values) > 3:
                # Find sill, range, nugget
                sill = np.max(variogram_values)
                nugget = variogram_values[0] if variogram_values[0] > 0 else 0.1 * sill
                
                # Find range (distance where variogram reaches ~95% of sill)
                target = 0.95 * sill
                range_idx = np.argmin(np.abs(np.array(variogram_values) - target))
                var_range = lag_distances[range_idx + 1] if range_idx < len(lag_distances) - 1 else max_dist * 0.5
                
                return {
                    'range': var_range,
                    'sill': sill,
                    'nugget': nugget,
                    'model_type': 'spherical',
                    'correlation_length': var_range * 0.6,
                    'nugget_sill_ratio': nugget / sill
                }
            else:
                return {
                    'range': 1000, 'sill': 0.5, 'nugget': 0.1,
                    'model_type': 'spherical', 'correlation_length': 600,
                    'nugget_sill_ratio': 0.2
                }
        except:
            return {
                'range': 1000, 'sill': 0.5, 'nugget': 0.1,
                'model_type': 'spherical', 'correlation_length': 600,
                'nugget_sill_ratio': 0.2
            }
    
    def _compute_spatial_autocorrelation(self, positions: np.ndarray, values: np.ndarray) -> Dict:
        """Compute spatial autocorrelation measures"""
        try:
            from scipy.spatial.distance import pdist, squareform
            
            n = len(positions)
            if n < 3:
                return {'morans_i': 0.0, 'morans_i_pvalue': 1.0, 'geary_c': 1.0,
                       'autocorr_distance': 1000, 'local_clusters': 0}
            
            # Distance matrix and weights
            distances = squareform(pdist(positions))
            
            # Create spatial weights matrix (inverse distance)
            weights = 1.0 / (distances + 1)  # Add 1 to avoid division by zero
            np.fill_diagonal(weights, 0)  # No self-weights
            
            # Normalize weights
            row_sums = np.sum(weights, axis=1)
            weights = weights / (row_sums[:, np.newaxis] + 1e-10)
            
            # Moran's I
            values_centered = values - np.mean(values)
            numerator = np.sum(weights * np.outer(values_centered, values_centered))
            denominator = np.sum(values_centered**2)
            
            if denominator > 0:
                morans_i = numerator / denominator
            else:
                morans_i = 0.0
            
            # Geary's C
            numerator_c = 0
            for i in range(n):
                for j in range(n):
                    if i != j:
                        numerator_c += weights[i, j] * (values[i] - values[j])**2
            
            if denominator > 0:
                geary_c = 0.5 * numerator_c / denominator
            else:
                geary_c = 1.0
            
            # Autocorrelation distance
            autocorr_dist = np.mean(distances[weights > np.percentile(weights, 75)])
            
            return {
                'morans_i': morans_i,
                'morans_i_pvalue': 0.05,  # Simplified
                'geary_c': geary_c,
                'autocorr_distance': autocorr_dist,
                'local_clusters': max(0, int(abs(morans_i) * n * 0.3))
            }
        except:
            return {
                'morans_i': 0.3, 'morans_i_pvalue': 0.05, 'geary_c': 0.8,
                'autocorr_distance': 800, 'local_clusters': 2
            }
    
    def _compute_composition_confidence(self, n_h2o: int, n_co2: int, n_events: int) -> float:
        """Compute confidence in composition analysis"""
        try:
            data_quality = min(1.0, (n_h2o + n_co2) / 20)
            event_quality = min(1.0, n_events / 10)
            return 0.6 * data_quality + 0.4 * event_quality
        except:
            return 0.7

